INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お金を儲けるための会社。", "primary_collocate": null, "pronunciation": "きぎょう", "ipa": "kʲiɡʲoː", "syllable_count": 3, "sentences": [{"text": "大きな企業に就職するために、毎日英語を勉強している。", "target_word": "企業", "complexity_tier": "T3", "furigana": "大[おお]きな企業[きぎょう]に就職[しゅうしょく]するために、毎日[まいにち]英語[えいご]を勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "この企業は新しい商品を作って、去年たくさんの利益を出した。", "target_word": "企業", "complexity_tier": "T3", "furigana": "この企業[きぎょう]は新[あたら]しい商品[しょうひん]を作[つく]って、去年[きょねん]たくさんの利益[りえき]を出[だ]した。", "sentence_source": "generated"}, {"text": "小さな企業でも、よい技術があれば世界で売れる。", "target_word": "企業", "complexity_tier": "T3", "furigana": "小[ちい]さな企業[きぎょう]でも、よい技術[ぎじゅつ]があれば世界[せかい]で売[う]れる。", "sentence_source": "generated"}, {"text": "企業は利益を出さなければ、社員に給料を払えない。", "target_word": "企業", "complexity_tier": "T3", "furigana": "企業[きぎょう]は利益[りえき]を出[だ]さなければ、社員[しゃいん]に給料[きゅうりょう]を払[はら]えない。", "sentence_source": "generated"}, {"text": "駅の近くには、有名な企業の本社が並んでいる。", "target_word": "企業", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くには、有名[ゆうめい]な企業[きぎょう]の本社[ほんしゃ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "環境を守る企業が増えて、町がきれいになってきた。", "target_word": "企業", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]る企業[きぎょう]が増[ふ]えて、町[まち]がきれいになってきた。", "sentence_source": "generated"}, {"text": "兄は大学を出てから、外国の企業で働いている。", "target_word": "企業", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]を出[で]てから、外国[がいこく]の企業[きぎょう]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "不景気で、多くの企業が新しい社員を採用しなくなった。", "target_word": "企業", "complexity_tier": "T3", "furigana": "不景気[ふけいき]で、多[おお]くの企業[きぎょう]が新[あたら]しい社員[しゃいん]を採用[さいよう]しなくなった。", "sentence_source": "generated"}, {"text": "その企業は、工場を海外に移して製造費を抑えた。", "target_word": "企業", "complexity_tier": "T3", "furigana": "その企業[きぎょう]は、工場[こうじょう]を海外[かいがい]に移[うつ]して製造費[せいぞうひ]を抑[おさ]えた。", "sentence_source": "generated"}, {"text": "就職活動では、行きたい企業についてよく調べておく。", "target_word": "企業", "complexity_tier": "T3", "furigana": "就職[しゅうしょく]活動[かつどう]では、行[い]きたい企業[きぎょう]についてよく調[しら]べておく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "企業", "label": "基本形"}, {"form": "企業の", "label": "連体形（の）"}, {"form": "企業が", "label": "主格（が）"}], "register": "標準（中立）", "sense_fingerprint": "利益を得るために事業を行う会社や組織", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企業", "is_correct": true, "explanation": "「大きな企業に就職する」で、利益を目的とする会社を指し文に合う。"}, {"text": "企画", "is_correct": false, "explanation": "企画は計画やイベントの案を指し、就職先の意味にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は四季の区分で、就職先の文には入らない。"}, {"text": "奇跡", "is_correct": false, "explanation": "奇跡は偶然の出来事で、就職先を表せない。"}], "explanations": {"企業": "「大きな企業に就職する」で、利益を目的とする会社を指し文に合う。", "企画": "企画は計画やイベントの案を指し、就職先の意味にはならない。", "季節": "季節は四季の区分で、就職先の文には入らない。", "奇跡": "奇跡は偶然の出来事で、就職先を表せない。"}, "sentence_index": 0, "correct_answer": "企業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "若い人が企業して、自分の店を開いた。", "explanation": "ここは〈起業〉（新しく事業を始めること）の意味。同じ読みの企業は会社のことで、動詞の「企業する」とは言わない。"}, {"text": "その企業は利益を目的とせず、地域の清掃活動を続けている。", "explanation": "ここは〈団体〉（利益を目的としない組織）の意味。企業は利益を得るための会社なので、非営利の団体には使わない。"}, {"text": "ボランティア企業が、地域の子どもたちを支えている。", "explanation": "ここは〈組織〉（非営利の集まり）の意味。ボランティアの集まりは利益を得る会社ではないので、企業とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企業", "is_correct": true, "explanation": "「外国の企業で働いている」で、勤務先となる会社を指し文に合う。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生き物の生存期間で、勤務先の文には合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は歌の言葉で、働く場所を表せない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文章のことで、「外国の手紙で働く」は成り立たない。"}], "explanations": {"企業": "「外国の企業で働いている」で、勤務先となる会社を指し文に合う。", "寿命": "寿命は生き物の生存期間で、勤務先の文には合わない。", "歌詞": "歌詞は歌の言葉で、働く場所を表せない。", "手紙": "手紙は文章のことで、「外国の手紙で働く」は成り立たない。"}, "sentence_index": 6, "correct_answer": "企業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国の企業が、災害時の情報を発表した。", "explanation": "ここは〈機関〉（公的な組織）の意味。国は利益を得るための会社ではないので、企業とは言わない。"}, {"text": "図書館は、市が運営する企業だ。", "explanation": "ここは〈施設〉（公共の建物や設備）の意味。図書館は市が運営する公共施設で、利益を目的とする会社ではない。"}, {"text": "来月のイベントの企業を話し合った。", "explanation": "ここは〈企画〉（計画を立てること）の意味。企業は会社のことなので、イベントの計画には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "企業な社員が増えて、町が明るくなった。", "corrected_sentence": "企業の社員が増えて、町が明るくなった。", "error_description": "「企業な」は誤り。名詞の「企業」が後ろの名詞「社員」を修飾するときは「の」を使うので、「な」を「の」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38044, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "行きたい企業に、よく調べておく。", "corrected_sentence": "行きたい企業を、よく調べておく。", "error_description": "「企業に」は誤り。「調べる」は「〜を調べる」と目的語の「を」を取るので、「に」を「を」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「起源を辿る」の形で、辿る対象を示す目的語の格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「起源がたどる」では起源が辿る主体になり、文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「起源でたどる」は手段や場所を示すが、辿る対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「起源とたどる」は共に行う相手を示すが、対象を辿る文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「起源を辿る」の形で、辿る対象を示す目的語の格助詞。", "が": "「起源がたどる」では起源が辿る主体になり、文の意味が合わない。", "で": "「起源でたどる」は手段や場所を示すが、辿る対象にはならない。", "と": "「起源とたどる」は共に行う相手を示すが、対象を辿る文には合わない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「起源には」と続き、ここで文の主題「起源」を導く形になる。"}, {"text": "が", "is_correct": false, "explanation": "「起源が」だと後続の「は」と重なり、「説がある」の文として不自然。"}, {"text": "を", "is_correct": false, "explanation": "「起源を」は目的語を示すが、「説がある」の存在文に目的語はない。"}, {"text": "の", "is_correct": false, "explanation": "「起源の」は名詞を修飾する形で、「いくつかの説がある」と続けると不自然。"}], "correct_answer": "に", "explanations": {"に": "「起源には」と続き、ここで文の主題「起源」を導く形になる。", "が": "「起源が」だと後続の「は」と重なり、「説がある」の文として不自然。", "を": "「起源を」は目的語を示すが、「説がある」の存在文に目的語はない。", "の": "「起源の」は名詞を修飾する形で、「いくつかの説がある」と続けると不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが始まったところのこと。", "primary_collocate": null, "pronunciation": "きげん", "ipa": "kiɡeɴ", "syllable_count": 3, "sentences": [{"text": "この祭りの起源は、千年前の小さな村にある。", "target_word": "起源", "complexity_tier": "T3", "furigana": "この祭[まつ]りの起源[きげん]は、千年前[せんねんまえ]の小[ちい]さな村[むら]にある。", "sentence_source": "generated"}, {"text": "川の起源をたどると、山の中の小さな泉に着いた。", "target_word": "起源", "complexity_tier": "T3", "furigana": "川[かわ]の起源[きげん]をたどると、山[やま]の中[なか]の小[ちい]さな泉[いずみ]に着[つ]いた。", "sentence_source": "generated"}, {"text": "先生は、この言葉の起源を図書館で調べた。", "target_word": "起源", "complexity_tier": "T3", "furigana": "先生[せんせい]は、この言葉[ことば]の起源[きげん]を図書館[としょかん]で調[しら]べた。", "sentence_source": "generated"}, {"text": "彼の家の起源は、四百年前の商人にさかのぼる。", "target_word": "起源", "complexity_tier": "T4", "furigana": "彼[かれ]の家[いえ]の起源[きげん]は、四百年前[よんひゃくねんまえ]の商人[しょうにん]にさかのぼる。", "sentence_source": "generated"}, {"text": "生命の起源は、まだ完全には分かっていない。", "target_word": "起源", "complexity_tier": "T4", "furigana": "生命[せいめい]の起源[きげん]は、まだ完全[かんぜん]には分[わ]かっていない。", "sentence_source": "generated"}, {"text": "この料理は起源が古く、作り方もほとんど変わっていない。", "target_word": "起源", "complexity_tier": "T3", "furigana": "この料理[りょうり]は起源[きげん]が古[ふる]く、作[つく]り方[かた]もほとんど変[か]わっていない。", "sentence_source": "generated"}, {"text": "日本の剣道の起源について、レポートを書いた。", "target_word": "起源", "complexity_tier": "T3", "furigana": "日本[にほん]の剣道[けんどう]の起源[きげん]について、レポートを書[か]いた。", "sentence_source": "generated"}, {"text": "このお菓子の起源には、いくつかの説がある。", "target_word": "起源", "complexity_tier": "T3", "furigana": "このお菓子[かし]の起源[きげん]には、いくつかの説[せつ]がある。", "sentence_source": "generated"}, {"text": "地名の起源を知ると、その町がもっと好きになった。", "target_word": "起源", "complexity_tier": "T3", "furigana": "地名[ちめい]の起源[きげん]を知[し]ると、その町[まち]がもっと好[す]きになった。", "sentence_source": "generated"}, {"text": "行事の起源が分からないので、お年寄りに聞いてみた。", "target_word": "起源", "complexity_tier": "T3", "furigana": "行事[ぎょうじ]の起源[きげん]が分[わ]からないので、お年寄[としよ]りに聞[き]いてみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起源", "label": "基本形"}, {"form": "起源が", "label": "主格"}, {"form": "起源を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "何かが最初に始まった場所や時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "「起源は千年前の小さな村にある」と続く主語で、祭りの始まりの地を示す唯一の語。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝」は人への気持ちを表し、祭りの成り立ちを述べる空所には入らない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「遠慮」は控えめな態度を表し、場所や由来を述べる文では意味が通らない。"}, {"text": "嫉妬", "is_correct": false, "explanation": "「嫉妬」は他人をうらやむ感情で、祭りが村にあることの説明にならない。"}], "explanations": {"起源": "「起源は千年前の小さな村にある」と続く主語で、祭りの始まりの地を示す唯一の語。", "感謝": "「感謝」は人への気持ちを表し、祭りの成り立ちを述べる空所には入らない。", "遠慮": "「遠慮」は控えめな態度を表し、場所や由来を述べる文では意味が通らない。", "嫉妬": "「嫉妬」は他人をうらやむ感情で、祭りが村にあることの説明にならない。"}, "sentence_index": 0, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このマラソンコースの起源は、ゴールの公園だ。", "explanation": "ここは〈終点〉の意味。起源は物事の始まりを指し、終わりの場所は言わない。終点が合う。"}, {"text": "あの事故の起源は、とても重かった。", "explanation": "ここは〈重さ〉の意味。起源は物事の始まりやもとを指し、重さの程度は言わない。"}, {"text": "この犬の起源は、五歳だ。", "explanation": "ここは〈年齢〉の意味。起源は始まりの時点を指すもので、年数は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "「剣道の起源について」の空所に入り、剣道の歴史的なはじまりを示す語。"}, {"text": "謙虚", "is_correct": false, "explanation": "「剣道の謙虚について」は対象として成り立たず、レポートの題にならない。"}, {"text": "不安", "is_correct": false, "explanation": "「剣道の不安について」は剣道の成り立ちを述べる文に合わない。"}, {"text": "憎しみ", "is_correct": false, "explanation": "「剣道の憎しみについて」は剣道の由来を指さず、文の意味が通らない。"}], "explanations": {"起源": "「剣道の起源について」の空所に入り、剣道の歴史的なはじまりを示す語。", "謙虚": "「剣道の謙虚について」は対象として成り立たず、レポートの題にならない。", "不安": "「剣道の不安について」は剣道の成り立ちを述べる文に合わない。", "憎しみ": "「剣道の憎しみについて」は剣道の由来を指さず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電池の起源は、五年ほどだ。", "explanation": "ここは〈寿命〉の意味。起源は始まりの時点を指し、どれだけもつかという期間は言わない。"}, {"text": "このバスの起源は、とても明るい性格だ。", "explanation": "ここは〈性格〉の意味。起源は物事の始まりを指し、人や物の性質は表さない。"}, {"text": "この薬の起源は、一日に三回だ。", "explanation": "ここは〈用法〉の意味。起源は物事の始まりを指し、服用の回数は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この祭りの起源を、千年前の小さな村にあると言われている。", "corrected_sentence": "この祭りの起源は、千年前の小さな村にあると言われている。", "error_description": "「起源」に続く助詞は主題の「は」が正しい。「を」にすると「ある」と結びつかず誤り。正しくは「起源は…にある」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38046, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その料理の起源で、中国の古い村にある。", "corrected_sentence": "その料理の起源は、中国の古い村にある。", "error_description": "「起源は」の「は」を「で」にすると、「ある」と結びつかず不自然になる。正しくは「起源は…にある」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「起源がある」で、「ある」の主語として存在を示す。"}, {"text": "を", "is_correct": false, "explanation": "「起源を」は目的語を示すが、「ある」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「イギリスに起源へある」は方向の「へ」が「ある」と結びつかず成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「起源の」は名詞を修飾するので、文末の「ある」とつながらない。"}], "correct_answer": "が", "explanations": {"が": "「起源がある」で、「ある」の主語として存在を示す。", "を": "「起源を」は目的語を示すが、「ある」は目的語を取らないので合わない。", "へ": "「イギリスに起源へある」は方向の「へ」が「ある」と結びつかず成り立たない。", "の": "「起源の」は名詞を修飾するので、文末の「ある」とつながらない。"}, "error_tags": {"を": "目的語", "へ": "方向・対象", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「起源を知る」の形で、知る対象を示す目的語の格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「起源が知る」では起源が知る主体になり、主語の私たちと合わない。"}, {"text": "に", "is_correct": false, "explanation": "「起源に知る」は対象を示す形にならず、「知る」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「起源で知る」は手段や場所を示すが、「知る」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「起源を知る」の形で、知る対象を示す目的語の格助詞。", "が": "「起源が知る」では起源が知る主体になり、主語の私たちと合わない。", "に": "「起源に知る」は対象を示す形にならず、「知る」の目的語にならない。", "で": "「起源で知る」は手段や場所を示すが、「知る」の対象にはならない。"}, "error_tags": {"が": "主語", "に": "方向・対象", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の始まりや、生まれたもととなるもの。", "primary_collocate": null, "pronunciation": "きげん", "ipa": "kiɡeɴ", "syllable_count": 3, "sentences": [{"text": "二つの言語は、同じ起源を持っている。", "target_word": "起源", "complexity_tier": "T3", "furigana": "二[ふた]つの言語[げんご]は、同[おな]じ起源[きげん]を持[も]っている。", "sentence_source": "generated"}, {"text": "多くのスポーツは、イギリスに起源がある。", "target_word": "起源", "complexity_tier": "T3", "furigana": "多[おお]くのスポーツは、イギリスに起源[きげん]がある。", "sentence_source": "generated"}, {"text": "この習慣の起源は、農業の仕事にある。", "target_word": "起源", "complexity_tier": "T3", "furigana": "この習慣[しゅうかん]の起源[きげん]は、農業[のうぎょう]の仕事[しごと]にある。", "sentence_source": "generated"}, {"text": "宇宙の起源を研究する科学者になりたい。", "target_word": "起源", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の起源[きげん]を研究[けんきゅう]する科学者[かがくしゃ]になりたい。", "sentence_source": "generated"}, {"text": "和食の起源は、米作りと深く関わっている。", "target_word": "起源", "complexity_tier": "T4", "furigana": "和食[わしょく]の起源[きげん]は、米作[こめづく]りと深[ふか]く関[かか]わっている。", "sentence_source": "generated"}, {"text": "その病気の起源は、百年前の流行にさかのぼる。", "target_word": "起源", "complexity_tier": "T4", "furigana": "その病気[びょうき]の起源[きげん]は、百年前[ひゃくねんまえ]の流行[りゅうこう]にさかのぼる。", "sentence_source": "generated"}, {"text": "麺類の起源には、中国説がある。", "target_word": "起源", "complexity_tier": "T3", "furigana": "麺類[めんるい]の起源[きげん]には、中国説[ちゅうごくせつ]がある。", "sentence_source": "generated"}, {"text": "私たちの文化の起源を知るために、博物館へ行った。", "target_word": "起源", "complexity_tier": "T3", "furigana": "私[わたし]たちの文化[ぶんか]の起源[きげん]を知[し]るために、博物館[はくぶつかん]へ行[い]った。", "sentence_source": "generated"}, {"text": "彼は、人間の起源を説明する本を読んでいる。", "target_word": "起源", "complexity_tier": "T3", "furigana": "彼[かれ]は、人間[にんげん]の起源[きげん]を説明[せつめい]する本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "起源が異なる二つの言葉なので、意味も全然違う。", "target_word": "起源", "complexity_tier": "T3", "furigana": "起源[きげん]が異[こと]なる二[ふた]つの言葉[ことば]なので、意味[いみ]も全然[ぜんぜん]違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起源", "label": "基本形"}, {"form": "起源が", "label": "主格"}, {"form": "起源を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "物事や文化が生まれたもとになるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "「同じ起源を持つ」で、言語が生まれたもとを表す語。"}, {"text": "感謝", "is_correct": false, "explanation": "「同じ感謝を持つ」は成り立たず、言語の関係を述べる文にならない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「同じ遠慮を持つ」は意味が通らず、言語の説明に合わない。"}, {"text": "嫉妬", "is_correct": false, "explanation": "「同じ嫉妬を持つ」は言語同士の関係を表さず、文が成り立たない。"}], "explanations": {"起源": "「同じ起源を持つ」で、言語が生まれたもとを表す語。", "感謝": "「同じ感謝を持つ」は成り立たず、言語の関係を述べる文にならない。", "遠慮": "「同じ遠慮を持つ」は意味が通らず、言語の説明に合わない。", "嫉妬": "「同じ嫉妬を持つ」は言語同士の関係を表さず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このロボットの起源は、三年ほどだ。", "explanation": "ここは〈寿命〉の意味。起源は生まれたもとを指し、どれだけ使えるかという期間は言わない。"}, {"text": "この旅の起源は、とても楽しかったという評判だ。", "explanation": "ここは〈評判〉の意味。起源は物事の始まりやもとを指し、世間の評価は言わない。"}, {"text": "この店の起源は、朝九時に開く。", "explanation": "ここは〈営業時間〉の意味。起源は物事の始まりを指し、店が開く時刻は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "「麺類の起源には」の空所に入り、麺がもとになった由来を示す語。"}, {"text": "謙虚", "is_correct": false, "explanation": "「麺類の謙虚には」は意味が通らず、中国説の説明にならない。"}, {"text": "不安", "is_correct": false, "explanation": "「麺類の不安には」は麺の由来を述べる文に合わない。"}, {"text": "憎しみ", "is_correct": false, "explanation": "「麺類の憎しみには」は成り立たず、由来の説を述べる文脈に合わない。"}], "explanations": {"起源": "「麺類の起源には」の空所に入り、麺がもとになった由来を示す語。", "謙虚": "「麺類の謙虚には」は意味が通らず、中国説の説明にならない。", "不安": "「麺類の不安には」は麺の由来を述べる文に合わない。", "憎しみ": "「麺類の憎しみには」は成り立たず、由来の説を述べる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この選手の起源は、チームの司令塔だ。", "explanation": "ここは〈役割〉の意味。起源は生まれたもとを指し、担う務めは言わない。"}, {"text": "この小説の起源は、悲しい結末だ。", "explanation": "ここは〈結末〉の意味。起源は始まりを指し、終わりの場面は指さない。"}, {"text": "この旅行の起源は、一人二万円だ。", "explanation": "ここは〈料金〉の意味。起源は物事の始まりを指し、代金は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多くのスポーツは、イギリスに起源をあると言われている。", "corrected_sentence": "多くのスポーツは、イギリスに起源があると言われている。", "error_description": "「起源が」の「が」は「ある」の主語。「を」にすると「起源をある」となり、「ある」と結びつかず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38047, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その菓子の起源を、古い寺院にあるらしい。", "corrected_sentence": "その菓子の起源は、古い寺院にあるらしい。", "error_description": "「起源は」の「は」を「を」にすると、「ある」と結びつかず誤り。正しくは「起源は…にあるらしい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「今年の後半は」で、話題にする範囲として後半を示す。"}, {"text": "を", "is_correct": false, "explanation": "「今年の後半を、仕事が忙しくて」は目的語の「を」で、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「今年の後半へ仕事が」は方向の「へ」で、主語の働きをしない。"}, {"text": "と", "is_correct": false, "explanation": "「今年の後半と仕事が忙しくて」は並列の「と」で、後半と仕事を並べる形になり、文の主語・述語の関係が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「今年の後半は」で、話題にする範囲として後半を示す。", "を": "「今年の後半を、仕事が忙しくて」は目的語の「を」で、文が成り立たない。", "へ": "「今年の後半へ仕事が」は方向の「へ」で、主語の働きをしない。", "と": "「今年の後半と仕事が忙しくて」は並列の「と」で、後半と仕事を並べる形になり、文の主語・述語の関係が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前半", "is_correct": true, "explanation": "後半の対義語で、全体を二つに分けたときの前の半分を指す。"}, {"text": "中盤", "is_correct": false, "explanation": "中盤は真ん中あたりの部分で、後半の対義語ではない。"}, {"text": "前途", "is_correct": false, "explanation": "前途は将来の見通しを指し、後半の対義語にはならない。"}, {"text": "先輩", "is_correct": false, "explanation": "先輩は年上の仲間を指し、時間区分の対義語ではない。"}], "correct_answer": "前半", "explanations": {"前半": "後半の対義語で、全体を二つに分けたときの前の半分を指す。", "中盤": "中盤は真ん中あたりの部分で、後半の対義語ではない。", "前途": "前途は将来の見通しを指し、後半の対義語にはならない。", "先輩": "先輩は年上の仲間を指し、時間区分の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前半", "is_correct": true, "explanation": "後半の対義語で、全体を二つに分けたときの前の半分を指す。"}, {"text": "初期", "is_correct": false, "explanation": "初期は始まりの時期を指し、後半の対義語ではない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は残る響きや感覚を指し、時間区分の対義語にならない。"}, {"text": "中間", "is_correct": false, "explanation": "中間は両端の間を指し、後半と対になる語ではない。"}], "correct_answer": "前半", "explanations": {"前半": "後半の対義語で、全体を二つに分けたときの前の半分を指す。", "初期": "初期は始まりの時期を指し、後半の対義語ではない。", "余韻": "余韻は残る響きや感覚を指し、時間区分の対義語にならない。", "中間": "中間は両端の間を指し、後半と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あとの半分。", "primary_collocate": null, "pronunciation": "こうはん", "ipa": "koːhaɴ", "syllable_count": 4, "sentences": [{"text": "サッカーの試合は、後半に入って急に動きが速くなった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "サッカーの試合[しあい]は、後半[こうはん]に入[はい]って急[きゅう]に動[うご]きが速[はや]くなった。", "sentence_source": "generated"}, {"text": "今年の後半は、仕事が忙しくて旅行に行けなかった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "今年[ことし]の後半[こうはん]は、仕事[しごと]が忙[いそが]しくて旅行[りょこう]に行[い]けなかった。", "sentence_source": "generated"}, {"text": "この映画は前半が長いが、後半はとても面白い。", "target_word": "後半", "complexity_tier": "T3", "furigana": "この映画[えいが]は前半[ぜんはん]が長[なが]いが、後半[こうはん]はとても面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "マラソンの後半、彼は疲れて走るのが遅くなった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "マラソンの後半[こうはん]、彼[かれ]は疲[つか]れて走[はし]るのが遅[おそ]くなった。", "sentence_source": "generated"}, {"text": "本の後半を読む前に、前半の内容を思い出した。", "target_word": "後半", "complexity_tier": "T3", "furigana": "本[ほん]の後半[こうはん]を読[よ]む前[まえ]に、前半[ぜんはん]の内容[ないよう]を思[おも]い出[だ]した。", "sentence_source": "generated"}, {"text": "前半は負けていたが、後半に三点取って勝った。", "target_word": "後半", "complexity_tier": "T3", "furigana": "前半[ぜんはん]は負[ま]けていたが、後半[こうはん]に三点[さんてん]取[と]って勝[か]った。", "sentence_source": "generated"}, {"text": "授業の後半で、先生は宿題について説明した。", "target_word": "後半", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の後半[こうはん]で、先生[せんせい]は宿題[しゅくだい]について説明[せつめい]した。", "sentence_source": "generated"}, {"text": "一月から六月までが前半で、七月からが後半だ。", "target_word": "後半", "complexity_tier": "T3", "furigana": "一月[いちがつ]から六月[ろくがつ]までが前半[ぜんはん]で、七月[しちがつ]からが後半[こうはん]だ。", "sentence_source": "generated"}, {"text": "後半は体力が必要なので、前半に力を使いすぎないほうがいい。", "target_word": "後半", "complexity_tier": "T3", "furigana": "後半[こうはん]は体力[たいりょく]が必要[ひつよう]なので、前半[ぜんはん]に力[ちから]を使[つか]いすぎないほうがいい。", "sentence_source": "generated"}, {"text": "試合の後半が始まる前に、監督は選手に話をした。", "target_word": "後半", "complexity_tier": "T3", "furigana": "試合[しあい]の後半[こうはん]が始[はじ]まる前[まえ]に、監督[かんとく]は選手[せんしゅ]に話[はなし]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後半", "label": "基本形"}, {"form": "後半に", "label": "時を表す（に）"}, {"form": "後半の", "label": "連体形（の）"}], "register": "標準（中立）", "sense_fingerprint": "全体を二つに分けたときの、あとの方の半分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後半", "is_correct": true, "explanation": "「試合の後半に入って」で、試合の後のほうの時間区切りを表し文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は日常の行動で、試合の時間の区切りを表せない。"}, {"text": "結婚", "is_correct": false, "explanation": "結婚は人生の出来事で、試合の経過には合わない。"}, {"text": "手話", "is_correct": false, "explanation": "手話は言語の一種で、試合の時間の区切りを表せない。"}], "explanations": {"後半": "「試合の後半に入って」で、試合の後のほうの時間区切りを表し文に合う。", "散歩": "散歩は日常の行動で、試合の時間の区切りを表せない。", "結婚": "結婚は人生の出来事で、試合の経過には合わない。", "手話": "手話は言語の一種で、試合の時間の区切りを表せない。"}, "sentence_index": 0, "correct_answer": "後半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の後輩は大学生で、来年卒業する。", "explanation": "ここは〈後輩〉（年下の仲間）の意味。後半は全体の後ろの部分を指すので、人には使わない。"}, {"text": "父は、息子を店の後半に決めた。", "explanation": "ここは〈後継〉（あとを継ぐ人）の意味。後半は全体の後ろの部分で、人を指さない。"}, {"text": "後半、改めて連絡します。", "explanation": "ここは〈後日〉（のちの日）の意味。後半は全体の後ろの部分で、日付のあとを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後半", "is_correct": true, "explanation": "「授業の後半で」で、授業のあとの時間を表し文に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は朝寝過ごすことで、授業の時間の区切りを表せない。"}, {"text": "宿舎", "is_correct": false, "explanation": "宿舎は泊まる施設で、授業の時間には合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書いた文章で、授業の時間を指せない。"}], "explanations": {"後半": "「授業の後半で」で、授業のあとの時間を表し文に合う。", "寝坊": "寝坊は朝寝過ごすことで、授業の時間の区切りを表せない。", "宿舎": "宿舎は泊まる施設で、授業の時間には合わない。", "手紙": "手紙は書いた文章で、授業の時間を指せない。"}, "sentence_index": 6, "correct_answer": "後半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの先輩は、私の後半になってくれた。", "explanation": "ここは〈後ろ盾〉（支えてくれる人や組織）の意味。後半は時間や全体の後ろの部分で、人を支える立場は表さない。"}, {"text": "後半から声がした。", "explanation": "ここは〈背後〉（うしろの方向）の意味。後半は時間や全体の後の部分で、場所の後ろを表さない。"}, {"text": "二つの案のうち、後半を選んだ。", "explanation": "ここは〈後者〉（二つのうちの後のもの）の意味。後半は全体の後ろの部分で、選択肢を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドラマの後半を、主人公が急に笑い出した。", "corrected_sentence": "ドラマの後半で、主人公が急に笑い出した。", "error_description": "「後半を」は誤り。時点や場面を示すので「後半で」と「で」を使う。「を」では目的語になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38048, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合の後半な時間に、監督は選手に話をした。", "corrected_sentence": "試合の後半の時間に、監督は選手に話をした。", "error_description": "「後半な」は誤り。名詞の「後半」が後ろの「時間」を修飾するときは「の」を使うので、「な」を「の」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「二十代の後半に」の「に」は時点を表し、後半が時期を示すことに合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、時期を指す「二十代の後半へ」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ働きで、「二十代の後半の、私は…」は述語が続かず文として切れてしまう。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を表すが、「二十代の後半を、私は…」では時期を目的語にできず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「二十代の後半に」の「に」は時点を表し、後半が時期を示すことに合う。", "へ": "「へ」は移動の方向を表すので、時期を指す「二十代の後半へ」は成り立たない。", "の": "「の」は名詞をつなぐ働きで、「二十代の後半の、私は…」は述語が続かず文として切れてしまう。", "を": "「を」は他動詞の目的語を表すが、「二十代の後半を、私は…」では時期を目的語にできず文が成り立たない。"}, "error_tags": {"へ": "direction", "の": "modifier", "を": "object"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前半", "is_correct": true, "explanation": "「後半」の対義語。時間や順序で、真ん中より前の部分を指す。"}, {"text": "中盤", "is_correct": false, "explanation": "中盤は全体の中ほどを指し、後半と対になる語ではない。"}, {"text": "途中", "is_correct": false, "explanation": "途中は物事が進んでいる最中を指し、後半の反対語にはならない。"}, {"text": "中頃", "is_correct": false, "explanation": "中頃は時期の真ん中あたりを指し、後半と対になる語ではない。"}], "correct_answer": "前半", "explanations": {"前半": "「後半」の対義語。時間や順序で、真ん中より前の部分を指す。", "中盤": "中盤は全体の中ほどを指し、後半と対になる語ではない。", "途中": "途中は物事が進んでいる最中を指し、後半の反対語にはならない。", "中頃": "中頃は時期の真ん中あたりを指し、後半と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前半", "is_correct": true, "explanation": "「後半」の対義語。時間や順序で、真ん中より前の部分を指す。"}, {"text": "中央", "is_correct": false, "explanation": "中央は位置の真ん中を指し、後半の反対語ではない。"}, {"text": "中核", "is_correct": false, "explanation": "中核は物事の中心部分を指し、後半と対になる語ではない。"}, {"text": "本題", "is_correct": false, "explanation": "本題は話の主題を指し、時間や順序で対になる語ではない。"}], "correct_answer": "前半", "explanations": {"前半": "「後半」の対義語。時間や順序で、真ん中より前の部分を指す。", "中央": "中央は位置の真ん中を指し、後半の反対語ではない。", "中核": "中核は物事の中心部分を指し、後半と対になる語ではない。", "本題": "本題は話の主題を指し、時間や順序で対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の後ろの部分。時間や順番で、真ん中より後ろの部分。", "primary_collocate": null, "pronunciation": "こうはん", "ipa": "koːhaɴ", "syllable_count": 4, "sentences": [{"text": "会議の後半は、予算についての話ばかりだった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "会議[かいぎ]の後半[こうはん]は、予算[よさん]についての話[はなし]ばかりだった。", "sentence_source": "generated"}, {"text": "二十代の後半に、私は初めて外国で暮らした。", "target_word": "後半", "complexity_tier": "T3", "furigana": "二十代[にじゅうだい]の後半[こうはん]に、私[わたし]は初[はじ]めて外国[がいこく]で暮[く]らした。", "sentence_source": "generated"}, {"text": "今月の後半は、出張が続いて家にほとんどいない。", "target_word": "後半", "complexity_tier": "T3", "furigana": "今月[こんげつ]の後半[こうはん]は、出張[しゅっちょう]が続[つづ]いて家[いえ]にほとんどいない。", "sentence_source": "generated"}, {"text": "この小説は後半になるほど、話が難しくなる。", "target_word": "後半", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は後半[こうはん]になるほど、話[はなし]が難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "九月の後半になると、朝晩が涼しくなってくる。", "target_word": "後半", "complexity_tier": "T3", "furigana": "九月[くがつ]の後半[こうはん]になると、朝晩[あさばん]が涼[すず]しくなってくる。", "sentence_source": "generated"}, {"text": "発表の後半で、質問が一気に増えた。", "target_word": "後半", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の後半[こうはん]で、質問[しつもん]が一気[いっき]に増[ふ]えた。", "sentence_source": "generated"}, {"text": "列の後半にいた人たちは、席に座れなかった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "列[れつ]の後半[こうはん]にいた人[ひと]たちは、席[せき]に座[すわ]れなかった。", "sentence_source": "generated"}, {"text": "旅行の後半は、雨が降って予定が変わった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "旅行[りょこう]の後半[こうはん]は、雨[あめ]が降[ふ]って予定[よてい]が変[か]わった。", "sentence_source": "generated"}, {"text": "この曲は後半で、リズムが急に速くなる。", "target_word": "後半", "complexity_tier": "T3", "furigana": "この曲[きょく]は後半[こうはん]で、リズムが急[きゅう]に速[はや]くなる。", "sentence_source": "generated"}, {"text": "試験の後半は問題が難しく、時間が足りなかった。", "target_word": "後半", "complexity_tier": "T3", "furigana": "試験[しけん]の後半[こうはん]は問題[もんだい]が難[むずか]しく、時間[じかん]が足[た]りなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後半", "label": "基本形"}, {"form": "後半に", "label": "時を表す（に）"}, {"form": "後半の", "label": "連体形（の）"}], "register": "標準（中立）", "sense_fingerprint": "時間や順序の流れで、真ん中より後ろにあたる部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後半", "is_correct": true, "explanation": "「会議の後半」は会議の後ろの部分を指し、予算の話ばかりだったという文に合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は会議の内容を表さないので、「会議の窓は、予算についての話ばかりだった」は意味をなさない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は話題になる物ではないので、「会議の天井は予算についての話ばかりだった」は成り立たない。"}, {"text": "照明", "is_correct": false, "explanation": "照明は話の内容を表さないので、「会議の照明は予算についての話ばかりだった」は不自然で合わない。"}], "explanations": {"後半": "「会議の後半」は会議の後ろの部分を指し、予算の話ばかりだったという文に合う。", "窓": "窓は会議の内容を表さないので、「会議の窓は、予算についての話ばかりだった」は意味をなさない。", "天井": "天井は話題になる物ではないので、「会議の天井は予算についての話ばかりだった」は成り立たない。", "照明": "照明は話の内容を表さないので、「会議の照明は予算についての話ばかりだった」は不自然で合わない。"}, "sentence_index": 0, "correct_answer": "後半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの案で迷い、後半を選んだ。", "explanation": "ここは〈後者〉の意味。後半は時間や順序の後ろの部分を指し、二つのうち後のものを言う〈後者〉の代わりにはならないので合わない。"}, {"text": "頭の後半を殴られた。", "explanation": "ここは〈後頭部〉の意味。後半は時間や順序の後ろの部分を指すので、頭の後ろ側を言う〈後頭部〉の代わりにはならず合わない。"}, {"text": "この記録を後半の人々に残したい。", "explanation": "ここは〈後世〉の意味。後半は時間の流れの一部で、未来の人々を指す〈後世〉の代わりにはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後半", "is_correct": true, "explanation": "「列の後半にいた人たち」は列の後ろの部分にいた人を指し、席に座れなかったという文に合う。"}, {"text": "看板", "is_correct": false, "explanation": "看板は列の一部ではないので、「列の看板にいた人たち」は意味をなさない。"}, {"text": "柱", "is_correct": false, "explanation": "柱は列の一部を表す語ではないので、「列の柱にいた人たち」は成り立たない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は列の位置を表す語ではないので、「列の地図にいた人たち」は不自然で合わない。"}], "explanations": {"後半": "「列の後半にいた人たち」は列の後ろの部分にいた人を指し、席に座れなかったという文に合う。", "看板": "看板は列の一部ではないので、「列の看板にいた人たち」は意味をなさない。", "柱": "柱は列の一部を表す語ではないので、「列の柱にいた人たち」は成り立たない。", "地図": "地図は列の位置を表す語ではないので、「列の地図にいた人たち」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "後半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物音がして、後半を振り向いた。", "explanation": "ここは〈背後〉の意味。後半は時間や順序の部分で、音のした後ろ側を振り向く場面には〈背後〉や〈後ろ〉を使うので合わない。"}, {"text": "仕事を後半の社員に引き継いだ。", "explanation": "ここは〈後任〉の意味。後半は人を指さないので、仕事を人に引き継ぐ場面では使えない。"}, {"text": "宿題を後半に任せた。", "explanation": "ここは〈後回し〉の意味。後半は時間の部分を指し、物事の実行を遅らせることは〈後回し〉で言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の後半を、予算の話になった。", "corrected_sentence": "会議の後半に、予算の話になった。", "error_description": "時点を表す「に」が正しいのに「を」になっている。「後半」は時の位置を示すので「に」で受ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38049, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "期末試験の後半な問題が難しかった。", "corrected_sentence": "期末試験の後半の問題が難しかった。", "error_description": "「後半な」は誤り。名詞の「後半」が後ろの「問題」を修飾するときは「の」を使うので、「な」を「の」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静まり", "is_correct": true, "explanation": "「高まり」の対義語。気持ちや興奮が静まって弱くなることを指す。"}, {"text": "規模", "is_correct": false, "explanation": "規模は物事の大きさを表し、気持ちの高まりの反対語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序を表し、高まりと対になる語ではない。"}, {"text": "変化", "is_correct": false, "explanation": "変化は状態が変わること全般を指し、高まりの反対語として特定されない。"}], "correct_answer": "静まり", "explanations": {"静まり": "「高まり」の対義語。気持ちや興奮が静まって弱くなることを指す。", "規模": "規模は物事の大きさを表し、気持ちの高まりの反対語ではない。", "手順": "手順は作業の順序を表し、高まりと対になる語ではない。", "変化": "変化は状態が変わること全般を指し、高まりの反対語として特定されない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静まり", "is_correct": true, "explanation": "「高まり」の対義語。喜びや気持ちが静まって弱くなることを指す。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の時期を表し、高まりの反対語ではない。"}, {"text": "手本", "is_correct": false, "explanation": "手本は見習うべき例を表し、高まりと対になる語ではない。"}, {"text": "歩幅", "is_correct": false, "explanation": "歩幅は歩くときの幅を表し、気持ちの高まりとは対にならない。"}], "correct_answer": "静まり", "explanations": {"静まり": "「高まり」の対義語。喜びや気持ちが静まって弱くなることを指す。", "季節": "季節は一年の時期を表し、高まりの反対語ではない。", "手本": "手本は見習うべき例を表し、高まりと対になる語ではない。", "歩幅": "歩幅は歩くときの幅を表し、気持ちの高まりとは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かの気持ちや勢いが、だんだん強くなること。", "primary_collocate": null, "pronunciation": "たかまり", "ipa": "takamaɾi", "syllable_count": 4, "sentences": [{"text": "発表の日が近づくにつれて、みんなの期待の高まりを感じた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の日[ひ]が近[ちか]づくにつれて、みんなの期待[きたい]の高[たか]まりを感[かん]じた。", "sentence_source": "generated"}, {"text": "本番前の緊張の高まりで、手が震えてしまった。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "本番前[ほんばんまえ]の緊張[きんちょう]の高[たか]まりで、手[て]が震[ふる]えてしまった。", "sentence_source": "generated"}, {"text": "給料が下がり、社員の不満の高まりが問題になっている。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が下[さ]がり、社員[しゃいん]の不満[ふまん]の高[たか]まりが問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "夜が近づくと、祭りの会場は熱気の高まりで包まれた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "夜[よる]が近[ちか]づくと、祭[まつ]りの会場[かいじょう]は熱気[ねっき]の高[たか]まりで包[つつ]まれた。", "sentence_source": "generated"}, {"text": "試合の終わりが近づき、ファンの興奮の高まりが止まらない。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "試合[しあい]の終[お]わりが近[ちか]づき、ファンの興奮[こうふん]の高[たか]まりが止[と]まらない。", "sentence_source": "generated"}, {"text": "不安の高まりを感じて、彼女は友達に電話をかけた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "不安[ふあん]の高[たか]まりを感[かん]じて、彼女[かのじょ]は友達[ともだち]に電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "音楽がだんだん大きくなり、感動の高まりに涙が出た。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "音楽[おんがく]がだんだん大[おお]きくなり、感動[かんどう]の高[たか]まりに涙[なみだ]が出[で]た。", "sentence_source": "generated"}, {"text": "気持ちの高まりを抑えられず、思わず大きな声で叫んだ。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "気持[きも]ちの高[たか]まりを抑[おさ]えられず、思[おも]わず大[おお]きな声[こえ]で叫[さけ]んだ。", "sentence_source": "generated"}, {"text": "国境付近で、両国の警戒の高まりが報じられた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "国境[こっきょう]付近[ふきん]で、両国[りょうこく]の警戒[けいかい]の高[たか]まりが報[ほう]じられた。", "sentence_source": "generated"}, {"text": "優勝が近づくにつれ、町では喜びの高まりが広がっていった。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]が近[ちか]づくにつれ、町[まち]では喜[よろこ]びの高[たか]まりが広[ひろ]がっていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高まり", "label": "基本形（動詞「高まる」の連用形名詞）"}, {"form": "高まりの", "label": "連体形（の）"}, {"form": "高まりが", "label": "主格（が）"}], "register": "標準（中立）", "sense_fingerprint": "期待・緊張・興奮など人の気持ちが次第に強くなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高まり", "is_correct": true, "explanation": "「期待の高まりを感じた」は期待の気持ちが強くなることを指し、文の意味に合う。"}, {"text": "段差", "is_correct": false, "explanation": "段差は地面の高低差を表すので、「期待の段差を感じた」は成り立たない。"}, {"text": "窓口", "is_correct": false, "explanation": "窓口は受付を表すので、「期待の窓口を感じた」は意味をなさない。"}, {"text": "目方", "is_correct": false, "explanation": "目方は重さを表すので、「期待の目方を感じた」は不自然で合わない。"}], "explanations": {"高まり": "「期待の高まりを感じた」は期待の気持ちが強くなることを指し、文の意味に合う。", "段差": "段差は地面の高低差を表すので、「期待の段差を感じた」は成り立たない。", "窓口": "窓口は受付を表すので、「期待の窓口を感じた」は意味をなさない。", "目方": "目方は重さを表すので、「期待の目方を感じた」は不自然で合わない。"}, "sentence_index": 0, "correct_answer": "高まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の接近で、庭の木の葉の高まりが心配された。", "explanation": "ここは〈茂み〉の意味。木の葉の量は〈茂み〉などで言い、〈高まり〉は気持ちや勢いの強まりを表すので、木の葉には合わない。"}, {"text": "彼は一年で身長の高まりが十センチあった。", "explanation": "ここは〈伸び〉の意味。身長の増加は〈伸び〉を使い、〈高まり〉は気持ちや勢いが強くなることに使うので合わない。"}, {"text": "風邪の喉の高まりで、熱が出た。", "explanation": "ここは〈腫れ〉の意味。喉の状態は〈腫れ〉で言い、〈高まり〉は気持ちや勢いの強まりに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高まり", "is_correct": true, "explanation": "「感動の高まりに涙が出た」は感動が強くなったことを指し、涙が出た理由として自然。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車などに使う券で、「感動の切符に涙が出た」は意味をなさない。"}, {"text": "看板", "is_correct": false, "explanation": "看板は店などの掲示物で、「感動の看板に涙が出た」は成り立たない。"}, {"text": "柱", "is_correct": false, "explanation": "柱は建物の部材で、「感動の柱に涙が出た」は不自然で合わない。"}], "explanations": {"高まり": "「感動の高まりに涙が出た」は感動が強くなったことを指し、涙が出た理由として自然。", "切符": "切符は乗車などに使う券で、「感動の切符に涙が出た」は意味をなさない。", "看板": "看板は店などの掲示物で、「感動の看板に涙が出た」は成り立たない。", "柱": "柱は建物の部材で、「感動の柱に涙が出た」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "高まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏になり、洗濯物の高まりで部屋が狭くなった。", "explanation": "ここは〈山積み〉の意味。洗濯物の量は〈山積み〉で言い、気持ちや勢いの強まりを表す〈高まり〉は使えないので合わない。"}, {"text": "会議の高まりを記録した。", "explanation": "ここは〈進行〉の意味。会議の進み具合は〈進行〉で言い、〈高まり〉は気持ちや勢いに使うので合わない。"}, {"text": "部屋の高まりを片付けた。", "explanation": "部屋の乱れは〈散らかり〉を使い、〈高まり〉は気持ちや勢いに使う。部屋には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合前の緊張の高まりを、足が震えてしまった。", "corrected_sentence": "試合前の緊張の高まりで、足が震えてしまった。", "error_description": "原因を表す「で」が正しいのに「を」になっている。「高まりで足が震えた」と原因を示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの当日、町では喜びの高まったが広がった。", "corrected_sentence": "祭りの当日、町では喜びの高まりが広がった。", "error_description": "名詞の「高まり」が正しいのに動詞の連用形「高まっ」を使っている。文の主語になる名詞形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「需要の高まりで」は原因を表し、工場が休みなく動いた理由として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「需要の高まりを、工場は休みなく動いた」は目的語が成り立たず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、原因を示す場面では使えず合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の働きで、「需要の高まりより工場は動いた」では比べる対象が合わない。"}], "correct_answer": "で", "explanations": {"で": "「需要の高まりで」は原因を表し、工場が休みなく動いた理由として自然に続く。", "を": "「需要の高まりを、工場は休みなく動いた」は目的語が成り立たず不自然。", "へ": "「へ」は方向を表すので、原因を示す場面では使えず合わない。", "より": "「より」は比較の働きで、「需要の高まりより工場は動いた」では比べる対象が合わない。"}, "error_tags": {"を": "object", "へ": "direction", "より": "comparison"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低下", "is_correct": true, "explanation": "「高まり」の対義語。程度や需要が次第に小さくなることを指す。"}, {"text": "変化", "is_correct": false, "explanation": "変化は状態が変わること全般を指し、高まりの反対語として特定されない。"}, {"text": "規模", "is_correct": false, "explanation": "規模は物事の大きさを表し、高まりと対になる語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序を表し、高まりの反対語ではない。"}], "correct_answer": "低下", "explanations": {"低下": "「高まり」の対義語。程度や需要が次第に小さくなることを指す。", "変化": "変化は状態が変わること全般を指し、高まりの反対語として特定されない。", "規模": "規模は物事の大きさを表し、高まりと対になる語ではない。", "手順": "手順は作業の順序を表し、高まりの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低下", "is_correct": true, "explanation": "「高まり」の対義語。消費などの程度が次第に小さくなることを指す。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の時期を表し、高まりの反対語ではない。"}, {"text": "手本", "is_correct": false, "explanation": "手本は見習うべき例を表し、高まりと対になる語ではない。"}, {"text": "歩幅", "is_correct": false, "explanation": "歩幅は歩くときの幅を表し、程度の高まりとは対にならない。"}], "correct_answer": "低下", "explanations": {"低下": "「高まり」の対義語。消費などの程度が次第に小さくなることを指す。", "季節": "季節は一年の時期を表し、高まりの反対語ではない。", "手本": "手本は見習うべき例を表し、高まりと対になる語ではない。", "歩幅": "歩幅は歩くときの幅を表し、程度の高まりとは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の程度や勢いが、次第に強くなったり大きくなったりすること。", "primary_collocate": null, "pronunciation": "たかまり", "ipa": "takamaɾi", "syllable_count": 4, "sentences": [{"text": "健康への関心の高まりで、運動用の靴がよく売れている。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "健康[けんこう]への関心[かんしん]の高[たか]まりで、運動用[うんどうよう]の靴[くつ]がよく売[う]れている。", "sentence_source": "generated"}, {"text": "夏になり、エアコンの需要の高まりで工場は休みなく動いた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "夏[なつ]になり、エアコンの需要[じゅよう]の高[たか]まりで工場[こうじょう]は休[やす]みなく動[うご]いた。", "sentence_source": "generated"}, {"text": "防災への意識の高まりを受け、学校で避難訓練が増えた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "防災[ぼうさい]への意識[いしき]の高[たか]まりを受[う]け、学校[がっこう]で避難[ひなん]訓練[くんれん]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "人気の高まりとともに、その店には毎日長い列ができる。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "人気[にんき]の高[たか]まりとともに、その店[みせ]には毎日[まいにち]長[なが]い列[れつ]ができる。", "sentence_source": "generated"}, {"text": "地震の可能性の高まりが伝えられ、備えをする家庭が増えた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "地震[じしん]の可能性[かのうせい]の高[たか]まりが伝[つた]えられ、備[そな]えをする家庭[かてい]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "台風の接近で、川の水位の高まりが心配されている。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "台風[たいふう]の接近[せっきん]で、川[かわ]の水位[すいい]の高[たか]まりが心配[しんぱい]されている。", "sentence_source": "generated"}, {"text": "物価の上昇で、節約を求める声の高まりが目立つ。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "物価[ぶっか]の上昇[じょうしょう]で、節約[せつやく]を求[もと]める声[こえ]の高[たか]まりが目立[めだ]つ。", "sentence_source": "generated"}, {"text": "英語教育への期待の高まりを背景に、新しい塾ができた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "英語[えいご]教育[きょういく]への期待[きたい]の高[たか]まりを背景[はいけい]に、新[あたら]しい塾[じゅく]ができた。", "sentence_source": "generated"}, {"text": "感染のリスクの高まりに備えて、病院は入り口を増やした。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "感染[かんせん]のリスクの高[たか]まりに備[そな]えて、病院[びょういん]は入[い]り口[ぐち]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "景気の回復とともに、消費の高まりが数字に表れてきた。", "target_word": "高まり", "complexity_tier": "T3", "furigana": "景気[けいき]の回復[かいふく]とともに、消費[しょうひ]の高[たか]まりが数字[すうじ]に表[あらわ]れてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高まり", "label": "基本形（動詞「高まる」の連用形名詞）"}, {"form": "高まりの", "label": "連体形（の）"}, {"form": "高まりが", "label": "主格（が）"}], "register": "標準（中立）", "sense_fingerprint": "需要・関心・水位・リスクなど物事の程度が次第に大きくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad4615db-e12b-407c-9b7f-20298e5e972d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高まり", "is_correct": true, "explanation": "「関心の高まり」は関心の程度が大きくなることを指し、運動用の靴がよく売れている理由として合う。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分が失われる状態を指し、「関心の乾燥で」は成り立たない。"}, {"text": "端切れ", "is_correct": false, "explanation": "端切れは布の余りを指し、「関心の端切れで」は意味をなさない。"}, {"text": "段差", "is_correct": false, "explanation": "段差は高低差を指し、「関心の段差で」は理由として成り立たない。"}], "explanations": {"高まり": "「関心の高まり」は関心の程度が大きくなることを指し、運動用の靴がよく売れている理由として合う。", "乾燥": "乾燥は水分が失われる状態を指し、「関心の乾燥で」は成り立たない。", "端切れ": "端切れは布の余りを指し、「関心の端切れで」は意味をなさない。", "段差": "段差は高低差を指し、「関心の段差で」は理由として成り立たない。"}, "sentence_index": 0, "correct_answer": "高まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祭りの準備で、資料の高まりを確認した。", "explanation": "ここは〈分量〉の意味。資料の量は〈分量〉で言い、〈高まり〉は気持ちや勢いの強まりに使うので合わない。"}, {"text": "土手の高まりに腰を下ろした。", "explanation": "ここは〈土手〉の意味。盛り上がった地形は〈土手〉で言い、程度や勢いが強まる〈高まり〉の意味にはならないので合わない。"}, {"text": "予定の高まりを数えた。", "explanation": "ここは〈件数〉の意味。予定の数は〈件数〉で言い、〈高まり〉は程度や勢いが次第に強くなることに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高まり", "is_correct": true, "explanation": "「節約を求める声の高まり」は、節約を求める声が次第に強まることを指し、目立つという文に合う。"}, {"text": "看板", "is_correct": false, "explanation": "看板は掲示物で、「声の看板が目立つ」は意味をなさない。"}, {"text": "窓枠", "is_correct": false, "explanation": "窓枠は建具の部材で、「声の窓枠が目立つ」は成り立たない。"}, {"text": "白髪", "is_correct": false, "explanation": "白髪は髪の色を表し、「声の白髪が目立つ」は不自然で合わない。"}], "explanations": {"高まり": "「節約を求める声の高まり」は、節約を求める声が次第に強まることを指し、目立つという文に合う。", "看板": "看板は掲示物で、「声の看板が目立つ」は意味をなさない。", "窓枠": "窓枠は建具の部材で、「声の窓枠が目立つ」は成り立たない。", "白髪": "白髪は髪の色を表し、「声の白髪が目立つ」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "高まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の高まりに花を植えた。", "explanation": "ここは〈築山〉の意味。庭の盛り土は〈築山〉で言い、程度や勢いの増大を表す〈高まり〉は使えないので合わない。"}, {"text": "山の高まりに登った。", "explanation": "ここは〈丘〉の意味。地形の盛り上がりは〈丘〉で言い、程度の増大を表す〈高まり〉は使えないので合わない。"}, {"text": "台所の高まりを磨いた。", "explanation": "台所は場所を表す語で、〈高まり〉は程度や勢いの増大を表すので、台所を磨く文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真夏になり、扇風機の需要の高まりを、工場は休みなく動いた。", "corrected_sentence": "真夏になり、扇風機の需要の高まりで、工場は休みなく動いた。", "error_description": "原因を表す「で」が正しいのに「を」になっている。「高まり」は動作の対象ではなく、動いた理由を示すので「で」で受ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38051, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "賃金の伸びとともに、消費の高まったが数字に表れてきた。", "corrected_sentence": "賃金の伸びとともに、消費の高まりが数字に表れてきた。", "error_description": "名詞の「高まり」が正しいのに動詞の連用形「高まっ」を使っている。文の主語になる名詞形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '689e4471-086f-4aac-905c-5c37734206ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『発達する』の主語を示す『が』。『工業が発達した』が自然な文。"}, {"text": "を", "is_correct": false, "explanation": "『発達する』は目的語を取らないので、『を』は誤り。"}, {"text": "に", "is_correct": false, "explanation": "帰着の『に』は『発達する』の主語にならないので、ここでは成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表すので、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "『発達する』の主語を示す『が』。『工業が発達した』が自然な文。", "を": "『発達する』は目的語を取らないので、『を』は誤り。", "に": "帰着の『に』は『発達する』の主語にならないので、ここでは成り立たない。", "と": "『と』は並列や相手を表すので、主語の位置には入らない。"}, "error_tags": {"を": "目的語の助詞", "に": "帰着の助詞", "と": "並列・相手の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『工業のおかげ』と名詞をつなぐ『の』。『工業のおかげで』が自然な文。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の『で』で、『工業で』と続けても『おかげ』に結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』で、名詞同士をつなぐ働きはない。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』で、『工業から』では『おかげ』と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "『工業のおかげ』と名詞をつなぐ『の』。『工業のおかげで』が自然な文。", "で": "手段や場所の『で』で、『工業で』と続けても『おかげ』に結びつかない。", "へ": "方向の『へ』で、名詞同士をつなぐ働きはない。", "から": "起点の『から』で、『工業から』では『おかげ』と結びつかない。"}, "error_tags": {"で": "手段・場所の助詞", "へ": "方向の助詞", "から": "起点の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをつくること。", "primary_collocate": null, "pronunciation": "こうぎょう", "ipa": "koːɡjoː", "syllable_count": 4, "sentences": [{"text": "弟は大学で工業を学び、ものづくりの仕事に就きたいと考えている。", "target_word": "工業", "complexity_tier": "T3", "furigana": "弟[おとうと]は大学[だいがく]で工業[こうぎょう]を学[まな]び、ものづくりの仕事[しごと]に就[つ]きたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "工業が発達したので、安い品物が多く作られるようになった。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]が発達[はったつ]したので、安[やす]い品物[しなもの]が多[おお]く作[つく]られるようになった。", "sentence_source": "generated"}, {"text": "この地方では昔から工業がさかんで、いろいろな道具が作られてきた。", "target_word": "工業", "complexity_tier": "T3", "furigana": "この地方[ちほう]では昔[むかし]から工業[こうぎょう]がさかんで、いろいろな道具[どうぐ]が作[つく]られてきた。", "sentence_source": "generated"}, {"text": "工業は人の手で物を作る仕事なので、細かい作業が得意な人に向いている。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]は人[ひと]の手[て]で物[もの]を作[つく]る仕事[しごと]なので、細[こま]かい作業[さぎょう]が得意[とくい]な人[ひと]に向[む]いている。", "sentence_source": "generated"}, {"text": "祖父は工業の仕事を長く続け、たくさんの部品を作った。", "target_word": "工業", "complexity_tier": "T3", "furigana": "祖父[そふ]は工業[こうぎょう]の仕事[しごと]を長[なが]く続[つづ]け、たくさんの部品[ぶひん]を作[つく]った。", "sentence_source": "generated"}, {"text": "工業が進むと、手作りの品は少しずつ減っていった。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]が進[すす]むと、手作[てづく]りの品[しな]は少[すこ]しずつ減[へ]っていった。", "sentence_source": "generated"}, {"text": "彼女は工業に興味があり、毎週工場を見学している。", "target_word": "工業", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は工業[こうぎょう]に興味[きょうみ]があり、毎週[まいしゅう]工場[こうじょう]を見学[けんがく]している。", "sentence_source": "generated"}, {"text": "工業のおかげで、私たちは便利な道具を買うことができる。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]のおかげで、私[わたし]たちは便利[べんり]な道具[どうぐ]を買[か]うことができる。", "sentence_source": "generated"}, {"text": "工業は物を作る仕事だが、農業は作物を育てる仕事だ。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]は物[もの]を作[つく]る仕事[しごと]だが、農業[のうぎょう]は作物[さくもつ]を育[そだ]てる仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "父は工業の知識が豊富で、壊れた機械もすぐに直してくれる。", "target_word": "工業", "complexity_tier": "T3", "furigana": "父[ちち]は工業[こうぎょう]の知識[ちしき]が豊富[ほうふ]で、壊[こわ]れた機械[きかい]もすぐに直[なお]してくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工業", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人の手や機械でものをつくる仕事・分野としての工業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工業", "is_correct": true, "explanation": "ものづくりの分野を指す語で、大学で学ぶ分野として文脈に合う。"}, {"text": "工場", "is_correct": false, "explanation": "ものをつくる建物を指す語。学ぶ対象の分野としては合わない。"}, {"text": "工具", "is_correct": false, "explanation": "作業に使う道具のこと。学問の対象にはならない。"}, {"text": "工員", "is_correct": false, "explanation": "工場で働く人を指す語で、学ぶ分野の名前ではない。"}], "explanations": {"工業": "ものづくりの分野を指す語で、大学で学ぶ分野として文脈に合う。", "工場": "ものをつくる建物を指す語。学ぶ対象の分野としては合わない。", "工具": "作業に使う道具のこと。学問の対象にはならない。", "工員": "工場で働く人を指す語で、学ぶ分野の名前ではない。"}, "sentence_index": 0, "correct_answer": "工業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工業の屋根が雨で壊れた。", "explanation": "ここは〈工場〉の意味。工業は『ものをつくること』や産業の分野を指し、建物ではないので屋根はない。"}, {"text": "完成した工業を港から海外へ出荷した。", "explanation": "ここは〈製品〉の意味。工業は作ることや分野を指し、出荷できる物ではない。"}, {"text": "この工業は三十年使っても故障しなかった。", "explanation": "ここは〈機械〉の意味。工業は機械そのものではないので、使ったり故障したりしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工業", "is_correct": true, "explanation": "『農業』と並ぶ産業分野の名前として、興味の対象に合う。"}, {"text": "倉庫", "is_correct": false, "explanation": "物を保管する建物を指す語で、興味の対象としては不自然。"}, {"text": "包装", "is_correct": false, "explanation": "商品を包むことを指す語で、興味の対象として文脈に合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類などを洗うことで、『に興味がある』の対象として意味が通らない。"}], "explanations": {"工業": "『農業』と並ぶ産業分野の名前として、興味の対象に合う。", "倉庫": "物を保管する建物を指す語で、興味の対象としては不自然。", "包装": "商品を包むことを指す語で、興味の対象として文脈に合わない。", "洗濯": "衣類などを洗うことで、『に興味がある』の対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "工業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工業は毎朝七時に会社の門で待ち合わせる。", "explanation": "ここは〈工員〉の意味。工業は人を指さないので、待ち合わせることはできない。"}, {"text": "今日の工業は一日中晴れるでしょう。", "explanation": "ここは〈天気〉の意味。工業は分野や活動の名前で、晴れることはない。"}, {"text": "工業は甘い味がする。", "explanation": "ここは〈砂糖〉の意味。工業は味を持たないので、甘いとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の工業を、新しい技術で大きく変わった。", "corrected_sentence": "この町の工業は、新しい技術で大きく変わった。", "error_description": "『工業』に続く助詞が『を』になっている。『変わる』の主語には『は』を使うので、正しくは『工業は』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38052, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町では工業が盛んなった。", "corrected_sentence": "この町では工業が盛んになった。", "error_description": "『盛んになった』の『に』が抜けて『盛んなった』になっている。形容動詞『盛んだ』は『盛んに』と活用するので、正しくは『盛んになった』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
