INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38053, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『工業の発展』と名詞をつなぐ『の』。『工業の発展は』が自然な文。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の『で』で、『工業で発展は』では名詞をつなげない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』で、名詞同士をつなぐ働きはない。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』で、『工業から発展』では名詞がつながらない。"}], "correct_answer": "の", "explanations": {"の": "『工業の発展』と名詞をつなぐ『の』。『工業の発展は』が自然な文。", "で": "手段や場所の『で』で、『工業で発展は』では名詞をつなげない。", "へ": "方向の『へ』で、名詞同士をつなぐ働きはない。", "から": "起点の『から』で、『工業から発展』では名詞がつながらない。"}, "error_tags": {"で": "手段・場所の助詞", "へ": "方向の助詞", "から": "起点の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38053, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "工業とは、原材料を加工して製品を生産する産業のこと。", "primary_collocate": null, "pronunciation": "こうぎょう", "ipa": "koːɡjoː", "syllable_count": 4, "sentences": [{"text": "この国は原料を輸入して加工する工業で発展してきた。", "target_word": "工業", "complexity_tier": "T3", "furigana": "この国[くに]は原料[げんりょう]を輸入[ゆにゅう]して加工[かこう]する工業[こうぎょう]で発展[はってん]してきた。", "sentence_source": "generated"}, {"text": "海に近い町では、重い荷物を運びやすいため工業が発達した。", "target_word": "工業", "complexity_tier": "T3", "furigana": "海[うみ]に近[ちか]い町[まち]では、重[おも]い荷物[にもつ]を運[はこ]びやすいため工業[こうぎょう]が発達[はったつ]した。", "sentence_source": "generated"}, {"text": "工業が盛んな地域では、工場から出る煙が問題になっている。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]が盛[さか]んな地域[ちいき]では、工場[こうじょう]から出[で]る煙[けむり]が問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "日本の工業は、自動車や電気製品の生産で世界に知られている。", "target_word": "工業", "complexity_tier": "T3", "furigana": "日本[にほん]の工業[こうぎょう]は、自動車[じどうしゃ]や電気製品[でんきせいひん]の生産[せいさん]で世界[せかい]に知[し]られている。", "sentence_source": "generated"}, {"text": "工業が成長すると、働く場所が増えて人口も多くなる。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]が成長[せいちょう]すると、働[はたら]く場所[ばしょ]が増[ふ]えて人口[じんこう]も多[おお]くなる。", "sentence_source": "generated"}, {"text": "政府は新しい工業を育てるために、工場の建設を支援した。", "target_word": "工業", "complexity_tier": "T3", "furigana": "政府[せいふ]は新[あたら]しい工業[こうぎょう]を育[そだ]てるために、工場[こうじょう]の建設[けんせつ]を支援[しえん]した。", "sentence_source": "generated"}, {"text": "農業と工業の両方がある県は、経済が安定しやすい。", "target_word": "工業", "complexity_tier": "T3", "furigana": "農業[のうぎょう]と工業[こうぎょう]の両方[りょうほう]がある県[けん]は、経済[けいざい]が安定[あんてい]しやすい。", "sentence_source": "generated"}, {"text": "工業の発展は便利な生活をもたらしたが、環境を汚すこともある。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]の発展[はってん]は便利[べんり]な生活[せいかつ]をもたらしたが、環境[かんきょう]を汚[よご]すこともある。", "sentence_source": "generated"}, {"text": "鉄を使った工業は、たくさんの水と電力を必要とする。", "target_word": "工業", "complexity_tier": "T3", "furigana": "鉄[てつ]を使[つか]った工業[こうぎょう]は、たくさんの水[みず]と電力[でんりょく]を必要[ひつよう]とする。", "sentence_source": "generated"}, {"text": "工業の現場では、使った水を何度もくり返し利用する。", "target_word": "工業", "complexity_tier": "T3", "furigana": "工業[こうぎょう]の現場[げんば]では、使[つか]った水[みず]を何度[なんど]もくり返[かえ]し利用[りよう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工業", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "原材料を加工して製品を大量に生産する産業としての工業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38053, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工業", "is_correct": true, "explanation": "原料を加工して製品を生産する産業の分野として、『加工する〜で発展した』に合う。"}, {"text": "包装", "is_correct": false, "explanation": "商品を包むことを指す語で、産業分野の名前としては合わない。"}, {"text": "倉庫", "is_correct": false, "explanation": "物を保管する建物で、加工の分野を表さないので合わない。"}, {"text": "工員", "is_correct": false, "explanation": "工場で働く人を指す語で、発展の場としては合わない。"}], "explanations": {"工業": "原料を加工して製品を生産する産業の分野として、『加工する〜で発展した』に合う。", "包装": "商品を包むことを指す語で、産業分野の名前としては合わない。", "倉庫": "物を保管する建物で、加工の分野を表さないので合わない。", "工員": "工場で働く人を指す語で、発展の場としては合わない。"}, "sentence_index": 0, "correct_answer": "工業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工業は海外から船で運ばれてくる。", "explanation": "ここは〈原料〉の意味。工業は産業の分野で、船で運ばれる物ではない。"}, {"text": "店には新しい工業が並んでいる。", "explanation": "ここは〈製品〉の意味。工業は産業の分野を指し、店に並ぶ品物ではない。"}, {"text": "工業が壊れて修理に三日かかった。", "explanation": "ここは〈機械〉の意味。工業は物ではないので、壊れて修理することはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38053, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工業", "is_correct": true, "explanation": "『農業』と並ぶ産業分野の名前として、文脈に合う。"}, {"text": "工具", "is_correct": false, "explanation": "作業に使う道具のことで、産業の分野を表さない。"}, {"text": "作業", "is_correct": false, "explanation": "仕事の一つ一つの動作を指す語で、分野名としては合わない。"}, {"text": "部品", "is_correct": false, "explanation": "機械を構成する部分で、農業と並ぶ分野ではない。"}], "explanations": {"工業": "『農業』と並ぶ産業分野の名前として、文脈に合う。", "工具": "作業に使う道具のことで、産業の分野を表さない。", "作業": "仕事の一つ一つの動作を指す語で、分野名としては合わない。", "部品": "機械を構成する部分で、農業と並ぶ分野ではない。"}, "sentence_index": 6, "correct_answer": "工業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の工業は確かで、どんな仕事も任される。", "explanation": "ここは〈腕前〉の意味。工業は技能ではなく、人の能力を表せない。"}, {"text": "明日の工業は雨が降るかもしれない。", "explanation": "ここは〈天気〉の意味。工業は分野の名で、雨が降ることはない。"}, {"text": "工業は子どもに読まれる。", "explanation": "ここは〈絵本〉の意味。工業は読み物ではないので、読まれることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38053, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工業を盛んになり、町の人口が増えた。", "corrected_sentence": "工業が盛んになり、町の人口が増えた。", "error_description": "『工業』に続く助詞が『を』になっている。『盛んになる』は主語に『が』を取るので、正しくは『工業が』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38053, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この国では、工業を働く人が増えた。", "corrected_sentence": "この国では、工業で働く人が増えた。", "error_description": "『働く』が場所・分野を示す『で』が『を』になっている。『工業で働く』が正しく、『を』では『働く』に目的語が付いて不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「減らす」は目的語を取る他動詞なので、「無駄遣いを」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「減らす」は他動詞で、目的語に「が」は使えない。「減る」（自動詞）なら「が」になる。"}, {"text": "に", "is_correct": false, "explanation": "「減らす」は「に」を目的語の印として取らないので、ここには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「減らす」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「減らす」は目的語を取る他動詞なので、「無駄遣いを」が正しい。", "が": "「減らす」は他動詞で、目的語に「が」は使えない。「減る」（自動詞）なら「が」になる。", "に": "「減らす」は「に」を目的語の印として取らないので、ここには合わない。", "へ": "「へ」は方向を表すので、「減らす」の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "節約", "is_correct": true, "explanation": "「節約」は、むだを省いて物やお金を大切に使うことで、「無駄遣い」の対義語。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は歩いて回ることで、「無駄遣い」の対義語ではない。"}, {"text": "家計", "is_correct": false, "explanation": "「家計」は家庭の収入と支出のことで、「無駄遣い」の対義語ではない。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行」は場所を移動して楽しむことで、「無駄遣い」の対義語ではない。"}], "correct_answer": "節約", "explanations": {"節約": "「節約」は、むだを省いて物やお金を大切に使うことで、「無駄遣い」の対義語。", "散歩": "「散歩」は歩いて回ることで、「無駄遣い」の対義語ではない。", "家計": "「家計」は家庭の収入と支出のことで、「無駄遣い」の対義語ではない。", "旅行": "「旅行」は場所を移動して楽しむことで、「無駄遣い」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多い」の主語（何が多いか）を示す「が」で、「無駄遣いが多い」となる。"}, {"text": "を", "is_correct": false, "explanation": "形容詞「多い」は目的語を取らないので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、ここでは「多い」の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表し、「多い」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「多い」の主語（何が多いか）を示す「が」で、「無駄遣いが多い」となる。", "を": "形容詞「多い」は目的語を取らないので、「を」は合わない。", "と": "「と」は並列や引用を表し、ここでは「多い」の主語にならない。", "で": "「で」は手段や場所を表し、「多い」の主語を示せない。"}, "error_tags": {"を": "目的語", "と": "並列・引用", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "節約", "is_correct": true, "explanation": "「節約」は、むだを省いて水などを大切に使うことで、「無駄遣い」の対義語。"}, {"text": "利益", "is_correct": false, "explanation": "「利益」は利潤のことで、「無駄遣い」の対義語ではない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書」は授業で使う本で、「無駄遣い」の対義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様のことで、「無駄遣い」の対義語ではない。"}], "correct_answer": "節約", "explanations": {"節約": "「節約」は、むだを省いて水などを大切に使うことで、「無駄遣い」の対義語。", "利益": "「利益」は利潤のことで、「無駄遣い」の対義語ではない。", "教科書": "「教科書」は授業で使う本で、「無駄遣い」の対義語ではない。", "天気": "「天気」は空模様のことで、「無駄遣い」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いらないものや、むだに使うこと。", "primary_collocate": null, "pronunciation": "むだづかい", "ipa": "mɯdadzɯkai", "syllable_count": 5, "sentences": [{"text": "お小遣いを無駄遣いしないで、貯金しましょう。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "お小遣[こづか]いを無駄遣[むだづか]いしないで、貯金[ちょきん]しましょう。", "sentence_source": "generated"}, {"text": "毎月の無駄遣いを減らしたら、旅行に行けるようになった。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "毎月[まいつき]の無駄遣[むだづか]いを減[へ]らしたら、旅行[りょこう]に行[い]けるようになった。", "sentence_source": "generated"}, {"text": "安いからといって、使わない物を買うのは無駄遣いだ。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "安[やす]いからといって、使[つか]わない物[もの]を買[か]うのは無駄遣[むだづか]いだ。", "sentence_source": "generated"}, {"text": "母は私の無駄遣いにいつも厳しい。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の無駄遣[むだづか]いにいつも厳[きび]しい。", "sentence_source": "generated"}, {"text": "ゲームに課金しすぎて、無駄遣いだったと後悔した。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "ゲームに課金[かきん]しすぎて、無駄遣[むだづか]いだったと後悔[こうかい]した。", "sentence_source": "generated"}, {"text": "電気をつけっぱなしにするのも無駄遣いだ。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "電気[でんき]をつけっぱなしにするのも無駄遣[むだづか]いだ。", "sentence_source": "generated"}, {"text": "家計簿をつけると、無駄遣いがすぐにわかる。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "家計簿[かけいぼ]をつけると、無駄遣[むだづか]いがすぐにわかる。", "sentence_source": "generated"}, {"text": "彼は無駄遣いが多いので、月末はいつもお金がない。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "彼[かれ]は無駄遣[むだづか]いが多[おお]いので、月末[げつまつ]はいつもお金[かね]がない。", "sentence_source": "generated"}, {"text": "必要のない服を買うと、結局無駄遣いになってしまう。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "必要[ひつよう]のない服[ふく]を買[か]うと、結局[けっきょく]無駄遣[むだづか]いになってしまう。", "sentence_source": "generated"}, {"text": "水の無駄遣いをやめようと、学校で呼びかけた。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "水[みず]の無駄遣[むだづか]いをやめようと、学校[がっこう]で呼[よ]びかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無駄遣い", "label": "基本形"}, {"form": "無駄遣いする", "label": "サ変動詞形"}, {"form": "無駄遣いだ", "label": "断定形"}], "register": "標準", "sense_fingerprint": "不要な物やお金をむだに使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無駄遣い", "is_correct": true, "explanation": "「無駄遣いしないで」は、必要のないことにお金を使わない、という意味になり、文脈に合う。"}, {"text": "財布", "is_correct": false, "explanation": "「お小遣いを財布しないで」とは言えない。財布は物入れの名詞で、「する」を続けられない。"}, {"text": "小銭", "is_correct": false, "explanation": "小銭は硬貨のことで、「小銭しないで」の形では意味が通らない。"}, {"text": "通帳", "is_correct": false, "explanation": "通帳は預金の記録を書いた帳面で、「通帳しないで」は動作として成り立たない。"}], "explanations": {"無駄遣い": "「無駄遣いしないで」は、必要のないことにお金を使わない、という意味になり、文脈に合う。", "財布": "「お小遣いを財布しないで」とは言えない。財布は物入れの名詞で、「する」を続けられない。", "小銭": "小銭は硬貨のことで、「小銭しないで」の形では意味が通らない。", "通帳": "通帳は預金の記録を書いた帳面で、「通帳しないで」は動作として成り立たない。"}, "sentence_index": 0, "correct_answer": "無駄遣い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお店では、無駄遣いを一つ百円で限定販売している。", "explanation": "「無駄遣い」は物をむだに使う行為を表す名詞で、商品として売るものにはならない。ここでは〈商品〉の意味としては使えない。"}, {"text": "うちの会社は、新しい無駄遣いを三人採用した。", "explanation": "ここは〈人材〉の意味。無駄遣いは行為を表す名詞で、人を採用する文脈には使えない。"}, {"text": "来月の無駄遣いを決めて、家計の計画を立てた。", "explanation": "ここは〈予算〉の意味。無駄遣いは必要のない出費を表すので、計画の上限として決める予算の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無駄遣い", "is_correct": true, "explanation": "「無駄遣いがすぐにわかる」は、家計簿で使いすぎたお金が把握できる、という意味で合う。"}, {"text": "領収書", "is_correct": false, "explanation": "領収書は支払いの証明書で、「領収書がすぐにわかる」は文として意味が通らない。"}, {"text": "割引券", "is_correct": false, "explanation": "割引券は値引きに使う券で、「割引券がすぐにわかる」は意味が通らない。"}, {"text": "札束", "is_correct": false, "explanation": "札束は紙幣をまとめたもので、「札束がすぐにわかる」は文の内容に合わない。"}], "explanations": {"無駄遣い": "「無駄遣いがすぐにわかる」は、家計簿で使いすぎたお金が把握できる、という意味で合う。", "領収書": "領収書は支払いの証明書で、「領収書がすぐにわかる」は文として意味が通らない。", "割引券": "割引券は値引きに使う券で、「割引券がすぐにわかる」は意味が通らない。", "札束": "札束は紙幣をまとめたもので、「札束がすぐにわかる」は文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "無駄遣い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、通勤に無駄遣いを使って電車に乗っている。", "explanation": "「無駄遣い」は行為を表す名詞で、乗り物のように使うものではない。"}, {"text": "庭に無駄遣いを植えて、花を楽しんだ。", "explanation": "ここは〈植物〉の意味。無駄遣いは行為を表す名詞で、庭に植えるものにはならない。"}, {"text": "彼は古い服を無駄遣いの店に売って、お金を作った。", "explanation": "ここは〈古着屋〉の意味。無駄遣いは行為を表す名詞で、店の名前や場所にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は無駄遣いを多いので、いつも給料が足りない。", "corrected_sentence": "兄は無駄遣いが多いので、いつも給料が足りない。", "error_description": "「多い」は形容詞で、その主語は「が」で示す。「無駄遣いを多い」は助詞が合わない。正しくは「無駄遣いが多い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゲームの課金を見直して、無駄遣いを気づいた。", "corrected_sentence": "ゲームの課金を見直して、無駄遣いに気づいた。", "error_description": "「気づく」は「〜に気づく」と言うので、「無駄遣いを」は誤り。正しくは「無駄遣いに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
