INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38055, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「防ぐ」は目的語を取る他動詞なので、「無駄遣いを防ぐ」となる。"}, {"text": "が", "is_correct": false, "explanation": "「無駄遣いが防ぐ」では、無駄遣いが防ぐ主体になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「防ぐ」は「に」を目的語の印として取らないので、ここには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「防ぐ」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「防ぐ」は目的語を取る他動詞なので、「無駄遣いを防ぐ」となる。", "が": "「無駄遣いが防ぐ」では、無駄遣いが防ぐ主体になり不自然。", "に": "「防ぐ」は「に」を目的語の印として取らないので、ここには合わない。", "へ": "「へ」は方向を表すので、「防ぐ」の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "節約", "is_correct": true, "explanation": "「節約」は、むだを省いてお金を大切に使うことで、「無駄遣い」の対義語。"}, {"text": "利益", "is_correct": false, "explanation": "「利益」は利潤のことで、「無駄遣い」の対義語ではない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書」は授業で使う本で、「無駄遣い」の対義語ではない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温」は体の温度のことで、「無駄遣い」の対義語ではない。"}], "correct_answer": "節約", "explanations": {"節約": "「節約」は、むだを省いてお金を大切に使うことで、「無駄遣い」の対義語。", "利益": "「利益」は利潤のことで、「無駄遣い」の対義語ではない。", "教科書": "「教科書」は授業で使う本で、「無駄遣い」の対義語ではない。", "体温": "「体温」は体の温度のことで、「無駄遣い」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38055, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要がないのに、お金や時間、物などをむだに使うこと。", "primary_collocate": null, "pronunciation": "むだづかい", "ipa": "mɯdadzɯkai", "syllable_count": 5, "sentences": [{"text": "会議が長すぎて、時間の無駄遣いだと感じた。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "会議[かいぎ]が長[なが]すぎて、時間[じかん]の無駄遣[むだづか]いだと感[かん]じた。", "sentence_source": "generated"}, {"text": "使わない道具をそろえたのは無駄遣いだった。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "使[つか]わない道具[どうぐ]をそろえたのは無駄遣[むだづか]いだった。", "sentence_source": "generated"}, {"text": "紙を無駄遣いしないように、両面に印刷する。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "紙[かみ]を無駄遣[むだづか]いしないように、両面[りょうめん]に印刷[いんさつ]する。", "sentence_source": "generated"}, {"text": "兄は無駄遣いをして、給料をすぐ使ってしまう。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "兄[あに]は無駄遣[むだづか]いをして、給料[きゅうりょう]をすぐ使[つか]ってしまう。", "sentence_source": "generated"}, {"text": "セールで買いすぎると、無駄遣いにつながる。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "セールで買[か]いすぎると、無駄遣[むだづか]いにつながる。", "sentence_source": "generated"}, {"text": "無駄遣いをやめた結果、貯金が増えた。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "無駄遣[むだづか]いをやめた結果[けっか]、貯金[ちょきん]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "食べきれないほど注文するのは、食べ物の無駄遣いだ。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "食[た]べきれないほど注文[ちゅうもん]するのは、食[た]べ物[もの]の無駄遣[むだづか]いだ。", "sentence_source": "generated"}, {"text": "彼女は無駄遣いを防ぐために、買い物リストを作っている。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は無駄遣[むだづか]いを防[ふせ]ぐために、買[か]い物[もの]リストを作[つく]っている。", "sentence_source": "generated"}, {"text": "いつも無駄遣いばかりしていると、将来困るよ。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "いつも無駄遣[むだづか]いばかりしていると、将来[しょうらい]困[こま]るよ。", "sentence_source": "generated"}, {"text": "国のお金の無駄遣いは、ニュースでもよく問題になる。", "target_word": "無駄遣い", "complexity_tier": "T3", "furigana": "国[くに]のお金[かね]の無駄遣[むだづか]いは、ニュースでもよく問題[もんだい]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無駄遣い", "label": "基本形"}, {"form": "無駄遣いする", "label": "サ変動詞形"}, {"form": "無駄遣いだ", "label": "断定形"}], "register": "標準", "sense_fingerprint": "必要がないのにお金・時間・物をむだに使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38055, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無駄遣い", "is_correct": true, "explanation": "「時間の無駄遣い」は、時間をむだに使うことで、文脈に合う。"}, {"text": "教室", "is_correct": false, "explanation": "「教室」は授業をする部屋で、「時間の教室」は意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙」は文書で、「時間の手紙」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様のことで、「時間の天気」は文の内容に合わない。"}], "explanations": {"無駄遣い": "「時間の無駄遣い」は、時間をむだに使うことで、文脈に合う。", "教室": "「教室」は授業をする部屋で、「時間の教室」は意味が通らない。", "手紙": "「手紙」は文書で、「時間の手紙」は成り立たない。", "天気": "「天気」は空模様のことで、「時間の天気」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "無駄遣い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前に新しい無駄遣いを開いた。", "explanation": "「無駄遣い」は行為を表す名詞で、店のように開くものではない。"}, {"text": "庭で無駄遣いを飼って、卵を集めた。", "explanation": "ここは〈鳥〉の意味。無駄遣いは行為を表す名詞で、動物として飼うことはできない。"}, {"text": "彼は去年、無駄遣いにかかって入院した。", "explanation": "ここは〈病気〉の意味。無駄遣いは行為を表す名詞で、人がかかって病気になるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38055, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無駄遣い", "is_correct": true, "explanation": "「食べ物の無駄遣い」は、食べ物をむだに使うことで、文の内容に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行」は移動して楽しむことで、「食べ物の旅行」は意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は眠くなる感覚で、「食べ物の眠気」は成り立たない。"}, {"text": "座席", "is_correct": false, "explanation": "「座席」は座る場所で、「食べ物の座席」は意味が通らない。"}], "explanations": {"無駄遣い": "「食べ物の無駄遣い」は、食べ物をむだに使うことで、文の内容に合う。", "旅行": "「旅行」は移動して楽しむことで、「食べ物の旅行」は意味が通らない。", "眠気": "「眠気」は眠くなる感覚で、「食べ物の眠気」は成り立たない。", "座席": "「座席」は座る場所で、「食べ物の座席」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "無駄遣い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この銀行では、無駄遣いの口座を作ることができる。", "explanation": "「無駄遣い」は行為の名詞で、口座の名称にはならない。"}, {"text": "余った布を、無駄遣いという素材にしてぬいぐるみを作った。", "explanation": "ここは〈材料〉の意味。無駄遣いは行為を表す名詞で、物の材料にはならない。"}, {"text": "この選手は、無駄遣いのスピードでゴールを決めた。", "explanation": "「無駄遣い」は速さを表さないので、速さの程度を述べる言葉としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
