INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38055, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は無駄遣いの防ぐために、毎月の支出を書き出した。", "corrected_sentence": "彼女は無駄遣いを防ぐために、毎月の支出を書き出した。", "error_description": "「防ぐ」の目的語には「を」を使う。「無駄遣いの防ぐ」は助詞が合わない。正しくは「無駄遣いを防ぐ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
