INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38056, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "もう、そうなってしまったら、変えられないことを表す言葉です。", "primary_collocate": null, "pronunciation": "もはや", "ipa": "mohaja", "syllable_count": 3, "sentences": [{"text": "最早、今から走っても電車には間に合わない。", "target_word": "最早", "complexity_tier": "T3", "furigana": "最早[もはや]、今[いま]から走[はし]っても電車[でんしゃ]には間[ま]に合[あ]わない。", "sentence_source": "generated"}, {"text": "病気は最早、薬では治らないところまで進んでいた。", "target_word": "最早", "complexity_tier": "T3", "furigana": "病気[びょうき]は最早[もはや]、薬[くすり]では治[なお]らないところまで進[すす]んでいた。", "sentence_source": "generated"}, {"text": "約束の時間を過ぎたので、最早彼は来ないだろう。", "target_word": "最早", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]を過[す]ぎたので、最早[もはや]彼[かれ]は来[こ]ないだろう。", "sentence_source": "generated"}, {"text": "町の古い店は閉まり、最早昔の面影はない。", "target_word": "最早", "complexity_tier": "T3", "furigana": "町[まち]の古[ふる]い店[みせ]は閉[し]まり、最早[もはや]昔[むかし]の面影[おもかげ]はない。", "sentence_source": "generated"}, {"text": "計画は最早、止められない段階に入っている。", "target_word": "最早", "complexity_tier": "T3", "furigana": "計画[けいかく]は最早[もはや]、止[と]められない段階[だんかい]に入[はい]っている。", "sentence_source": "generated"}, {"text": "彼の気持ちは最早変わらないと、みんな分かっていた。", "target_word": "最早", "complexity_tier": "T3", "furigana": "彼[かれ]の気持[きも]ちは最早[もはや]変[か]わらないと、みんな分[わ]かっていた。", "sentence_source": "generated"}, {"text": "最早、言い訳をしても遅い。", "target_word": "最早", "complexity_tier": "T3", "furigana": "最早[もはや]、言[い]い訳[わけ]をしても遅[おそ]い。", "sentence_source": "generated"}, {"text": "川の水があふれ、最早この道は通れなくなった。", "target_word": "最早", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]があふれ、最早[もはや]この道[みち]は通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "最早これまでだと思い、彼は試合をあきらめた。", "target_word": "最早", "complexity_tier": "T3", "furigana": "最早[もはや]これまでだと思[おも]い、彼[かれ]は試合[しあい]をあきらめた。", "sentence_source": "generated"}, {"text": "工事がここまで進んでは、最早計画を取りやめることはできない。", "target_word": "最早", "complexity_tier": "T3", "furigana": "工事[こうじ]がここまで進[すす]んでは、最早[もはや]計画[けいかく]を取[と]りやめることはできない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最早", "label": "基本形"}], "register": "formal", "sense_fingerprint": "状況がすでに進み、今さら変えられないことを表す副詞（もはや）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38056, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最早", "is_correct": true, "explanation": "もう今さら変えられないという意味の副詞で、文頭の『〜、今から走っても』の文脈に合う。"}, {"text": "偶然", "is_correct": false, "explanation": "たまたまを表す語で、状況が変えられないことを示せない。"}, {"text": "常に", "is_correct": false, "explanation": "いつも、という意味で、ここでは文脈に合わない。"}, {"text": "静かに", "is_correct": false, "explanation": "声や動きの様子を表すので、時間の状況には合わない。"}], "explanations": {"最早": "もう今さら変えられないという意味の副詞で、文頭の『〜、今から走っても』の文脈に合う。", "偶然": "たまたまを表す語で、状況が変えられないことを示せない。", "常に": "いつも、という意味で、ここでは文脈に合わない。", "静かに": "声や動きの様子を表すので、時間の状況には合わない。"}, "sentence_index": 0, "correct_answer": "最早"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最早時間があるから、落ち着いて準備しよう。", "explanation": "ここは〈まだ〉の意味。最早は取り返しがつかない状態に使うので、時間に余裕がある文脈と矛盾する。"}, {"text": "最早、来週の旅行の準備を始めよう。", "explanation": "ここは〈今から〉の意味。最早は取り返しがつかない時点に使うので、これから準備を始める提案とは合わない。"}, {"text": "最早、早く来てください。", "explanation": "ここは〈もう〉（急かす『もう』）の意味。最早は取り返しがつかない状態に使うので、急かす命令には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38056, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最早", "is_correct": true, "explanation": "もう手遅れだという意味で、文頭に置いて『言い訳をしても遅い』に続けられる。"}, {"text": "丁寧に", "is_correct": false, "explanation": "ていねいに行う様子を表すので、ここでは意味が通らない。"}, {"text": "大きく", "is_correct": false, "explanation": "程度や大きさを表すので、文脈に合わない。"}, {"text": "軽く", "is_correct": false, "explanation": "程度が軽い様子を表すので、文脈に合わない。"}], "explanations": {"最早": "もう手遅れだという意味で、文頭に置いて『言い訳をしても遅い』に続けられる。", "丁寧に": "ていねいに行う様子を表すので、ここでは意味が通らない。", "大きく": "程度や大きさを表すので、文脈に合わない。", "軽く": "程度が軽い様子を表すので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "最早"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最早、やり直しはいくらでもできる。", "explanation": "ここは〈まだ取り返せる〉の意味。最早は取り返しがつかない時点に使うので、『いくらでもやり直せる』と続けると矛盾する。"}, {"text": "来月の旅行は最早、これから相談する段階だ。", "explanation": "ここは〈これから〉（これから始める段階）の意味。最早は取り返しがつかない時点に使うので、これから相談を始める段階とは合わない。"}, {"text": "最早、今からでも遅くない。", "explanation": "ここは〈まだ間に合う〉の意味。最早は手遅れの時点に使うので、『今からでも遅くない』と続けると矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38056, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最早、言い訳は通用するしない。", "corrected_sentence": "最早、言い訳は通用しない。", "error_description": "『通用する』と『しない』が重なっている。『通用しない』と一つにまとめる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38056, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最早、ここまで来たら戻れなく。", "corrected_sentence": "最早、ここまで来たら戻れない。", "error_description": "『戻れない』の語尾が『戻れなく』で止まっている。『戻れなく』では文末で言い切れず、『最早』の結びには『戻れない』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す『で』。『色で表現する』は色を使って表すという意味。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ『の』では『表現している』と続かず、非文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』にすると手段の意味が消え、『色を表現する』は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』で、ここでは成り立たない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す『で』。『色で表現する』は色を使って表すという意味。", "の": "名詞をつなぐ『の』では『表現している』と続かず、非文になる。", "を": "目的語の『を』にすると手段の意味が消え、『色を表現する』は不自然。", "へ": "方向の『へ』で、ここでは成り立たない。"}, "error_tags": {"の": "連体修飾の助詞", "を": "目的語の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『表現』と『一つ』をつなぐ『の』。『表現の一つだ』が自然な文。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』で、名詞同士をつなぐ働きはない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す『と』で、『表現と一つだ』は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』で、名詞をつなげない。"}], "correct_answer": "の", "explanations": {"の": "『表現』と『一つ』をつなぐ『の』。『表現の一つだ』が自然な文。", "から": "起点の『から』で、名詞同士をつなぐ働きはない。", "と": "並列や相手を表す『と』で、『表現と一つだ』は成り立たない。", "より": "比較の『より』で、名詞をつなげない。"}, "error_tags": {"から": "起点の助詞", "と": "並列・相手の助詞", "より": "比較の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "心の中や考えを、絵や言葉などで外に出すこと。", "primary_collocate": null, "pronunciation": "ひょうげん", "ipa": "çjoːɡeɴ", "syllable_count": 4, "sentences": [{"text": "自分の気持ちを言葉で表現するのは難しい。", "target_word": "表現", "complexity_tier": "T3", "furigana": "自分[じぶん]の気持[きも]ちを言葉[ことば]で表現[ひょうげん]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "この絵は、悲しみを色で表現している。", "target_word": "表現", "complexity_tier": "T3", "furigana": "この絵[え]は、悲[かな]しみを色[いろ]で表現[ひょうげん]している。", "sentence_source": "generated"}, {"text": "彼女の表現は豊かで、読む人の心に残る。", "target_word": "表現", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の表現[ひょうげん]は豊[ゆた]かで、読[よ]む人[ひと]の心[こころ]に残[のこ]る。", "sentence_source": "generated"}, {"text": "彼は季節の移ろいを、絵と音楽で表現した。", "target_word": "表現", "complexity_tier": "T3", "furigana": "彼[かれ]は季節[きせつ]の移[うつ]ろいを、絵[え]と音楽[おんがく]で表現[ひょうげん]した。", "sentence_source": "generated"}, {"text": "子どもたちは、ダンスで自由に表現することを楽しんだ。", "target_word": "表現", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ダンスで自由[じゆう]に表現[ひょうげん]することを楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "相手を傷つけないように、怒りの気持ちを穏やかに表現した。", "target_word": "表現", "complexity_tier": "T3", "furigana": "相手[あいて]を傷[きず]つけないように、怒[いか]りの気持[きも]ちを穏[おだ]やかに表現[ひょうげん]した。", "sentence_source": "generated"}, {"text": "作文では、自分の考えをはっきり表現することが大切だ。", "target_word": "表現", "complexity_tier": "T3", "furigana": "作文[さくぶん]では、自分[じぶん]の考[かんが]えをはっきり表現[ひょうげん]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "歌は、言葉で言えない思いを伝える表現の一つだ。", "target_word": "表現", "complexity_tier": "T3", "furigana": "歌[うた]は、言葉[ことば]で言[い]えない思[おも]いを伝[つた]える表現[ひょうげん]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "彼は感動を、笑顔と拍手で表現した。", "target_word": "表現", "complexity_tier": "T3", "furigana": "彼[かれ]は感動[かんどう]を、笑顔[えがお]と拍手[はくしゅ]で表現[ひょうげん]した。", "sentence_source": "generated"}, {"text": "同じ喜びでも、笑顔で表現すると周りの人に伝わりやすくなる。", "target_word": "表現", "complexity_tier": "T3", "furigana": "同[おな]じ喜[よろこ]びでも、笑顔[えがお]で表現[ひょうげん]すると周[まわ]りの人[ひと]に伝[つた]わりやすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表現", "label": "基本形"}, {"form": "表現する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "気持ちや考えを言葉・絵・動作などで外に表すこと、またその言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表現", "is_correct": true, "explanation": "気持ちを言葉で外に出すという意味で、『言葉で〜するのは難しい』に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "楽器などで音楽を奏でることで、言葉で行うものではない。"}, {"text": "計算", "is_correct": false, "explanation": "数を求めることで、気持ちを言葉で行うものではない。"}, {"text": "散歩", "is_correct": false, "explanation": "町などを歩くことで、言葉で行う文脈には合わない。"}], "explanations": {"表現": "気持ちを言葉で外に出すという意味で、『言葉で〜するのは難しい』に合う。", "演奏": "楽器などで音楽を奏でることで、言葉で行うものではない。", "計算": "数を求めることで、気持ちを言葉で行うものではない。", "散歩": "町などを歩くことで、言葉で行う文脈には合わない。"}, "sentence_index": 0, "correct_answer": "表現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この机の表現に傷がついた。", "explanation": "ここは〈表面〉の意味。表現は気持ちや考えを外に出す語で、机の表面を指すことはない。"}, {"text": "玄関に表現を掲げた。", "explanation": "ここは〈表札〉の意味。表現は形のある物ではないので、掲げることはできない。"}, {"text": "本の表現を破いた。", "explanation": "ここは〈表紙〉の意味。表現は本の外側の部分ではないので、破くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表現", "is_correct": true, "explanation": "考えを言葉で外に出すという意味で、『はっきり〜することが大切だ』に合う。"}, {"text": "解体", "is_correct": false, "explanation": "組み立てたものを分けることで、考えには使わない。"}, {"text": "運搬", "is_correct": false, "explanation": "物を運ぶことで、考えを対象にしない。"}, {"text": "調理", "is_correct": false, "explanation": "料理を作ることで、考えには使わない。"}], "explanations": {"表現": "考えを言葉で外に出すという意味で、『はっきり〜することが大切だ』に合う。", "解体": "組み立てたものを分けることで、考えには使わない。", "運搬": "物を運ぶことで、考えを対象にしない。", "調理": "料理を作ることで、考えには使わない。"}, "sentence_index": 6, "correct_answer": "表現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪を表現した。", "explanation": "ここは〈風邪を引く〉の意味。表現は気持ちや考えを外に出す語で、病気には使わない。"}, {"text": "駅で表現を買った。", "explanation": "ここは〈切符〉の意味。表現は売り買いできる物ではない。"}, {"text": "電話を表現した。", "explanation": "ここは〈かける〉の意味。電話は気持ちを表すものではないので、表現の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは絵で気持ちを表現しした。", "corrected_sentence": "子どもたちは絵で気持ちを表現した。", "error_description": "『表現した』が『表現しした』になっている。『する』の過去形は『した』で、『し』が余分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38058, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この絵は表現を豊かで、見る人の心に残る。", "corrected_sentence": "この絵は表現が豊かで、見る人の心に残る。", "error_description": "『表現』に続く助詞が『を』になっている。『豊かだ』の主語には『が』を使うので、正しくは『表現が』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。『平和のシンボルとして使われています』の『として』で、シンボルを役割として示す"}, {"text": "で", "is_correct": false, "explanation": "『シンボルでして』となり、後の『使われています』とつながらず文が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、『平和のシンボルへして』は意味が通らない"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞なので、『平和のシンボルのして使われています』は文が成り立たない"}], "correct_answer": "と", "explanations": {"と": "正解。『平和のシンボルとして使われています』の『として』で、シンボルを役割として示す", "で": "『シンボルでして』となり、後の『使われています』とつながらず文が成り立たない", "へ": "『へ』は方向を表すので、『平和のシンボルへして』は意味が通らない", "の": "『の』は名詞をつなぐ助詞なので、『平和のシンボルのして使われています』は文が成り立たない"}, "error_tags": {"で": "手段", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。『男女のシンボルをつけた』で、つける対象を示す"}, {"text": "が", "is_correct": false, "explanation": "『男女のシンボルがつけた』ではシンボルが主語になり、誰がつけたのか分からず不自然"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すので、『男女のシンボルからつけた』は意味が通らない"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すので、『男女のシンボルよりつけた』は文が成り立たない"}], "correct_answer": "を", "explanations": {"を": "正解。『男女のシンボルをつけた』で、つける対象を示す", "が": "『男女のシンボルがつけた』ではシンボルが主語になり、誰がつけたのか分からず不自然", "から": "『から』は起点を示すので、『男女のシンボルからつけた』は意味が通らない", "より": "『より』は比較を示すので、『男女のシンボルよりつけた』は文が成り立たない"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの形や絵を使って、何かを表したものです。", "primary_collocate": null, "pronunciation": "しんぼる", "ipa": "ɕimboɾɯ", "syllable_count": 4, "sentences": [{"text": "ハートの形は、愛を表すシンボルです。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "ハートの形[かたち]は、愛[あい]を表[あらわ]すシンボルです。", "sentence_source": "generated"}, {"text": "鳩の絵は、平和のシンボルとして使われています。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "鳩[はと]の絵[え]は、平和[へいわ]のシンボルとして使[つか]われています。", "sentence_source": "generated"}, {"text": "白地に赤い丸は、日本のシンボルとして知られています。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "白地[しろじ]に赤[あか]い丸[まる]は、日本[にほん]のシンボルとして知[し]られています。", "sentence_source": "generated"}, {"text": "地図の中の飛行機の絵は、空港のシンボルです。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "地図[ちず]の中[なか]の飛行機[ひこうき]の絵[え]は、空港[くうこう]のシンボルです。", "sentence_source": "generated"}, {"text": "非常口のドアには、走る人のシンボルがかいてあります。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "非常口[ひじょうぐち]のドアには、走[はし]る人[ひと]のシンボルがかいてあります。", "sentence_source": "generated"}, {"text": "王冠の絵は、王様のシンボルになることが多い。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "王冠[おうかん]の絵[え]は、王様[おうさま]のシンボルになることが多[おお]い。", "sentence_source": "generated"}, {"text": "私たちのチームは、くまの絵をシンボルにしました。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "私[わたし]たちのチームは、くまの絵[え]をシンボルにしました。", "sentence_source": "generated"}, {"text": "子どもにも分かるように、トイレのドアに男女のシンボルをつけた。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "子[こ]どもにも分[わ]かるように、トイレのドアに男女[だんじょ]のシンボルをつけた。", "sentence_source": "generated"}, {"text": "十字の形は、病院を表すシンボルとして使われることがある。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "十字[じゅうじ]の形[かたち]は、病院[びょういん]を表[あらわ]すシンボルとして使[つか]われることがある。", "sentence_source": "generated"}, {"text": "言葉が通じない旅行先でも、シンボルを見ればトイレの場所が分かる。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "言葉[ことば]が通[つう]じない旅行先[りょこうさき]でも、シンボルを見[み]ればトイレの場所[ばしょ]が分[わ]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シンボル", "label": "基本形"}, {"form": "シンボルを", "label": "を格"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "形や絵で何かの意味を表した印", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シンボル", "is_correct": true, "explanation": "正解。『愛を表すシンボルです』で、形や絵で何かを表したものを指す"}, {"text": "天気", "is_correct": false, "explanation": "天気は形や絵で何かを表すものではないので、『愛を表す天気です』は意味が通らない"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は形や絵で表すものではないので、『愛を表す教科書です』は成り立たない"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は何かを表す印ではないので、『愛を表す冷蔵庫です』は文が成り立たない"}], "explanations": {"シンボル": "正解。『愛を表すシンボルです』で、形や絵で何かを表したものを指す", "天気": "天気は形や絵で何かを表すものではないので、『愛を表す天気です』は意味が通らない", "教科書": "教科書は形や絵で表すものではないので、『愛を表す教科書です』は成り立たない", "冷蔵庫": "冷蔵庫は何かを表す印ではないので、『愛を表す冷蔵庫です』は文が成り立たない"}, "sentence_index": 0, "correct_answer": "シンボル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お腹が痛いので、シンボルを飲んで寝た。", "explanation": "ここは〈薬〉の意味。薬は飲んで使うものだが、シンボルは形や絵で何かを表すものなので飲むことはできない。"}, {"text": "旅行のシンボルには、家族の笑顔がたくさん写っている。", "explanation": "ここは〈写真〉の意味。写真は人や風景を写したものだが、シンボルは形や絵で何かを表すものなので、笑顔が写るという文には合わない"}, {"text": "事務所のドアを、シンボルで開けた。", "explanation": "ここは〈鍵〉の意味。鍵はドアを開ける道具だが、シンボルは形や絵で何かを表すものなので、ドアを開けるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シンボル", "is_correct": true, "explanation": "正解。『くまの絵をシンボルにしました』で、絵を何かを表す印として使ったという意味になる"}, {"text": "野球", "is_correct": false, "explanation": "『くまの絵を野球にしました』では絵を野球に変えたことになり、チームの話として成り立たない"}, {"text": "辞書", "is_correct": false, "explanation": "『くまの絵を辞書にしました』は絵を辞書に変えることになり、印として使ったという意味にならない"}, {"text": "電車", "is_correct": false, "explanation": "『くまの絵を電車にしました』は意味が通らない"}], "explanations": {"シンボル": "正解。『くまの絵をシンボルにしました』で、絵を何かを表す印として使ったという意味になる", "野球": "『くまの絵を野球にしました』では絵を野球に変えたことになり、チームの話として成り立たない", "辞書": "『くまの絵を辞書にしました』は絵を辞書に変えることになり、印として使ったという意味にならない", "電車": "『くまの絵を電車にしました』は意味が通らない"}, "sentence_index": 6, "correct_answer": "シンボル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先から送ったシンボルには、景色の写真が印刷されている。", "explanation": "ここは〈絵はがき〉の意味。絵はがきは写真を印刷した紙だが、シンボルは意味を示す形や絵なので、写真が印刷されているという文には合わない"}, {"text": "胸につけるシンボルには、名前が書いてある。", "explanation": "ここは〈名札〉の意味。名前を書いて身につける物を指すので、何かを表す形や絵のシンボルには合わない"}, {"text": "彼女は毎朝、シンボルを焼いて朝食にしている。", "explanation": "ここは〈パン〉の意味。パンは焼いて食べる食品だが、シンボルは形や絵で何かを表すものなので、焼いて食べる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その絵は、地域のシンボルがなっている。", "corrected_sentence": "その絵は、地域のシンボルになっている。", "error_description": "誤りは『に』が『が』になっていること。『〜になる』は『に』を使うので、正しい形は『シンボルになっている』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38060, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その星の形は、夢のシンボルを知られている。", "corrected_sentence": "その星の形は、夢のシンボルとして知られている。", "error_description": "誤りは『として知られている』の『として』が『を』になっていること。『シンボルを知られている』は文が成り立たない", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。『太陽のシンボルが晴れを意味する』で、シンボルが主語になる"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や向かう先を示すので、『太陽のシンボルに晴れを意味する』は成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、『太陽のシンボルへ晴れを意味する』は意味が通らない"}, {"text": "と", "is_correct": false, "explanation": "『と』は並べる働きで、『太陽のシンボルと晴れを意味する』は文の構造が合わず不自然"}], "correct_answer": "が", "explanations": {"が": "正解。『太陽のシンボルが晴れを意味する』で、シンボルが主語になる", "に": "『に』は相手や向かう先を示すので、『太陽のシンボルに晴れを意味する』は成り立たない", "へ": "『へ』は方向を表すので、『太陽のシンボルへ晴れを意味する』は意味が通らない", "と": "『と』は並べる働きで、『太陽のシンボルと晴れを意味する』は文の構造が合わず不自然"}, "error_tags": {"に": "相手・方向", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。『シンボルを使えば』で、使う対象を示す"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐので、『シンボルの使えば』は動詞の目的語が欠けて文が成り立たない"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すので、『シンボルから使えば』は不自然で意味が通らない"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すので、『シンボルより使えば』は文が成り立たない"}], "correct_answer": "を", "explanations": {"を": "正解。『シンボルを使えば』で、使う対象を示す", "の": "『の』は名詞をつなぐので、『シンボルの使えば』は動詞の目的語が欠けて文が成り立たない", "から": "『から』は起点を示すので、『シンボルから使えば』は不自然で意味が通らない", "より": "『より』は比較を示すので、『シンボルより使えば』は文が成り立たない"}, "error_tags": {"の": "連体修飾", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある概念や、もの、情報などを、絵や形で表すための記号。", "primary_collocate": null, "pronunciation": "しんぼる", "ipa": "ɕimboɾɯ", "syllable_count": 4, "sentences": [{"text": "画面の鍵のシンボルは、安全な通信を表している。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "画面[がめん]の鍵[かぎ]のシンボルは、安全[あんぜん]な通信[つうしん]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "天気予報では、太陽のシンボルが晴れを意味する。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]では、太陽[たいよう]のシンボルが晴[は]れを意味[いみ]する。", "sentence_source": "generated"}, {"text": "この説明書では、注意を表すシンボルが各ページに使われている。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "この説明書[せつめいしょ]では、注意[ちゅうい]を表[あらわ]すシンボルが各[かく]ページに使[つか]われている。", "sentence_source": "generated"}, {"text": "電池のシンボルが赤くなったら、充電が必要だ。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "電池[でんち]のシンボルが赤[あか]くなったら、充電[じゅうでん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "地図には、温泉を示すシンボルがたくさん並んでいる。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "地図[ちず]には、温泉[おんせん]を示[しめ]すシンボルがたくさん並[なら]んでいる。", "sentence_source": "generated"}, {"text": "洗濯表示のシンボルを見れば、洗い方が分かる。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "洗濯表示[せんたくひょうじ]のシンボルを見[み]れば、洗[あら]い方[かた]が分[わ]かる。", "sentence_source": "generated"}, {"text": "音量を表すシンボルをクリックすると、音が消えます。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "音量[おんりょう]を表[あらわ]すシンボルをクリックすると、音[おと]が消[き]えます。", "sentence_source": "generated"}, {"text": "シンボルを使えば、長い説明がなくても情報を短く伝えられる。", "target_word": "シンボル", "complexity_tier": "T4", "furigana": "シンボルを使[つか]えば、長[なが]い説明[せつめい]がなくても情報[じょうほう]を短[みじか]く伝[つた]えられる。", "sentence_source": "generated"}, {"text": "看板のシンボルが小さすぎて、何の意味か分からなかった。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "看板[かんばん]のシンボルが小[ちい]さすぎて、何[なん]の意味[いみ]か分[わ]からなかった。", "sentence_source": "generated"}, {"text": "私は新しいアプリのシンボルを、丸と三角で作った。", "target_word": "シンボル", "complexity_tier": "T3", "furigana": "私[わたし]は新[あたら]しいアプリのシンボルを、丸[まる]と三角[さんかく]で作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シンボル", "label": "基本形"}, {"form": "シンボルが", "label": "が格"}], "register": "標準（普通体・丁寧体）", "sense_fingerprint": "概念や情報を絵や形で示す記号・アイコン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シンボル", "is_correct": true, "explanation": "正解。『画面の鍵のシンボルは、安全な通信を表している』で、概念を絵で示す記号を指す"}, {"text": "天気", "is_correct": false, "explanation": "『画面の鍵の天気は』では、鍵の天気が通信を表すという文の主語にならない"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は通信を表す記号ではないので、『画面の鍵の教科書は』は成り立たない"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は通信を表す記号ではないので、『画面の鍵の冷蔵庫は』は意味が通らない"}], "explanations": {"シンボル": "正解。『画面の鍵のシンボルは、安全な通信を表している』で、概念を絵で示す記号を指す", "天気": "『画面の鍵の天気は』では、鍵の天気が通信を表すという文の主語にならない", "教科書": "教科書は通信を表す記号ではないので、『画面の鍵の教科書は』は成り立たない", "冷蔵庫": "冷蔵庫は通信を表す記号ではないので、『画面の鍵の冷蔵庫は』は意味が通らない"}, "sentence_index": 0, "correct_answer": "シンボル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は暗くなった部屋で、シンボルを点けて本を読んだ。", "explanation": "ここは〈照明〉の意味。照明は点けて使うものだが、シンボルは形や絵で概念を表す記号なので、点けるものではないので合わない。"}, {"text": "アプリのシンボルは、アプリを開いたことを知らせる音だ。", "explanation": "ここは〈起動音〉の意味。音で知らせるものを指すので、絵や形で情報を示す記号ではないこの語には合わない"}, {"text": "シンボルは、大きな声で歌う人たちの集まりのことだ。", "explanation": "ここは〈合唱団〉の意味。歌う人の集まりを指し、絵や形で情報を示す記号ではないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シンボル", "is_correct": true, "explanation": "正解。『音量を表すシンボルをクリックすると、音が消えます』で、音量を示す記号を指す"}, {"text": "野球", "is_correct": false, "explanation": "『音量を表す野球をクリック』は意味が通らず、クリックする対象にもならない"}, {"text": "辞書", "is_correct": false, "explanation": "『音量を表す辞書をクリック』は成り立たず、ここでは音量を示す記号が入る"}, {"text": "電車", "is_correct": false, "explanation": "『音量を表す電車をクリック』は文が成り立たない"}], "explanations": {"シンボル": "正解。『音量を表すシンボルをクリックすると、音が消えます』で、音量を示す記号を指す", "野球": "『音量を表す野球をクリック』は意味が通らず、クリックする対象にもならない", "辞書": "『音量を表す辞書をクリック』は成り立たず、ここでは音量を示す記号が入る", "電車": "『音量を表す電車をクリック』は文が成り立たない"}, "sentence_index": 6, "correct_answer": "シンボル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アプリのシンボルは、ユーザーの名前を入力する欄だ。", "explanation": "ここは〈入力欄〉の意味。入力欄は文字を書き込む場所で、シンボルは形や絵で概念を表す記号なので合わない。"}, {"text": "シンボルは、文字を別の記号に置き換えて隠す仕組みだ。", "explanation": "ここは〈暗号〉の意味。文字を隠す仕組みを指し、絵や形で概念を示す記号とは違うので合わない"}, {"text": "シンボルは、決まった言葉を言って仲間かどうかを確かめるものだ。", "explanation": "ここは〈合言葉〉の意味。言葉で確かめる合図を指し、絵や形で示す記号ではないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この画面の鍵は、安全な通信を示すシンボルがなる。", "corrected_sentence": "この画面の鍵は、安全な通信を示すシンボルになる。", "error_description": "誤りは『になる』の『に』が『が』になっていること。『〜になる』には『に』が必要なので、正しい形は『シンボルになる』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38061, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電池のシンボルを聞けば、残りの量が分かる。", "corrected_sentence": "電池のシンボルを見れば、残りの量が分かる。", "error_description": "誤りは『見れば』が『聞けば』になっていること。シンボルは目で見て確かめるものなので、正しくは『見れば』", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「好き」の対象は「が」で示すので、「美術が好き」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「好き」は「を」を取らないので、対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「好き」は「に」を取らず、対象の示し方として合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、「好き」の対象には使えない。"}], "correct_answer": "が", "explanations": {"が": "「好き」の対象は「が」で示すので、「美術が好き」と自然につながる。", "を": "「好き」は「を」を取らないので、対象を示せない。", "に": "「好き」は「に」を取らず、対象の示し方として合わない。", "で": "「で」は場所や手段を表し、「好き」の対象には使えない。"}, "error_tags": {"を": "目的格（好きの対象には使わない）", "に": "方向・相手（好きには合わない）", "で": "場所・手段（対象には使えない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。美術について述べる文の主題になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。心を豊かにする対象の示し方に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。ここでは文の主題を作れない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。文の主題の位置には立てない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。美術について述べる文の主題になる。", "へ": "方向を示す「へ」。心を豊かにする対象の示し方に合わない。", "と": "並列・共同の「と」。ここでは文の主題を作れない。", "の": "連体修飾の「の」。文の主題の位置には立てない。"}, "error_tags": {"へ": "方向（豊かにする対象には不可）", "と": "並列・共同（主題にならない）", "の": "連体修飾（文の主題にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを作ったり、絵をかいたりする、うつくしいものを楽しむこと。", "primary_collocate": null, "pronunciation": "びじゅつ", "ipa": "bidʑɯtsɯ", "syllable_count": 3, "sentences": [{"text": "私は美術の時間に、友達の顔を絵にかいた。", "target_word": "美術", "complexity_tier": "T3", "furigana": "私[わたし]は美術[びじゅつ]の時間[じかん]に、友達[ともだち]の顔[かお]を絵[え]にかいた。", "sentence_source": "generated"}, {"text": "姉は美術が好きで、休みの日は絵を見に出かける。", "target_word": "美術", "complexity_tier": "T3", "furigana": "姉[あね]は美術[びじゅつ]が好[す]きで、休[やす]みの日[ひ]は絵[え]を見[み]に出[で]かける。", "sentence_source": "generated"}, {"text": "美術の先生は、粘土で動物を作る方法を教えてくれた。", "target_word": "美術", "complexity_tier": "T3", "furigana": "美術[びじゅつ]の先生[せんせい]は、粘土[ねんど]で動物[どうぶつ]を作[つく]る方法[ほうほう]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "弟は美術が得意で、いつも上手な絵をかく。", "target_word": "美術", "complexity_tier": "T3", "furigana": "弟[おとうと]は美術[びじゅつ]が得意[とくい]で、いつも上手[じょうず]な絵[え]をかく。", "sentence_source": "generated"}, {"text": "美術を学ぶために、彼女は外国の大学へ行った。", "target_word": "美術", "complexity_tier": "T3", "furigana": "美術[びじゅつ]を学[まな]ぶために、彼女[かのじょ]は外国[がいこく]の大学[だいがく]へ行[い]った。", "sentence_source": "generated"}, {"text": "美術に興味がない人でも、この展覧会は楽しめる。", "target_word": "美術", "complexity_tier": "T3", "furigana": "美術[びじゅつ]に興味[きょうみ]がない人[ひと]でも、この展覧会[てんらんかい]は楽[たの]しめる。", "sentence_source": "generated"}, {"text": "古い寺の建物を調べることは、美術を研究する人にとって大切だ。", "target_word": "美術", "complexity_tier": "T3", "furigana": "古[ふる]い 寺[てら]の 建物[たてもの]を 調[しら]べることは、美術[びじゅつ]を 研究[けんきゅう]する 人[ひと]にとって 大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "美術は、見る人の心を豊かにしてくれる。", "target_word": "美術", "complexity_tier": "T3", "furigana": "美術[びじゅつ]は、見[み]る人[ひと]の心[こころ]を豊[ゆた]かにしてくれる。", "sentence_source": "generated"}, {"text": "今日の美術の授業では、色の使い方を勉強した。", "target_word": "美術", "complexity_tier": "T3", "furigana": "今日[きょう]の美術[びじゅつ]の授業[じゅぎょう]では、色[いろ]の使[つか]い方[かた]を勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "兄は音楽より美術のほうが好きだと言った。", "target_word": "美術", "complexity_tier": "T3", "furigana": "兄[あに]は音楽[おんがく]より美術[びじゅつ]のほうが好[す]きだと言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "美術", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "絵や彫刻など、美しいものを作ったり味わったりする芸術の分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美術", "is_correct": true, "explanation": "美術は絵をかいたり作ったりする教科なので、友達の顔を絵にかいた出来事に合う。"}, {"text": "数学", "is_correct": false, "explanation": "数学は計算や論理の教科で、顔を絵にかく内容とは結びつかない。"}, {"text": "体育", "is_correct": false, "explanation": "体育は体を動かす教科で、絵をかくことには合わない。"}, {"text": "国語", "is_correct": false, "explanation": "国語は文章を読み書きする教科で、絵をかくことには合わない。"}], "explanations": {"美術": "美術は絵をかいたり作ったりする教科なので、友達の顔を絵にかいた出来事に合う。", "数学": "数学は計算や論理の教科で、顔を絵にかく内容とは結びつかない。", "体育": "体育は体を動かす教科で、絵をかくことには合わない。", "国語": "国語は文章を読み書きする教科で、絵をかくことには合わない。"}, "sentence_index": 0, "correct_answer": "美術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は美術で彫刻を見てまわった。", "explanation": "ここは〈美術館〉の意味。美術は場所を表さないので、見に行く所としては使えない。"}, {"text": "祖母は毎日、美術で陶器を焼いている。", "explanation": "ここは〈工芸〉の意味。美術は分野の名で、陶器を焼く場所や道具にはならない。"}, {"text": "彼女は有名な美術で、毎年個展を開いている。", "explanation": "ここは〈美術家〉の意味。美術は分野の名前なので、人を指す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美術", "is_correct": true, "explanation": "美術は絵や彫刻などの造形の分野で、寺の建物の美しさを研究する文脈に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は調理の分野で、寺の建物を研究する話とは結びつかない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は音を扱う分野で、建物を調べる研究とは合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は衣類を洗う家事で、研究の対象になる分野ではない。"}], "explanations": {"美術": "美術は絵や彫刻などの造形の分野で、寺の建物の美しさを研究する文脈に合う。", "料理": "料理は調理の分野で、寺の建物を研究する話とは結びつかない。", "音楽": "音楽は音を扱う分野で、建物を調べる研究とは合わない。", "洗濯": "洗濯は衣類を洗う家事で、研究の対象になる分野ではない。"}, "sentence_index": 6, "correct_answer": "美術"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この美術は、百年前にパリで描かれた。", "explanation": "ここは〈絵画〉の意味。美術は分野の名前で、一枚の作品を指す語としては使えない。"}, {"text": "姉は毎晩、ピアノで美術を練習している。", "explanation": "ここは〈音楽〉の意味。美術は楽器で練習するものではないので、ピアノの練習には使えない。"}, {"text": "美術で、空の色を描いた。", "explanation": "ここは〈絵の具〉の意味。美術は道具や材料ではないので、色を描く手段には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は美術を得意で、毎日スケッチブックを持ち歩いている。", "corrected_sentence": "妹は美術が得意で、毎日スケッチブックを持ち歩いている。", "error_description": "「得意」は「〜が得意」の形で対象を「が」で示す。「美術を」と「を」を使うのは誤りで、正しくは「美術が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38062, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は美術に専攻して、今は大学で教えている。", "corrected_sentence": "彼は美術を専攻して、今は大学で教えている。", "error_description": "「専攻する」は専攻する分野を「を」で示す。「美術に」と「に」を使うのは誤りで、正しくは「美術を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「目を」は「閉じた」の目的語になり、閉じる対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「目で閉じた」は道具として不自然で、目を閉じる動作に合わないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「目より閉じた」は比較の意味になり、ここには合わないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「目から閉じた」は起点を示し、閉じる対象を示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「目を」は「閉じた」の目的語になり、閉じる対象を示す。", "で": "「目で閉じた」は道具として不自然で、目を閉じる動作に合わないので合わない。", "より": "「目より閉じた」は比較の意味になり、ここには合わないので合わない。", "から": "「目から閉じた」は起点を示し、閉じる対象を示さないので合わない。"}, "error_tags": {"で": "手段", "より": "比較", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開く", "is_correct": true, "explanation": "「閉じる」（すき間をなくす）の反対語で、すき間を作る動作を表す。"}, {"text": "話す", "is_correct": false, "explanation": "「閉じる」の反対語ではない。口を閉じる場面とは別の動作なので合わない。"}, {"text": "包む", "is_correct": false, "explanation": "「閉じる」の反対語ではなく、物をくるむ動作なので合わない。"}, {"text": "固める", "is_correct": false, "explanation": "「閉じる」の反対語ではなく、かたくする意味なので合わない。"}], "correct_answer": "開く", "explanations": {"開く": "「閉じる」（すき間をなくす）の反対語で、すき間を作る動作を表す。", "話す": "「閉じる」の反対語ではない。口を閉じる場面とは別の動作なので合わない。", "包む": "「閉じる」の反対語ではなく、物をくるむ動作なので合わない。", "固める": "「閉じる」の反対語ではなく、かたくする意味なので合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ふたが」は「閉じない」の主語で、閉じないのがふたであることを示す。"}, {"text": "に", "is_correct": false, "explanation": "「ふたに」は主語を示せず、この文の構造に合わないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「ふたと」は並列や共同を表し、ふたの動作を示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「ふたへ」は方向を示し、閉じないのがふたである文とは合わないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「ふたが」は「閉じない」の主語で、閉じないのがふたであることを示す。", "に": "「ふたに」は主語を示せず、この文の構造に合わないので合わない。", "と": "「ふたと」は並列や共同を表し、ふたの動作を示せないので合わない。", "へ": "「ふたへ」は方向を示し、閉じないのがふたである文とは合わないので合わない。"}, "error_tags": {"に": "相手・場所", "と": "並列・共同", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開く", "is_correct": true, "explanation": "「閉じる」の反対語で、ノートを開くという動作を表す。"}, {"text": "押す", "is_correct": false, "explanation": "「閉じる」の反対語ではなく、力を加える動作なので合わない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「閉じる」の反対語ではなく、物を移動させる動作なので合わない。"}, {"text": "数える", "is_correct": false, "explanation": "「閉じる」の反対語ではなく、数量を確かめる動作なので合わない。"}], "correct_answer": "開く", "explanations": {"開く": "「閉じる」の反対語で、ノートを開くという動作を表す。", "押す": "「閉じる」の反対語ではなく、力を加える動作なので合わない。", "運ぶ": "「閉じる」の反対語ではなく、物を移動させる動作なので合わない。", "数える": "「閉じる」の反対語ではなく、数量を確かめる動作なので合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、ぴったりと合わさって、あいているところがなくなること。", "primary_collocate": null, "pronunciation": "とじる", "ipa": "toʑiɾɯ", "syllable_count": 3, "sentences": [{"text": "本を閉じて、かばんに入れた。", "target_word": "閉じて", "complexity_tier": "T3", "furigana": "本[ほん]を閉[と]じて、かばんに入[い]れた。", "sentence_source": "generated"}, {"text": "眠くなって、思わず目を閉じた。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "眠[ねむ]くなって、思[おも]わず目[め]を閉[と]じた。", "sentence_source": "generated"}, {"text": "雨がやんだので、傘を閉じた。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだので、傘[かさ]を閉[と]じた。", "sentence_source": "generated"}, {"text": "彼は口を固く閉じて、何も話さなかった。", "target_word": "閉じて", "complexity_tier": "T3", "furigana": "彼[かれ]は口[くち]を固[かた]く閉[と]じて、何[なに]も話[はな]さなかった。", "sentence_source": "generated"}, {"text": "電車に乗る前に、濡れた傘を閉じる。", "target_word": "閉じる", "complexity_tier": "T3", "furigana": "電車[でんしゃ]に乗[の]る前[まえ]に、濡[ぬ]れた傘[かさ]を閉[と]じる。", "sentence_source": "generated"}, {"text": "貝は危険を感じると、殻をぴったり閉じる。", "target_word": "閉じる", "complexity_tier": "T3", "furigana": "貝[かい]は危険[きけん]を感[かん]じると、殻[から]をぴったり閉[と]じる。", "sentence_source": "generated"}, {"text": "花は夜になると、花びらを閉じる。", "target_word": "閉じる", "complexity_tier": "T3", "furigana": "花[はな]は夜[よる]になると、花[はな]びらを閉[と]じる。", "sentence_source": "generated"}, {"text": "箱のふたがうまく閉じないので、手で押さえた。", "target_word": "閉じない", "complexity_tier": "T3", "furigana": "箱[はこ]のふたがうまく閉[と]じないので、手[て]で押[おさ]えた。", "sentence_source": "generated"}, {"text": "赤ちゃんは小さな手を閉じて眠っている。", "target_word": "閉じて", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは小[ちい]さな手[て]を閉[と]じて眠[ねむ]っている。", "sentence_source": "generated"}, {"text": "ノートを閉じたとたん、チャイムが鳴った。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "ノートを閉[と]じたとたん、チャイムが鳴[な]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "閉じる", "label": "辞書形"}, {"form": "閉じます", "label": "丁寧形"}, {"form": "閉じた", "label": "過去形"}, {"form": "閉じて", "label": "て形"}, {"form": "閉じない", "label": "否定形"}, {"form": "閉じれば", "label": "条件形"}], "register": "日常的な話し言葉（常体）", "sense_fingerprint": "目・口・本・傘・ふたなどが合わさって、すき間がなくなる、またはそうすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "閉じて", "is_correct": true, "explanation": "本をすき間なくとじてからかばんに入れる流れに合う。"}, {"text": "投げて", "is_correct": false, "explanation": "本を投げてからかばんに入れる流れは不自然で、閉じる動作に合わない。"}, {"text": "燃やして", "is_correct": false, "explanation": "本を燃やしてからかばんに入れるのは文脈に合わないので合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "本を洗ってからかばんに入れるのは文脈に合わないので合わない。"}], "explanations": {"閉じて": "本をすき間なくとじてからかばんに入れる流れに合う。", "投げて": "本を投げてからかばんに入れる流れは不自然で、閉じる動作に合わない。", "燃やして": "本を燃やしてからかばんに入れるのは文脈に合わないので合わない。", "洗って": "本を洗ってからかばんに入れるのは文脈に合わないので合わない。"}, "sentence_index": 0, "correct_answer": "閉じて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出かける前に、ネクタイを閉じた。", "explanation": "ここは〈締める〉の意味。ネクタイは閉じるのではなく締めるものなので合わない。"}, {"text": "靴ひもを閉じて、家を出た。", "explanation": "ここは〈結ぶ〉の意味。靴ひもは閉じるのではなく結ぶものなので合わない。"}, {"text": "寝る前に、ラジオのスイッチを閉じた。", "explanation": "ここは〈切る〉の意味。スイッチは閉じるものではなく切るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "閉じる", "is_correct": true, "explanation": "花が夜になると花びらをすぼめる、という文脈に合う。"}, {"text": "開く", "is_correct": false, "explanation": "夜に花びらを開くのは逆の動きで、閉じる文脈に合わないので合わない。"}, {"text": "散らす", "is_correct": false, "explanation": "花びらを散らすのは別の動作で、夜に閉じる説明に合わないので合わない。"}, {"text": "集める", "is_correct": false, "explanation": "花びらを集めるのは人の作業で、花が夜に閉じる文に合わないので合わない。"}], "explanations": {"閉じる": "花が夜になると花びらをすぼめる、という文脈に合う。", "開く": "夜に花びらを開くのは逆の動きで、閉じる文脈に合わないので合わない。", "散らす": "花びらを散らすのは別の動作で、夜に閉じる説明に合わないので合わない。", "集める": "花びらを集めるのは人の作業で、花が夜に閉じる文に合わないので合わない。"}, "sentence_index": 6, "correct_answer": "閉じる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に、玄関の鍵を閉じた。", "explanation": "ここは〈かける〉の意味。鍵は閉じるものではなくかけるものなので合わない。"}, {"text": "夜中、テレビを閉じて寝た。", "explanation": "ここは〈消す〉の意味。テレビは閉じるものではなく消すものなので合わない。"}, {"text": "乾いた洗濯物を閉じて、たんすにしまった。", "explanation": "ここは〈たたむ〉の意味。洗濯物は閉じるのではなくたたむものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風が来たので、テントの入り口を閉じった。", "corrected_sentence": "強い風が来たので、テントの入り口を閉じた。", "error_description": "「閉じる」は一段動詞なので過去形は「閉じた」。「閉じった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "閉じた", "is_correct": true, "explanation": "過去形で、「思わず目を閉じた」という文末に合う。"}, {"text": "閉じて", "is_correct": false, "explanation": "て形は文末に置けないので、この文には合わない。"}, {"text": "閉じたら", "is_correct": false, "explanation": "条件の「たら」は後ろに文が続くので、文末では成り立たない。"}, {"text": "閉じれば", "is_correct": false, "explanation": "条件形は後ろに続く文が必要で、文末では成り立たないので合わない。"}], "correct_form": "閉じた", "base_form": "閉じる", "form_label": "過去形", "sentence_index": 1, "explanations": {"閉じた": "過去形で、「思わず目を閉じた」という文末に合う。", "閉じて": "て形は文末に置けないので、この文には合わない。", "閉じたら": "条件の「たら」は後ろに文が続くので、文末では成り立たない。", "閉じれば": "条件形は後ろに続く文が必要で、文末では成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38064, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜、窓に閉じて寝た。", "corrected_sentence": "夜、窓を閉じて寝た。", "error_description": "「閉じる」は「〜を閉じる」の形で目的語に「を」をとる。「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "閉じない", "is_correct": true, "explanation": "否定形で、「ふたがうまく閉じない」の状態を表し、文に合う。"}, {"text": "閉じろ", "is_correct": false, "explanation": "命令形は「ので」の前には置けず、ふたの状態を述べる文に合わない。"}, {"text": "閉じよう", "is_correct": false, "explanation": "意向形は「ので」の前に続けられず、ふたの状態を述べる文には合わないので合わない。"}, {"text": "閉じ", "is_correct": false, "explanation": "連用形だけでは「ので」の前に続く述語にならず、文として成り立たない。"}], "correct_form": "閉じない", "base_form": "閉じる", "form_label": "否定形", "sentence_index": 7, "explanations": {"閉じない": "否定形で、「ふたがうまく閉じない」の状態を表し、文に合う。", "閉じろ": "命令形は「ので」の前には置けず、ふたの状態を述べる文に合わない。", "閉じよう": "意向形は「ので」の前に続けられず、ふたの状態を述べる文には合わないので合わない。", "閉じ": "連用形だけでは「ので」の前に続く述語にならず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「幕を」は「閉じた」の目的語になり、閉じられる対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「幕に」は閉じる対象を示さないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「幕と」は並列を表し、閉じる対象を示さないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「幕へ」は方向を示し、閉じる対象を示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「幕を」は「閉じた」の目的語になり、閉じられる対象を示す。", "に": "「幕に」は閉じる対象を示さないので合わない。", "と": "「幕と」は並列を表し、閉じる対象を示さないので合わない。", "へ": "「幕へ」は方向を示し、閉じる対象を示さないので合わない。"}, "error_tags": {"に": "相手・場所", "と": "並列・共同", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開く", "is_correct": true, "explanation": "「会を閉じる」の反対で、「会を開く」は開会を意味するので対になる。"}, {"text": "受ける", "is_correct": false, "explanation": "会を受けるとは言わず、反対語ではないので合わない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "反対語ではなく、物を移動させる動作なので合わない。"}, {"text": "数える", "is_correct": false, "explanation": "反対語ではなく、数量を確かめる動作なので合わない。"}], "correct_answer": "開く", "explanations": {"開く": "「会を閉じる」の反対で、「会を開く」は開会を意味するので対になる。", "受ける": "会を受けるとは言わず、反対語ではないので合わない。", "運ぶ": "反対語ではなく、物を移動させる動作なので合わない。", "数える": "反対語ではなく、数量を確かめる動作なので合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「営業を」は「閉じた」の目的語になり、閉じた対象を示す。"}, {"text": "より", "is_correct": false, "explanation": "「営業より」は比較を表し、閉じた対象にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「営業の」は修飾を表し、閉じた対象を示さないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「営業から」は起点を表し、閉じた対象を示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「営業を」は「閉じた」の目的語になり、閉じた対象を示す。", "より": "「営業より」は比較を表し、閉じた対象にはならないので合わない。", "の": "「営業の」は修飾を表し、閉じた対象を示さないので合わない。", "から": "「営業から」は起点を表し、閉じた対象を示さないので合わない。"}, "error_tags": {"より": "比較", "の": "修飾", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開く", "is_correct": true, "explanation": "「閉じられた」（閉会になった）の反対で、「開かれた」が対になる。"}, {"text": "押す", "is_correct": false, "explanation": "反対語ではなく、力を加える動作なので合わない。"}, {"text": "食べる", "is_correct": false, "explanation": "反対語ではなく、食物を口に入れる動作なので合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "反対語ではなく、睡眠の状態を表すので合わない。"}], "correct_answer": "開く", "explanations": {"開く": "「閉じられた」（閉会になった）の反対で、「開かれた」が対になる。", "押す": "反対語ではなく、力を加える動作なので合わない。", "食べる": "反対語ではなく、食物を口に入れる動作なので合わない。", "眠る": "反対語ではなく、睡眠の状態を表すので合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "開いていたものが動かなくなったり、ふさがったりすること。また、動作や状態が終わって、それ以上続かなくなること。", "primary_collocate": null, "pronunciation": "とじる", "ipa": "toʑiɾɯ", "syllable_count": 3, "sentences": [{"text": "画面の右上を押して、ウィンドウを閉じる。", "target_word": "閉じる", "complexity_tier": "T3", "furigana": "画面[がめん]の右上[みぎうえ]を押[お]して、ウィンドウを閉[と]じる。", "sentence_source": "generated"}, {"text": "三日間の祭りは、花火とともに幕を閉じた。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "三日間[みっかかん]の祭[まつ]りは、花火[はなび]とともに幕[まく]を閉[と]じた。", "sentence_source": "generated"}, {"text": "傷口が閉じるまで、お風呂は我慢してください。", "target_word": "閉じる", "complexity_tier": "T3", "furigana": "傷口[きずぐち]が閉[と]じるまで、お風呂[ふろ]は我慢[がまん]してください。", "sentence_source": "generated"}, {"text": "会議の最後に、司会者が会を閉じた。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "会議[かいぎ]の最後[さいご]に、司会者[しかいしゃ]が会[かい]を閉[と]じた。", "sentence_source": "generated"}, {"text": "祖父は九十歳で、その人生の幕を閉じた。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "祖父[そふ]は九十歳[きゅうじゅっさい]で、その人生[じんせい]の幕[まく]を閉[と]じた。", "sentence_source": "generated"}, {"text": "古いアプリを閉じないと、動きが遅くなる。", "target_word": "閉じない", "complexity_tier": "T3", "furigana": "古[ふる]いアプリを閉[と]じないと、動[うご]きが遅[おそ]くなる。", "sentence_source": "generated"}, {"text": "作業が終わったら、ファイルを閉じて保存してください。", "target_word": "閉じて", "complexity_tier": "T3", "furigana": "作業[さぎょう]が終[お]わったら、ファイルを閉[と]じて保存[ほぞん]してください。", "sentence_source": "generated"}, {"text": "町の古い映画館は、今年の春に営業を閉じた。", "target_word": "閉じた", "complexity_tier": "T3", "furigana": "町[まち]の古[ふる]い映画館[えいがかん]は、今年[ことし]の春[はる]に営業[えいぎょう]を閉[と]じた。", "sentence_source": "generated"}, {"text": "彼は心を閉じて、だれとも話さなくなった。", "target_word": "閉じて", "complexity_tier": "T3", "furigana": "彼[かれ]は心[こころ]を閉[と]じて、だれとも話[はな]さなくなった。", "sentence_source": "generated"}, {"text": "大会は、盛大な式で閉じられた。", "target_word": "閉じられた", "complexity_tier": "T3", "furigana": "大会[たいかい]は、盛大[せいだい]な式[しき]で閉[と]じられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "閉じる", "label": "辞書形"}, {"form": "閉じます", "label": "丁寧形"}, {"form": "閉じた", "label": "過去形"}, {"form": "閉じて", "label": "て形"}, {"form": "閉じない", "label": "否定形"}, {"form": "閉じれば", "label": "条件形"}], "register": "日常的な話し言葉（常体）", "sense_fingerprint": "開いていたものがふさがる、または会・営業・画面などが終わる、終わらせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "閉じる", "is_correct": true, "explanation": "ウィンドウを終わらせて画面から消す、という文脈に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "ウィンドウを食べるとは言わないので合わない。"}, {"text": "料理する", "is_correct": false, "explanation": "ウィンドウを料理するとは言わないので合わない。"}, {"text": "数える", "is_correct": false, "explanation": "ウィンドウを数えるという操作はないので合わない。"}], "explanations": {"閉じる": "ウィンドウを終わらせて画面から消す、という文脈に合う。", "食べる": "ウィンドウを食べるとは言わないので合わない。", "料理する": "ウィンドウを料理するとは言わないので合わない。", "数える": "ウィンドウを数えるという操作はないので合わない。"}, "sentence_index": 0, "correct_answer": "閉じる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "誕生日に、プレゼントを閉じて渡した。", "explanation": "ここは〈包む〉の意味。プレゼントは閉じるのではなく包むものなので合わない。"}, {"text": "夜中、テレビを閉じて寝た。", "explanation": "ここは〈消す〉の意味。テレビは閉じるものではなく消すものなので合わない。"}, {"text": "寝る前に、ラジオのスイッチを閉じた。", "explanation": "ここは〈切る〉の意味。スイッチは閉じるものではなく切るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "閉じて", "is_correct": true, "explanation": "作業のあとにファイルを閉じてから保存する流れに合う。"}, {"text": "消して", "is_correct": false, "explanation": "ファイルを消して保存するのは別の作業で、閉じてから保存する文脈に合わないので合わない。"}, {"text": "送って", "is_correct": false, "explanation": "ファイルを送って保存するのは文脈に合わないので合わない。"}, {"text": "食べて", "is_correct": false, "explanation": "ファイルを食べるとは言わないので、保存の文脈に合わない。"}], "explanations": {"閉じて": "作業のあとにファイルを閉じてから保存する流れに合う。", "消して": "ファイルを消して保存するのは別の作業で、閉じてから保存する文脈に合わないので合わない。", "送って": "ファイルを送って保存するのは文脈に合わないので合わない。", "食べて": "ファイルを食べるとは言わないので、保存の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "閉じて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に、ネクタイを閉じた。", "explanation": "ここは〈締める〉の意味。ネクタイは閉じるのではなく締めるものなので合わない。"}, {"text": "駐車場で、車のエンジンを閉じた。", "explanation": "ここは〈止める〉の意味。エンジンは閉じるのではなく止めるものなので合わない。"}, {"text": "旅行の予定を閉じた。", "explanation": "ここは〈取り消す〉の意味。予定は閉じるのではなく取り消すものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の市は、花火とともに幕を閉じった。", "corrected_sentence": "夏の市は、花火とともに幕を閉じた。", "error_description": "「閉じる」は一段動詞なので過去形は「閉じた」。「閉じった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "閉じた", "is_correct": true, "explanation": "過去形で、「幕を閉じた」という文末に合う。"}, {"text": "閉じて", "is_correct": false, "explanation": "て形は文末に置けないので、この文には合わない。"}, {"text": "閉じたら", "is_correct": false, "explanation": "条件の「たら」は後ろに文が続くので、文末では成り立たない。"}, {"text": "閉じれば", "is_correct": false, "explanation": "条件形は後ろに続く文が必要で、文末では成り立たないので合わない。"}], "correct_form": "閉じた", "base_form": "閉じる", "form_label": "過去形", "sentence_index": 1, "explanations": {"閉じた": "過去形で、「幕を閉じた」という文末に合う。", "閉じて": "て形は文末に置けないので、この文には合わない。", "閉じたら": "条件の「たら」は後ろに文が続くので、文末では成り立たない。", "閉じれば": "条件形は後ろに続く文が必要で、文末では成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38065, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事が済んだら、ウィンドウに閉じて帰る。", "corrected_sentence": "仕事が済んだら、ウィンドウを閉じて帰る。", "error_description": "「閉じる」は目的語に「を」をとる。「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "閉じた", "is_correct": true, "explanation": "過去形で、映画館が営業を閉じた事実を表す文に合う。"}, {"text": "閉じ", "is_correct": false, "explanation": "連用形だけでは文末に置けず、文として成り立たない。"}, {"text": "閉じられ", "is_correct": false, "explanation": "受身の語幹だけでは文末に置けず、文として成り立たない。"}, {"text": "閉じさせ", "is_correct": false, "explanation": "使役の語幹だけでは文末に置けず、文として成り立たない。"}], "correct_form": "閉じた", "base_form": "閉じる", "form_label": "過去形", "sentence_index": 7, "explanations": {"閉じた": "過去形で、映画館が営業を閉じた事実を表す文に合う。", "閉じ": "連用形だけでは文末に置けず、文として成り立たない。", "閉じられ": "受身の語幹だけでは文末に置けず、文として成り立たない。", "閉じさせ": "使役の語幹だけでは文末に置けず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ループになっていて」の「に」で、「なる」の結果を表すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ループをなっていて」は目的語にできず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「ループでなっていて」は手段の意味になり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「ループへなっていて」は方向の意味で、「なる」の結果が表せない。"}], "correct_answer": "に", "explanations": {"に": "「ループになっていて」の「に」で、「なる」の結果を表すので正しい。", "を": "「ループをなっていて」は目的語にできず、不自然。", "で": "「ループでなっていて」は手段の意味になり、不自然。", "へ": "「ループへなっていて」は方向の意味で、「なる」の結果が表せない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ループになっていて」の「に」で、「なる」の結果を表すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ループをなっていて」は目的語にできず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「ループよりなっていて」は比較の意味になり、文が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「ループのなっていて」は所属の意味になり、「なる」の結果が合わない。"}], "correct_answer": "に", "explanations": {"に": "「ループになっていて」の「に」で、「なる」の結果を表すので正しい。", "を": "「ループをなっていて」は目的語にできず、不自然。", "より": "「ループよりなっていて」は比較の意味になり、文が通らない。", "の": "「ループのなっていて」は所属の意味になり、「なる」の結果が合わない。"}, "error_tags": {"を": "目的語", "より": "比較", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ぐるぐるまわること。同じところを何度も回ること。", "primary_collocate": null, "pronunciation": "るーぷ", "ipa": "ɾɯːpɯ", "syllable_count": 3, "sentences": [{"text": "飛行機が空で大きなループを描いて、観客をよろこばせました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "飛行機(ひこうき)が空(そら)で大(おお)きなループを描(えが)いて、観客(かんきゃく)をよろこばせました。", "sentence_source": "generated"}, {"text": "この線路はループになっていて、電車は同じ場所をぐるぐる回ります。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "この線路(せんろ)はループになっていて、電車(でんしゃ)は同(おな)じ場所(ばしょ)をぐるぐる回(まわ)ります。", "sentence_source": "generated"}, {"text": "ジェットコースターが一回転するループに入ると、みんな叫びました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "ジェットコースターが一回転(いっかいてん)するループに入(はい)ると、みんな叫(さけ)びました。", "sentence_source": "generated"}, {"text": "スケートボードの選手が、ランプの上でループを決めました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "スケートボードの選手[せんしゅ]が、ランプの上[うえ]でループを決[き]めました。", "sentence_source": "generated"}, {"text": "ドローンが公園の上空で、ループを描きながら飛び続けていました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "ドローンが公園[こうえん]の上空[じょうくう]で、ループを描[えが]きながら飛[と]び続[つづ]けていました。", "sentence_source": "generated"}, {"text": "道にまよって、同じところをループのように何度も歩いてしまいました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "道(みち)にまよって、同(おな)じところをループのように何度(なんど)も歩(ある)いてしまいました。", "sentence_source": "generated"}, {"text": "スケートの選手は、氷の上でトリプルのループを跳びました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "スケートの選手[せんしゅ]は、氷[こおり]の上[うえ]でトリプルのループを跳[と]びました。", "sentence_source": "generated"}, {"text": "公園のジョギングコースはループになっていて、同じ場所を何度も走れます。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "公園(こうえん)のジョギングコースはループになっていて、同(おな)じ場所(ばしょ)を何度(なんど)も走(はし)れます。", "sentence_source": "generated"}, {"text": "ジェットコースターのループに何度も乗ると、目が回りそうです。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "ジェットコースターのループに何度[なんど]も乗[の]ると、目[め]が回[まわ]りそうです。", "sentence_source": "generated"}, {"text": "工場のベルトコンベアーは、ひとつのループになって休まず回っています。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "工場(こうじょう)のベルトコンベアーは、ひとつのループになって休(やす)まず回(まわ)っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ループ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "輪を描いたり、同じ場所をぐるぐる何度も回ったりする動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: よろこば (Zipf 1.64)','sentence 5 above tier T3: contains vocabulary far above tier T3: まよっ (Zipf 1.53)','sentence 9 above tier T3: contains vocabulary far above tier T3: ベルトコンベアー (Zipf 1.7)']::text[], '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ループ", "is_correct": true, "explanation": "大きな輪を空にえがく動きを指すので、文の内容に合う。"}, {"text": "歌", "is_correct": false, "explanation": "歌は描くものではないので、「大きな歌を描いて」は成り立たない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は空に描けるものではないので、「大きなを描いて」に合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は描くものではなく、聞くものなので合わない。"}], "explanations": {"ループ": "大きな輪を空にえがく動きを指すので、文の内容に合う。", "歌": "歌は描くものではないので、「大きな歌を描いて」は成り立たない。", "雷": "雷は空に描けるものではないので、「大きなを描いて」に合わない。", "音": "音は描くものではなく、聞くものなので合わない。"}, "sentence_index": 0, "correct_answer": "ループ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は婚約のループを左手の薬指にはめました。", "explanation": "ここは〈指輪〉の意味。ループは指輪のことではなく、ぐるぐる回る動きを指すので、この文では使わない。"}, {"text": "彼女はループを首にかけて、パーティーに出かけました。", "explanation": "ここは〈首飾り〉の意味。ループは回る動きを表すので、首飾りの意味では合わない。"}, {"text": "ひもの結び目のループをほどいて、靴を脱ぎました。", "explanation": "ここは〈結び目〉の意味。ループは回る動きを表すので、結び目の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ループ", "is_correct": true, "explanation": "トリプルの回転ジャンプを指し、「跳ぶ」と合うので正しい。"}, {"text": "料理", "is_correct": false, "explanation": "料理は跳ぶものではないので、「トリプルの料理を跳びました」に合わない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は跳ぶものではないので、「トリプルの歌を跳びました」に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は跳ぶものではないので、文が成り立たない。"}], "explanations": {"ループ": "トリプルの回転ジャンプを指し、「跳ぶ」と合うので正しい。", "料理": "料理は跳ぶものではないので、「トリプルの料理を跳びました」に合わない。", "歌": "歌は跳ぶものではないので、「トリプルの歌を跳びました」に合わない。", "手紙": "手紙は跳ぶものではないので、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ループ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お寺の鐘のループを、強くたたいて鳴らしました。", "explanation": "ここは〈鐘〉の意味。ループは鐘を指さないので、この文では使わない。"}, {"text": "ドアのループを引いて、部屋に入りました。", "explanation": "ここは〈取っ手〉の意味。ループは回る動きを表すので、取っ手の意味では合わない。"}, {"text": "くさりのループをつないで、ベルトを作りました。", "explanation": "ここは〈鎖〉の意味。ループは回る動きを表すので、鎖の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドローンが空で大きなループに描きました。", "corrected_sentence": "ドローンが空で大きなループを描きました。", "error_description": "誤りは助詞「に」。「描く」は目的語を取るので「ループを描きました」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38066, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車はループで回りました。", "corrected_sentence": "電車はループを回りました。", "error_description": "誤りは助詞「で」。「回る」は、めぐる場所を「を」で表すので「ループを回りました」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38067, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ループが続いています」の「が」で、続く主語を示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ループを続いています」は目的語にすると不自然。"}, {"text": "の", "is_correct": false, "explanation": "「ループの続いています」は所属の意味で、続く主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「ループと続く」は文が成り立たず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「ループが続いています」の「が」で、続く主語を示すので正しい。", "を": "「ループを続いています」は目的語にすると不自然。", "の": "「ループの続いています」は所属の意味で、続く主語にならない。", "と": "「ループと続く」は文が成り立たず、不自然。"}, "error_tags": {"を": "目的語", "の": "所属", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
