INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38067, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が循環する仕組みや、繰り返される過程。特に、始まりと終わりがつながっている状態。", "primary_collocate": null, "pronunciation": "るーぷ", "ipa": "ɾɯːpɯ", "syllable_count": 3, "sentences": [{"text": "悪いループにはまると、同じ失敗をくり返してしまいます。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "悪(わる)いループにはまると、同(おな)じ失敗(しっぱい)をくり返(かえ)してしまいます。", "sentence_source": "generated"}, {"text": "不安で眠れず、眠れないからまた不安になるというループが続いています。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "不安(ふあん)で眠(ねむ)れず、眠(ねむ)れないからまた不安(ふあん)になるというループが続(つづ)いています。", "sentence_source": "generated"}, {"text": "水は雨になり、川から海へ流れ、また雲になるというループができています。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "水[みず]は雨[あめ]になり、川[かわ]から海[うみ]へ流[なが]れ、また雲[くも]になるというループができています。", "sentence_source": "generated"}, {"text": "プログラムの中でループが止まらなくなり、パソコンが動かなくなりました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "プログラムの中(なか)でループが止(と)まらなくなり、パソコンが動(うご)かなくなりました。", "sentence_source": "generated"}, {"text": "同じ一日をくり返すループの物語を読みました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "同(おな)じ一日(いちにち)をくり返(かえ)すループの物語(ものがたり)を読(よ)みました。", "sentence_source": "generated"}, {"text": "買い物をして、お金の心配でストレスがたまり、また買い物をするループから抜け出したいです。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "買(か)い物(もの)をして、お金(かね)の心配(しんぱい)でストレスがたまり、また買(か)い物(もの)をするループから抜(ぬ)け出(だ)したいです。", "sentence_source": "generated"}, {"text": "学んで、試して、直して、また試すというループが上達の近道です。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "学(まな)んで、試(ため)して、直(なお)して、また試(ため)すというループが上達(じょうたつ)の近道(ちかみち)です。", "sentence_source": "generated"}, {"text": "申し込みの画面が最初にもどってばかりで、ループから出られません。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "申(もう)し込(こ)みの画面(がめん)が最初(さいしょ)にもどってばかりで、ループから出(で)られません。", "sentence_source": "generated"}, {"text": "彼は毎日同じ時間に起きて同じ電車に乗る、ループのような生活をしています。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "彼(かれ)は毎日(まいにち)同(おな)じ時間(じかん)に起(お)きて同(おな)じ電車(でんしゃ)に乗(の)る、ループのような生活(せいかつ)をしています。", "sentence_source": "generated"}, {"text": "始まりと終わりがつながったループを、図にかいて説明しました。", "target_word": "ループ", "complexity_tier": "T3", "furigana": "始(はじ)まりと終(お)わりがつながったループを、図(ず)にかいて説明(せつめい)しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ループ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "原因と結果がつながって繰り返される循環の仕組み・過程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38067, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ループ", "is_correct": true, "explanation": "同じ失敗が繰り返される悪循環の意味で、「はまる」と合う。"}, {"text": "数字", "is_correct": false, "explanation": "数字に「はまる」とは言わないので、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気に「はまる」とは言わないので、文が成り立たない。"}, {"text": "夏", "is_correct": false, "explanation": "「夏にはまる」とは言えず、文が成り立たない。"}], "explanations": {"ループ": "同じ失敗が繰り返される悪循環の意味で、「はまる」と合う。", "数字": "数字に「はまる」とは言わないので、文が成り立たない。", "天気": "天気に「はまる」とは言わないので、文が成り立たない。", "夏": "「夏にはまる」とは言えず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "ループ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラジオのループを回して、局をさがしました。", "explanation": "ここはダイヤルの意味。ループは循環や繰り返しの仕組みを指すので、ダイヤルの意味では合わない。"}, {"text": "帽子のループに、小さな飾りをつけました。", "explanation": "ここは〈輪〉の飾りの意味。循環や繰り返しの仕組みを指す定義とは違う。"}, {"text": "バッグのループを肩にかけて出かけました。", "explanation": "ここは〈持ち手〉の意味。循環や繰り返しの仕組みを指す定義とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38067, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ループ", "is_correct": true, "explanation": "学びと試行が繰り返される循環の意味で、「上達の近道」と合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は上達の近道にはならないので、文の内容に合わない。"}, {"text": "忘れ物", "is_correct": false, "explanation": "忘れ物は上達の近道にはならないので、文の内容に合わない。"}, {"text": "悩み", "is_correct": false, "explanation": "悩みは上達の近道にはならず、「学んで、試して」の流れに合わない。"}], "explanations": {"ループ": "学びと試行が繰り返される循環の意味で、「上達の近道」と合う。", "寝坊": "寝坊は上達の近道にはならないので、文の内容に合わない。", "忘れ物": "忘れ物は上達の近道にはならないので、文の内容に合わない。", "悩み": "悩みは上達の近道にはならず、「学んで、試して」の流れに合わない。"}, "sentence_index": 6, "correct_answer": "ループ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ホースのループを外して、庭に水をまきました。", "explanation": "ここは〈ホース〉の輪の意味。循環や繰り返しの仕組みを指す定義とは違う。"}, {"text": "財布のループに、お札をはさんで入れました。", "explanation": "ここは〈輪の留め具〉の意味。循環や繰り返しの仕組みを指す定義とは違う。"}, {"text": "時計のループをはずして、腕をふきました。", "explanation": "ここは〈バンドの輪〉の意味。循環や繰り返しの仕組みを指す定義とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38067, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "悪いループに抜け出せません。", "corrected_sentence": "悪いループから抜け出せません。", "error_description": "誤りは助詞「に」。「抜け出す」は出る場所を「から」で表すので「ループから」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38067, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ作業のループに止めたいです。", "corrected_sentence": "同じ作業のループを止めたいです。", "error_description": "誤りは助詞「に」。「止める」は目的語を取るので「ループを止めたい」が正しい。「ループに止めたい」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語を「が」で示すので、「低い垣根がある」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は「を」を取らないので、存在するものを示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、存在するものの主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「ある」とは結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語を「が」で示すので、「低い垣根がある」と自然につながる。", "を": "「ある」は「を」を取らないので、存在するものを示せない。", "で": "「で」は場所や手段を表し、存在するものの主語にはならない。", "へ": "「へ」は方向を表し、「ある」とは結びつかない。"}, "error_tags": {"を": "目的格（「ある」とは結びつかない）", "で": "場所・手段（存在の主語にならない）", "へ": "方向（「ある」とは結びつかない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」で、垣根のすき間という所属関係を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、垣根が猫の動作の主語になり、すき間を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や方向を示し、すき間の所属を表せない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」で、すき間とは結びつかない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」で、垣根のすき間という所属関係を示す。", "が": "「が」は主語を示すので、垣根が猫の動作の主語になり、すき間を示せない。", "に": "「に」は位置や方向を示し、すき間の所属を表せない。", "と": "並列・共同の「と」で、すき間とは結びつかない。"}, "error_tags": {"が": "主格（垣根を主語にすると意味が崩れる）", "に": "位置・方向（所属を示せない）", "と": "並列（すき間とは結びつかない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "庭や家の境に作られた、木や竹などの囲い。", "primary_collocate": null, "pronunciation": "かきね", "ipa": "kakine", "syllable_count": 3, "sentences": [{"text": "庭の垣根にバラの花が咲いている。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "庭[にわ]の垣根[かきね]にバラの花[はな]が咲[さ]いている。", "sentence_source": "generated"}, {"text": "隣の家との間に低い垣根がある。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]との間[あいだ]に低[ひく]い垣根[かきね]がある。", "sentence_source": "generated"}, {"text": "犬が垣根の下をくぐって道に出てしまった。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "犬[いぬ]が垣根[かきね]の下[した]をくぐって道[みち]に出[で]てしまった。", "sentence_source": "generated"}, {"text": "父は毎年、秋に庭の垣根を刈っている。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "父[ちち]は毎年[まいとし]、秋[あき]に庭[にわ]の垣根[かきね]を刈[か]っている。", "sentence_source": "generated"}, {"text": "垣根が高いので、隣の庭の様子は見えない。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "垣根[かきね]が高[たか]いので、隣[となり]の庭[にわ]の様子[ようす]は見[み]えない。", "sentence_source": "generated"}, {"text": "ボールが垣根を越えて、隣の庭に入ってしまった。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "ボールが垣根[かきね]を越[こ]えて、隣[となり]の庭[にわ]に入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "古い垣根が壊れたため、新しいものに作り直した。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "古[ふる]い垣根[かきね]が壊[こわ]れたため、新[あたら]しいものに作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "垣根のすき間から猫が顔を出した。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "垣根[かきね]のすき間[ま]から猫[ねこ]が顔[かお]を出[だ]した。", "sentence_source": "generated"}, {"text": "垣根のそばに小さな花を植えた。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "垣根[かきね]のそばに小[ちい]さな花[はな]を植[う]えた。", "sentence_source": "generated"}, {"text": "台風で垣根が倒れ、庭が道から丸見えになった。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "台風[たいふう]で垣根[かきね]が倒[たお]れ、庭[にわ]が道[みち]から丸見[まるみ]えになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "垣根", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "垣根: 庭や家の境に作られた、木や竹などの囲い(実物の垣)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垣根", "is_correct": true, "explanation": "垣根は植物や竹でできた囲いで、バラを這わせて花を咲かせる場所になる。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、花が咲く場所ではない。"}, {"text": "蛇口", "is_correct": false, "explanation": "蛇口は水を出す器具で、花が咲く場所ではない。"}, {"text": "郵便受け", "is_correct": false, "explanation": "郵便受けは手紙を入れる箱で、花が咲く場所ではない。"}], "explanations": {"垣根": "垣根は植物や竹でできた囲いで、バラを這わせて花を咲かせる場所になる。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、花が咲く場所ではない。", "蛇口": "蛇口は水を出す器具で、花が咲く場所ではない。", "郵便受け": "郵便受けは手紙を入れる箱で、花が咲く場所ではない。"}, "sentence_index": 0, "correct_answer": "垣根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "泥棒を防ぐため、庭の垣根をコンクリートで固めた。", "explanation": "ここは〈塀〉の意味。垣根は植物や竹でできた囲いなので、コンクリートで固める対象ではない。"}, {"text": "地震に備えて、庭の垣根を積み直した。", "explanation": "ここは〈石垣〉の意味。垣根は石を積んで作るものではないので、積み直す対象には合わない。"}, {"text": "夜になったので、庭の垣根を閉めて鍵をかけた。", "explanation": "ここは〈門〉の意味。垣根には閉めたり鍵をかけたりする扉がないので、門の代わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垣根", "is_correct": true, "explanation": "垣根は壊れたら作り直せる囲いで、古い垣根が壊れて新しく作り直す文脈に合う。"}, {"text": "電子レンジ", "is_correct": false, "explanation": "電子レンジは食べ物を温める家電で、壊れたら買い替えるもので、作り直す対象ではない。"}, {"text": "植木", "is_correct": false, "explanation": "植木は植えてある木で、作り直す対象にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は読んで学ぶ本で、壊れて作り直す対象ではない。"}], "explanations": {"垣根": "垣根は壊れたら作り直せる囲いで、古い垣根が壊れて新しく作り直す文脈に合う。", "電子レンジ": "電子レンジは食べ物を温める家電で、壊れたら買い替えるもので、作り直す対象ではない。", "植木": "植木は植えてある木で、作り直す対象にはならない。", "教科書": "教科書は読んで学ぶ本で、壊れて作り直す対象ではない。"}, "sentence_index": 6, "correct_answer": "垣根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨でぬかるんだので、垣根を舗装した。", "explanation": "ここは〈道路〉の意味。舗装は道路の表面を固めることなので、植物でできた垣根には使えない。"}, {"text": "寒い冬は、垣根に断熱材を入れると家が暖かくなる。", "explanation": "ここは〈壁〉の意味。断熱材は建物の壁に入れるもので、垣根に入れるものではないので合わない。"}, {"text": "嵐の中、垣根を開けて客を招き入れた。", "explanation": "ここは〈玄関〉の意味。客を迎え入れる出入り口は玄関で、垣根は人を通す入口にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は、庭の垣根を青い朝顔をからませた。", "corrected_sentence": "母は、庭の垣根に青い朝顔をからませた。", "error_description": "「からませる」は絡ませる先を「に」で示す。「垣根を」と「を」を使うと垣根が対象になり不自然。正しくは「垣根に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38070, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は、裏庭の垣根を割った。", "corrected_sentence": "祖父は、裏庭の垣根を刈った。", "error_description": "垣根は「刈る」で手入れする。「割る」は硬いものを砕く動詞で、垣根には使わない。正しくは「刈った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「言葉の垣根」と名詞を結び、「言葉による隔たり」という修飾関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。ここは「言葉」と「垣根」を結ぶ修飾なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「言葉と垣根」は二つを並べるだけで、「言葉の垣根」という一つの隔たりを表せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「言葉で垣根」では名詞同士を結べず、ここには入らない。"}], "correct_answer": "の", "explanations": {"の": "「言葉の垣根」と名詞を結び、「言葉による隔たり」という修飾関係を示す。", "を": "「を」は動作の対象を示す。ここは「言葉」と「垣根」を結ぶ修飾なので合わない。", "と": "「と」は並列や相手を示す。「言葉と垣根」は二つを並べるだけで、「言葉の垣根」という一つの隔たりを表せない。", "で": "「で」は場所や手段を示す。「言葉で垣根」では名詞同士を結べず、ここには入らない。"}, "error_tags": {"を": "object", "で": "location/means", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「越えた」の対象を示す。垣根は越えられる対象なので「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示す。「垣根に越えた」では対象が示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「垣根へ越えた」は、越える対象ではなく向かう先を示してしまう。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「垣根と越えた」は動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「越えた」の対象を示す。垣根は越えられる対象なので「を」が正しい。", "に": "「に」は到達点や相手を示す。「垣根に越えた」では対象が示せず不自然。", "へ": "「へ」は方向を示す。「垣根へ越えた」は、越える対象ではなく向かう先を示してしまう。", "と": "「と」は相手や並列を示す。「垣根と越えた」は動作の対象にならない。"}, "error_tags": {"に": "indirect target", "へ": "direction", "と": "companion"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "境界や区切りとなるもの。また、互いの間にある違いや隔たり。", "primary_collocate": null, "pronunciation": "かきね", "ipa": "kakine", "syllable_count": 3, "sentences": [{"text": "国と国の間にある垣根を取り払うために、話し合いが続いている。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "国[くに]と国[くに]の間[あいだ]にある垣根[かきね]を取[と]り払[はら]うために、話[はな]し合[あ]いが続[つづ]いている。", "sentence_source": "generated"}, {"text": "音楽には言葉の垣根を越える力がある。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "音楽[おんがく]には言葉[ことば]の垣根[かきね]を越[こ]える力[ちから]がある。", "sentence_source": "generated"}, {"text": "二つの会社は、業種の垣根を越えて協力することにした。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は、業種[ぎょうしゅ]の垣根[かきね]を越[こ]えて協力[きょうりょく]することにした。", "sentence_source": "generated"}, {"text": "年齢の垣根がなく、誰とでも仲良くなれる人だ。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "年齢[ねんれい]の垣根[かきね]がなく、誰[だれ]とでも仲良[なかよ]くなれる人[ひと]だ。", "sentence_source": "generated"}, {"text": "男女の垣根をなくした職場づくりを目指している。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "男女[だんじょ]の垣根[かきね]をなくした職場[しょくば]づくりを目指[めざ]している。", "sentence_source": "generated"}, {"text": "彼女は先生と生徒という垣根を気にせず、気軽に話しかけてくれる。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は先生[せんせい]と生徒[せいと]という垣根[かきね]を気[き]にせず、気軽[きがる]に話[はな]しかけてくれる。", "sentence_source": "generated"}, {"text": "スポーツは国籍の垣根を越えて人々をつなぐ。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "スポーツは国籍[こくせき]の垣根[かきね]を越[こ]えて人々[ひとびと]をつなぐ。", "sentence_source": "generated"}, {"text": "学部の垣根を越えた研究が、新しい発見につながった。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "学部[がくぶ]の垣根[かきね]を越[こ]えた研究[けんきゅう]が、新[あたら]しい発見[はっけん]につながった。", "sentence_source": "generated"}, {"text": "長い間、二つの地域の間には心の垣根があった。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]、二[ふた]つの地域[ちいき]の間[あいだ]には心[こころ]の垣根[かきね]があった。", "sentence_source": "generated"}, {"text": "最初は垣根を感じていたが、一緒に働くうちに打ち解けた。", "target_word": "垣根", "complexity_tier": "T3", "furigana": "最初[さいしょ]は垣根[かきね]を感[かん]じていたが、一緒[いっしょ]に働[はたら]くうちに打[う]ち解[と]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "垣根", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "垣根: 人・国・分野などの間にある目に見えない隔たりや壁(比喩)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垣根", "is_correct": true, "explanation": "「国と国の間にある隔たり」を指し、「取り払う」と合う。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入り口で、国と国の間にある隔たりを取り払うという文脈には入らない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車などに使う紙片で、国の間にあって取り払う対象にはならない。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本で、国の間に置かれて取り払うものではない。"}], "explanations": {"垣根": "「国と国の間にある隔たり」を指し、「取り払う」と合う。", "玄関": "建物の出入り口で、国と国の間にある隔たりを取り払うという文脈には入らない。", "切符": "乗車などに使う紙片で、国の間にあって取り払う対象にはならない。", "辞書": "言葉を調べる本で、国の間に置かれて取り払うものではない。"}, "sentence_index": 0, "correct_answer": "垣根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は英語の垣根が広く、どんな話題にもついていける。", "explanation": "ここは〈幅〉の意味。能力や知識の広さは垣根ではなく幅で言うので合わない。"}, {"text": "来週の垣根が決まった。", "explanation": "ここは〈予定〉の意味。予定が決まることは垣根とは言わないので合わない。"}, {"text": "彼は仕事の垣根を三つ抱えて、休む暇がない。", "explanation": "ここは〈案件〉の意味。抱えるのは案件や仕事で、垣根は抱えるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垣根", "is_correct": true, "explanation": "国籍などの間にある目に見えない隔たりを指し、「越える」と合う。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部で、国籍の間の隔たりを越えるという文には入らない。"}, {"text": "鍵", "is_correct": false, "explanation": "戸を開け閉めする道具で、国籍の隔たりを越える対象にはならない。"}, {"text": "地図", "is_correct": false, "explanation": "場所を示す図で、国籍の隔たりを越えるものとして成り立たない。"}], "explanations": {"垣根": "国籍などの間にある目に見えない隔たりを指し、「越える」と合う。", "窓": "建物の開口部で、国籍の間の隔たりを越えるという文には入らない。", "鍵": "戸を開け閉めする道具で、国籍の隔たりを越える対象にはならない。", "地図": "場所を示す図で、国籍の隔たりを越えるものとして成り立たない。"}, "sentence_index": 6, "correct_answer": "垣根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は確かな垣根を示して、無実を証明した。", "explanation": "ここは〈証拠〉の意味。無実を示すのは証拠で、垣根は証明の材料にならないので合わない。"}, {"text": "先生は大きな垣根を出して、答えを考えさせた。", "explanation": "ここは〈ヒント〉の意味。出すのはヒントで、垣根は出すものではないので合わない。"}, {"text": "彼は垣根をこめて、母に手紙を書いた。", "explanation": "ここは〈気持ち〉の意味。こめるのは気持ちで、垣根は込めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この企画は部署の垣根が越えて、全員が参加できる。", "corrected_sentence": "この企画は部署の垣根を越えて、全員が参加できる。", "error_description": "「越える」の目的語は「垣根」なので、垣根の直後は「を」が正しい。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38071, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学部の垣根を越いた共同研究が、新しい発見につながった。", "corrected_sentence": "学部の垣根を越えた共同研究が、新しい発見につながった。", "error_description": "「越える」の活用が誤り。正しくは「越えた」。垣根に付く動詞の活用を誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「電車やバスで」と範囲を示し、通用の使える場所を表す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示す。「バスに通用する」では範囲の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。通用は目的語を取らず、「バスを通用する」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「電車やバスから通用する」は使える範囲を表せない。"}], "correct_answer": "で", "explanations": {"で": "「電車やバスで」と範囲を示し、通用の使える場所を表す。", "に": "「に」は到達点や相手を示す。「バスに通用する」では範囲の意味にならない。", "を": "「を」は目的語を示す。通用は目的語を取らず、「バスを通用する」は成り立たない。", "から": "「から」は起点を示す。「電車やバスから通用する」は使える範囲を表せない。"}, "error_tags": {"に": "direction", "を": "object", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「書店で」と場所を示し、どの店で使えるかを表す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「書店へ通用する」は場所の範囲にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「書店と通用する」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「書店から通用する」は使える範囲を表せない。"}], "correct_answer": "で", "explanations": {"で": "「書店で」と場所を示し、どの店で使えるかを表す。", "へ": "「へ」は方向を示す。「書店へ通用する」は場所の範囲にならない。", "と": "「と」は相手や並列を示す。「書店と通用する」は成り立たない。", "から": "「から」は起点を示す。「書店から通用する」は使える範囲を表せない。"}, "error_tags": {"へ": "direction", "と": "companion", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんながつかえること。", "primary_collocate": null, "pronunciation": "つうよう", "ipa": "tsɯːjoː", "syllable_count": 4, "sentences": [{"text": "この切符は、JRのどの路線でも通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "この切符[きっぷ]は、JRのどの路線[ろせん]でも通用[つうよう]する。", "sentence_source": "generated"}, {"text": "このICカードは、全国のほとんどの電車やバスで通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "このICカードは、全国[ぜんこく]のほとんどの電車[でんしゃ]やバスで通用[つうよう]する。", "sentence_source": "generated"}, {"text": "この商品券は、市内のすべての店で通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "この商品券[しょうひんけん]は、市内[しない]のすべての店[みせ]で通用[つうよう]する。", "sentence_source": "generated"}, {"text": "このパスは、大人にも子どもにも通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "このパスは、大人[おとな]にも子[こ]どもにも通用[つうよう]する。", "sentence_source": "generated"}, {"text": "昔の百円玉は、今でも自動販売機で通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "昔[むかし]の百円玉[ひゃくえんだま]は、今[いま]でも自動販売機[じどうはんばいき]で通用[つうよう]する。", "sentence_source": "generated"}, {"text": "この回数券は、バスにも地下鉄にも通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "この回数券[かいすうけん]は、バスにも地下鉄[ちかてつ]にも通用[つうよう]する。", "sentence_source": "generated"}, {"text": "このパスは、家族のだれが使っても通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "このパスは、家族[かぞく]のだれが使[つか]っても通用[つうよう]する。", "sentence_source": "generated"}, {"text": "この図書カードは、全国の書店で通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "この図書[としょ]カードは、全国[ぜんこく]の書店[しょてん]で通用[つうよう]する。", "sentence_source": "generated"}, {"text": "学生証は、市内の博物館や美術館で通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "学生証[がくせいしょう]は、市内[しない]の博物館[はくぶつかん]や美術館[びじゅつかん]で通用[つうよう]する。", "sentence_source": "generated"}, {"text": "この共通券は、五つの施設すべてで通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "この共通券[きょうつうけん]は、五[いつ]つの施設[しせつ]すべてで通用[つうよう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用する", "label": "動詞形(サ変)"}], "register": "neutral", "sense_fingerprint": "通用: 切符・カード・券などが、場所や人を問わず共通して使えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "その切符が路線を問わず使えることを表し、文に合う。"}, {"text": "走行", "is_correct": false, "explanation": "乗り物が走ることを言う。切符は走行しないので文が成り立たない。"}, {"text": "掃除", "is_correct": false, "explanation": "場所をきれいにする行為で、切符は掃除の対象ではなく文に合わない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す行為で、切符は修理するものとして文に合わない。"}], "explanations": {"通用": "その切符が路線を問わず使えることを表し、文に合う。", "走行": "乗り物が走ることを言う。切符は走行しないので文が成り立たない。", "掃除": "場所をきれいにする行為で、切符は掃除の対象ではなく文に合わない。", "修理": "壊れたものを直す行為で、切符は修理するものとして文に合わない。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このバスは毎日、通用している。", "explanation": "ここは〈利用〉の意味。個人が毎日使うことは言わず、使える範囲を示す通用は合わない。"}, {"text": "この道は通用止めだ。", "explanation": "ここは〈通行〉の意味。道を人や車が通ることの話で、通用とは言わない。"}, {"text": "電波が悪くて、通用が途絶えた。", "explanation": "ここは〈通信〉の意味。電波で情報が届く話で、券などが使える話ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "家族のだれが使っても使えることを表し、文に合う。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売ることで、パスを使う人にかかる文脈では成り立たない。"}, {"text": "保管", "is_correct": false, "explanation": "物をしまっておくことで、だれが使っても、という文には合わない。"}, {"text": "監視", "is_correct": false, "explanation": "見張ることで、パスを使う人の違いを述べる文には入らない。"}], "explanations": {"通用": "家族のだれが使っても使えることを表し、文に合う。", "販売": "商品を売ることで、パスを使う人にかかる文脈では成り立たない。", "保管": "物をしまっておくことで、だれが使っても、という文には合わない。", "監視": "見張ることで、パスを使う人の違いを述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今回の試験は、三回目の挑戦でようやく通用した。", "explanation": "ここは〈合格〉の意味。試験に受かることは合格・通ると言い、通用とは言わないので合わない。"}, {"text": "夜の時間が、すっかり通用した。", "explanation": "ここは〈過ぎる〉の意味。時間が流れて過ぎることは過ぎると言い、通用とは言わないので合わない。"}, {"text": "必要な人数が通用した。", "explanation": "ここは〈足りる〉の意味。必要な数がそろうことは足りると言い、通用とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この定期券は、JRのどの路線を通用する。", "corrected_sentence": "この定期券は、JRのどの路線でも通用する。", "error_description": "「通用する」は範囲を示す「でも」と使う。「を」は目的語で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38072, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この割引券は、全国の店で通用しる。", "corrected_sentence": "この割引券は、全国の店で通用する。", "error_description": "「通用する」の活用が誤り。終止形は「通用する」で、「通用しる」は存在しない形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
