INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38073, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "広く一般に使われること。また、有効であること。", "primary_collocate": null, "pronunciation": "つうよう", "ipa": "tsɯːjoː", "syllable_count": 4, "sentences": [{"text": "英語は世界の多くの国で通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "英語[えいご]は世界[せかい]の多[おお]くの国[くに]で通用[つうよう]する。", "sentence_source": "generated"}, {"text": "そんな言い訳は、私には通用しない。", "target_word": "通用", "complexity_tier": "T3", "furigana": "そんな言[い]い訳[わけ]は、私[わたし]には通用[つうよう]しない。", "sentence_source": "generated"}, {"text": "日本の常識が海外では通用しないこともある。", "target_word": "通用", "complexity_tier": "T3", "furigana": "日本[にほん]の常識[じょうしき]が海外[かいがい]では通用[つうよう]しないこともある。", "sentence_source": "generated"}, {"text": "彼の実力は、プロの世界でも通用すると思う。", "target_word": "通用", "complexity_tier": "T3", "furigana": "彼[かれ]の実力[じつりょく]は、プロの世界[せかい]でも通用[つうよう]すると思[おも]う。", "sentence_source": "generated"}, {"text": "昔の考え方は、今の社会では通用しなくなった。", "target_word": "通用", "complexity_tier": "T3", "furigana": "昔[むかし]の考[かんが]え方[かた]は、今[いま]の社会[しゃかい]では通用[つうよう]しなくなった。", "sentence_source": "generated"}, {"text": "このことわざは、日本中で通用している。", "target_word": "通用", "complexity_tier": "T3", "furigana": "このことわざは、日本中[にほんじゅう]で通用[つうよう]している。", "sentence_source": "generated"}, {"text": "学校での成績が、社会に出ても通用するとは限らない。", "target_word": "通用", "complexity_tier": "T3", "furigana": "学校[がっこう]での成績[せいせき]が、社会[しゃかい]に出[で]ても通用[つうよう]するとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "その方法は、この会社でしか通用しない。", "target_word": "通用", "complexity_tier": "T3", "furigana": "その方法[ほうほう]は、この会社[かいしゃ]でしか通用[つうよう]しない。", "sentence_source": "generated"}, {"text": "簡単な日本語でも、旅行なら十分に通用する。", "target_word": "通用", "complexity_tier": "T3", "furigana": "簡単[かんたん]な日本語[にほんご]でも、旅行[りょこう]なら十分[じゅうぶん]に通用[つうよう]する。", "sentence_source": "generated"}, {"text": "子どもだましの手は、もう通用しない。", "target_word": "通用", "complexity_tier": "T3", "furigana": "子[こ]どもだましの手[て]は、もう通用[つうよう]しない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用する", "label": "動詞形(サ変)"}, {"form": "通用しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "通用: 言葉・常識・実力・手などが広く認められ、効き目を持つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54768d52-ea97-4604-bce7-54e5692f6771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38073, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "英語が多くの国で使われ認められることを表し、文に合う。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点をつけることで、言語が国で認められるという文には合わない。"}, {"text": "解体", "is_correct": false, "explanation": "組み立てたものを分けることで、言語の広がりを述べる文には入らない。"}, {"text": "掃除", "is_correct": false, "explanation": "場所をきれいにする行為で、言語が広く認められる文脈では成り立たない。"}], "explanations": {"通用": "英語が多くの国で使われ認められることを表し、文に合う。", "採点": "答案に点をつけることで、言語が国で認められるという文には合わない。", "解体": "組み立てたものを分けることで、言語の広がりを述べる文には入らない。", "掃除": "場所をきれいにする行為で、言語が広く認められる文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会社に退職の通用を伝えた。", "explanation": "ここは〈通告〉の意味。退職を相手に告げるのは通告で、通用とは言わないので合わない。"}, {"text": "市民は、決まりの通用に従うことができる。", "explanation": "ここは〈決まり〉の意味。従うのは決まりや規則で、通用は従う対象にならないので合わない。"}, {"text": "合格の通用が届いた。", "explanation": "ここは〈通知〉の意味。知らせを送る話で、有効性を言う通用は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38073, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "学校の成績が社会で認められるかどうかを表し、「限らない」と合う。"}, {"text": "発熱", "is_correct": false, "explanation": "体温が上がることで、社会に出ても、という文には合わない。"}, {"text": "着席", "is_correct": false, "explanation": "席につくことで、成績が社会で認められるかという文には入らない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗り物に乗ることで、成績の話には成り立たない。"}], "explanations": {"通用": "学校の成績が社会で認められるかどうかを表し、「限らない」と合う。", "発熱": "体温が上がることで、社会に出ても、という文には合わない。", "着席": "席につくことで、成績が社会で認められるかという文には入らない。", "乗車": "乗り物に乗ることで、成績の話には成り立たない。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察に通用の届けを出した。", "explanation": "ここは〈届け出〉の意味。届けを出すのは届け出で、通用とは言わないので合わない。"}, {"text": "毎日、会社に通用する。", "explanation": "ここは〈通う〉の意味。決まった場所へ行き来することは通用とは言わない。"}, {"text": "電話が通用しない。", "explanation": "ここは〈通じる〉の意味。回線がつながる話で、言葉や常識が認められる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38073, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その理屈は、世界を通用する。", "corrected_sentence": "その理屈は、世界で通用する。", "error_description": "「通用する」は範囲を示す「で」と使う。「を」は目的語で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38073, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その資格が、社会に出ても通用をするとは限らない。", "corrected_sentence": "その資格が、社会に出ても通用するとは限らない。", "error_description": "「通用する」は目的語を取らないので、「通用を」の「を」は余分で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad939a67-10e6-4aac-b1ab-eaedf74e7fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
