INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38074, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものが、高いか低いかのこと。", "primary_collocate": null, "pronunciation": "こうてい", "ipa": "koːteː", "syllable_count": 4, "sentences": [{"text": "この道は高低が激しくて、自転車で走るのが大変だ。", "target_word": "高低", "complexity_tier": "T3", "furigana": "この道[みち]は高低[こうてい]が激[はげ]しくて、自転車[じてんしゃ]で走[はし]るのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "土地の高低に合わせて、家の庭を三段に作った。", "target_word": "高低", "complexity_tier": "T3", "furigana": "土地[とち]の高低[こうてい]に合[あ]わせて、家[いえ]の庭[にわ]を三段[さんだん]に作[つく]った。", "sentence_source": "generated"}, {"text": "屋根の高低がばらばらで、この町並みは独特だ。", "target_word": "高低", "complexity_tier": "T3", "furigana": "屋根の高低[こうてい]がばらばらで、この町並みは独特だ。", "sentence_source": "generated"}, {"text": "床に高低があるので、椅子がぐらついてしまう。", "target_word": "高低", "complexity_tier": "T3", "furigana": "床に高低[こうてい]があるので、椅子がぐらついてしまう。", "sentence_source": "generated"}, {"text": "山道は高低が多いので、ゆっくり歩いた。", "target_word": "高低", "complexity_tier": "T3", "furigana": "山道[やまみち]は高低[こうてい]が多[おお]いので、ゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "この地域は高低が激しく、家の多くは斜面に建っている。", "target_word": "高低", "complexity_tier": "T3", "furigana": "この地域は高低[こうてい]が激しく、家の多くは斜面に建っている。", "sentence_source": "generated"}, {"text": "地図の線で、土地の高低がよくわかる。", "target_word": "高低", "complexity_tier": "T3", "furigana": "地図[ちず]の線[せん]で、土地[とち]の高低[こうてい]がよくわかる。", "sentence_source": "generated"}, {"text": "道路の高低が少ないので、荷物を積んだ台車でも押しやすい。", "target_word": "高低", "complexity_tier": "T3", "furigana": "道路の高低[こうてい]が少ないので、荷物を積んだ台車でも押しやすい。", "sentence_source": "generated"}, {"text": "波の高低が大きい日は、船が止まる。", "target_word": "高低", "complexity_tier": "T3", "furigana": "波[なみ]の高低[こうてい]が大[おお]きい日[ひ]は、船[ふね]が止[と]まる。", "sentence_source": "generated"}, {"text": "この庭は石の高低をつけて、池のまわりを囲んでいる。", "target_word": "高低", "complexity_tier": "T3", "furigana": "この庭は石の高低[こうてい]をつけて、池のまわりを囲んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高低", "label": "基本形"}, {"form": "高低の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "ものの位置や音が高いか低いか、その差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38074, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高低", "is_correct": true, "explanation": "正解。「この道は〜が激しい」で、道の凹凸（高いところと低いところの差）を表す。"}, {"text": "体温", "is_correct": false, "explanation": "人や動物の体の熱の度合いのことで、道の起伏には当てはまらない。「体温が激しい」も不自然。"}, {"text": "手触り", "is_correct": false, "explanation": "手で触れたときの感じのことで、道の起伏の激しさを表す語としては合わない。"}, {"text": "色合い", "is_correct": false, "explanation": "色の組み合わせや濃淡のことで、道の起伏には使えない。"}], "explanations": {"高低": "正解。「この道は〜が激しい」で、道の凹凸（高いところと低いところの差）を表す。", "体温": "人や動物の体の熱の度合いのことで、道の起伏には当てはまらない。「体温が激しい」も不自然。", "手触り": "手で触れたときの感じのことで、道の起伏の激しさを表す語としては合わない。", "色合い": "色の組み合わせや濃淡のことで、道の起伏には使えない。"}, "sentence_index": 0, "correct_answer": "高低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本は高低が五センチもあって、持ち運ぶのが大変だ。", "explanation": "ここは〈厚さ〉の意味。高低は高いところと低いところの差を言うので、本の厚みには使わない。"}, {"text": "この荷物は高低が五キロもあって、一人では持てない。", "explanation": "ここは〈重さ〉の意味。重さは重さで表し、高低は上下の差の状態なので、目方には使わない。"}, {"text": "この道は高低が狭くて、車がすれ違えない。", "explanation": "ここは〈幅〉の意味。道の横の広さは幅で表し、高低は上下の差なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38074, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高低", "is_correct": true, "explanation": "正解。地図の線で土地の起伏がわかる、という文脈に合う。"}, {"text": "重さ", "is_correct": false, "explanation": "地図の線からは土地の重さはわからず、意味が通らない。"}, {"text": "音量", "is_correct": false, "explanation": "土地に音量はなく、地図でも示せないので合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "土地に寿命という概念を当てはめる文脈ではない。"}], "explanations": {"高低": "正解。地図の線で土地の起伏がわかる、という文脈に合う。", "重さ": "地図の線からは土地の重さはわからず、意味が通らない。", "音量": "土地に音量はなく、地図でも示せないので合わない。", "寿命": "土地に寿命という概念を当てはめる文脈ではない。"}, "sentence_index": 6, "correct_answer": "高低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関に高低が一か所あるので、車椅子では家に入れない。", "explanation": "ここは〈段差〉の意味。一つの段の差は段差と言い、高低は全体の上下の差を表すので、一か所の段について言う使い方には合わない。"}, {"text": "この飛行機は高低を下げて、着陸の準備に入った。", "explanation": "ここは〈高度〉の意味。高度は上げ下げできる一つの高さを表すが、高低は上下の差の状態なので、下げるという動作の目的語にはならない。"}, {"text": "このビルは高低が百メートルあり、町で一番目立つ。", "explanation": "ここは〈高さ〉の意味。建物の一つの高さは高さと言い、高低は上下の差や入り混じった状態を指すので、一つの建物の高さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38074, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この坂は高低に激しくて、自転車では上れない。", "corrected_sentence": "この坂は高低が激しくて、自転車では上れない。", "error_description": "「高低」が「激しい」の主語になるので、直後の助詞は「が」が正しい。「高低に激しい」は成り立たない。誤りは助詞「に」（正しくは「が」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38074, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地図では、高低激しい山道の様子が一目でわかる。", "corrected_sentence": "この地図では、高低の激しい山道の様子が一目でわかる。", "error_description": "「高低」が「激しい」を連体修飾する形では、助詞「の」が必要。「高低激しい」は名詞と形容詞が直接つながって不自然。誤りは「の」の欠落。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「値段の高低に」の形で「かかわらず」と結びつく。"}, {"text": "が", "is_correct": false, "explanation": "「値段の高低が」は主語の形になり、「かかわらず」の前には「に」が必要なので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「高低を」は目的語の形で、「かかわらず」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「高低へ」は方向を表すが、「かかわらず」の前には使えず不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「値段の高低に」の形で「かかわらず」と結びつく。", "が": "「値段の高低が」は主語の形になり、「かかわらず」の前には「に」が必要なので合わない。", "を": "「高低を」は目的語の形で、「かかわらず」と結びつかない。", "へ": "「高低へ」は方向を表すが、「かかわらず」の前には使えず不自然。"}, "error_tags": {"が": "主格", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数量や程度が、上であるか下であるかという状態。", "primary_collocate": null, "pronunciation": "こうてい", "ipa": "koːteː", "syllable_count": 4, "sentences": [{"text": "気温の高低が大きく、体調を崩す人が多い。", "target_word": "高低", "complexity_tier": "T3", "furigana": "気温[きおん]の高低[こうてい]が大[おお]きく、体調[たいちょう]を崩[くず]す人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "値段の高低にかかわらず、品質はどれも同じだ。", "target_word": "高低", "complexity_tier": "T3", "furigana": "値段[ねだん]の高低[こうてい]にかかわらず、品質[ひんしつ]はどれも同[おな]じだ。", "sentence_source": "generated"}, {"text": "成績の高低で、クラスを分けることはしない。", "target_word": "高低", "complexity_tier": "T3", "furigana": "成績[せいせき]の高低[こうてい]で、クラスを分[わ]けることはしない。", "sentence_source": "generated"}, {"text": "為替の高低を見て、買う時期を決めた。", "target_word": "高低", "complexity_tier": "T3", "furigana": "為替[かわせ]の高低[こうてい]を見[み]て、買[か]う時期[じき]を決[き]めた。", "sentence_source": "generated"}, {"text": "気圧の高低が変わると、頭が痛くなる人がいる。", "target_word": "高低", "complexity_tier": "T3", "furigana": "気圧の高低[こうてい]が変わると、頭が痛くなる人がいる。", "sentence_source": "generated"}, {"text": "物価の高低は、地域によって差がある。", "target_word": "高低", "complexity_tier": "T3", "furigana": "物価[ぶっか]の高低[こうてい]は、地域[ちいき]によって差[さ]がある。", "sentence_source": "generated"}, {"text": "血圧の高低を毎朝記録している。", "target_word": "高低", "complexity_tier": "T3", "furigana": "血圧[けつあつ]の高低[こうてい]を毎朝[まいあさ]記録[きろく]している。", "sentence_source": "generated"}, {"text": "給料の高低だけで、仕事を選ばないほうがいい。", "target_word": "高低", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]の高低[こうてい]だけで、仕事[しごと]を選[えら]ばないほうがいい。", "sentence_source": "generated"}, {"text": "湿度の高低によって、部屋の快適さが変わる。", "target_word": "高低", "complexity_tier": "T3", "furigana": "湿度[しつど]の高低[こうてい]によって、部屋[へや]の快適[かいてき]さが変[か]わる。", "sentence_source": "generated"}, {"text": "人気の高低は、売り上げに大きく影響する。", "target_word": "高低", "complexity_tier": "T3", "furigana": "人気[にんき]の高低[こうてい]は、売[う]り上[あ]げに大[おお]きく影響[えいきょう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高低", "label": "基本形"}, {"form": "高低の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "数値や程度の上下、その差や違い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高低", "is_correct": true, "explanation": "正解。「気温の〜が大きく」で、気温の上がり下がりの差を表す。"}, {"text": "音色", "is_correct": false, "explanation": "楽器や声の響きのことで、気温には当てはまらない。"}, {"text": "寿命", "is_correct": false, "explanation": "生き物や物が続く期間のことで、気温の差には使わない。"}, {"text": "香り", "is_correct": false, "explanation": "においのことで、気温の差を表す文脈には合わない。"}], "explanations": {"高低": "正解。「気温の〜が大きく」で、気温の上がり下がりの差を表す。", "音色": "楽器や声の響きのことで、気温には当てはまらない。", "寿命": "生き物や物が続く期間のことで、気温の差には使わない。", "香り": "においのことで、気温の差を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "高低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は一日の高低を三錠と決められている。", "explanation": "ここは〈これ以上は超えない量〉の意味の〈上限〉。高低は上下の差の状態で、三錠という量の上限を決める言い方にはならない。"}, {"text": "この店は来月の客数を三割高低させる計画だ。", "explanation": "ここは〈増やしたり減らしたりする〉の意味の〈増減〉。高低は上下の差や状態を表し、客数を三割動かすという変化の動詞としては使わない。"}, {"text": "この会社は、昨年の売上を高低して、今年の目標を決めた。", "explanation": "ここは〈比べて調べる〉の意味の〈比較〉。高低は上下の差や状態で、売上を比べて調べる動作の動詞にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高低", "is_correct": true, "explanation": "正解。「血圧の〜を毎朝記録している」で、血圧の上がり下がりの値を表す。"}, {"text": "色彩", "is_correct": false, "explanation": "色の組み合わせのことで、血圧の記録とは結びつかない。"}, {"text": "音階", "is_correct": false, "explanation": "音の高さの並びのことで、血圧には当てはまらない。"}, {"text": "柔らかさ", "is_correct": false, "explanation": "触ったときの感じのことで、血圧の記録の対象にはならない。"}], "explanations": {"高低": "正解。「血圧の〜を毎朝記録している」で、血圧の上がり下がりの値を表す。", "色彩": "色の組み合わせのことで、血圧の記録とは結びつかない。", "音階": "音の高さの並びのことで、血圧には当てはまらない。", "柔らかさ": "触ったときの感じのことで、血圧の記録の対象にはならない。"}, "sentence_index": 6, "correct_answer": "高低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は品質の高低を保ち、どの商品も安心して買える。", "explanation": "ここは〈一定の水準〉の意味。高低は上下の差を言うので、水準を保つという使い方にはならない。"}, {"text": "この株は今年の春、高低を更新して市場を驚かせた。", "explanation": "ここは〈最高値〉の意味。記録を更新するという場面では、上下の差である高低は合わない。"}, {"text": "学年の高低は七十点で、クラス全体がほっとした。", "explanation": "ここは〈平均〉の意味。全体を代表する一つの値は、高低では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は気温の高低を大きく、体調を崩す人が増える。", "corrected_sentence": "夏は気温の高低が大きく、体調を崩す人が増える。", "error_description": "「高低」が「大きく」の主語になるので、直後の助詞は「が」が正しい。「高低を大きく」は目的語の形と述語が合わない。誤りは助詞「を」（正しくは「が」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38075, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湿度の高低が激しくい季節は、カビが生えやすい。", "corrected_sentence": "湿度の高低が激しい季節は、カビが生えやすい。", "error_description": "「激しい」の活用の誤り。「激しくい」は形容詞の活用が混ざった誤りで、連体修飾の形は「激しい季節」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「有無を問う」で、有無を相手にたずねる、という目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「有無が問う」は主語と動詞が合わず、慣用句としても成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「有無に問う」は言い方として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「問う」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「有無を問う」で、有無を相手にたずねる、という目的語を示す。", "が": "「有無が問う」は主語と動詞が合わず、慣用句としても成り立たない。", "に": "「有無に問う」は言い方として成り立たない。", "へ": "「へ」は方向を表すので、「問う」の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「近況を問う」で、近況をたずねる、という目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、「問う」の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表し、「問う」の目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「問う」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「近況を問う」で、近況をたずねる、という目的語を示す。", "と": "「と」は並列や引用を表し、「問う」の目的語にはならない。", "で": "「で」は手段や場所を表し、「問う」の目的語を示せない。", "より": "「より」は比較を表し、「問う」の目的語にはならない。"}, "error_tags": {"と": "並列・引用", "で": "手段・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「問う」は、人に質問することです。", "primary_collocate": null, "pronunciation": "とう", "ipa": "toɯ", "syllable_count": 2, "sentences": [{"text": "先生は生徒に考えを問う形で授業を進めた。", "target_word": "問う", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に考[かんが]えを問[と]う形[かたち]で授業[じゅぎょう]を進[すす]めた。", "sentence_source": "generated"}, {"text": "医者は患者に、痛みの有無を問うて確かめた。", "target_word": "問うて", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]に、痛[いた]みの有無[うむ]を問[と]うて確[たし]かめた。", "sentence_source": "generated"}, {"text": "面接では、志望の理由を問うことが多い。", "target_word": "問う", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、志望[しぼう]の理由[りゆう]を問[と]うことが多[おお]い。", "sentence_source": "generated"}, {"text": "彼は部下に、なぜ報告が遅れたのかを問うた。", "target_word": "問うた", "complexity_tier": "T3", "furigana": "彼[かれ]は部下[ぶか]に、なぜ報告[ほうこく]が遅[おく]れたのかを問[と]うた。", "sentence_source": "generated"}, {"text": "彼は友人に「本当にそれでいいのか」と問うた。", "target_word": "問うた", "complexity_tier": "T3", "furigana": "彼[かれ]は友人[ゆうじん]に「本当[ほんとう]にそれでいいのか」と問[と]うた。", "sentence_source": "generated"}, {"text": "アンケートで、市民に暮らしの満足度を問う。", "target_word": "問う", "complexity_tier": "T3", "furigana": "アンケートで、市民[しみん]に暮[く]らしの満足度[まんぞくど]を問[と]う。", "sentence_source": "generated"}, {"text": "疑問があって、先生に直接問うために職員室へ行った。", "target_word": "問うために", "complexity_tier": "T3", "furigana": "疑問[ぎもん]があって、先生[せんせい]に直接[ちょくせつ]問[と]うために職員室[しょくいんしつ]へ行[い]った。", "sentence_source": "generated"}, {"text": "友人に近況を問うと、元気だと返事が来た。", "target_word": "問う", "complexity_tier": "T3", "furigana": "友人[ゆうじん]に近況[きんきょう]を問[と]うと、元気[げんき]だと返事[へんじ]が来[き]た。", "sentence_source": "generated"}, {"text": "試験では、本文の内容を問う問題がいちばん多い。", "target_word": "問う", "complexity_tier": "T3", "furigana": "試験[しけん]では、本文[ほんぶん]の内容[ないよう]を問[と]う問題[もんだい]がいちばん多[おお]い。", "sentence_source": "generated"}, {"text": "裁判官は証人に事実を問うて、答えを記録した。", "target_word": "問うて", "complexity_tier": "T3", "furigana": "裁判官[さいばんかん]は証人[しょうにん]に事実[じじつ]を問[と]うて、答[こた]えを記録[きろく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "問う", "label": "終止形"}, {"form": "問わない", "label": "未然形"}, {"form": "問います", "label": "連用形"}, {"form": "問うた", "label": "過去形"}, {"form": "問うて", "label": "て形"}, {"form": "問えば", "label": "仮定形"}, {"form": "問われる", "label": "受身形"}], "register": "文語的", "sense_fingerprint": "相手に質問する・たずねる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "問う", "is_correct": true, "explanation": "「考えを問う」は、相手に考えをたずねる、という意味で、文脈に合う。"}, {"text": "飲む", "is_correct": false, "explanation": "「考えを飲む」とは言わない。「飲む」は液体などを取り込む動詞。"}, {"text": "割る", "is_correct": false, "explanation": "「考えを割る」は不自然で、この文脈では使えない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は目的語を取らない動詞なので、「考えを眠る」は成り立たない。"}], "explanations": {"問う": "「考えを問う」は、相手に考えをたずねる、という意味で、文脈に合う。", "飲む": "「考えを飲む」とは言わない。「飲む」は液体などを取り込む動詞。", "割る": "「考えを割る」は不自然で、この文脈では使えない。", "眠る": "「眠る」は目的語を取らない動詞なので、「考えを眠る」は成り立たない。"}, "sentence_index": 0, "correct_answer": "問う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は部下の質問に、すぐ問うた。", "explanation": "ここは〈答える〉の意味。問うは質問する動作で、答えることは表さない。"}, {"text": "久しぶりに、友人の家を問うた。", "explanation": "ここは〈訪ねる〉の意味。問うは質問する動作で、家を訪れる意味はない。"}, {"text": "雨が降っていたので、彼は外へ問うた。", "explanation": "問うは質問する動詞で、場所へ移動する意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "問うために", "is_correct": true, "explanation": "「先生に直接問うために職員室へ行った」は、直接たずねるため、という目的を表し、文脈に合う。"}, {"text": "煮るために", "is_correct": false, "explanation": "「先生に直接煮るために」は意味が通らない。"}, {"text": "乾かすために", "is_correct": false, "explanation": "「乾かす」は物を乾燥させる動詞で、人にたずねる場面には合わない。"}, {"text": "磨くために", "is_correct": false, "explanation": "「磨く」は物をきれいにする動詞で、ここでは意味が通らない。"}], "explanations": {"問うために": "「先生に直接問うために職員室へ行った」は、直接たずねるため、という目的を表し、文脈に合う。", "煮るために": "「先生に直接煮るために」は意味が通らない。", "乾かすために": "「乾かす」は物を乾燥させる動詞で、人にたずねる場面には合わない。", "磨くために": "「磨く」は物をきれいにする動詞で、ここでは意味が通らない。"}, "sentence_index": 6, "correct_answer": "問うために"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな声で、ドアを問うて閉めた。", "explanation": "ここは〈閉める〉の意味。問うは質問する動詞で、ドアを閉める動作を表さない。"}, {"text": "昔の友人の顔を問うた。", "explanation": "ここは〈思い出す〉の意味。問うは質問することで、記憶を呼び起こす意味はない。"}, {"text": "嬉しさのあまり、風景を問うた。", "explanation": "ここは〈眺める〉の意味。問うは相手に尋ねる動作で、景色を見て楽しむ意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒に考えを問いて、授業を進めた。", "corrected_sentence": "先生は生徒に考えを問うて、授業を進めた。", "error_description": "「問う」は五段活用で、て形は「問うて」。「問いて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "問うて", "is_correct": true, "explanation": "「問う」のて形で、「問うて確かめた」と続くので文脈に合う。"}, {"text": "問わない", "is_correct": false, "explanation": "否定形で、「確かめた」へ自然につながらない。"}, {"text": "問います", "is_correct": false, "explanation": "丁寧形で、普通体の文の流れに合わない。"}, {"text": "問えば", "is_correct": false, "explanation": "仮定形で、「確かめた」の文とは続かない。"}], "correct_form": "問うて", "base_form": "問う", "form_label": "て形", "sentence_index": 1, "explanations": {"問うて": "「問う」のて形で、「問うて確かめた」と続くので文脈に合う。", "問わない": "否定形で、「確かめた」へ自然につながらない。", "問います": "丁寧形で、普通体の文の流れに合わない。", "問えば": "仮定形で、「確かめた」の文とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38076, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "テストでは、読解の内容を問いる問題が多い。", "corrected_sentence": "テストでは、読解の内容を問う問題が多い。", "error_description": "「問う」は五段活用で、名詞を修飾する形は「問う」。「問いる」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "問う", "is_correct": true, "explanation": "「問う」の終止形で、「友人に近況を問うと」と文の流れに合う。"}, {"text": "問えない", "is_correct": false, "explanation": "可能形の否定で、「問えないと」となり、「問うと」の条件の流れに合わない。"}, {"text": "問うた", "is_correct": false, "explanation": "過去形で、条件の「と」に続かない。"}, {"text": "問わず", "is_correct": false, "explanation": "「〜を問わず」の形で使われる語で、「問うと」の文脈には合わない。"}], "correct_form": "問う", "base_form": "問う", "form_label": "終止形", "sentence_index": 7, "explanations": {"問う": "「問う」の終止形で、「友人に近況を問うと」と文の流れに合う。", "問えない": "可能形の否定で、「問えないと」となり、「問うと」の条件の流れに合わない。", "問うた": "過去形で、条件の「と」に続かない。", "問わず": "「〜を問わず」の形で使われる語で、「問うと」の文脈には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
