INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38078, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まだ十分に進んでいないこと。", "primary_collocate": null, "pronunciation": "とじょう", "ipa": "toʑoː", "syllable_count": 3, "sentences": [{"text": "この国の医療制度はまだ途上にあり、地方では医師が足りない。", "target_word": "途上", "complexity_tier": "T3", "furigana": "この国(くに)の医療制度(いりょうせいど)はまだ途上(とじょう)にあり、地方(ちほう)では医師(いし)が足(た)りない。", "sentence_source": "generated"}, {"text": "私の日本語学習は途上で、敬語にはまだ自信がない。", "target_word": "途上", "complexity_tier": "T2", "furigana": "私(わたし)の日本語(にほんご)学習(がくしゅう)は途上(とじょう)で、敬語(けいご)にはまだ自信(じしん)がない。", "sentence_source": "generated"}, {"text": "新しい空港の建設は途上であり、開港は来年以降になる。", "target_word": "途上", "complexity_tier": "T3", "furigana": "新(あたら)しい空港(くうこう)の建設(けんせつ)は途上(とじょう)であり、開港(かいこう)は来年(らいねん)以降(いこう)になる。", "sentence_source": "generated"}, {"text": "彼の回復は途上にあるので、無理な運動は避けたほうがいい。", "target_word": "途上", "complexity_tier": "T3", "furigana": "彼(かれ)の回復(かいふく)は途上(とじょう)にあるので、無理(むり)な運動(うんどう)は避(さ)けたほうがいい。", "sentence_source": "generated"}, {"text": "環境対策は途上の段階で、目標の半分も達成できていない。", "target_word": "途上", "complexity_tier": "T4", "furigana": "環境対策(かんきょうたいさく)は途上(とじょう)の段階(だんかい)で、目標(もくひょう)の半分(はんぶん)も達成(たっせい)できていない。", "sentence_source": "generated"}, {"text": "その計画はまだ途上にあるため、詳細は発表されていない。", "target_word": "途上", "complexity_tier": "T3", "furigana": "その計画(けいかく)はまだ途上(とじょう)にあるため、詳細(しょうさい)は発表(はっぴょう)されていない。", "sentence_source": "generated"}, {"text": "この作品はまだ途上にあり、完成にはほど遠い。", "target_word": "途上", "complexity_tier": "T2", "furigana": "この作品(さくひん)はまだ途上(とじょう)にあり、完成(かんせい)にはほど遠(どお)い。", "sentence_source": "generated"}, {"text": "町の復興は途上であり、仮設住宅で暮らす人も多い。", "target_word": "途上", "complexity_tier": "T3", "furigana": "町(まち)の復興(ふっこう)は途上(とじょう)であり、仮設住宅(かせつじゅうたく)で暮(く)らす人(ひと)も多(おお)い。", "sentence_source": "generated"}, {"text": "彼女の夢は途上にあるが、毎日の努力が少しずつ実を結んでいる。", "target_word": "途上", "complexity_tier": "T4", "furigana": "彼女(かのじょ)の夢(ゆめ)は途上(とじょう)にあるが、毎日(まいにち)の努力(どりょく)が少(すこ)しずつ実(み)を結(むす)んでいる。", "sentence_source": "generated"}, {"text": "技術開発は途上にあるので、実用化を急ぐのは危険だ。", "target_word": "途上", "complexity_tier": "T3", "furigana": "技術開発(ぎじゅつかいはつ)は途上(とじょう)にあるので、実用化(じつようか)を急(いそ)ぐのは危険(きけん)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "途上", "label": "基本形"}, {"form": "途上の", "label": "連体形"}, {"form": "途上にある", "label": "状態表現"}], "register": "やや硬い", "sense_fingerprint": "まだ十分に進んでいない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38078, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "途上", "is_correct": true, "explanation": "まだ十分に進んでいない段階を表し、医療制度が整っていない文に合う。"}, {"text": "頂点", "is_correct": false, "explanation": "到達点を指し、まだ十分に進んでいない制度の状態と矛盾する。"}, {"text": "名残", "is_correct": false, "explanation": "過去の跡を指し、現在の制度の状態を表す語として文に合わない。"}, {"text": "祝祭", "is_correct": false, "explanation": "催しを指すため、制度の進み具合を表す文には入らない。"}], "explanations": {"途上": "まだ十分に進んでいない段階を表し、医療制度が整っていない文に合う。", "頂点": "到達点を指し、まだ十分に進んでいない制度の状態と矛盾する。", "名残": "過去の跡を指し、現在の制度の状態を表す語として文に合わない。", "祝祭": "催しを指すため、制度の進み具合を表す文には入らない。"}, "sentence_index": 0, "correct_answer": "途上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の回復はすでに終わり、途上の状態にある。", "explanation": "ここは〈終了〉の意味と取った誤用。途上は回復の途中を表すので、終わった回復には合わない。"}, {"text": "彼の途上を、家族みんなが喜んだ。", "explanation": "ここは〈完治〉の意味。途上は回復の途中の段階なので、完治を喜ぶ文とは合わない。"}, {"text": "世界の途上が実現した。", "explanation": "ここは〈完了〉の意味。途上は途中の段階を表すので、結果が出来上がった状態を示す文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38078, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "途上", "is_correct": true, "explanation": "まだ十分に進んでいない段階を表し、完成にはほど遠い文に合う。"}, {"text": "完成品", "is_correct": false, "explanation": "完成した品を指し、完成にはほど遠いという文脈と矛盾する。"}, {"text": "絶頂", "is_correct": false, "explanation": "頂点を指し、まだ進んでいない作品の状態とは合わない。"}, {"text": "余白", "is_correct": false, "explanation": "空いている部分を指し、作品の進み具合を表す語として文に収まらない。"}], "explanations": {"途上": "まだ十分に進んでいない段階を表し、完成にはほど遠い文に合う。", "完成品": "完成した品を指し、完成にはほど遠いという文脈と矛盾する。", "絶頂": "頂点を指し、まだ進んでいない作品の状態とは合わない。", "余白": "空いている部分を指し、作品の進み具合を表す語として文に収まらない。"}, "sentence_index": 6, "correct_answer": "途上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この技術は十分に進みきった途上にあり、もう改良の余地がない。", "explanation": "ここは〈十分に進んだ段階〉の意味と取った誤用。途上は十分に進んでいない状態を指すので、進みきった技術には合わない。"}, {"text": "学生は試験の途上を先生に提出した。", "explanation": "ここは〈答案〉の意味と取った誤用。途上は進みの途中を表すので、提出する書類を指す語としては合わない。"}, {"text": "その契約は途上の金額で一括払いされた。", "explanation": "ここは〈代金〉の意味と取った誤用。途上は途中の段階を表すので、支払う金額を指す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38078, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究はまだ途上にいる。", "corrected_sentence": "この研究はまだ途上にある。", "error_description": "「途上」は物事の状態なので「ある」と組む。「いる」は人や動物に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38078, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事業は今まさに途上をある。", "corrected_sentence": "この事業は今まさに途上にある。", "error_description": "「ある」は場所を示す「に」と組むので、「途上に」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「修業の途上」の「の」で、名詞どうしを結ぶ連体修飾を表す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示し、名詞同士を結んで修飾する働きはない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、修業と途上を結ぶ語としては合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、名詞同士の修飾には使えない。"}], "correct_answer": "の", "explanations": {"の": "「修業の途上」の「の」で、名詞どうしを結ぶ連体修飾を表す。", "に": "「に」は場所や対象を示し、名詞同士を結んで修飾する働きはない。", "へ": "「へ」は方向を示すため、修業と途上を結ぶ語としては合わない。", "で": "「で」は手段や場所を示すため、名詞同士の修飾には使えない。"}, "error_tags": {"に": "location/target", "へ": "direction", "で": "means/location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が未完成な状態であること。まだ発展の途中であること。", "primary_collocate": null, "pronunciation": "とじょう", "ipa": "toʑoː", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "途上", "complexity_tier": "T5", "furigana": "修業(しゅぎょう)の途上(とじょう)にある若(わか)きパン職人(しょくにん)は、夜明(よあ)け前(まえ)の凛(りん)とした空気(くうき)が張(は)り詰(つ)めるアトリエにて、野生(やせい)の酵母(こうぼ)が織(お)りなす微細(びさい)かつ劇的(げきてき)な化学反応(かがくはんのう)と黙々(もくもく)と格闘(かくとう)していた。", "sentence_source": "mined"}, {"text": "彼はまだ修業の途上で、一人前の職人とは言えない。", "target_word": "途上", "complexity_tier": "T2", "furigana": "彼(かれ)はまだ修業(しゅぎょう)の途上(とじょう)で、一人前(いちにんまえ)の職人(しょくにん)とは言(い)えない。", "sentence_source": "generated"}, {"text": "この町の再開発は途上にあり、完成までにあと五年かかる。", "target_word": "途上", "complexity_tier": "T3", "furigana": "この町(まち)の再開発(さいかいはつ)は途上(とじょう)にあり、完成(かんせい)までにあと五年(ごねん)かかる。", "sentence_source": "generated"}, {"text": "研究は途上の段階なので、結論を急ぐべきではない。", "target_word": "途上", "complexity_tier": "T3", "furigana": "研究(けんきゅう)は途上(とじょう)の段階(だんかい)なので、結論(けつろん)を急(いそ)ぐべきではない。", "sentence_source": "generated"}, {"text": "彼女は成長の途上にある選手だから、これからの伸びが楽しみだ。", "target_word": "途上", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は成長(せいちょう)の途上(とじょう)にある選手(せんしゅ)だから、これからの伸(の)びが楽(たの)しみだ。", "sentence_source": "generated"}, {"text": "新しい制度は導入の途上にあり、現場にはまだ混乱が残っている。", "target_word": "途上", "complexity_tier": "T4", "furigana": "新(あたら)しい制度(せいど)は導入(どうにゅう)の途上(とじょう)にあり、現場(げんば)にはまだ混乱(こんらん)が残(のこ)っている。", "sentence_source": "generated"}, {"text": "私の英語は上達の途上で、まだ映画を字幕なしでは楽しめない。", "target_word": "途上", "complexity_tier": "T3", "furigana": "私(わたし)の英語(えいご)は上達(じょうたつ)の途上(とじょう)で、まだ映画(えいが)を字幕(じまく)なしでは楽(たの)しめない。", "sentence_source": "generated"}, {"text": "改革は途上であり、成果を評価するには早すぎる。", "target_word": "途上", "complexity_tier": "T3", "furigana": "改革(かいかく)は途上(とじょう)であり、成果(せいか)を評価(ひょうか)するには早(はや)すぎる。", "sentence_source": "generated"}, {"text": "彼の技術は発展の途上にあるが、基礎はすでにしっかりしている。", "target_word": "途上", "complexity_tier": "T4", "furigana": "彼(かれ)の技術(ぎじゅつ)は発展(はってん)の途上(とじょう)にあるが、基礎(きそ)はすでにしっかりしている。", "sentence_source": "generated"}, {"text": "道路の整備はまだ途上で、雨の日は通れない区間も多い。", "target_word": "途上", "complexity_tier": "T3", "furigana": "道路(どうろ)の整備(せいび)はまだ途上(とじょう)で、雨(あめ)の日(ひ)は通(とお)れない区間(くかん)も多(おお)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "途上", "label": "基本形"}, {"form": "途上の", "label": "連体形"}, {"form": "途上にある", "label": "状態表現"}], "register": "やや硬い", "sense_fingerprint": "未完成で発展の途中にある状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 張り詰める (Zipf 1.07)']::text[], 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "途上", "is_correct": true, "explanation": "未完成で発展の途中にある段階を表し、修業中の若い職人に合う。"}, {"text": "停止", "is_correct": false, "explanation": "動きが止まることを指し、修業の途中にある状態とは合わない。"}, {"text": "余韻", "is_correct": false, "explanation": "終わった後に残る響きを指し、修業の段階を表さない。"}, {"text": "結末", "is_correct": false, "explanation": "物事の終わりを指すため、黙々と修業を続ける場面には合わない。"}], "explanations": {"途上": "未完成で発展の途中にある段階を表し、修業中の若い職人に合う。", "停止": "動きが止まることを指し、修業の途中にある状態とは合わない。", "余韻": "終わった後に残る響きを指し、修業の段階を表さない。", "結末": "物事の終わりを指すため、黙々と修業を続ける場面には合わない。"}, "sentence_index": 0, "correct_answer": "途上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "完成した橋は、今も途上の段階にある。", "explanation": "ここは〈仕上がった状態〉の意味と取った誤用。途上は未完成の段階を指すので、完成した橋には合わない。"}, {"text": "長く続いた企画が幕を閉じ、皆で途上を祝って乾杯した。", "explanation": "ここは〈完結〉の意味と取った誤用。途上は未完成の段階なので、幕を閉じた企画を祝う文とは合わない。"}, {"text": "大会の途上が宣言された。", "explanation": "ここは〈終了〉の意味。途上は途中の段階を表すので、終わりを宣言する文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "途上", "is_correct": true, "explanation": "まだ進みの途中にある段階を表し、英語の上達の文に合う。"}, {"text": "完成形", "is_correct": false, "explanation": "完成した形を指すため、まだ字幕なしで楽しめない段階とは矛盾する。"}, {"text": "絶頂", "is_correct": false, "explanation": "頂点を指し、上達の途中にある状態とは合わない。"}, {"text": "名残", "is_correct": false, "explanation": "過ぎ去ったものの跡を指し、これから上達する段階には合わない。"}], "explanations": {"途上": "まだ進みの途中にある段階を表し、英語の上達の文に合う。", "完成形": "完成した形を指すため、まだ字幕なしで楽しめない段階とは矛盾する。", "絶頂": "頂点を指し、上達の途中にある状態とは合わない。", "名残": "過ぎ去ったものの跡を指し、これから上達する段階には合わない。"}, "sentence_index": 6, "correct_answer": "途上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この事業は今月で途上を終えた。", "explanation": "ここは〈終局〉の意味と取った誤用。途上は未完成の段階を表すので、終わりを迎えた事業の状態を示す文とは合わない。"}, {"text": "物語は途上を迎えた。", "explanation": "ここは〈大団円〉の意味。途上は未完成の途中を表すので、物語の終わりを迎える文とは合わない。"}, {"text": "彼は途上を遂げた。", "explanation": "ここは〈大往生〉の意味。途上は未完成の状態を指すので、人生の終わりを遂げる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その計画はまだ途上にいる。", "corrected_sentence": "その計画はまだ途上にある。", "error_description": "「途上」は物事の状態を表すので「ある」と組む。「いる」は人や動物に使うため誤り。正しくは「途上にある」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38079, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事業は今まさに途上をある。", "corrected_sentence": "この事業は今まさに途上にある。", "error_description": "「ある」は場所を示す「に」と組むため、「途上に」が正しい。「を」は目的語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「道具を」は「収集して」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の形になるが、道具が集める主体になるのは不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表すが、収集の対象を示す形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「収集して」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「道具を」は「収集して」の目的語を示す。", "が": "主語の形になるが、道具が集める主体になるのは不自然。", "に": "位置や相手を表すが、収集の対象を示す形にはならない。", "へ": "方向を表すが、「収集して」の対象にはならない。"}, "error_tags": {"が": "主格", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「収集が好き」で、好きな対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「収集を好き」は目的語の形になり、「好き」と結びつかないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「収集と好き」は並列の形で、「好き」の対象を示せず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「収集へ好き」は方向を表し、「好き」の対象にはならず不自然。"}], "correct_answer": "が", "explanations": {"が": "正解。「収集が好き」で、好きな対象を示す。", "を": "「収集を好き」は目的語の形になり、「好き」と結びつかないので不自然。", "と": "「収集と好き」は並列の形で、「好き」の対象を示せず成り立たない。", "へ": "「収集へ好き」は方向を表し、「好き」の対象にはならず不自然。"}, "error_tags": {"を": "対象", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あちこちにあるものを、一つにまとめて集めること。", "primary_collocate": null, "pronunciation": "しゅうしゅう", "ipa": "ɕuːɕuː", "syllable_count": 4, "sentences": [{"text": "弟は外国の切手の収集が趣味だ。", "target_word": "収集", "complexity_tier": "T3", "furigana": "弟[おとうと]は外国[がいこく]の切手[きって]の収集[しゅうしゅう]が趣味[しゅみ]だ。", "sentence_source": "generated"}, {"text": "古い道具を収集して、小さな博物館に並べた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "古[ふる]い道具[どうぐ]を収集[しゅうしゅう]して、小[ちい]さな博物館[はくぶつかん]に並[なら]べた。", "sentence_source": "generated"}, {"text": "祖母は若い頃から、各地の押し花を収集してきた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "祖母[そぼ]は若[わか]い頃[ころ]から、各地[かくち]の押[お]し花[ばな]を収集[しゅうしゅう]してきた。", "sentence_source": "generated"}, {"text": "兄は昔のレコードを収集している。", "target_word": "収集", "complexity_tier": "T3", "furigana": "兄[あに]は昔[むかし]のレコードを収集[しゅうしゅう]している。", "sentence_source": "generated"}, {"text": "祖父は各地の石を収集し、箱に整理していた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "祖父[そふ]は各地[かくち]の石[いし]を収集[しゅうしゅう]し、箱[はこ]に整理[せいり]していた。", "sentence_source": "generated"}, {"text": "資料の収集に時間がかかり、発表の準備が遅れた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "資料[しりょう]の収集[しゅうしゅう]に時間[じかん]がかかり、発表[はっぴょう]の準備[じゅんび]が遅[おく]れた。", "sentence_source": "generated"}, {"text": "この図書館は地域の古い写真を収集している。", "target_word": "収集", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は地域[ちいき]の古[ふる]い写真[しゃしん]を収集[しゅうしゅう]している。", "sentence_source": "generated"}, {"text": "兄は各地の陶器の収集が好きで、棚がいっぱいだ。", "target_word": "収集", "complexity_tier": "T3", "furigana": "兄[あに]は各地[かくち]の陶器[とうき]の収集[しゅうしゅう]が好[す]きで、棚[たな]がいっぱいだ。", "sentence_source": "generated"}, {"text": "彼女は世界中の人形を収集するのが夢だ。", "target_word": "収集", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は世界中[せかいじゅう]の人形[にんぎょう]を収集[しゅうしゅう]するのが夢[ゆめ]だ。", "sentence_source": "generated"}, {"text": "収集した貝殻を、友達に見せた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "収集[しゅうしゅう]した貝殻[かいがら]を、友達[ともだち]に見[み]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収集", "label": "基本形"}, {"form": "収集する", "label": "動詞形"}, {"form": "収集した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "趣味や仕事で、各地のものを集めてそろえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 押し花 (Zipf 2.25)']::text[], '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "収集", "is_correct": true, "explanation": "正解。「切手の〜が趣味」で、切手を集めることを指す。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作る意味で、切手の趣味には当てはまらない。"}, {"text": "解体", "is_correct": false, "explanation": "分解する意味で、切手の趣味の文脈では合わない。"}, {"text": "粉砕", "is_correct": false, "explanation": "砕く意味で、切手の趣味とは結びつかない。"}], "explanations": {"収集": "正解。「切手の〜が趣味」で、切手を集めることを指す。", "作曲": "曲を作る意味で、切手の趣味には当てはまらない。", "解体": "分解する意味で、切手の趣味の文脈では合わない。", "粉砕": "砕く意味で、切手の趣味とは結びつかない。"}, "sentence_index": 0, "correct_answer": "収集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝礼のあと、生徒たちを校庭に収集した。", "explanation": "ここは〈人が一か所に集まる〉の意味の〈集合〉。収集は物や情報を集める語なので、人を集める場面には合わない。"}, {"text": "彼は試験の日、勉強に収集していて、電話に気づかなかった。", "explanation": "ここは〈一つのことに心を向ける〉の意味の〈集中〉。収集は物や情報を寄せ集める語なので、注意の向け方には使わない。"}, {"text": "騒ぎを収集するため、警察官が現場に駆けつけた。", "explanation": "ここは〈混乱をおさめる〉の意味の〈収拾〉。読みは同じだが、散らばった物を集める収集とは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "収集", "is_correct": true, "explanation": "正解。地域の古い写真を集めて保管する図書館の活動に合う。"}, {"text": "消毒", "is_correct": false, "explanation": "菌を取り除く意味で、写真の文脈には合わない。"}, {"text": "発熱", "is_correct": false, "explanation": "熱が出る意味で、写真には当てはまらない。"}, {"text": "冷却", "is_correct": false, "explanation": "冷やす意味で、写真を集める活動とは合わない。"}], "explanations": {"収集": "正解。地域の古い写真を集めて保管する図書館の活動に合う。", "消毒": "菌を取り除く意味で、写真の文脈には合わない。", "発熱": "熱が出る意味で、写真には当てはまらない。", "冷却": "冷やす意味で、写真を集める活動とは合わない。"}, "sentence_index": 6, "correct_answer": "収集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震のあと、住民を避難所に収集した。", "explanation": "ここは〈人を一定の場所に入れる〉の意味の〈収容〉。物や情報を集める収集は人には使わない。"}, {"text": "この店は月の収集が三割増えた。", "explanation": "ここは〈もうけ〉の意味の〈収益〉。収集は物や情報を寄せ集める意味なので、利益の増減には使わない。"}, {"text": "事故の騒ぎは、夜までにほぼ収集した。", "explanation": "ここは〈物事がおさまる〉の意味の〈収束〉。収集は散らばったものを集める意味で、事態が落ち着く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は週末、古い硬貨を収集しる。", "corrected_sentence": "兄は週末、古い硬貨を収集している。", "error_description": "「収集している」の活用の誤り。「収集しる」は「する」の連用形に「て・いる」が続いた形が必要で、「しる」という形は存在しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38080, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は古い写真の収集を力を入れている。", "corrected_sentence": "市は古い写真の収集に力を入れている。", "error_description": "「収集に力を入れる」の助詞は「に」が正しい。「収集を」では「力を入れる」の「に」の形と合わない。誤りは収集に続く助詞「を」（正しくは「に」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「資料を」は「収集して」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、資料が集める主体になるのは不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表すが、収集の対象を示す形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、収集の対象を示さないので合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「資料を」は「収集して」の目的語を示す。", "が": "主語を表すが、資料が集める主体になるのは不自然。", "に": "位置や相手を表すが、収集の対象を示す形にはならない。", "へ": "方向を表すが、収集の対象を示さないので合わない。"}, "error_tags": {"が": "主格", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「データの収集を」は「担当する」の目的語を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「収集から担当する」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「収集より担当する」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、「収集で担当する」は不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「データの収集を」は「担当する」の目的語を示す。", "から": "起点を表すが、「収集から担当する」は意味が通らない。", "より": "比較を表すが、「収集より担当する」は成り立たない。", "で": "手段を表すが、「収集で担当する」は不自然。"}, "error_tags": {"から": "起点", "より": "比較", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "散らばっている物や情報などを、一か所に集めること。", "primary_collocate": null, "pronunciation": "しゅうしゅう", "ipa": "ɕuːɕuː", "syllable_count": 4, "sentences": [{"text": "事故の原因を調べるため、まず情報の収集を始めた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を調[しら]べるため、まず情報[じょうほう]の収集[しゅうしゅう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "散らばった資料を収集して、一冊にまとめた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "散[ち]らばった資料[しりょう]を収集[しゅうしゅう]して、一冊[いっさつ]にまとめた。", "sentence_source": "generated"}, {"text": "町の古い言い伝えを収集する活動に参加した。", "target_word": "収集", "complexity_tier": "T3", "furigana": "町[まち]の古[ふる]い言[い]い伝[つた]えを収集[しゅうしゅう]する活動[かつどう]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "災害の被害情報を収集するため、職員が各地に出かけた。", "target_word": "収集", "complexity_tier": "T3", "furigana": "災害の被害情報を収集[しゅうしゅう]するため、職員が各地に出かけた。", "sentence_source": "generated"}, {"text": "海岸のごみを収集するボランティアに参加した。", "target_word": "収集", "complexity_tier": "T3", "furigana": "海岸[かいがん]のごみを収集[しゅうしゅう]するボランティアに参加[さんか]した。", "sentence_source": "generated"}, {"text": "記者は現場で証言を収集している。", "target_word": "収集", "complexity_tier": "T3", "furigana": "記者[きしゃ]は現場[げんば]で証言[しょうげん]を収集[しゅうしゅう]している。", "sentence_source": "generated"}, {"text": "研究のために、各地の方言を収集した。", "target_word": "収集", "complexity_tier": "T3", "furigana": "研究[けんきゅう]のために、各地[かくち]の方言[ほうげん]を収集[しゅうしゅう]した。", "sentence_source": "generated"}, {"text": "データの収集を担当する人が足りない。", "target_word": "収集", "complexity_tier": "T3", "furigana": "データの収集[しゅうしゅう]を担当[たんとう]する人[ひと]が足[た]りない。", "sentence_source": "generated"}, {"text": "買い物の前に、店の価格情報を収集した。", "target_word": "収集", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の前[まえ]に、店[みせ]の価格[かかく]情報[じょうほう]を収集[しゅうしゅう]した。", "sentence_source": "generated"}, {"text": "地図を作るため、山の地形データを収集している。", "target_word": "収集", "complexity_tier": "T3", "furigana": "地図[ちず]を作[つく]るため、山[やま]の地形[ちけい]データを収集[しゅうしゅう]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収集", "label": "基本形"}, {"form": "収集する", "label": "動詞形"}, {"form": "収集した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "散らばった物や情報、データを一か所に集めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "収集", "is_correct": true, "explanation": "正解。「情報の〜を始めた」で、散らばった情報を集めることを表す。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、情報には当てはまらない。"}, {"text": "消毒", "is_correct": false, "explanation": "菌を取り除く意味で、情報の文脈には合わない。"}, {"text": "冷却", "is_correct": false, "explanation": "冷やす意味で、情報には使わない。"}], "explanations": {"収集": "正解。「情報の〜を始めた」で、散らばった情報を集めることを表す。", "点火": "火をつける意味で、情報には当てはまらない。", "消毒": "菌を取り除く意味で、情報の文脈には合わない。", "冷却": "冷やす意味で、情報には使わない。"}, "sentence_index": 0, "correct_answer": "収集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "混乱を収集するため、市長が会見を開いた。", "explanation": "ここは〈混乱をおさめる〉の意味の〈収拾〉。読みは同じだが、散らばった物や情報を集める収集とは意味が違う。"}, {"text": "彼は資料の整理に収集して、昼食を忘れた。", "explanation": "ここは〈一つのことに心を向ける〉の意味の〈集中〉。収集は散らばった物を寄せ集める語で、注意の向け方には使わない。"}, {"text": "その犯人は、町から収集された。", "explanation": "ここは〈追い出す〉の意味の〈追放〉。収集は物や情報を集める意味なので、人を追い出す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "収集", "is_correct": true, "explanation": "正解。「各地の方言を〜した」で、各地の方言を集めることを表す。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作る意味で、方言の文脈には合わない。"}, {"text": "粉砕", "is_correct": false, "explanation": "砕く意味で、方言を集める文脈とは合わない。"}, {"text": "発熱", "is_correct": false, "explanation": "熱が出る意味で、方言には当てはまらない。"}], "explanations": {"収集": "正解。「各地の方言を〜した」で、各地の方言を集めることを表す。", "作曲": "曲を作る意味で、方言の文脈には合わない。", "粉砕": "砕く意味で、方言を集める文脈とは合わない。", "発熱": "熱が出る意味で、方言には当てはまらない。"}, "sentence_index": 6, "correct_answer": "収集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の試験に向けて、昼寝を収集した。", "explanation": "「昼寝」は集めるものではなく「とる」ものなので、収集とは組み合わない。〈睡眠をとる〉の意味の誤用。"}, {"text": "今月は給料の収集が三割増えた。", "explanation": "ここは〈収入〉の意味。給料やもうけは収入と言い、散らばったものを一か所に集める収集は使わない。"}, {"text": "議論は夜までに収集した。", "explanation": "ここは〈議論などがおさまる〉の意味の〈収束〉。収集は散らばったものを集める意味で、議論の終わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "避難者の情報の収集を、三日かかった。", "corrected_sentence": "避難者の情報の収集に、三日かかった。", "error_description": "「収集に時間がかかる」の助詞は「に」が正しい。「収集を」にすると「かかる」の形と合わない。誤りは収集に続く助詞「を」（正しくは「に」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38081, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は毎年、人口の統計を収集し続けいる。", "corrected_sentence": "市は毎年、人口の統計を収集し続けている。", "error_description": "「続けている」の「て」が抜けた誤り。「収集し続けいる」は「続け」＋「て」＋「いる」の形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「インターネットでの販売」で、場所を表す「で」に続けて名詞を修飾する「の」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「でに」は連続せず、「インターネットでに販売」は文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「販売」は動作の名詞で、ここに目的語の「を」は入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「でへ」となり不自然で、名詞句の修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「インターネットでの販売」で、場所を表す「で」に続けて名詞を修飾する「の」が入る。", "に": "「でに」は連続せず、「インターネットでに販売」は文として成り立たない。", "を": "「販売」は動作の名詞で、ここに目的語の「を」は入らない。", "へ": "方向の「へ」は「でへ」となり不自然で、名詞句の修飾にならない。"}, "error_tags": {"に": "格の誤り（「でに」は連続しない）", "を": "目的語の格（動作名詞に付かない）", "へ": "方向の格（修飾関係が成り立たない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "購入", "is_correct": true, "explanation": "「販売」（売ること）の対義語で、「買うこと」を表す。"}, {"text": "製造", "is_correct": false, "explanation": "「製造」は作ることで、売る・買うの対にはならない。"}, {"text": "寄付", "is_correct": false, "explanation": "「寄付」は無償で渡すことで、「販売」の対義語ではない。"}, {"text": "修理", "is_correct": false, "explanation": "「修理」は壊れたものを直すことで、「販売」とは対の関係にない。"}], "correct_answer": "購入", "explanations": {"購入": "「販売」（売ること）の対義語で、「買うこと」を表す。", "製造": "「製造」は作ることで、売る・買うの対にはならない。", "寄付": "「寄付」は無償で渡すことで、「販売」の対義語ではない。", "修理": "「修理」は壊れたものを直すことで、「販売」とは対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "購入", "is_correct": true, "explanation": "「販売」（売ること）の対義語で、「買うこと」を表す。"}, {"text": "寄贈", "is_correct": false, "explanation": "「寄贈」は無償で贈ることで、「販売」の対義語ではない。"}, {"text": "清掃", "is_correct": false, "explanation": "「清掃」は掃除することで、売買とは対の関係にない。"}, {"text": "出版", "is_correct": false, "explanation": "「出版」は本などを世に出すことで、「販売」の対義語ではない。"}], "correct_answer": "購入", "explanations": {"購入": "「販売」（売ること）の対義語で、「買うこと」を表す。", "寄贈": "「寄贈」は無償で贈ることで、「販売」の対義語ではない。", "清掃": "「清掃」は掃除することで、売買とは対の関係にない。", "出版": "「出版」は本などを世に出すことで、「販売」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを売ること", "primary_collocate": null, "pronunciation": "はんばい", "ipa": "hambai", "syllable_count": 4, "sentences": [{"text": "この店では、新しい靴の販売を来週から始める。", "target_word": "販売", "complexity_tier": "T3", "furigana": "この店[みせ]では、新[あたら]しい靴[くつ]の販売[はんばい]を来週[らいしゅう]から始[はじ]める。", "sentence_source": "generated"}, {"text": "インターネットでの販売が、年々増えている。", "target_word": "販売", "complexity_tier": "T3", "furigana": "インターネットでの販売[はんばい]が、年々[ねんねん]増[ふ]えている。", "sentence_source": "generated"}, {"text": "古くなった商品は、販売をやめることにした。", "target_word": "販売", "complexity_tier": "T3", "furigana": "古[ふる]くなった商品[しょうひん]は、販売[はんばい]をやめることにした。", "sentence_source": "generated"}, {"text": "販売する前に、味を何度も確かめた。", "target_word": "販売", "complexity_tier": "T3", "furigana": "販売[はんばい]する前[まえ]に、味[あじ]を何度[なんど]も確[たし]かめた。", "sentence_source": "generated"}, {"text": "この店は人気のパンを一日百個だけ販売する。", "target_word": "販売", "complexity_tier": "T3", "furigana": "この店[みせ]は人気[にんき]のパンを一日[いちにち]百個[ひゃっこ]だけ販売[はんばい]する。", "sentence_source": "generated"}, {"text": "今月は、新型の掃除機の販売が好調だ。", "target_word": "販売", "complexity_tier": "T3", "furigana": "今月[こんげつ]は、新型[しんがた]の掃除機[そうじき]の販売[はんばい]が好調[こうちょう]だ。", "sentence_source": "generated"}, {"text": "酒の販売は、二十歳以上の人にだけ許されている。", "target_word": "販売", "complexity_tier": "T3", "furigana": "酒[さけ]の販売[はんばい]は、二十歳[はたち]以上[いじょう]の人[ひと]にだけ許[ゆる]されている。", "sentence_source": "generated"}, {"text": "工場で作った野菜ジュースを、店で販売している。", "target_word": "販売", "complexity_tier": "T3", "furigana": "工場[こうじょう]で作[つく]った野菜[やさい]ジュースを、店[みせ]で販売[はんばい]している。", "sentence_source": "generated"}, {"text": "販売の担当者が、商品の使い方を説明した。", "target_word": "販売", "complexity_tier": "T3", "furigana": "販売[はんばい]の担当者[たんとうしゃ]が、商品[しょうひん]の使[つか]い方[かた]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "雨のせいで、お祭りでの販売は一時中止になった。", "target_word": "販売", "complexity_tier": "T3", "furigana": "雨[あめ]のせいで、お祭[まつ]りでの販売[はんばい]は一時中止[いちじちゅうし]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "販売", "label": "基本形"}, {"form": "販売する", "label": "動詞形"}, {"form": "販売した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "店や会社が商品を客に売ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "販売", "is_correct": true, "explanation": "「新しい靴を売り始める」という意味で、この文の空欄に入る。"}, {"text": "演奏", "is_correct": false, "explanation": "靴を演奏することはできないので、「靴の演奏を始める」は成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "「靴の散歩」は意味をなさず、店が来週から始める事業とも合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "靴が寝坊するという内容になり、店の事業として不自然。"}], "explanations": {"販売": "「新しい靴を売り始める」という意味で、この文の空欄に入る。", "演奏": "靴を演奏することはできないので、「靴の演奏を始める」は成り立たない。", "散歩": "「靴の散歩」は意味をなさず、店が来週から始める事業とも合わない。", "寝坊": "靴が寝坊するという内容になり、店の事業として不自然。"}, "sentence_index": 0, "correct_answer": "販売"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はお金を払って、ほしかった本を販売した。", "explanation": "ここは〈購入〉の意味。販売は売る側の行為で、お金を払って手に入れる場面には合わない。"}, {"text": "駅前で、チラシを無料で販売していた。", "explanation": "ここは〈配布〉の意味。販売は代金を受け取って売ることなので、無料とは合わない。"}, {"text": "祖父は大切にしていた時計を、博物館に無償で販売した。", "explanation": "ここは〈寄贈〉の意味。販売は代金を受け取る取引なので、無償で渡す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "販売", "is_correct": true, "explanation": "「酒を売ること」の意味で、この文の空欄に入る。"}, {"text": "寝室", "is_correct": false, "explanation": "「酒の寝室」は文として成り立たない。"}, {"text": "演劇", "is_correct": false, "explanation": "「酒の演劇」は文として成り立たない。"}, {"text": "読書", "is_correct": false, "explanation": "「酒の読書」は意味が通らず、年齢制限の対象にもならない。"}], "explanations": {"販売": "「酒を売ること」の意味で、この文の空欄に入る。", "寝室": "「酒の寝室」は文として成り立たない。", "演劇": "「酒の演劇」は文として成り立たない。", "読書": "「酒の読書」は意味が通らず、年齢制限の対象にもならない。"}, "sentence_index": 6, "correct_answer": "販売"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館は、新しい本を一週間だけ販売して、返してもらう。", "explanation": "ここは〈貸与〉の意味。販売は所有権を相手に渡す取引で、返してもらう前提の貸し出しには合わない。"}, {"text": "警察は、盗まれた自転車を見つけて、持ち主に販売した。", "explanation": "ここは〈返却〉の意味。販売は代金を受け取って品を渡す取引で、持ち主に品を返す場面には合わない。"}, {"text": "店員は、届いた商品を販売して、数を確かめた。", "explanation": "ここは〈検品〉の意味。販売は商品を客に売ることで、届いた品の数や状態を確かめる作業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏休みの間、家の前でレモンを販売に出した。", "corrected_sentence": "夏休みの間、家の前でレモンを販売した。", "error_description": "「販売に出した」は誤り。「販売」は「販売する」の名詞なので、そのまま「販売した」と言う。「売りに出す」と混同している。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38082, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋台は、かき氷を販売ずに閉めた。", "corrected_sentence": "屋台は、かき氷を販売せずに閉めた。", "error_description": "「販売ず」は誤り。サ変動詞「販売する」の未然形「販売せ」に打ち消しの「ず」を続けて「販売せず」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「洗練が足りない」の主語で、足りなさの対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「洗練を足りない」は「足りない」が目的語を取らないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「洗練に足りない」は成立せず、「足りない」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「洗練へ足りない」は方向の「へ」が「足りない」と結びつかず成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「洗練が足りない」の主語で、足りなさの対象を示す。", "を": "「洗練を足りない」は「足りない」が目的語を取らないので不自然。", "に": "「洗練に足りない」は成立せず、「足りない」と結びつかない。", "へ": "「洗練へ足りない」は方向の「へ」が「足りない」と結びつかず成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "手を加えて無駄をなくし、よりよく仕上げること。", "primary_collocate": null, "pronunciation": "せんれん", "ipa": "seɴɾeɴ", "syllable_count": 4, "sentences": [{"text": "何度も作り直したので、この計画は洗練が進んでいる。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "何度[なんど]も作[つく]り直[なお]したので、この計画[けいかく]は洗練[せんれん]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "職人は、長い年月をかけて道具の洗練を重ねてきた。", "target_word": "洗練", "complexity_tier": "T4", "furigana": "職人[しょくにん]は、長[なが]い年月[ねんげつ]をかけて道具[どうぐ]の洗練[せんれん]を重[かさ]ねてきた。", "sentence_source": "generated"}, {"text": "文章の洗練には、時間と練習が必要だ。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]の洗練[せんれん]には、時間[じかん]と練習[れんしゅう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "無駄をなくすことが、デザインの洗練につながる。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "無駄[むだ]をなくすことが、デザインの洗練[せんれん]につながる。", "sentence_source": "generated"}, {"text": "彼女はスピーチの洗練のために、毎晩原稿を直した。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はスピーチの洗練[せんれん]のために、毎晩[まいばん]原稿[げんこう]を直[なお]した。", "sentence_source": "generated"}, {"text": "技術の洗練によって、機械はとても小さくなった。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の洗練[せんれん]によって、機械[きかい]はとても小[ちい]さくなった。", "sentence_source": "generated"}, {"text": "この料理は洗練を重ねて、今の味になった。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "この料理[りょうり]は洗練[せんれん]を重[かさ]ねて、今[いま]の味[あじ]になった。", "sentence_source": "generated"}, {"text": "このルールは洗練が足りないので、まだ分かりにくい。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "このルールは洗練[せんれん]が足[た]りないので、まだ分[わ]かりにくい。", "sentence_source": "generated"}, {"text": "先生はレポートの洗練を手伝ってくれた。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "先生[せんせい]はレポートの洗練[せんれん]を手伝[てつだ]ってくれた。", "sentence_source": "generated"}, {"text": "洗練を目指して、チームは動きをもう一度見直した。", "target_word": "洗練", "complexity_tier": "T3", "furigana": "洗練[せんれん]を目指[めざ]して、チームは動[うご]きをもう一度[いちど]見直[みなお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗練", "label": "基本形"}, {"form": "洗練する", "label": "サ変動詞"}, {"form": "洗練された", "label": "受身過去"}], "register": "neutral", "sense_fingerprint": "手を加えて無駄をなくし、よりよく仕上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗練", "is_correct": true, "explanation": "「計画は洗練が進んでいる」と続き、仕上げを磨く過程を表す唯一の語。"}, {"text": "感謝", "is_correct": false, "explanation": "「計画は感謝が進んでいる」は意味が通らず、作り直しの文脈に合わない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「遠慮が進んでいる」は計画の仕上がりを述べる文に合わない。"}, {"text": "嫉妬", "is_correct": false, "explanation": "「嫉妬が進んでいる」は計画の状態を表さず、文が成り立たない。"}], "explanations": {"洗練": "「計画は洗練が進んでいる」と続き、仕上げを磨く過程を表す唯一の語。", "感謝": "「計画は感謝が進んでいる」は意味が通らず、作り直しの文脈に合わない。", "遠慮": "「遠慮が進んでいる」は計画の仕上がりを述べる文に合わない。", "嫉妬": "「嫉妬が進んでいる」は計画の状態を表さず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "洗練"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隣の部屋の洗練がうるさくて、眠れなかった。", "explanation": "ここは〈騒音〉の意味。洗練は作りを磨く意味で、物音の大きさには使わない。"}, {"text": "毎朝の洗練で、熱が下がった。", "explanation": "ここは〈治療〉の意味。洗練は作りを磨く意味で、病気を治すことには使わない。"}, {"text": "この靴の洗練は、一年ほどもつ。", "explanation": "ここは〈寿命〉の意味。洗練は仕上げを磨くことで、履ける期間は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗練", "is_correct": true, "explanation": "「この料理は洗練を重ねて」と続き、仕上げを磨いた結果を表す語。"}, {"text": "謙虚", "is_correct": false, "explanation": "「料理は謙虚を重ねて」は意味が通らず、味の変化を述べる文に合わない。"}, {"text": "不安", "is_correct": false, "explanation": "「料理は不安を重ねて」は料理の変化を表さず、文が成り立たない。"}, {"text": "憎しみ", "is_correct": false, "explanation": "「料理は憎しみを重ねて」は味の変化を述べる文脈に合わない。"}], "explanations": {"洗練": "「この料理は洗練を重ねて」と続き、仕上げを磨いた結果を表す語。", "謙虚": "「料理は謙虚を重ねて」は意味が通らず、味の変化を述べる文に合わない。", "不安": "「料理は不安を重ねて」は料理の変化を表さず、文が成り立たない。", "憎しみ": "「料理は憎しみを重ねて」は味の変化を述べる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "洗練"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英単語の洗練を毎晩続けて、テストに備えた。", "explanation": "ここは〈暗記〉の意味。洗練は仕上げを磨くことで、覚えることには使わない。"}, {"text": "毎日の洗練で、犬は芸を覚えた。", "explanation": "ここは〈訓練〉の意味。洗練は質を高める仕上げで、動物に繰り返し教え込むことは言わない。"}, {"text": "散らかった机の洗練を、朝のうちに終わらせた。", "explanation": "ここは〈整理〉の意味。洗練は質を磨くことで、物を片付ける作業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "何度も直したので、この計画は洗練を進んでいると言える。", "corrected_sentence": "何度も直したので、この計画は洗練が進んでいると言える。", "error_description": "「洗練が進む」の「が」は進む主体を示す。「を」にすると「進む」と結びつかず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38084, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は作品の洗練が重ねた。", "corrected_sentence": "彼女は作品の洗練を重ねた。", "error_description": "「洗練を重ねる」の「を」を「が」にすると、「重ねる」の目的語にならず、文の形が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
