INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38085, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "工夫されていて、質が高く、優れている様子。", "primary_collocate": null, "pronunciation": "せんれん", "ipa": "seɴɾeɴ", "syllable_count": 4, "sentences": [{"text": "洗練されたデザインの時計を、母にプレゼントした。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "洗練[せんれん]されたデザインの時計[とけい]を、母[はは]にプレゼントした。", "sentence_source": "generated"}, {"text": "あのホテルは、洗練された雰囲気で人気がある。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "あのホテルは、洗練[せんれん]された雰囲気[ふんいき]で人気[にんき]がある。", "sentence_source": "generated"}, {"text": "彼の洗練された話し方に、みんなが感心した。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "彼[かれ]の洗練[せんれん]された話[はな]し方[かた]に、みんなが感心[かんしん]した。", "sentence_source": "generated"}, {"text": "無駄のない洗練された部屋で、ゆっくり過ごした。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "無駄[むだ]のない洗練[せんれん]された部屋[へや]で、ゆっくり過[す]ごした。", "sentence_source": "generated"}, {"text": "この店の料理は洗練されていて、見た目も美しい。", "target_word": "洗練されて", "complexity_tier": "T3", "furigana": "この店[みせ]の料理[りょうり]は洗練[せんれん]されていて、見[み]た目[め]も美[うつく]しい。", "sentence_source": "generated"}, {"text": "洗練された動きのダンサーに、観客は拍手を送った。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "洗練[せんれん]された動[うご]きのダンサーに、観客[かんきゃく]は拍手[はくしゅ]を送[おく]った。", "sentence_source": "generated"}, {"text": "姉は洗練された服を選ぶのが上手だ。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "姉[あね]は洗練[せんれん]された服[ふく]を選[えら]ぶのが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "派手ではないが、洗練されたロゴだと思う。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "派手[はで]ではないが、洗練[せんれん]されたロゴだと思[おも]う。", "sentence_source": "generated"}, {"text": "洗練された文章なので、とても読みやすい。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "洗練[せんれん]された文章[ぶんしょう]なので、とても読[よ]みやすい。", "sentence_source": "generated"}, {"text": "新しい駅は洗練された建物で、町の顔になっている。", "target_word": "洗練された", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]は洗練[せんれん]された建物[たてもの]で、町[まち]の顔[かお]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗練", "label": "基本形"}, {"form": "洗練された", "label": "受身過去"}, {"form": "洗練されて", "label": "受身て形"}], "register": "neutral", "sense_fingerprint": "無駄がなく上品で、質が高く優れている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38085, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗練された", "is_correct": true, "explanation": "連体形で、後ろの「デザイン」を修飾して「デザインの時計」を作る形。"}, {"text": "洗練されて", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、「デザインの時計」につながらない。"}, {"text": "洗練では", "is_correct": false, "explanation": "「では」は場所や主題を示し、名詞を修飾できず「デザインの時計」と続かない。"}, {"text": "洗練を", "is_correct": false, "explanation": "「を」は目的語の格助詞で、「デザインの時計」を修飾する形にならない。"}], "explanations": {"洗練された": "連体形で、後ろの「デザイン」を修飾して「デザインの時計」を作る形。", "洗練されて": "て形は名詞を直接修飾できず、「デザインの時計」につながらない。", "洗練では": "「では」は場所や主題を示し、名詞を修飾できず「デザインの時計」と続かない。", "洗練を": "「を」は目的語の格助詞で、「デザインの時計」を修飾する形にならない。"}, "sentence_index": 0, "correct_answer": "洗練された"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この川の水は洗練されていて、底まではっきり見える。", "explanation": "ここは〈澄んだ〉の意味。洗練された は質の高さを言い、水の透明さには使わない。"}, {"text": "この靴下は洗練されていて、洗ったあとも白く輝いている。", "explanation": "ここは〈洗濯〉の意味（洗う行為）。洗練された は工夫や質の高さを表し、洗って汚れを落とした状態は言わない。"}, {"text": "この工事の音は洗練されていて、一晩中鳴り続けている。", "explanation": "ここは〈騒音〉の意味。洗練された は工夫や質の高さを表し、物音の大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38085, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗練された", "is_correct": true, "explanation": "連体形で、後ろの「服」を修飾して「洗練された服」を作る形。"}, {"text": "洗練させ", "is_correct": false, "explanation": "使役の連用形で、「服」を修飾できず文が途切れる。"}, {"text": "洗練に", "is_correct": false, "explanation": "「に」は方向や対象を示すが、名詞を修飾できず「服」につながらない。"}, {"text": "洗練から", "is_correct": false, "explanation": "「から」は起点を示し、名詞修飾の形になっていないので「服」と続かない。"}], "explanations": {"洗練された": "連体形で、後ろの「服」を修飾して「洗練された服」を作る形。", "洗練させ": "使役の連用形で、「服」を修飾できず文が途切れる。", "洗練に": "「に」は方向や対象を示すが、名詞を修飾できず「服」につながらない。", "洗練から": "「から」は起点を示し、名詞修飾の形になっていないので「服」と続かない。"}, "sentence_index": 6, "correct_answer": "洗練された"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は洗練された成績で大学を卒業した。", "explanation": "ここは〈優秀〉の意味。洗練された は工夫や趣の高さを言い、成績の良さには使わない。"}, {"text": "この箱は洗練された重さで、持つと腕が疲れる。", "explanation": "ここは〈重い〉の意味。洗練された は工夫や質の高さを表し、重さの程度は言わない。"}, {"text": "この駅は洗練された混雑で、人が多すぎて進めない。", "explanation": "ここは〈混雑〉の意味。洗練された は工夫や質の高さを表し、人が込み合う様子は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38085, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その店は、洗練された内装を人気がある。", "corrected_sentence": "その店は、洗練された内装で人気がある。", "error_description": "「人気がある」の前は「で」（理由）。「を」にすると「人気がある」と結びつかず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38085, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その時計は、洗練されデザインで評判になった。", "corrected_sentence": "その時計は、洗練されたデザインで評判になった。", "error_description": "連体形の「た」が必要。「された」は直後の名詞「デザイン」を修飾するため、「た」を省くと文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「メッセージを打って」の形で、打つ対象を示す目的語になる。"}, {"text": "に", "is_correct": false, "explanation": "「メッセージに打って」は方向や対象を示すが、打つ対象としては不自然。"}, {"text": "が", "is_correct": false, "explanation": "「メッセージが打って」は主語の形で、打つ動作の対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「メッセージの打って」は所有を示すが、動詞の対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「メッセージを打って」の形で、打つ対象を示す目的語になる。", "に": "「メッセージに打って」は方向や対象を示すが、打つ対象としては不自然。", "が": "「メッセージが打って」は主語の形で、打つ動作の対象にはならない。", "の": "「メッセージの打って」は所有を示すが、動詞の対象として成り立たない。"}, "error_tags": {"に": "方向・対象", "が": "主語", "の": "所有・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「メッセージが三件」の形で、三件あるものの主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「メッセージを三件も入っていた」は目的語の形だが、入っている状態には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「メッセージで三件も入っていた」は手段や場所を示すが、主語として合わない。"}, {"text": "と", "is_correct": false, "explanation": "「メッセージと三件も入っていた」は並列を示すが、入っている主体として不自然。"}], "correct_answer": "が", "explanations": {"が": "「メッセージが三件」の形で、三件あるものの主語になる。", "を": "「メッセージを三件も入っていた」は目的語の形だが、入っている状態には合わない。", "で": "「メッセージで三件も入っていた」は手段や場所を示すが、主語として合わない。", "と": "「メッセージと三件も入っていた」は並列を示すが、入っている主体として不自然。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "だれかに何かを伝えるための言葉やしるしのことです。", "primary_collocate": null, "pronunciation": "めっせーじ", "ipa": "messeːdʑi", "syllable_count": 5, "sentences": [{"text": "先生にお礼のメッセージを書いて渡した。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "先生[せんせい]にお礼[れい]のメッセージを書[か]いて渡[わた]した。", "sentence_source": "generated"}, {"text": "電車の中で、母にメッセージを打って遅れると伝えた。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で、母[はは]にメッセージを打[う]って遅[おく]れると伝[つた]えた。", "sentence_source": "generated"}, {"text": "山田さんが留守だったので、受付にメッセージを残して帰った。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "山田[やまだ]さんが留守[るす]だったので、受付[うけつけ]にメッセージを残[のこ]して帰[かえ]った。", "sentence_source": "generated"}, {"text": "SNSで知らない人からメッセージが届いて、少し怖かった。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "SNSで知[し]らない人[ひと]からメッセージが届[とど]いて、少[すこ]し怖[こわ]かった。", "sentence_source": "generated"}, {"text": "彼は手紙の最後に、短い応援のメッセージを添えた。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "彼[かれ]は手紙[てがみ]の最後[さいご]に、短[みじか]い応援[おうえん]のメッセージを添[そ]えた。", "sentence_source": "generated"}, {"text": "この歌には、平和への願いというメッセージがある。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "この歌[うた]には、平和[へいわ]への願[ねが]いというメッセージがある。", "sentence_source": "generated"}, {"text": "ケーキの上のチョコレートに、お祝いのメッセージが書いてあった。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "ケーキの上[うえ]のチョコレートに、お祝[いわ]いのメッセージが書[か]いてあった。", "sentence_source": "generated"}, {"text": "スマートフォンの通知を見ると、友人のメッセージが三件も入っていた。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "スマートフォンの通知[つうち]を見[み]ると、友人[ゆうじん]のメッセージが三件[さんけん]も入[はい]っていた。", "sentence_source": "generated"}, {"text": "結婚式で、新郎新婦にお祝いのメッセージを読んだ。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]で、新郎新婦[しんろうしんぷ]にお祝[いわ]いのメッセージを読[よ]んだ。", "sentence_source": "generated"}, {"text": "留守番電話のメッセージを聞いて、すぐに電話をかけ直した。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "留守番電話[るすばんでんわ]のメッセージを聞[き]いて、すぐに電話[でんわ]をかけ直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メッセージ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "だれかに何かを伝えるための言葉やしるし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メッセージ", "is_correct": true, "explanation": "だれかに伝えるための言葉の意味。「お礼のメッセージを書いて渡した」は、先生に伝える言葉として自然。"}, {"text": "花束", "is_correct": false, "explanation": "花をまとめたもの。「お礼の花束を書いて」は成り立たず、書く対象として合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "氏名や所属を記した札の意味。「お礼の名刺を書いて」は意味が通らない。"}, {"text": "機械", "is_correct": false, "explanation": "動力で動く装置の意味。「お礼の機械を書いて」は文の意味を成さない。"}], "explanations": {"メッセージ": "だれかに伝えるための言葉の意味。「お礼のメッセージを書いて渡した」は、先生に伝える言葉として自然。", "花束": "花をまとめたもの。「お礼の花束を書いて」は成り立たず、書く対象として合わない。", "名刺": "氏名や所属を記した札の意味。「お礼の名刺を書いて」は意味が通らない。", "機械": "動力で動く装置の意味。「お礼の機械を書いて」は文の意味を成さない。"}, "sentence_index": 0, "correct_answer": "メッセージ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "包丁のメッセージで、野菜を切った。", "explanation": "ここは〈包丁〉の意味。包丁は野菜を切る道具で、言葉や記号のメッセージは道具にならない。"}, {"text": "朝、メッセージを焼いた。", "explanation": "ここは〈パン〉の意味。パンは焼ける食べ物だが、言葉のメッセージは焼く対象にならない。"}, {"text": "体重計で、メッセージを測った。", "explanation": "ここは〈体重〉の意味。体重計で測れるのは重さで、メッセージは測定の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メッセージ", "is_correct": true, "explanation": "伝える言葉の意味。「お祝いのメッセージが書いてあった」は、チョコレートに書かれた言葉として自然。"}, {"text": "値段", "is_correct": false, "explanation": "商品の価格の意味。「お祝いの値段が書いてあった」は意味が通らない。"}, {"text": "写真", "is_correct": false, "explanation": "画像の意味。「お祝いの写真が書いてあった」は、書いてあるものとして成り立たない。"}, {"text": "色彩", "is_correct": false, "explanation": "色の種類や色合いの意味。「お祝いの色彩が書いてあった」は文に合わない。"}], "explanations": {"メッセージ": "伝える言葉の意味。「お祝いのメッセージが書いてあった」は、チョコレートに書かれた言葉として自然。", "値段": "商品の価格の意味。「お祝いの値段が書いてあった」は意味が通らない。", "写真": "画像の意味。「お祝いの写真が書いてあった」は、書いてあるものとして成り立たない。", "色彩": "色の種類や色合いの意味。「お祝いの色彩が書いてあった」は文に合わない。"}, "sentence_index": 6, "correct_answer": "メッセージ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープのメッセージを見て、塩を足した。", "explanation": "ここは〈味〉の意味。味は舌で確かめる風味で、言葉や記号のメッセージは味見の対象にならない。"}, {"text": "メッセージを押して、ドアを開けた。", "explanation": "ここは〈ボタン〉の意味。ボタンは押せる装置だが、メッセージは押して動かせるものではない。"}, {"text": "昨日は彼とメッセージが取れず、心配した。", "explanation": "ここは〈連絡〉の意味。『連絡が取れる』と言うが、伝える言葉のメッセージは取るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は電話でメッセージに残した。", "corrected_sentence": "彼は電話でメッセージを残した。", "error_description": "「を」が「に」になっている。『残す』の目的語は『を』で示す。『に』では残すものとして不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38086, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は母にメッセージに謝った。", "corrected_sentence": "私は母にメッセージで謝った。", "error_description": "「で」が「に」になっている。『謝る』は手段を『で』で示す。『に』では謝る相手や対象を示すことになり、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「メッセージを送った」の形で、送られるものを示す目的語になる。"}, {"text": "に", "is_correct": false, "explanation": "「メッセージに送った」は方向や対象を示すが、送るものとしては不自然。"}, {"text": "が", "is_correct": false, "explanation": "「メッセージが送った」は主語の形で、動詞の目的語として合わない。"}, {"text": "と", "is_correct": false, "explanation": "「メッセージと送った」は並列や相手を示すが、送るものとしては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「メッセージを送った」の形で、送られるものを示す目的語になる。", "に": "「メッセージに送った」は方向や対象を示すが、送るものとしては不自然。", "が": "「メッセージが送った」は主語の形で、動詞の目的語として合わない。", "と": "「メッセージと送った」は並列や相手を示すが、送るものとしては成り立たない。"}, "error_tags": {"に": "方向・対象", "が": "主語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人に情報や気持ちを伝えるために送る言葉や記号。", "primary_collocate": null, "pronunciation": "めっせーじ", "ipa": "messeːdʑi", "syllable_count": 5, "sentences": [{"text": "色は単なる装飾ではなく、記号論の観点から特定のメッセージを伝える記号として機能するのだ。", "target_word": "メッセージ", "complexity_tier": "T4", "furigana": "色[いろ]は単[たん]なる装飾[そうしょく]ではなく、記号論[きごうろん]の観点[かんてん]から特定[とくてい]のメッセージを伝[つた]える記号[きごう]として機能[きのう]するのだ。", "sentence_source": "mined"}, {"text": "友達に「誕生日おめでとう」というメッセージを送った。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "友達[ともだち]に「誕生日[たんじょうび]おめでとう」というメッセージを送[おく]った。", "sentence_source": "generated"}, {"text": "留守番電話にメッセージを残しておいたので、折り返しの電話を待っている。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "留守番電話[るすばんでんわ]にメッセージを残[のこ]しておいたので、折[お]り返[かえ]しの電話[でんわ]を待[ま]っている。", "sentence_source": "generated"}, {"text": "このポスターは、環境を守ろうというメッセージを強く伝えている。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "このポスターは、環境[かんきょう]を守[まも]ろうというメッセージを強[つよ]く伝[つた]えている。", "sentence_source": "generated"}, {"text": "彼女からのメッセージを読んで、思わず笑ってしまった。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]からのメッセージを読[よ]んで、思[おも]わず笑[わら]ってしまった。", "sentence_source": "generated"}, {"text": "画面に「パスワードが違います」というメッセージが出たので、もう一度入力した。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "画面[がめん]に「パスワードが違[ちが]います」というメッセージが出[で]たので、もう一度[いちど]入力[にゅうりょく]した。", "sentence_source": "generated"}, {"text": "卒業する先輩に、みんなで寄せ書きのメッセージを書いた。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]する先輩[せんぱい]に、みんなで寄[よ]せ書[が]きのメッセージを書[か]いた。", "sentence_source": "generated"}, {"text": "忙しくて返事が遅れたが、夜になってやっとメッセージに返信した。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "忙[いそが]しくて返事[へんじ]が遅[おく]れたが、夜[よる]になってやっとメッセージに返信[へんしん]した。", "sentence_source": "generated"}, {"text": "大統領は国民に向けて、団結を呼びかけるメッセージを発表した。", "target_word": "メッセージ", "complexity_tier": "T4", "furigana": "大統領[だいとうりょう]は国民[こくみん]に向[む]けて、団結[だんけつ]を呼[よ]びかけるメッセージを発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "この映画は、家族を大切にしろというメッセージが込められている。", "target_word": "メッセージ", "complexity_tier": "T3", "furigana": "この映画[えいが]は、家族[かぞく]を大切[たいせつ]にしろというメッセージが込[こ]められている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メッセージ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人に情報や気持ちを伝えるために送る言葉や記号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 寄せ書き (Zipf 2.49)']::text[], '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メッセージ", "is_correct": true, "explanation": "人に伝える言葉や記号の意味。「特定のメッセージを伝える」として、伝える内容にあたるので文に合う。"}, {"text": "雑巾", "is_correct": false, "explanation": "雑巾は掃除に使う布で、伝える内容や記号にはならないので文に合わない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建物の段で、伝える内容や記号にはならないので文に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さで、伝える内容や記号にはならないので文に合わない。"}], "explanations": {"メッセージ": "人に伝える言葉や記号の意味。「特定のメッセージを伝える」として、伝える内容にあたるので文に合う。", "雑巾": "雑巾は掃除に使う布で、伝える内容や記号にはならないので文に合わない。", "階段": "階段は建物の段で、伝える内容や記号にはならないので文に合わない。", "体重": "体重は体の重さで、伝える内容や記号にはならないので文に合わない。"}, "sentence_index": 0, "correct_answer": "メッセージ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引っ越しの荷物を、大きなメッセージに詰めて運んだ。", "explanation": "ここは〈箱〉の意味。メッセージは言葉や記号で、物を入れる容器にはならない。"}, {"text": "夕方、メッセージを冷凍庫に入れた。", "explanation": "ここは〈食材〉の意味。冷凍庫に入れるのは食べ物で、言葉のメッセージは入れない。"}, {"text": "彼は部屋を出るとき、メッセージを閉めた。", "explanation": "ここは〈ドア〉の意味。ドアは開け閉めする物だが、言葉のメッセージは閉める対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メッセージ", "is_correct": true, "explanation": "伝える言葉の意味。「寄せ書きのメッセージを書いた」は、卒業する人に送る言葉として自然。"}, {"text": "名刺", "is_correct": false, "explanation": "職場の連絡先などを記した札の意味。寄せ書きとは結びつかず、ここには入らない。"}, {"text": "写真", "is_correct": false, "explanation": "画像の意味。「寄せ書きの写真を書いた」は、書くものとして成り立たない。"}, {"text": "装飾", "is_correct": false, "explanation": "飾りの意味。「寄せ書きの装飾を書いた」は、書く対象として意味が通らない。"}], "explanations": {"メッセージ": "伝える言葉の意味。「寄せ書きのメッセージを書いた」は、卒業する人に送る言葉として自然。", "名刺": "職場の連絡先などを記した札の意味。寄せ書きとは結びつかず、ここには入らない。", "写真": "画像の意味。「寄せ書きの写真を書いた」は、書くものとして成り立たない。", "装飾": "飾りの意味。「寄せ書きの装飾を書いた」は、書く対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "メッセージ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紅茶は、ほのかなメッセージを淹れて出した。", "explanation": "ここは〈茶葉〉の意味。茶葉を淹れるのであって、言葉のメッセージは淹れない。"}, {"text": "この鞄は、丈夫なメッセージで作られている。", "explanation": "ここは〈素材〉の意味。鞄を作る材料にはなるが、言葉や記号のメッセージは材料にならない。"}, {"text": "この機械は、水のメッセージを自動で調節する。", "explanation": "ここは〈水量〉の意味。水の量は数値として調節されるもので、伝える内容のメッセージは調節の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は友達にメッセージに送った。", "corrected_sentence": "彼女は友達にメッセージを送った。", "error_description": "「に」が余分に付いている。『送る』の目的語は『を』で示す。『に』を付けると、メッセージを送る相手と重なり不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38087, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は届いたメッセージに読んだ。", "corrected_sentence": "彼は届いたメッセージを読んだ。", "error_description": "「に」が「を」になっている。『読む』の目的語は『を』で示す。『に』では読む対象として不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国連の本部」で、所属を表す「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「国連を本部は」は目的語の「を」が文の構造に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「国連へ本部」となり、名詞の結びつきが成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「国連に本部は」は場所の「に」が名詞の結びつきに合わない。"}], "correct_answer": "の", "explanations": {"の": "「国連の本部」で、所属を表す「の」が入る。", "を": "「国連を本部は」は目的語の「を」が文の構造に合わない。", "へ": "方向の「へ」は「国連へ本部」となり、名詞の結びつきが成り立たない。", "に": "「国連に本部は」は場所の「に」が名詞の結びつきに合わない。"}, "error_tags": {"を": "目的語の格（名詞に続く用法がない）", "へ": "方向の格（名詞の結びつきが成立しない）", "に": "場所の格（所属の意味にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「国連が出した報告書」で、動作の主体を表す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「国連を出した」は目的語の「を」では、主体と動作の関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「国連と出した」は共同の相手を表す「と」が動作と結びつかず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」は「国連より出した」となり、報告書の主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "「国連が出した報告書」で、動作の主体を表す「が」が入る。", "を": "「国連を出した」は目的語の「を」では、主体と動作の関係が成り立たない。", "と": "「国連と出した」は共同の相手を表す「と」が動作と結びつかず不自然。", "より": "比較・起点の「より」は「国連より出した」となり、報告書の主体を表せない。"}, "error_tags": {"を": "目的語の格（主体を表せない）", "と": "並列・共同の格（動作の主体にならない）", "より": "比較・起点の格（主体を表せない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "複数の国が加盟する国際的な組織。平和の維持や国際協力を目的とし、本部はニューヨークにある。", "primary_collocate": null, "pronunciation": "こくれん", "ipa": "kokɯɾeɴ", "syllable_count": 4, "sentences": [{"text": "国連は、世界の平和を守るために作られた組織です。", "target_word": "国連", "complexity_tier": "T3", "furigana": "国連(こくれん)は、世界(せかい)の平和(へいわ)を守(まも)るために作(つく)られた組織(そしき)です。", "sentence_source": "generated"}, {"text": "国連の本部はニューヨークにあります。", "target_word": "国連", "complexity_tier": "T3", "furigana": "国連(こくれん)の本部(ほんぶ)はニューヨークにあります。", "sentence_source": "generated"}, {"text": "日本は一九五六年に国連に加盟しました。", "target_word": "国連", "complexity_tier": "T3", "furigana": "日本(にほん)は一九五六年(せんきゅうひゃくごじゅうろくねん)に国連(こくれん)に加盟(かめい)しました。", "sentence_source": "generated"}, {"text": "国連は、戦争で困っている人々に食べ物を送っています。", "target_word": "国連", "complexity_tier": "T3", "furigana": "国連(こくれん)は、戦争(せんそう)で困(こま)っている人々(ひとびと)に食(た)べ物(もの)を送(おく)っています。", "sentence_source": "generated"}, {"text": "各国の代表が国連に集まって、環境問題を話し合った。", "target_word": "国連", "complexity_tier": "T3", "furigana": "各国(かっこく)の代表(だいひょう)が国連(こくれん)に集(あつ)まって、環境問題(かんきょうもんだい)を話(はな)し合(あ)った。", "sentence_source": "generated"}, {"text": "国連で働くために、彼女は英語とフランス語を勉強している。", "target_word": "国連", "complexity_tier": "T3", "furigana": "国連(こくれん)で働(はたら)くために、彼女(かのじょ)は英語(えいご)とフランス語(ご)を勉強(べんきょう)している。", "sentence_source": "generated"}, {"text": "国連の会議では、多くの国が意見を出し合う。", "target_word": "国連", "complexity_tier": "T3", "furigana": "国連(こくれん)の会議(かいぎ)では、多(おお)くの国(くに)が意見(いけん)を出(だ)し合(あ)う。", "sentence_source": "generated"}, {"text": "国連が出した報告書によると、水が足りない地域が増えている。", "target_word": "国連", "complexity_tier": "T3", "furigana": "国連(こくれん)が出(だ)した報告書(ほうこくしょ)によると、水(みず)が足(た)りない地域(ちいき)が増(ふ)えている。", "sentence_source": "generated"}, {"text": "この問題は一つの国だけでは解決できないので、国連に助けを求めた。", "target_word": "国連", "complexity_tier": "T3", "furigana": "この問題(もんだい)は一(ひと)つの国(くに)だけでは解決(かいけつ)できないので、国連(こくれん)に助(たす)けを求(もと)めた。", "sentence_source": "generated"}, {"text": "小学校の授業で、国連の仕事について調べた。", "target_word": "国連", "complexity_tier": "T3", "furigana": "小学校(しょうがっこう)の授業(じゅぎょう)で、国連(こくれん)の仕事(しごと)について調(しら)べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国連", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "世界の国々が加盟する、平和と協力のための国際組織", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 出し合う (Zipf 1.9)']::text[], '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国連", "is_correct": true, "explanation": "世界の平和を守るために作られた国際組織を指し、この文の主語に入る。"}, {"text": "料理", "is_correct": false, "explanation": "料理は組織ではないので、「組織です」と合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は組織ではなく、平和を守るために作られたという内容に合わない。"}, {"text": "温泉", "is_correct": false, "explanation": "温泉は組織ではなく、平和を守る目的とも結びつかない。"}], "explanations": {"国連": "世界の平和を守るために作られた国際組織を指し、この文の主語に入る。", "料理": "料理は組織ではないので、「組織です」と合わない。", "天気": "天気は組織ではなく、平和を守るために作られたという内容に合わない。", "温泉": "温泉は組織ではなく、平和を守る目的とも結びつかない。"}, "sentence_index": 0, "correct_answer": "国連"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国連は、国内の道路を造る工事を担当する役所だ。", "explanation": "ここは〈役所〉の意味。国連は国際組織で、国内の道路工事を担う役所ではない。"}, {"text": "国連は、国の法律を決める議会で、議員が選ばれる。", "explanation": "ここは〈議会〉の意味。国連は国際組織で、国内の法律を決める機関ではない。"}, {"text": "この山脈は、二つの国を分ける国連になっている。", "explanation": "ここは〈国境〉の意味。国連は国を分ける境界ではなく、国々が加盟する組織を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国連", "is_correct": true, "explanation": "加盟国が集まって意見を出し合う場を指し、「国連の会議」として文に合う。"}, {"text": "野球", "is_correct": false, "explanation": "「野球の会議」では、多くの国が意見を出し合う文脈に合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室の会議」は文として成り立たない。"}, {"text": "海水", "is_correct": false, "explanation": "「海水の会議」は意味をなさず、国の意見交換とも結びつかない。"}], "explanations": {"国連": "加盟国が集まって意見を出し合う場を指し、「国連の会議」として文に合う。", "野球": "「野球の会議」では、多くの国が意見を出し合う文脈に合わない。", "寝室": "「寝室の会議」は文として成り立たない。", "海水": "「海水の会議」は意味をなさず、国の意見交換とも結びつかない。"}, "sentence_index": 6, "correct_answer": "国連"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は国連で、旅行のビザを出してもらった。", "explanation": "ここは〈大使館〉の意味。ビザを発行するのは大使館や領事館で、国連は発行しない。"}, {"text": "国連は、新しい車を売るために工場を建てた。", "explanation": "ここは〈企業〉の意味。車を売るために工場を建てるのは企業で、国際組織の国連の活動ではない。"}, {"text": "父は国連で電車の運転士として働いていた。", "explanation": "ここは〈国鉄〉の意味。電車を運転するのは鉄道会社で、国連の業務ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その国は、新しい政府ができてから、国連を加盟した。", "corrected_sentence": "その国は、新しい政府ができてから、国連に加盟した。", "error_description": "「国連を加盟した」は誤り。「加盟する」は「〜に加盟する」と言うので、「国連に加盟した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38089, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、昨年、国連を行った。", "corrected_sentence": "父は、昨年、国連に行った。", "error_description": "「国連を行った」は誤り。「行く」は場所に「に」を付けて「国連に行く」と言うので、「を」は使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
