INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38090, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地球の環境を守るために国が協力する計画のことです。", "primary_collocate": null, "pronunciation": "ゆねっぷ", "ipa": "junepːɯ", "syllable_count": 4, "sentences": [{"text": "UNEP は、地球の環境を守るために国が協力する計画です。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP は、地球(ちきゅう)の環境(かんきょう)を守(まも)るために国(くに)が協力(きょうりょく)する計画(けいかく)です。", "sentence_source": "generated"}, {"text": "UNEP のおかげで、多くの国が海のごみを減らす活動を始めた。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP のおかげで、多(おお)くの国(くに)が海(うみ)のごみを減(へ)らす活動(かつどう)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "この国は UNEP に参加して、森を増やしている。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "この国(くに)は UNEP に参加(さんか)して、森(もり)を増(ふ)やしている。", "sentence_source": "generated"}, {"text": "UNEP は、きれいな空気を守ることも目標にしている。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP は、きれいな空気(くうき)を守(まも)ることも目標(もくひょう)にしている。", "sentence_source": "generated"}, {"text": "先生は UNEP を例にして、国どうしの協力の大切さを話した。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "先生(せんせい)は UNEP を例(れい)にして、国(くに)どうしの協力(きょうりょく)の大切(たいせつ)さを話(はな)した。", "sentence_source": "generated"}, {"text": "UNEP の計画に合わせて、町は木を植えることにした。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP の計画(けいかく)に合(あ)わせて、町(まち)は木(き)を植(う)えることにした。", "sentence_source": "generated"}, {"text": "環境の授業で UNEP について調べて、発表した。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "環境(かんきょう)の授業(じゅぎょう)で UNEP について調(しら)べて、発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "UNEP は、一つの国だけでは守れない自然を守るための計画だ。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP は、一(ひと)つの国(くに)だけでは守(まも)れない自然(しぜん)を守(まも)るための計画(けいかく)だ。", "sentence_source": "generated"}, {"text": "UNEP に協力する国が増えれば、川の水もきれいになるだろう。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP に協力(きょうりょく)する国(くに)が増(ふ)えれば、川(かわ)の水(みず)もきれいになるだろう。", "sentence_source": "generated"}, {"text": "兄は UNEP の目標がわかりやすく書かれた本を読んだ。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "兄(あに)は UNEP の目標(もくひょう)がわかりやすく書(か)かれた本(ほん)を読(よ)んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "UNEP", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地球の環境を守るために各国が協力する計画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38090, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "UNEP", "is_correct": true, "explanation": "地球の環境を守るために国が協力する計画を指し、この文の主語に入る。"}, {"text": "料理", "is_correct": false, "explanation": "料理は計画ではないので、「地球の環境を守る計画です」と合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は計画ではなく、環境を守るために国が協力するという内容に合わない。"}, {"text": "温泉", "is_correct": false, "explanation": "温泉は計画ではなく、地球の環境を守るという目的とも結びつかない。"}], "explanations": {"UNEP": "地球の環境を守るために国が協力する計画を指し、この文の主語に入る。", "料理": "料理は計画ではないので、「地球の環境を守る計画です」と合わない。", "天気": "天気は計画ではなく、環境を守るために国が協力するという内容に合わない。", "温泉": "温泉は計画ではなく、地球の環境を守るという目的とも結びつかない。"}, "sentence_index": 0, "correct_answer": "UNEP"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "UNEP は、世界中の人々の病気を減らすために、ワクチンを配っている。", "explanation": "ここは〈世界保健機関〉の役割。UNEP は環境を守る計画で、病気対策には合わない。"}, {"text": "UNEP は、貧しい国にお金を貸して経済を立て直している。", "explanation": "ここは〈国際通貨基金〉の役割。UNEP は環境の計画で、融資を行う組織ではない。"}, {"text": "UNEP は、世界遺産の建物を登録して守っている。", "explanation": "ここは〈ユネスコ〉の役割。UNEP は環境問題の計画で、遺産の登録は行わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38090, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "UNEP", "is_correct": true, "explanation": "環境に関する計画の名称で、「環境の授業でUNEPについて調べた」に入る。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室について調べて」は環境の授業の内容として成り立たない。"}, {"text": "野球", "is_correct": false, "explanation": "「野球について調べて発表した」は環境の授業の文脈に合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊について調べて」は環境の授業の内容として成り立たない。"}], "explanations": {"UNEP": "環境に関する計画の名称で、「環境の授業でUNEPについて調べた」に入る。", "寝室": "「寝室について調べて」は環境の授業の内容として成り立たない。", "野球": "「野球について調べて発表した」は環境の授業の文脈に合わない。", "寝坊": "「寝坊について調べて」は環境の授業の内容として成り立たない。"}, "sentence_index": 6, "correct_answer": "UNEP"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "UNEP は、戦争を止めるために各国の兵士を集めている。", "explanation": "ここは〈国連〉の役割（平和維持活動）。UNEP は環境の計画で、軍隊は扱わない。"}, {"text": "UNEP は、災害で被害を受けた人々に薬と食べ物を届けている。", "explanation": "ここは〈赤十字〉の役割。UNEP は環境の計画で、救援物資は届けない。"}, {"text": "UNEP は、国内の環境を守る法律を作る役所だ。", "explanation": "ここは〈環境省〉の役割。UNEP は国際的な計画で、国内の法律を作る役所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38090, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国は UNEP を参加して、海の環境を守る計画を始めた。", "corrected_sentence": "この国は UNEP に参加して、海の環境を守る計画を始めた。", "error_description": "「UNEPを参加した」は誤り。「参加する」は「〜に参加する」と言うので、「UNEPに参加した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38090, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "発表会で UNEP を話して、みんなに紹介した。", "corrected_sentence": "発表会で UNEP について話して、みんなに紹介した。", "error_description": "「UNEPを話した」は誤り。「話す」は話題に「について」を付けて「UNEPについて話す」と言う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
