INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38091, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "国際連合が環境問題について話し合い、対策を進めるための組織です。", "primary_collocate": null, "pronunciation": "ゆねっぷ", "ipa": "junepːɯ", "syllable_count": 4, "sentences": [{"text": "UNEP は、国際連合が環境問題について話し合うための組織です。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP は、国際連合(こくさいれんごう)が環境問題(かんきょうもんだい)について話(はな)し合(あ)うための組織(そしき)です。", "sentence_source": "generated"}, {"text": "UNEP の会議には、多くの国の代表が出席した。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP の会議(かいぎ)には、多(おお)くの国(くに)の代表(だいひょう)が出席(しゅっせき)した。", "sentence_source": "generated"}, {"text": "UNEP は、各国に環境を守る方法をアドバイスしている。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP は、各国(かっこく)に環境(かんきょう)を守(まも)る方法(ほうほう)をアドバイスしている。", "sentence_source": "generated"}, {"text": "彼は UNEP で働くことを夢見て、環境学を勉強している。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "彼(かれ)は UNEP で働(はたら)くことを夢見(ゆめみ)て、環境学(かんきょうがく)を勉強(べんきょう)している。", "sentence_source": "generated"}, {"text": "UNEP が発表した報告書を読んで、ごみの問題に興味を持った。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP が発表(はっぴょう)した報告書(ほうこくしょ)を読(よ)んで、ごみの問題(もんだい)に興味(きょうみ)を持(も)った。", "sentence_source": "generated"}, {"text": "UNEP の事務所はケニアのナイロビにある。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP の事務所(じむしょ)はケニアのナイロビにある。", "sentence_source": "generated"}, {"text": "国際連合の中で、環境を担当するのは UNEP です。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "国際連合(こくさいれんごう)の中(なか)で、環境(かんきょう)を担当(たんとう)するのは UNEP です。", "sentence_source": "generated"}, {"text": "学校のポスターで、UNEP の仕事について知った。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "学校(がっこう)のポスターで、UNEP の仕事(しごと)について知(し)った。", "sentence_source": "generated"}, {"text": "UNEP は、世界の海をきれいにするための対策を進めている。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "UNEP は、世界(せかい)の海(うみ)をきれいにするための対策(たいさく)を進(すす)めている。", "sentence_source": "generated"}, {"text": "会議で UNEP の代表が、森を守る大切さについて話した。", "target_word": "UNEP", "complexity_tier": "T3", "furigana": "会議(かいぎ)で UNEP の代表(だいひょう)が、森(もり)を守(まも)る大切(たいせつ)さについて話(はな)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "UNEP", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "国際連合の環境問題を扱う組織", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38091, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "UNEP", "is_correct": true, "explanation": "国際連合が環境問題を話し合うための組織を指し、この文の主語に入る。"}, {"text": "料理", "is_correct": false, "explanation": "料理は組織ではないので、「話し合うための組織です」と合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は組織ではなく、環境問題を話し合うという内容に合わない。"}, {"text": "温泉", "is_correct": false, "explanation": "温泉は組織ではなく、国際連合の環境問題の話し合いとも結びつかない。"}], "explanations": {"UNEP": "国際連合が環境問題を話し合うための組織を指し、この文の主語に入る。", "料理": "料理は組織ではないので、「話し合うための組織です」と合わない。", "天気": "天気は組織ではなく、環境問題を話し合うという内容に合わない。", "温泉": "温泉は組織ではなく、国際連合の環境問題の話し合いとも結びつかない。"}, "sentence_index": 0, "correct_answer": "UNEP"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "UNEP は、日本の環境を守るために国内の法律を作る政府機関だ。", "explanation": "ここは〈環境省〉の意味。UNEP は国際組織で、国内の法律を作る政府機関ではない。"}, {"text": "UNEP は、戦争で争う国々の間に軍隊を送って平和を守っている。", "explanation": "ここは〈国連〉の役割（平和維持活動）。UNEP は環境問題を扱うので、軍隊は送らない。"}, {"text": "UNEP は、世界中の感染症を調べて、ワクチンを配っている。", "explanation": "ここは〈世界保健機関〉の役割。UNEP は環境問題を扱い、感染症対策は行わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38091, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "UNEP", "is_correct": true, "explanation": "国際連合の中で環境を担当する組織を指し、この文の主語に入る。"}, {"text": "演奏", "is_correct": false, "explanation": "「環境を担当するのは演奏です」は意味をなさない。"}, {"text": "散歩", "is_correct": false, "explanation": "「環境を担当するのは散歩です」は文として成り立たない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「環境を担当するのは寝坊です」は内容として成り立たない。"}], "explanations": {"UNEP": "国際連合の中で環境を担当する組織を指し、この文の主語に入る。", "演奏": "「環境を担当するのは演奏です」は意味をなさない。", "散歩": "「環境を担当するのは散歩です」は文として成り立たない。", "寝坊": "「環境を担当するのは寝坊です」は内容として成り立たない。"}, "sentence_index": 6, "correct_answer": "UNEP"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "UNEP は、災害で家を失った人々に食べ物を届けている。", "explanation": "ここは〈赤十字〉の役割。UNEP は環境問題を扱うので、災害の救援は行わない。"}, {"text": "UNEP は、学生に環境学の学位を出す大学だ。", "explanation": "ここは〈大学〉の意味。UNEP は学位を出す教育機関ではない。"}, {"text": "UNEP は、ナイロビに本社を置く会社で、製品を売っている。", "explanation": "ここは〈会社〉の意味。UNEP は国際的な計画で、製品を売る会社ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38091, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は、UNEPから働くことを夢見ている。", "corrected_sentence": "兄は、UNEP で働くことを夢見ている。", "error_description": "「UNEPから働く」は誤り。働く場所には「で」を使うので、「UNEPで働く」が正しい。「から」は起点を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38091, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、学校は UNEP を問い合わせた。", "corrected_sentence": "先週、学校は UNEP に問い合わせた。", "error_description": "「UNEPを問い合わせた」は誤り。「問い合わせる」は相手に「に」を付けて「UNEPに問い合わせる」と言う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を示す「に」。「本の始めに」で、本の冒頭の位置を表す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」。「本の始めで」では時点の意味にならず、文に合わない。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す「を」。「本の始めを」は書いてある内容の対象にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「本の始めへ」は方向の意味になり、文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "時点を示す「に」。「本の始めに」で、本の冒頭の位置を表す。", "で": "場所や手段を示す「で」。「本の始めで」では時点の意味にならず、文に合わない。", "を": "対象を示す「を」。「本の始めを」は書いてある内容の対象にならず、不自然。", "へ": "方向を示す「へ」。「本の始めへ」は方向の意味になり、文脈に合わない。"}, "error_tags": {"で": "location_or_means", "を": "object_marker", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わり", "is_correct": true, "explanation": "「始め」の対義語。最初と最後として対になる語。"}, {"text": "途中", "is_correct": false, "explanation": "最初でも最後でもない中間を指す語で、対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "中央の位置を指す名詞で、最初の部分とは対にならない。"}, {"text": "出来事", "is_correct": false, "explanation": "起こったことを指す名詞で、「始め」の対義語ではない。"}], "correct_answer": "終わり", "explanations": {"終わり": "「始め」の対義語。最初と最後として対になる語。", "途中": "最初でも最後でもない中間を指す語で、対義語ではない。", "中心": "中央の位置を指す名詞で、最初の部分とは対にならない。", "出来事": "起こったことを指す名詞で、「始め」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わり", "is_correct": true, "explanation": "「始め」の対義語。最初と最後として対になる語。"}, {"text": "途中", "is_correct": false, "explanation": "最初でも最後でもない中間を指す語で、対義語ではない。"}, {"text": "完結", "is_correct": false, "explanation": "物事が終わって完成することを指す語で、対義語ではない。"}, {"text": "余韻", "is_correct": false, "explanation": "終わった後に残る響きを指す語で、対義語ではない。"}], "correct_answer": "終わり", "explanations": {"終わり": "「始め」の対義語。最初と最後として対になる語。", "途中": "最初でも最後でもない中間を指す語で、対義語ではない。", "完結": "物事が終わって完成することを指す語で、対義語ではない。", "余韻": "終わった後に残る響きを指す語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを新しく、または初めて行うこと。また、ものごとの最初の部分。", "primary_collocate": null, "pronunciation": "はじめ", "ipa": "hadʑime", "syllable_count": 3, "sentences": [{"text": "物語の始めは、静かな村の朝の場面です。", "target_word": "始め", "complexity_tier": "T3", "furigana": "物語(ものがたり)の始(はじ)めは、静(しず)かな村(むら)の朝(あさ)の場面(ばめん)です。", "sentence_source": "generated"}, {"text": "本の始めに、この本の使い方が書いてあります。", "target_word": "始め", "complexity_tier": "T3", "furigana": "本(ほん)の始(はじ)めに、この本(ほん)の使(つか)い方(かた)が書(か)いてあります。", "sentence_source": "generated"}, {"text": "週の始めに、その週の計画をノートに書いた。", "target_word": "始め", "complexity_tier": "T3", "furigana": "週[しゅう]の 始[はじ]めに、その 週[しゅう]の 計画[けいかく]をノートに 書[か]いた。", "sentence_source": "generated"}, {"text": "夏休みの始めに、宿題の計画を立てた。", "target_word": "始め", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの 始[はじ]めに、 宿題[しゅくだい]の 計画[けいかく]を 立[た]てた。", "sentence_source": "generated"}, {"text": "この映画は、始めが長くて少し退屈だった。", "target_word": "始め", "complexity_tier": "T3", "furigana": "この映画(えいが)は、始(はじ)めが長(なが)くて少(すこ)し退屈(たいくつ)だった。", "sentence_source": "generated"}, {"text": "始めと終わりの部分だけ読んでも、話はだいたいわかる。", "target_word": "始め", "complexity_tier": "T3", "furigana": "始(はじ)めと終(お)わりの部分(ぶぶん)だけ読(よ)んでも、話(はなし)はだいたいわかる。", "sentence_source": "generated"}, {"text": "手紙の始めに、お礼の言葉を書いた。", "target_word": "始め", "complexity_tier": "T3", "furigana": "手紙(てがみ)の始(はじ)めに、お礼(れい)の言葉(ことば)を書(か)いた。", "sentence_source": "generated"}, {"text": "英語の勉強は、まず始めの十ページから進めよう。", "target_word": "始め", "complexity_tier": "T3", "furigana": "英語(えいご)の勉強(べんきょう)は、まず始(はじ)めの十(じゅう)ページから進(すす)めよう。", "sentence_source": "generated"}, {"text": "月の始めに、家計簿を見直すことにしている。", "target_word": "始め", "complexity_tier": "T3", "furigana": "月[つき]の 始[はじ]めに、 家計簿[かけいぼ]を 見直[みなお]すことにしている。", "sentence_source": "generated"}, {"text": "この曲は始めがゆっくりで、後ろになるほど速くなる。", "target_word": "始め", "complexity_tier": "T3", "furigana": "この曲(きょく)は始(はじ)めがゆっくりで、後(うし)ろになるほど速(はや)くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "始め", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものごとの最初の部分、また何かを新しく行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 家計 (Zipf 3.75), 簿 (Zipf 3.76), 見直す (Zipf 3.64)']::text[], '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "始め", "is_correct": true, "explanation": "名詞の「始め」。「物語の始めは」で物語の最初の部分を表し、主題として文に収まる。"}, {"text": "始めた", "is_correct": false, "explanation": "過去形の動詞。名詞の位置には入らず、「物語の始めたは」は文にならない。"}, {"text": "始めよう", "is_correct": false, "explanation": "意向形の動詞。名詞の位置に入らず、この文脈では成り立たない。"}, {"text": "始めない", "is_correct": false, "explanation": "否定形の動詞。名詞の位置に入らず、「物語の始めないは」は文にならない。"}], "explanations": {"始め": "名詞の「始め」。「物語の始めは」で物語の最初の部分を表し、主題として文に収まる。", "始めた": "過去形の動詞。名詞の位置には入らず、「物語の始めたは」は文にならない。", "始めよう": "意向形の動詞。名詞の位置に入らず、この文脈では成り立たない。", "始めない": "否定形の動詞。名詞の位置に入らず、「物語の始めないは」は文にならない。"}, "sentence_index": 0, "correct_answer": "始め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は始めなので、まだ上手ではない。", "explanation": "ここは〈初心者〉の意味。「始め」は出来事の最初の部分を指す語で、人を表す使い方はしない。"}, {"text": "彼は始めを食べて、大学へ行った。", "explanation": "ここは〈食べ物〉の意味。「始め」は食べられるものではなく、物事の最初の部分を指す語。"}, {"text": "初心者向けの始めのコースに申し込んだ。", "explanation": "ここは〈初級〉の意味。「始め」は段階の最初を指すが、学習の難易度を表す「初級」の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "始め", "is_correct": true, "explanation": "名詞の「始め」。「手紙の始めに」で手紙の最初の部分を表し、「に」で時点を示す。"}, {"text": "始めて", "is_correct": false, "explanation": "て形の動詞。名詞の位置に入らず、文として成り立たない。"}, {"text": "始めれば", "is_correct": false, "explanation": "仮定形の動詞。名詞の位置に入らず、「手紙の始めれば」は文にならない。"}, {"text": "始める", "is_correct": false, "explanation": "辞書形の動詞。名詞の位置に入らず、この文脈では成り立たない。"}], "explanations": {"始め": "名詞の「始め」。「手紙の始めに」で手紙の最初の部分を表し、「に」で時点を示す。", "始めて": "て形の動詞。名詞の位置に入らず、文として成り立たない。", "始めれば": "仮定形の動詞。名詞の位置に入らず、「手紙の始めれば」は文にならない。", "始める": "辞書形の動詞。名詞の位置に入らず、この文脈では成り立たない。"}, "sentence_index": 6, "correct_answer": "始め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作業は始めを終えて、そのまま完成してしまった。", "explanation": "ここは〈完成〉の意味。「始め」は段階の最初を指す語で、作業が完成したという意味は持たない。"}, {"text": "この店は、始めの評判を捨てて売り上げを伸ばした。", "explanation": "ここは〈評判〉の意味。「始め」は物事の最初の段階を指す語で、評判や品数の意味は持たない。"}, {"text": "試合は始めを締めくくり、点差が開いた。", "explanation": "ここは〈締めくくり〉の意味。「始め」は最初の段階なので、締めくくるという行為とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週の始めを、新しい計画を立てる予定だ。", "corrected_sentence": "来週の始めに、新しい計画を立てる予定だ。", "error_description": "「始め」は時点を表す名詞なので、続く助詞は時点を示す「に」が正しい。「を」は対象を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38092, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次の月の始めを、家計簿を見直す予定だ。", "corrected_sentence": "次の月の始めに、家計簿を見直す予定だ。", "error_description": "「始め」は時点を表す名詞なので「に」が必要。「を」は対象を示すため、時点を表す語には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「始めの一歩」で、「始め」と「一歩」をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「始めが一歩」では名詞同士をつなげず、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す「を」。「始めを一歩」は踏み出す対象にならず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」。「始めで一歩」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「始めの一歩」で、「始め」と「一歩」をつなぐ。", "が": "主語を示す「が」。「始めが一歩」では名詞同士をつなげず、意味が通らない。", "を": "対象を示す「を」。「始めを一歩」は踏み出す対象にならず、不自然。", "で": "場所や手段を示す「で」。「始めで一歩」は意味が通らない。"}, "error_tags": {"が": "subject", "を": "object_marker", "で": "location_or_means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わり", "is_correct": true, "explanation": "「始め」の対義語。最初と最後として対になる語。"}, {"text": "中盤", "is_correct": false, "explanation": "中間の段階を指す語で、対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "中央の位置を指す名詞で、最初の部分とは対にならない。"}, {"text": "出来事", "is_correct": false, "explanation": "起こったことを指す名詞で、「始め」の対義語ではない。"}], "correct_answer": "終わり", "explanations": {"終わり": "「始め」の対義語。最初と最後として対になる語。", "中盤": "中間の段階を指す語で、対義語ではない。", "中心": "中央の位置を指す名詞で、最初の部分とは対にならない。", "出来事": "起こったことを指す名詞で、「始め」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「始めは」で、新しい生活の最初の段階を取り上げる。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す「を」。「始めを、わからないことばかりだった」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」。「始めで、わからないこと」は文脈に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「始めへ、わからないこと」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「始めは」で、新しい生活の最初の段階を取り上げる。", "を": "対象を示す「を」。「始めを、わからないことばかりだった」では文が成り立たない。", "で": "場所や手段を示す「で」。「始めで、わからないこと」は文脈に合わない。", "へ": "方向を示す「へ」。「始めへ、わからないこと」は意味が通らない。"}, "error_tags": {"を": "object_marker", "で": "location_or_means", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わり", "is_correct": true, "explanation": "「始め」の対義語。最初と最後として対になる語。"}, {"text": "途中", "is_correct": false, "explanation": "最初でも最後でもない中間を指す語で、対義語ではない。"}, {"text": "完結", "is_correct": false, "explanation": "物事が終わって完成することを指す語で、対義語ではない。"}, {"text": "余韻", "is_correct": false, "explanation": "終わった後に残る響きを指す語で、対義語ではない。"}], "correct_answer": "終わり", "explanations": {"終わり": "「始め」の対義語。最初と最後として対になる語。", "途中": "最初でも最後でもない中間を指す語で、対義語ではない。", "完結": "物事が終わって完成することを指す語で、対義語ではない。", "余韻": "終わった後に残る響きを指す語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の最初の段階。開始。", "primary_collocate": null, "pronunciation": "はじめ", "ipa": "hadʑime", "syllable_count": 3, "sentences": [{"text": "何事も始めが大切だと、祖父はよく言っていた。", "target_word": "始め", "complexity_tier": "T3", "furigana": "何事(なにごと)も始(はじ)めが大切(たいせつ)だと、祖父(そふ)はよく言(い)っていた。", "sentence_source": "generated"}, {"text": "始めの一歩を踏み出すのは、いつも勇気がいる。", "target_word": "始め", "complexity_tier": "T3", "furigana": "始(はじ)めの一歩(いっぽ)を踏(ふ)み出(だ)すのは、いつも勇気(ゆうき)がいる。", "sentence_source": "generated"}, {"text": "始めが悪くても、あきらめずに続ければ上手になる。", "target_word": "始め", "complexity_tier": "T3", "furigana": "始(はじ)めが悪(わる)くても、あきらめずに続(つづ)ければ上手(じょうず)になる。", "sentence_source": "generated"}, {"text": "試合の始めに、両チームの選手があいさつをした。", "target_word": "始め", "complexity_tier": "T3", "furigana": "試合(しあい)の始(はじ)めに、両(りょう)チームの選手(せんしゅ)があいさつをした。", "sentence_source": "generated"}, {"text": "この仕事は、始めの段階で計画をしっかり立てることが大事だ。", "target_word": "始め", "complexity_tier": "T3", "furigana": "この仕事(しごと)は、始(はじ)めの段階(だんかい)で計画(けいかく)をしっかり立(た)てることが大事(だいじ)だ。", "sentence_source": "generated"}, {"text": "始めは緊張したが、すぐに慣れた。", "target_word": "始め", "complexity_tier": "T3", "furigana": "始(はじ)めは緊張(きんちょう)したが、すぐに慣(な)れた。", "sentence_source": "generated"}, {"text": "練習の始めに、軽く体を動かした。", "target_word": "始め", "complexity_tier": "T3", "furigana": "練習(れんしゅう)の始(はじ)めに、軽(かる)く体(からだ)を動(うご)かした。", "sentence_source": "generated"}, {"text": "新しい生活の始めは、わからないことばかりだった。", "target_word": "始め", "complexity_tier": "T3", "furigana": "新(あたら)しい生活(せいかつ)の始(はじ)めは、わからないことばかりだった。", "sentence_source": "generated"}, {"text": "授業の始めに、先生が出席をとった。", "target_word": "始め", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)の始(はじ)めに、先生(せんせい)が出席(しゅっせき)をとった。", "sentence_source": "generated"}, {"text": "始めがうまくいったので、最後まで楽しく進められた。", "target_word": "始め", "complexity_tier": "T3", "furigana": "始(はじ)めがうまくいったので、最後(さいご)まで楽(たの)しく進(すす)められた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "始め", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事の最初の段階、開始のとき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "始め", "is_correct": true, "explanation": "名詞の「始め」。「何事も始めが大切」で物事の最初の段階を表し、「が」で主題になる。"}, {"text": "始めて", "is_correct": false, "explanation": "て形の動詞。名詞の位置に入らず、「何事も始めてが大切」は文にならない。"}, {"text": "始める", "is_correct": false, "explanation": "辞書形の動詞。名詞の位置に入らず、この文脈では成り立たない。"}, {"text": "始めます", "is_correct": false, "explanation": "丁寧形の動詞。名詞の位置に入らず、文として成り立たない。"}], "explanations": {"始め": "名詞の「始め」。「何事も始めが大切」で物事の最初の段階を表し、「が」で主題になる。", "始めて": "て形の動詞。名詞の位置に入らず、「何事も始めてが大切」は文にならない。", "始める": "辞書形の動詞。名詞の位置に入らず、この文脈では成り立たない。", "始めます": "丁寧形の動詞。名詞の位置に入らず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "始め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は始めを食べて、試合には出られなかった。", "explanation": "ここは〈食べ物〉の意味。「始め」は食べられるものではなく、物事の最初の段階を指す語。"}, {"text": "彼女は始めなので、まだ試合には出られない。", "explanation": "ここは〈初心者〉の意味。「始め」は出来事の最初の部分を指す語で、人を表さない。"}, {"text": "初心者向けの始めのクラスに入った。", "explanation": "ここは〈初級〉の意味。「始め」は段階の最初を指すが、学習の難易度を表す「初級」の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "始め", "is_correct": true, "explanation": "名詞の「始め」。「練習の始めに」で練習の最初の部分を表し、「に」で時点を示す。"}, {"text": "始めれば", "is_correct": false, "explanation": "仮定形の動詞。名詞の位置に入らず、文として成り立たない。"}, {"text": "始めよ", "is_correct": false, "explanation": "命令形の動詞。名詞の位置に入らず、文脈に合わない。"}, {"text": "始めない", "is_correct": false, "explanation": "否定形の動詞。名詞の位置に入らず、「練習の始めないに」は文にならない。"}], "explanations": {"始め": "名詞の「始め」。「練習の始めに」で練習の最初の部分を表し、「に」で時点を示す。", "始めれば": "仮定形の動詞。名詞の位置に入らず、文として成り立たない。", "始めよ": "命令形の動詞。名詞の位置に入らず、文脈に合わない。", "始めない": "否定形の動詞。名詞の位置に入らず、「練習の始めないに」は文にならない。"}, "sentence_index": 6, "correct_answer": "始め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は練習の始めを鍋に入れて、煮込んだ。", "explanation": "ここは〈食材〉の意味。「始め」は物事の最初の段階を指す語で、料理の材料ではない。"}, {"text": "この薬は始めを飲みすぎると危険だ。", "explanation": "ここは〈初回の量〉の意味ではない。「始め」は物事の最初の段階を指す語で、薬の量の意味は持たない。"}, {"text": "彼は練習の始めを笑い飛ばして、すぐ帰った。", "explanation": "ここは〈軽視する〉の意味。「始め」は物事の最初の段階を指す語で、笑い飛ばす対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週の始めを、いつも気分が重い。", "corrected_sentence": "週の始めは、いつも気分が重い。", "error_description": "「始め」は主題を示す「は」で続くのが自然。「を」は対象を示すので、この文では文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38093, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "練習の始めて、ストレッチをしてから走った。", "corrected_sentence": "練習の始めに、ストレッチをしてから走った。", "error_description": "「始めて」は動詞「始める」の連用形で、名詞「始め」の後に「の」で続けることはできない。時点を示す「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を示す「を」。「顔を向けて」で、動かされる顔を表す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」。「顔で向けて」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「顔の向けて」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「顔が向けて」は述語とつながらず、不自然。"}], "correct_answer": "を", "explanations": {"を": "対象を示す「を」。「顔を向けて」で、動かされる顔を表す。", "で": "場所や手段を示す「で」。「顔で向けて」は意味が通らない。", "の": "連体修飾の「の」。「顔の向けて」は文として成り立たない。", "が": "主語を示す「が」。「顔が向けて」は述語とつながらず、不自然。"}, "error_tags": {"で": "location_or_means", "の": "attributive", "が": "subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背ける", "is_correct": true, "explanation": "「向ける」の対義語。向きを反対に変えて遠ざける意味で、対になる語。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる語で、向きを変える意味の対義語ではない。"}, {"text": "渡す", "is_correct": false, "explanation": "相手に物を受け渡す語で、対義語ではない。"}, {"text": "出す", "is_correct": false, "explanation": "外へ出す意味の語で、「向ける」の対義語ではない。"}], "correct_answer": "背ける", "explanations": {"背ける": "「向ける」の対義語。向きを反対に変えて遠ざける意味で、対になる語。", "運ぶ": "物を移動させる語で、向きを変える意味の対義語ではない。", "渡す": "相手に物を受け渡す語で、対義語ではない。", "出す": "外へ出す意味の語で、「向ける」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背ける", "is_correct": true, "explanation": "「向ける」の対義語。向きを反対に変えて遠ざける意味で、対になる語。"}, {"text": "送る", "is_correct": false, "explanation": "物や人を別の場所へ届ける語で、対義語ではない。"}, {"text": "投げる", "is_correct": false, "explanation": "物を勢いよく飛ばす語で、「向ける」の対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物を一定の場所に据える語で、対義語ではない。"}], "correct_answer": "背ける", "explanations": {"背ける": "「向ける」の対義語。向きを反対に変えて遠ざける意味で、対になる語。", "送る": "物や人を別の場所へ届ける語で、対義語ではない。", "投げる": "物を勢いよく飛ばす語で、「向ける」の対義語ではない。", "置く": "物を一定の場所に据える語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをある方向へ動かすこと。", "primary_collocate": null, "pronunciation": "むける", "ipa": "mɯkeɾɯ", "syllable_count": 3, "sentences": [{"text": "彼女はカメラを私に向けた。", "target_word": "向けた", "complexity_tier": "T3", "furigana": "彼女(かのじょ)はカメラを私(わたし)に向(む)けた。", "sentence_source": "generated"}, {"text": "先生は生徒たちのほうに顔を向けて、にっこり笑った。", "target_word": "向けて", "complexity_tier": "T3", "furigana": "先生(せんせい)は生徒(せいと)たちのほうに顔(かお)を向(む)けて、にっこり笑(わら)った。", "sentence_source": "generated"}, {"text": "犬に背中を向けると、吠えられた。", "target_word": "向ける", "complexity_tier": "T3", "furigana": "犬(いぬ)に背中(せなか)を向(む)けると、吠(ほ)えられた。", "sentence_source": "generated"}, {"text": "店員はレジの画面をお客さんのほうに向けた。", "target_word": "向けた", "complexity_tier": "T3", "furigana": "店員[てんいん]はレジの 画面[がめん]をお客[きゃく]さんのほうに 向[む]けた。", "sentence_source": "generated"}, {"text": "その子はボールを壁に向けて、勢いよく投げた。", "target_word": "向けて", "complexity_tier": "T3", "furigana": "その 子[こ]はボールを 壁[かべ]に 向[む]けて、 勢[いきお]いよく 投[な]げた。", "sentence_source": "generated"}, {"text": "彼は怒った顔を弟に向けた。", "target_word": "向けた", "complexity_tier": "T3", "furigana": "彼(かれ)は怒(おこ)った顔(かお)を弟(おとうと)に向(む)けた。", "sentence_source": "generated"}, {"text": "ライトを窓のほうに向ければ、部屋が明るくなる。", "target_word": "向ければ", "complexity_tier": "T3", "furigana": "ライトを窓(まど)のほうに向(む)ければ、部屋(へや)が明(あか)るくなる。", "sentence_source": "generated"}, {"text": "失礼なので、人に指を向けてはいけません。", "target_word": "向けて", "complexity_tier": "T3", "furigana": "失礼(しつれい)なので、人(ひと)に指(ゆび)を向(む)けてはいけません。", "sentence_source": "generated"}, {"text": "みんなが私に目を向けたので、少し恥ずかしかった。", "target_word": "向けた", "complexity_tier": "T3", "furigana": "みんなが私(わたし)に目(め)を向(む)けたので、少(すこ)し恥(は)ずかしかった。", "sentence_source": "generated"}, {"text": "彼は私に笑顔を向けて、手を振った。", "target_word": "向けて", "complexity_tier": "T3", "furigana": "彼(かれ)は私(わたし)に笑顔(えがお)を向(む)けて、手(て)を振(ふ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "向ける", "label": "辞書形"}, {"form": "向けます", "label": "丁寧形"}, {"form": "向けない", "label": "否定形"}, {"form": "向けて", "label": "て形"}, {"form": "向けた", "label": "た形"}, {"form": "向ければ", "label": "仮定形"}, {"form": "向けられる", "label": "受身形"}, {"form": "向けよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "体や物、視線などをある方向へ向きを変えて動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22fa4ac9-fa67-46b9-94a9-63b0d2a85822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向けた", "is_correct": true, "explanation": "過去形。「カメラを私に向けた」で、動作の結果を述べ、文の述語として終わる。"}, {"text": "向けれ", "is_correct": false, "explanation": "正しくない活用形。文の述語として成り立たず、「向ける」の活用としても誤り。"}, {"text": "向けば", "is_correct": false, "explanation": "仮定の形。条件を示す節になり、文を終えられない。"}, {"text": "向けさせ", "is_correct": false, "explanation": "使役の形。目的語とつながらず、文が成り立たない。"}], "explanations": {"向けた": "過去形。「カメラを私に向けた」で、動作の結果を述べ、文の述語として終わる。", "向けれ": "正しくない活用形。文の述語として成り立たず、「向ける」の活用としても誤り。", "向けば": "仮定の形。条件を示す節になり、文を終えられない。", "向けさせ": "使役の形。目的語とつながらず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "向けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、会社に向けて電車で出かける。", "explanation": "ここは〈向かう〉の意味。人が移動する場面は「向かう」を使い、「向ける」は物や視線の向きを変える語。"}, {"text": "彼は夢に向けて、ドアを閉めた。", "explanation": "ここは〈閉める〉の意味。ドアを閉める動作には「向ける」は使わず、向きを変えて動かす意味にはならない。"}, {"text": "スマホの電源を向けて、充電を始めた。", "explanation": "ここは電源の向きを変える文脈ではない。電源は入れたり切ったりするもので、「向ける」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向ければ", "is_correct": true, "explanation": "仮定形。「窓のほうに向ければ、部屋が明るくなる」と条件を示し、文が成り立つ。"}, {"text": "向けた", "is_correct": false, "explanation": "た形。後ろの「、部屋が明るくなる」と条件の関係にならず、文が成り立たない。"}, {"text": "向けよう", "is_correct": false, "explanation": "意向形。意志を表す形で、条件の節としても文としても成り立たない。"}, {"text": "向けます", "is_correct": false, "explanation": "丁寧形。条件を示す節を作れず、「向けます、部屋が明るくなる」は不自然。"}], "explanations": {"向ければ": "仮定形。「窓のほうに向ければ、部屋が明るくなる」と条件を示し、文が成り立つ。", "向けた": "た形。後ろの「、部屋が明るくなる」と条件の関係にならず、文が成り立たない。", "向けよう": "意向形。意志を表す形で、条件の節としても文としても成り立たない。", "向けます": "丁寧形。条件を示す節を作れず、「向けます、部屋が明るくなる」は不自然。"}, "sentence_index": 6, "correct_answer": "向ければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は駅に向けて、毎朝自転車で走っている。", "explanation": "ここは〈向かう〉の意味。人が移動する場面は「向かう」を使い、「向ける」は物や視線の向きを変える語。"}, {"text": "彼女は朝早く家を出て、空港に向けて歩き出した。", "explanation": "ここは〈向かう〉の意味。人が移動する場面で「向ける」は使わない。"}, {"text": "雨が窓に向けて降っている。", "explanation": "ここは雨の降る方向を述べる場面。「向ける」は人や物が向きを変えて動かす語で、雨には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩は資料を私に向いて、説明を始めた。", "corrected_sentence": "先輩は資料を私に向けて、説明を始めた。", "error_description": "「向ける」は他動詞で「を」を取り、動かす対象を示す。「向く」は自動詞なので、「資料を向いて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "向けて", "is_correct": true, "explanation": "て形。「顔を向けて、にっこり笑った」で、動作を続けて次の動作へつなぐ。"}, {"text": "向けろ", "is_correct": false, "explanation": "命令形。文の途中に入れると命令になり、前後の流れと合わない。"}, {"text": "向けない", "is_correct": false, "explanation": "否定形。向けないという意味になり、笑う動作の流れと合わない。"}, {"text": "向けます", "is_correct": false, "explanation": "丁寧形。文体が合わず、前後の文脈とつながらない。"}], "correct_form": "向けて", "base_form": "向ける", "form_label": "て形", "sentence_index": 1, "explanations": {"向けて": "て形。「顔を向けて、にっこり笑った」で、動作を続けて次の動作へつなぐ。", "向けろ": "命令形。文の途中に入れると命令になり、前後の流れと合わない。", "向けない": "否定形。向けないという意味になり、笑う動作の流れと合わない。", "向けます": "丁寧形。文体が合わず、前後の文脈とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38094, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は私に笑顔が向けて、会釈した。", "corrected_sentence": "彼は私に笑顔を向けて、会釈した。", "error_description": "「向ける」の対象を示すのは「を」。「笑顔が」と主語の「が」を使うと、対象との関係が成り立たず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "向けて", "is_correct": true, "explanation": "て形。「人に指を向けてはいけません」で、動作を表しつつ次の否定の文へつなぐ。"}, {"text": "向けます", "is_correct": false, "explanation": "丁寧形。「はいけません」と続けると文体が崩れ、文脈と合わない。"}, {"text": "向けられる", "is_correct": false, "explanation": "受身形。「指を向けられる」は受ける側を表し、文の主体が合わない。"}, {"text": "向けよう", "is_correct": false, "explanation": "意向形。意志を表す形で、禁止の文脈と合わない。"}], "correct_form": "向けて", "base_form": "向ける", "form_label": "て形", "sentence_index": 7, "explanations": {"向けて": "て形。「人に指を向けてはいけません」で、動作を表しつつ次の否定の文へつなぐ。", "向けます": "丁寧形。「はいけません」と続けると文体が崩れ、文脈と合わない。", "向けられる": "受身形。「指を向けられる」は受ける側を表し、文の主体が合わない。", "向けよう": "意向形。意志を表す形で、禁止の文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0ee068-6c48-4147-b22d-9632107a8bd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「帰ることで合意した」の「で」は、合意の内容や決め方を示す。"}, {"text": "を", "is_correct": false, "explanation": "「合意」は「〜ことに」「〜ことで」で内容を示し、「を」では続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、合意の内容を表せず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「帰ることから合意した」では合意の内容が通らない。"}], "correct_answer": "で", "explanations": {"で": "「帰ることで合意した」の「で」は、合意の内容や決め方を示す。", "を": "「合意」は「〜ことに」「〜ことで」で内容を示し、「を」では続かない。", "へ": "「へ」は方向を示すので、合意の内容を表せず文が成り立たない。", "から": "「から」は起点を示し、「帰ることから合意した」では合意の内容が通らない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "から": "起点の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「合意が成立した」の「が」は、成立する主体である合意を示す。"}, {"text": "に", "is_correct": false, "explanation": "「成立」は「合意に」を取らず、「合意に成立した」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「合意の成立した」は、「成立した」の主語を示せず文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「合意より成立した」と比べる対象がずれ、文意が通らない。"}], "correct_answer": "が", "explanations": {"が": "「合意が成立した」の「が」は、成立する主体である合意を示す。", "に": "「成立」は「合意に」を取らず、「合意に成立した」は不自然。", "の": "「合意の成立した」は、「成立した」の主語を示せず文が続かない。", "より": "比較の「より」は「合意より成立した」と比べる対象がずれ、文意が通らない。"}, "error_tags": {"に": "位置・対象の誤り", "の": "連体修飾の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みんなの意見を合わせること。", "primary_collocate": null, "pronunciation": "ごうい", "ipa": "ɡoːi", "syllable_count": 3, "sentences": [{"text": "話し合いの結果、全員が合意した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いの結果[けっか]、全員[ぜんいん]が合意[ごうい]した。", "sentence_source": "generated"}, {"text": "兄と私は、夜十時までに帰ることで合意した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は、夜[よる]十時[じゅうじ]までに帰[かえ]ることで合意[ごうい]した。", "sentence_source": "generated"}, {"text": "二つの会社は、値段について合意に達した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は、値段[ねだん]について合意[ごうい]に達[たっ]した。", "sentence_source": "generated"}, {"text": "意見が分かれたので、なかなか合意できなかった。", "target_word": "合意", "complexity_tier": "T3", "furigana": "意見[いけん]が分[わ]かれたので、なかなか合意[ごうい]できなかった。", "sentence_source": "generated"}, {"text": "クラスの合意がないと、このルールは決められない。", "target_word": "合意", "complexity_tier": "T3", "furigana": "クラスの合意[ごうい]がないと、このルールは決[き]められない。", "sentence_source": "generated"}, {"text": "家族みんなの合意を得てから、犬を飼うことにした。", "target_word": "合意", "complexity_tier": "T3", "furigana": "家族[かぞく]みんなの合意[ごうい]を得[え]てから、犬[いぬ]を飼[か]うことにした。", "sentence_source": "generated"}, {"text": "合意したのに、彼は約束を守らなかった。", "target_word": "合意", "complexity_tier": "T3", "furigana": "合意[ごうい]したのに、彼[かれ]は約束[やくそく]を守[まも]らなかった。", "sentence_source": "generated"}, {"text": "長い議論のあと、やっと合意が成立した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "長[なが]い議論[ぎろん]のあと、やっと合意[ごうい]が成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "旅行の行き先は、三人の合意で京都に決まった。", "target_word": "合意", "complexity_tier": "T3", "furigana": "旅行[りょこう]の行[い]き先[さき]は、三人[さんにん]の合意[ごうい]で京都[きょうと]に決[き]まった。", "sentence_source": "generated"}, {"text": "二人は料金を半分ずつ払うことに合意した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "二人[ふたり]は料金[りょうきん]を半分[はんぶん]ずつ払[はら]うことに合意[ごうい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合意する", "label": "辞書形"}, {"form": "合意した", "label": "過去形"}, {"form": "合意して", "label": "て形"}, {"form": "合意しない", "label": "否定形"}], "register": "中立（普通体）", "sense_fingerprint": "話し合いの末に、関係する人たちの意見が同じになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合意", "is_correct": true, "explanation": "話し合いの結果、全員が意見を一致させたという文脈に合う。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、「全員が地震した」という人の動作の文にならない。"}, {"text": "台風", "is_correct": false, "explanation": "台風も自然現象で、「全員が台風した」は意味をなさない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は物の名前で、「全員が花瓶した」と人の動作の文にはできない。"}], "explanations": {"合意": "話し合いの結果、全員が意見を一致させたという文脈に合う。", "地震": "地震は自然現象で、「全員が地震した」という人の動作の文にならない。", "台風": "台風も自然現象で、「全員が台風した」は意味をなさない。", "花瓶": "花瓶は物の名前で、「全員が花瓶した」と人の動作の文にはできない。"}, "sentence_index": 0, "correct_answer": "合意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一人で考えた末、自分の判断に合意した。", "explanation": "ここは〈納得〉の意味。合意は複数の人の意見が一致することなので、一人が自分の判断に納得する場面には使わない。"}, {"text": "友人の親切に、彼は合意して深く感謝した。", "explanation": "ここは〈感謝〉の意味。親切に礼を言うことは感謝で、合意は当事者が話し合って同じ結論に達すること。"}, {"text": "先生の質問に、彼は合意して大きな声で答えた。", "explanation": "ここは〈返答〉の意味。質問に答えることは返答で、合意は当事者が意見を一致させることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合意", "is_correct": true, "explanation": "「合意したのに、彼は約束を守らなかった」で、取り決めをしたのに守らなかったという文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は動作の主体にならず、「雨したのに」は動詞として成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "机は物の名前で、「机したのに」は人の動作として通じない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は物の名前で、「椅子したのに」は意味をなさない。"}], "explanations": {"合意": "「合意したのに、彼は約束を守らなかった」で、取り決めをしたのに守らなかったという文脈に合う。", "雨": "雨は動作の主体にならず、「雨したのに」は動詞として成り立たない。", "机": "机は物の名前で、「机したのに」は人の動作として通じない。", "椅子": "椅子は物の名前で、「椅子したのに」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "合意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日は雨になると、天気予報が合意した。", "explanation": "ここは〈予想〉の意味。天気の見通しは人が一致させて決めるものではないので、合意は使わない。"}, {"text": "彼は遅刻を、先生の前で合意して謝った。", "explanation": "ここは〈謝罪〉の意味。過ちを詫びることは謝罪で、相手と意見を一致させる合意とは違う。"}, {"text": "社長は全員に残業を命じるという合意を、一人で押しつけた。", "explanation": "ここは〈命令〉の意味。一方的に指示することは命令で、双方が話し合って決める合意とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは来週の日程を合意した。", "corrected_sentence": "私たちは来週の日程に合意した。", "error_description": "「合意」は「〜に合意する」と内容に「に」を付ける。「日程を合意した」の「を」が誤りで、正しくは「日程に合意した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38096, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は昼食代を割り勘にすることに合意ない。", "corrected_sentence": "二人は昼食代を割り勘にすることに合意した。", "error_description": "「合意」は名詞なので「合意した」「合意しなかった」と活用する。「合意ない」は形容詞の形で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「合意により」の「に」は「により」の一部で、合意を理由や手段として示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「合意を、より」の形は作れない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「合意が、より」と続けられず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「合意へ、により」とはつながらない。"}], "correct_answer": "に", "explanations": {"に": "「合意により」の「に」は「により」の一部で、合意を理由や手段として示す。", "を": "「を」は目的語を示すが、「合意を、より」の形は作れない。", "が": "「が」は主語を示すが、「合意が、より」と続けられず文が成り立たない。", "へ": "「へ」は方向を示し、「合意へ、により」とはつながらない。"}, "error_tags": {"を": "目的語の誤り", "が": "主語の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「組合の合意」の「の」は、合意を行う主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「組合を合意」は名詞として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「組合へ合意」と合意の当事者を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「組合より合意は難しい」と比べる対象がずれる。"}], "correct_answer": "の", "explanations": {"の": "「組合の合意」の「の」は、合意を行う主体を示す。", "を": "「を」は目的語を示すが、「組合を合意」は名詞として続かない。", "へ": "「へ」は方向を示し、「組合へ合意」と合意の当事者を表せない。", "より": "比較の「より」は「組合より合意は難しい」と比べる対象がずれる。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人の意見や考えを一致させて、一つのまとまったものにすること。", "primary_collocate": null, "pronunciation": "ごうい", "ipa": "ɡoːi", "syllable_count": 3, "sentences": [{"text": "両国は貿易の新しいルールについて合意した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "両国[りょうこく]は貿易[ぼうえき]の新[あたら]しいルールについて合意[ごうい]した。", "sentence_source": "generated"}, {"text": "労使の合意により、来月から勤務時間が短くなる。", "target_word": "合意", "complexity_tier": "T3", "furigana": "労使[ろうし]の合意[ごうい]により、来月[らいげつ]から勤務[きんむ]時間[じかん]が短[みじか]くなる。", "sentence_source": "generated"}, {"text": "会議では、全体の合意が得られなかった。", "target_word": "合意", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、全体[ぜんたい]の合意[ごうい]が得[え]られなかった。", "sentence_source": "generated"}, {"text": "各国の代表は、環境を守る方針で合意に至った。", "target_word": "合意", "complexity_tier": "T3", "furigana": "各国[かっこく]の代表[だいひょう]は、環境[かんきょう]を守[まも]る方針[ほうしん]で合意[ごうい]に至[いた]った。", "sentence_source": "generated"}, {"text": "住民の合意がないまま、工事を始めてはいけない。", "target_word": "合意", "complexity_tier": "T3", "furigana": "住民[じゅうみん]の合意[ごうい]がないまま、工事[こうじ]を始[はじ]めてはいけない。", "sentence_source": "generated"}, {"text": "交渉は続いたが、双方は最後まで合意しなかった。", "target_word": "合意", "complexity_tier": "T3", "furigana": "交渉[こうしょう]は続[つづ]いたが、双方[そうほう]は最後[さいご]まで合意[ごうい]しなかった。", "sentence_source": "generated"}, {"text": "社内で合意ができたので、計画を進めることにした。", "target_word": "合意", "complexity_tier": "T3", "furigana": "社内[しゃない]で合意[ごうい]ができたので、計画[けいかく]を進[すす]めることにした。", "sentence_source": "generated"}, {"text": "条件が厳しすぎて、会社と組合の合意は難しい。", "target_word": "合意", "complexity_tier": "T3", "furigana": "条件[じょうけん]が厳[きび]しすぎて、会社[かいしゃ]と組合[くみあい]の合意[ごうい]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "合意の内容は、明日の朝に発表される。", "target_word": "合意", "complexity_tier": "T3", "furigana": "合意[ごうい]の内容[ないよう]は、明日[あした]の朝[あさ]に発表[はっぴょう]される。", "sentence_source": "generated"}, {"text": "二つの政党は、増税をしないことで合意した。", "target_word": "合意", "complexity_tier": "T3", "furigana": "二[ふた]つの政党[せいとう]は、増税[ぞうぜい]をしないことで合意[ごうい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合意する", "label": "辞書形"}, {"form": "合意した", "label": "過去形"}, {"form": "合意して", "label": "て形"}, {"form": "合意しない", "label": "否定形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "国・組織・集団などが交渉や会議を通じて一つの結論にまとまること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合意", "is_correct": true, "explanation": "「ルールについて合意した」は、交渉の末に結論にまとまったという文脈に合う。"}, {"text": "机", "is_correct": false, "explanation": "机は物の名前で、「ルールについて机した」は動詞として成り立たない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は物の名前で、「ルールについて椅子した」は意味をなさない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は物の名前で、「ルールについて花瓶した」は文として通じない。"}], "explanations": {"合意": "「ルールについて合意した」は、交渉の末に結論にまとまったという文脈に合う。", "机": "机は物の名前で、「ルールについて机した」は動詞として成り立たない。", "椅子": "椅子は物の名前で、「ルールについて椅子した」は意味をなさない。", "花瓶": "花瓶は物の名前で、「ルールについて花瓶した」は文として通じない。"}, "sentence_index": 0, "correct_answer": "合意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "委員長の一存で、新しい条例に合意した。", "explanation": "ここは〈決定〉の意味。一人が判断して決めることは決定で、複数の人が意見を一致させる合意とは違う。"}, {"text": "敵国は国境で、突然の攻撃に合意した。", "explanation": "ここは〈決行〉の意味。一方的に攻撃を仕掛けることは決行で、双方が一致させる合意とは違う。"}, {"text": "母の手伝いに、彼は合意して心から感謝した。", "explanation": "ここは〈感謝〉の意味。好意に礼を言うことは感謝で、双方の一致を目指す合意とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合意", "is_correct": true, "explanation": "「社内で合意ができたので」は、社内で意見がまとまったという文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は話し合いの結論にならず、「社内で雨ができた」は意味をなさない。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、「社内で地震ができた」は文脈に合わない。"}, {"text": "台風", "is_correct": false, "explanation": "台風は自然現象で、「社内で台風ができた」は文脈に合わない。"}], "explanations": {"合意": "「社内で合意ができたので」は、社内で意見がまとまったという文脈に合う。", "雨": "雨は話し合いの結論にならず、「社内で雨ができた」は意味をなさない。", "地震": "地震は自然現象で、「社内で地震ができた」は文脈に合わない。", "台風": "台風は自然現象で、「社内で台風ができた」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "合意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの企業は、昨日の天気について合意した。", "explanation": "ここは〈雑談〉の意味。世間話をすることは雑談で、結論を一つにまとめる合意とは違う。"}, {"text": "二つの政党は、増税案をめぐって激しく合意した。", "explanation": "ここは〈口論〉の意味。激しく言い争うことは口論で、意見を一致させる合意とは逆の行為。"}, {"text": "首相は、増税の見送りについて、国民の前で一人で合意した。", "explanation": "ここは〈宣言〉の意味。一人の方針を公に示すことは宣言で、双方の話し合いで一致させる合意ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両国は国境の問題を合意した。", "corrected_sentence": "両国は国境の問題について合意した。", "error_description": "「合意」は「〜について合意する」と内容を「について」で示す。「国境の問題を合意した」は誤りで、「について」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38097, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二国は水資源の利用について合意を飲んだ。", "corrected_sentence": "二国は水資源の利用について合意した。", "error_description": "「合意」は「する」で動詞になる。「合意を飲んだ」は「条件を飲む」と混同した誤りで、正しくは「合意した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38098, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「力に昇華する」で、怒りが変わって至る先の到達点（力）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「怒りを」で目的語の「を」がすでに使われており、「力を昇華」は二つ目の目的語が重なって不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞同士をつなぐ。「力の昇華できれば」では後ろに名詞がなく、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を表す。「力と昇華できれば」では変化の到達点が示せず、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。「力に昇華する」で、怒りが変わって至る先の到達点（力）を示す。", "を": "「怒りを」で目的語の「を」がすでに使われており、「力を昇華」は二つ目の目的語が重なって不自然。", "の": "「の」は名詞同士をつなぐ。「力の昇華できれば」では後ろに名詞がなく、文が成り立たない。", "と": "「と」は相手や共同を表す。「力と昇華できれば」では変化の到達点が示せず、意味が通らない。"}, "error_tags": {"に": "変化の到達点", "を": "目的語の重複", "の": "名詞修飾", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
