INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38098, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが、もっとすばらしいものや高いものに変わること。", "primary_collocate": null, "pronunciation": "しょうか", "ipa": "ɕoːka", "syllable_count": 3, "sentences": [{"text": "彼は失恋の苦しみを一編の詩へと昇華させた。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "彼[かれ]は失恋[しつれん]の苦[くる]しみを一編[いっぺん]の詩[し]へと昇華[しょうか]させた。", "sentence_source": "generated"}, {"text": "怒りを創作の力に昇華できれば、人は前に進める。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "怒[いか]りを創作[そうさく]の力[ちから]に昇華[しょうか]できれば、人[ひと]は前[まえ]に進[すす]める。", "sentence_source": "generated"}, {"text": "二人の友情は、やがて深い信頼へと昇華していった。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "二人[ふたり]の友情[ゆうじょう]は、やがて深[ふか]い信頼[しんらい]へと昇華[しょうか]していった。", "sentence_source": "generated"}, {"text": "悲しい経験を音楽に昇華した作品が、多くの人の心を打った。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "悲[かな]しい経験[けいけん]を音楽[おんがく]に昇華[しょうか]した作品[さくひん]が、多[おお]くの人[ひと]の心[こころ]を打[う]った。", "sentence_source": "generated"}, {"text": "彼女は自分の苦労を笑える物語に昇華して発表した。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の苦労[くろう]を笑[わら]える物語[ものがたり]に昇華[しょうか]して発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "単なる憧れが、本物の尊敬へと昇華することもある。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "単[たん]なる憧[あこが]れが、本物[ほんもの]の尊敬[そんけい]へと昇華[しょうか]することもある。", "sentence_source": "generated"}, {"text": "画家は戦争の記憶を一枚の絵に昇華させた。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "画家[がか]は戦争[せんそう]の記憶[きおく]を一枚[いちまい]の絵[え]に昇華[しょうか]させた。", "sentence_source": "generated"}, {"text": "個人的な恨みを社会を良くする活動に昇華させた人もいる。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "個人的[こじんてき]な恨[うら]みを社会[しゃかい]を良[よ]くする活動[かつどう]に昇華[しょうか]させた人[ひと]もいる。", "sentence_source": "generated"}, {"text": "彼の努力は、ただの技術を芸術の域にまで昇華させた。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "彼[かれ]の努力[どりょく]は、ただの技術[ぎじゅつ]を芸術[げいじゅつ]の域[いき]にまで昇華[しょうか]させた。", "sentence_source": "generated"}, {"text": "苦しみを作品に昇華するのは、簡単なことではない。", "target_word": "昇華", "complexity_tier": "T3", "furigana": "苦[くる]しみを作品[さくひん]に昇華[しょうか]するのは、簡単[かんたん]なことではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昇華する", "label": "辞書形"}, {"form": "昇華した", "label": "過去形"}, {"form": "昇華させる", "label": "使役形"}, {"form": "昇華して", "label": "て形"}, {"form": "昇華しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "感情や経験がより高い価値のあるもの(芸術・信頼など)へ変わること。比喩的な意味で、物質の状態変化ではない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38098, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昇華", "is_correct": true, "explanation": "正解。「へと昇華させた」で、苦しみがより高い価値を持つ一編の詩に変わったことを表す。"}, {"text": "消滅", "is_correct": false, "explanation": "消滅は無くなってしまう意味。苦しみを詩という形に高めて残す内容と逆になる。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は手放して捨てる意味で、苦しみを詩に変えるという行為と逆になる。"}, {"text": "分解", "is_correct": false, "explanation": "分解は要素に分けてばらばらにする意味。苦しみを一つの作品にまとめる文脈には合わない。"}], "explanations": {"昇華": "正解。「へと昇華させた」で、苦しみがより高い価値を持つ一編の詩に変わったことを表す。", "消滅": "消滅は無くなってしまう意味。苦しみを詩という形に高めて残す内容と逆になる。", "放棄": "放棄は手放して捨てる意味で、苦しみを詩に変えるという行為と逆になる。", "分解": "分解は要素に分けてばらばらにする意味。苦しみを一つの作品にまとめる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "昇華"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汚れた空気をフィルターで昇華して、きれいにした。", "explanation": "ここは〈浄化〉の意味。汚れを取り除いて清くすることは浄化と言い、より高いものへ変わる昇華とは別なので合わない。"}, {"text": "夏の暑さで牛乳が昇華した。", "explanation": "ここは〈変質〉の意味。牛乳が傷んで質が落ちることは、質が高まって変わる〈昇華〉とは逆で、この言葉は使わない。"}, {"text": "天気が急に昇華して、雨が降り出した。", "explanation": "ここは〈変化〉の意味。天気が変わることは表せるが、価値が高まる変化ではないので昇華は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38098, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昇華", "is_correct": true, "explanation": "正解。「一枚の絵に昇華させた」で、記憶が絵という形ある価値に変わったことを表す。"}, {"text": "解体", "is_correct": false, "explanation": "解体は組み立てたものを壊してばらばらにする意味。記憶を絵に高めて残す文脈とは逆の行為になる。"}, {"text": "忘却", "is_correct": false, "explanation": "忘却は記憶を忘れてしまう意味で、記憶を絵として残すという内容と反する。"}, {"text": "抹消", "is_correct": false, "explanation": "抹消は消して無かったことにする意味。絵に残すという文脈には合わない。"}], "explanations": {"昇華": "正解。「一枚の絵に昇華させた」で、記憶が絵という形ある価値に変わったことを表す。", "解体": "解体は組み立てたものを壊してばらばらにする意味。記憶を絵に高めて残す文脈とは逆の行為になる。", "忘却": "忘却は記憶を忘れてしまう意味で、記憶を絵として残すという内容と反する。", "抹消": "抹消は消して無かったことにする意味。絵に残すという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "昇華"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病気を昇華するのは、医者の大切な仕事だ。", "explanation": "ここは〈克服〉の意味。病気は価値の高いものへ変わるものではないので、昇華は合わない。"}, {"text": "夢の意味を昇華して、ノートに書き写した。", "explanation": "ここは〈解釈〉の意味。夢の意味を読み解く行為で、より高いものへ変わる昇華とは合わない。"}, {"text": "データを昇華して、原因を突き止めた。", "explanation": "ここは〈分析〉の意味。データを細かく調べる行為であり、昇華では意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38098, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人は自分の失敗を笑い話を昇華して語った。", "corrected_sentence": "友人は自分の失敗を笑い話に昇華して語った。", "error_description": "変化の到達点を示す「に」が必要なところを「を」にした誤り。「AをBに昇華する」の形で、Bの後ろには「に」が付く。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38098, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は戦争体験を一冊の本に昇華せた。", "corrected_sentence": "祖母は戦争体験を一冊の本に昇華させた。", "error_description": "「昇華する」の使役形は「昇華させる」。「昇華せた」は「せる」を付けた誤った形で、正しくは「昇華させた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38100, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "複雑", "is_correct": true, "explanation": "〈かんたん〉の反対で、シンプルの対義語として対になる。"}, {"text": "穏やか", "is_correct": false, "explanation": "形状詞だが、シンプルの対義語ではない。"}, {"text": "丈夫", "is_correct": false, "explanation": "形状詞だが、シンプルの対義語ではない。"}, {"text": "確か", "is_correct": false, "explanation": "形状詞だが、シンプルの対義語ではない。"}], "correct_answer": "複雑", "explanations": {"複雑": "〈かんたん〉の反対で、シンプルの対義語として対になる。", "穏やか": "形状詞だが、シンプルの対義語ではない。", "丈夫": "形状詞だが、シンプルの対義語ではない。", "確か": "形状詞だが、シンプルの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
