INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38100, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かんたんだ、という意味。むずかしくない。", "primary_collocate": null, "pronunciation": "しんぷる", "ipa": "ɕimpɯɾɯ", "syllable_count": 4, "sentences": [{"text": "このカレーの作り方はシンプルで、三十分でできます。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "このカレーの作[つく]り方[かた]はシンプルで、三十分[さんじゅっぷん]でできます。", "sentence_source": "generated"}, {"text": "シンプルな説明のほうが、子どもにはわかりやすいです。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "シンプルな説明[せつめい]のほうが、子[こ]どもにはわかりやすいです。", "sentence_source": "generated"}, {"text": "使い方がシンプルなので、説明書は要りません。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "使[つか]い方[かた]がシンプルなので、説明書[せつめいしょ]は要[い]りません。", "sentence_source": "generated"}, {"text": "ルールがシンプルだから、誰でもすぐ遊べます。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "ルールがシンプルだから、誰[だれ]でもすぐ遊[あそ]べます。", "sentence_source": "generated"}, {"text": "シンプルな問題から始めて、少しずつ難しくします。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "シンプルな問題[もんだい]から始[はじ]めて、少[すこ]しずつ難[むずか]しくします。", "sentence_source": "generated"}, {"text": "彼女の答えはいつもシンプルで、短いです。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の答[こた]えはいつもシンプルで、短[みじか]いです。", "sentence_source": "generated"}, {"text": "このアプリは操作がシンプルで、迷いません。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "このアプリは操作[そうさ]がシンプルで、迷[まよ]いません。", "sentence_source": "generated"}, {"text": "シンプルに考えれば、答えは一つだけです。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "シンプルに考[かんが]えれば、答[こた]えは一[ひと]つだけです。", "sentence_source": "generated"}, {"text": "手順がシンプルな料理は、準備が楽です。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "手順[てじゅん]がシンプルな料理[りょうり]は、準備[じゅんび]が楽[らく]です。", "sentence_source": "generated"}, {"text": "テストの内容はシンプルで、誰でも解けました。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "テストの内容[ないよう]はシンプルで、誰[だれ]でも解[と]けました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シンプルだ", "label": "終止形"}, {"form": "シンプルな", "label": "連体形"}, {"form": "シンプルに", "label": "連用形"}], "register": "中立", "sense_fingerprint": "かんたんで難しくない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38100, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シンプルで", "is_correct": true, "explanation": "〈かんたん〉の意味。「作り方はシンプルで、三十分でできる」と続き自然。"}, {"text": "穏やかで", "is_correct": false, "explanation": "おだやかな様子を表す。作り方の説明には合わない。"}, {"text": "丈夫で", "is_correct": false, "explanation": "強く壊れにくい様子を表す。作り方の話には合わない。"}, {"text": "静かで", "is_correct": false, "explanation": "音が少ない様子を表す。作り方の話には合わない。"}], "explanations": {"シンプルで": "〈かんたん〉の意味。「作り方はシンプルで、三十分でできる」と続き自然。", "穏やかで": "おだやかな様子を表す。作り方の説明には合わない。", "丈夫で": "強く壊れにくい様子を表す。作り方の話には合わない。", "静かで": "音が少ない様子を表す。作り方の話には合わない。"}, "sentence_index": 0, "correct_answer": "シンプルで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はシンプルに大声で叫んだ。", "explanation": "ここは〈かんたん〉の意味。かんたんは声の大きさを表せず、「シンプルに叫ぶ」は成り立たない。"}, {"text": "このレシピはシンプルで、材料が十種類も必要だ。", "explanation": "ここは〈手間が少ない〉の意味で使っているが、材料が多いという文脈とは矛盾し、この語の使い方として合わない。"}, {"text": "彼はシンプルな性格で、いつも複雑な駆け引きをしている。", "explanation": "ここは〈単純〉の意味で、〈かんたん〉の義とは別。複雑な駆け引きとも矛盾し、この語の使い方として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38100, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シンプルで", "is_correct": true, "explanation": "〈かんたん〉の意味。「操作がシンプルで迷わない」と続き、使いやすさの説明に合う。"}, {"text": "頑丈で", "is_correct": false, "explanation": "丈夫で壊れにくい様子を表す。操作の説明には合わない。"}, {"text": "賑やかで", "is_correct": false, "explanation": "にぎやかな様子を表す。操作の話には合わない。"}, {"text": "元気で", "is_correct": false, "explanation": "健康な様子を表す。操作の説明には合わない。"}], "explanations": {"シンプルで": "〈かんたん〉の意味。「操作がシンプルで迷わない」と続き、使いやすさの説明に合う。", "頑丈で": "丈夫で壊れにくい様子を表す。操作の説明には合わない。", "賑やかで": "にぎやかな様子を表す。操作の話には合わない。", "元気で": "健康な様子を表す。操作の説明には合わない。"}, "sentence_index": 6, "correct_answer": "シンプルで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作文はシンプルに長すぎて、読み終わるのに一時間かかった。", "explanation": "〈かんたん〉の意味では長さを表せず、長い作文を「シンプル」と言うのは語の誤用になる。"}, {"text": "この作戦はシンプルに失敗した。", "explanation": "〈かんたん〉の意味では「シンプルに失敗する」とは続かず、この語の誤用になる。"}, {"text": "彼は話をシンプルに盛って、大げさに伝えた。", "explanation": "〈かんたん〉の意味では「話を盛る」と続かず、この語の誤用になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38100, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この料理の手順はシンプルが、初心者でもできます。", "corrected_sentence": "この料理の手順はシンプルで、初心者でもできます。", "error_description": "誤りは「シンプル」に続く形。正しくは中止形の「で」。「が」は逆接の助詞で、ここでは文が続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "シンプル", "is_correct": true, "explanation": "語幹の形。「シンプルな説明」の「な」が続く前の基になる形。"}, {"text": "シンプルだ", "is_correct": false, "explanation": "終止形。文を終える形で、名詞「説明」を修飾する形ではない。"}, {"text": "シンプルに", "is_correct": false, "explanation": "連用形。動詞を修飾する形で、名詞「説明」を修飾できない。"}, {"text": "シンプルで", "is_correct": false, "explanation": "中止形。「シンプルで、わかりやすい」と続く形で、ここでは名詞を修飾しない。"}], "correct_form": "シンプル", "base_form": "シンプルだ", "form_label": "語幹", "sentence_index": 1, "explanations": {"シンプル": "語幹の形。「シンプルな説明」の「な」が続く前の基になる形。", "シンプルだ": "終止形。文を終える形で、名詞「説明」を修飾する形ではない。", "シンプルに": "連用形。動詞を修飾する形で、名詞「説明」を修飾できない。", "シンプルで": "中止形。「シンプルで、わかりやすい」と続く形で、ここでは名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38100, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このアプリは操作がシンプルに、初心者でも迷いません。", "corrected_sentence": "このアプリは操作がシンプルで、初心者でも迷いません。", "error_description": "誤りは「シンプル」の連用形。正しくは中止形の「で」。「に」は副詞形で、名詞「操作」を修飾する形ではない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "シンプルに", "is_correct": true, "explanation": "連用形。「考えれば」を修飾する副詞の形で、ここに入る。"}, {"text": "シンプルだった", "is_correct": false, "explanation": "過去形。「考えれば」の前には来ない。"}, {"text": "シンプルな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、「考えれば」とは続かない。"}, {"text": "シンプルじゃない", "is_correct": false, "explanation": "否定形。「答えは一つだけ」と矛盾し、文の意味が逆になる。"}], "correct_form": "シンプルに", "base_form": "シンプルだ", "form_label": "連用形", "sentence_index": 7, "explanations": {"シンプルに": "連用形。「考えれば」を修飾する副詞の形で、ここに入る。", "シンプルだった": "過去形。「考えれば」の前には来ない。", "シンプルな": "連体形。名詞を修飾する形で、「考えれば」とは続かない。", "シンプルじゃない": "否定形。「答えは一つだけ」と矛盾し、文の意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
