INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38101, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "飾りや複雑さがなく、すっきりとした様子を表す形状詞。", "primary_collocate": null, "pronunciation": "しんぷる", "ipa": "ɕimpɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この部屋はシンプルな家具だけで、広く見えます。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "この部屋[へや]はシンプルな家具[かぐ]だけで、広[ひろ]く見[み]えます。", "sentence_source": "generated"}, {"text": "シンプルなデザインの時計は、どんな服にも合います。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "シンプルなデザインの時計[とけい]は、どんな服[ふく]にも合[あ]います。", "sentence_source": "generated"}, {"text": "彼の生活はシンプルで、物をほとんど持っていません。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "彼[かれ]の生活[せいかつ]はシンプルで、物[もの]をほとんど持[も]っていません。", "sentence_source": "generated"}, {"text": "仕組みがシンプルな機械は、壊れにくいです。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "仕組[しく]みがシンプルな機械[きかい]は、壊[こわ]れにくいです。", "sentence_source": "generated"}, {"text": "シンプルな味付けにして、魚の味を楽しんだ。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "シンプルな味付[あじつ]けにして、魚[さかな]の味[あじ]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "構造がシンプルなので、修理も短時間で終わった。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "構造[こうぞう]がシンプルなので、修理[しゅうり]も短時間[たんじかん]で終[お]わった。", "sentence_source": "generated"}, {"text": "彼女のシンプルな暮らしに憧れる人は多い。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のシンプルな暮[く]らしに憧[あこが]れる人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "余計な飾りをやめて、ポスターをシンプルにした。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "余計[よけい]な飾[かざ]りをやめて、ポスターをシンプルにした。", "sentence_source": "generated"}, {"text": "ロゴはシンプルなほど、人の記憶に残りやすい。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "ロゴはシンプルなほど、人[ひと]の記憶[きおく]に残[のこ]りやすい。", "sentence_source": "generated"}, {"text": "このカフェの内装はとてもシンプルです。", "target_word": "シンプル", "complexity_tier": "T3", "furigana": "このカフェの内装[ないそう]はとてもシンプルです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シンプルだ", "label": "終止形"}, {"form": "シンプルな", "label": "連体形"}, {"form": "シンプルに", "label": "連用形"}], "register": "中立", "sense_fingerprint": "飾りや複雑さがない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38101, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シンプルな", "is_correct": true, "explanation": "〈飾りがない〉の意味。家具の見た目を表し、「広く見える」と続く。"}, {"text": "穏やかな", "is_correct": false, "explanation": "おだやかな様子を表す。家具の見た目には合わない。"}, {"text": "丈夫な", "is_correct": false, "explanation": "強く壊れにくい様子を表す。見た目の説明には合わない。"}, {"text": "静かな", "is_correct": false, "explanation": "音が少ない様子を表す。家具の話には合わない。"}], "explanations": {"シンプルな": "〈飾りがない〉の意味。家具の見た目を表し、「広く見える」と続く。", "穏やかな": "おだやかな様子を表す。家具の見た目には合わない。", "丈夫な": "強く壊れにくい様子を表す。見た目の説明には合わない。", "静かな": "音が少ない様子を表す。家具の話には合わない。"}, "sentence_index": 0, "correct_answer": "シンプルな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋はシンプルで、壁一面に金の装飾が施されている。", "explanation": "〈飾りがない〉の意味だが、壁一面の装飾と矛盾し、この語の使い方として合わない。"}, {"text": "この味付けはシンプルに、十種類のスパイスを使う。", "explanation": "〈飾りがない〉の意味だが、十種類のスパイスを使う文脈と矛盾し、この語の使い方として合わない。"}, {"text": "彼は大量の服をシンプルに並べて、持ち物を増やした。", "explanation": "〈飾りがない〉の意味では持ち物を増やすことは表せず、「シンプルに並べて増やす」は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38101, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シンプルな", "is_correct": true, "explanation": "〈飾りがない〉の意味。暮らしの様子を表し、「憧れる人は多い」と続く。"}, {"text": "頑丈な", "is_correct": false, "explanation": "丈夫で壊れにくい様子を表す。暮らしの説明には合わない。"}, {"text": "無愛想な", "is_correct": false, "explanation": "愛想がない様子を表す。暮らしに憧れる文には合わない。"}, {"text": "高速な", "is_correct": false, "explanation": "速い様子を表す。暮らしの様子を表す文には合わない。"}], "explanations": {"シンプルな": "〈飾りがない〉の意味。暮らしの様子を表し、「憧れる人は多い」と続く。", "頑丈な": "丈夫で壊れにくい様子を表す。暮らしの説明には合わない。", "無愛想な": "愛想がない様子を表す。暮らしに憧れる文には合わない。", "高速な": "速い様子を表す。暮らしの様子を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "シンプルな"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自然にシンプルに笑った。", "explanation": "ここは〈飾りがない〉の意味だが、笑う動作を修飾する副詞的な使い方は不自然。〈地味な〉の意味で使うなら「地味に笑う」になる。"}, {"text": "彼女はシンプルな人で、人の気持ちを深く読み取れる。", "explanation": "〈単純〉の意味で、深く読み取る能力と矛盾する。この語の使い方として合わない。"}, {"text": "山道をシンプルに歩いたら、迷わず帰れた。", "explanation": "〈飾りがない〉の意味では「シンプルに歩く」は成り立たず、語の誤用になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38101, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の内装はシンプルが、落ち着いた雰囲気です。", "corrected_sentence": "この店の内装はシンプルで、落ち着いた雰囲気です。", "error_description": "誤りは「シンプル」に続く形。正しくは中止形の「で」。「が」は主語を示すため、ここでは文が続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "シンプル", "is_correct": true, "explanation": "語幹の形。「シンプルなデザイン」の「な」が続く前の基になる形。"}, {"text": "シンプルだ", "is_correct": false, "explanation": "終止形。文を終える形で、名詞「デザイン」を修飾できない。"}, {"text": "シンプルに", "is_correct": false, "explanation": "連用形。動詞を修飾する形で、名詞「デザイン」を修飾できない。"}, {"text": "シンプルで", "is_correct": false, "explanation": "中止形。「シンプルで、どんな服にも合う」と続く形で、名詞を修飾しない。"}], "correct_form": "シンプル", "base_form": "シンプルだ", "form_label": "語幹", "sentence_index": 1, "explanations": {"シンプル": "語幹の形。「シンプルなデザイン」の「な」が続く前の基になる形。", "シンプルだ": "終止形。文を終える形で、名詞「デザイン」を修飾できない。", "シンプルに": "連用形。動詞を修飾する形で、名詞「デザイン」を修飾できない。", "シンプルで": "中止形。「シンプルで、どんな服にも合う」と続く形で、名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38101, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このカフェの内装はシンプルに、落ち着けます。", "corrected_sentence": "このカフェの内装はシンプルで、落ち着けます。", "error_description": "誤りは「シンプル」の連用形。正しくは中止形の「で」。「に」は副詞形で、「内装」の説明としては続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "シンプルに", "is_correct": true, "explanation": "連用形。「にした」で変化の結果を表し、ここに入る形。"}, {"text": "シンプルだった", "is_correct": false, "explanation": "過去形。「ポスターを」の後の形として合わない。"}, {"text": "シンプルな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、「にした」とは続かない。"}, {"text": "シンプルじゃない", "is_correct": false, "explanation": "否定形。「シンプルにした」の意味と逆になる。"}], "correct_form": "シンプルに", "base_form": "シンプルだ", "form_label": "連用形", "sentence_index": 7, "explanations": {"シンプルに": "連用形。「にした」で変化の結果を表し、ここに入る形。", "シンプルだった": "過去形。「ポスターを」の後の形として合わない。", "シンプルな": "連体形。名詞を修飾する形で、「にした」とは続かない。", "シンプルじゃない": "否定形。「シンプルにした」の意味と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自動車の形の変遷を知る」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「変遷に知る」は不自然で、「知る」は対象に「を」を取る。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すため、「変遷で知る」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「変遷へ知る」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「自動車の形の変遷を知る」の目的語を示す。", "に": "「変遷に知る」は不自然で、「知る」は対象に「を」を取る。", "で": "手段を表すため、「変遷で知る」は成り立たない。", "へ": "方向を表し、「変遷へ知る」は不自然。"}, "error_tags": {"に": "方向・相手", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "変わっていくこと。時間がたつにつれて、形やようすがかわること。", "primary_collocate": null, "pronunciation": "へんせん", "ipa": "heɴseɴ", "syllable_count": 4, "sentences": [{"text": "この町の人口の変遷をグラフで見ると、戦後に大きく増えたことがわかる。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "この町[まち]の人口[じんこう]の変遷[へんせん]をグラフで見[み]ると、戦後[せんご]に大[おお]きく増[ふ]えたことがわかる。", "sentence_source": "generated"}, {"text": "日本の食生活の変遷について、先生が授業で詳しく説明した。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "日本[にほん]の食生活[しょくせいかつ]の変遷[へんせん]について、先生[せんせい]が授業[じゅぎょう]で詳[くわ]しく説明[せつめい]した。", "sentence_source": "generated"}, {"text": "言葉の意味の変遷を調べるのは、とても面白い。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "言葉[ことば]の意味[いみ]の変遷[へんせん]を調[しら]べるのは、とても面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "駅の周りの景色の変遷を、古い写真で確認した。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "駅[えき]の周[まわ]りの景色[けしき]の変遷[へんせん]を、古[ふる]い写真[しゃしん]で確認[かくにん]した。", "sentence_source": "generated"}, {"text": "音楽の流行の変遷は、それぞれの時代の空気をよく映している。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "音楽[おんがく]の流行[りゅうこう]の変遷[へんせん]は、それぞれの時代[じだい]の空気[くうき]をよく映[うつ]している。", "sentence_source": "generated"}, {"text": "本の表紙のデザインの変遷を、展示会で比べて見た。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "本[ほん]の表紙[ひょうし]のデザインの変遷[へんせん]を、展示会[てんじかい]で比[くら]べて見[み]た。", "sentence_source": "generated"}, {"text": "町の祭りの形の変遷を、お年寄りに聞いて回った。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "町[まち]の祭[まつ]りの形[かたち]の変遷[へんせん]を、お年寄[としよ]りに聞[き]いて回[まわ]った。", "sentence_source": "generated"}, {"text": "自動車の形の変遷を知ると、技術の進歩がよくわかる。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "自動車[じどうしゃ]の形[かたち]の変遷[へんせん]を知[し]ると、技術[ぎじゅつ]の進歩[しんぽ]がよくわかる。", "sentence_source": "generated"}, {"text": "家族の暮らしの変遷を、アルバムを見ながら振り返った。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "家族[かぞく]の暮[く]らしの変遷[へんせん]を、アルバムを見[み]ながら振[ふ]り返[かえ]った。", "sentence_source": "generated"}, {"text": "この川の流れの変遷は、古い地図を並べるとはっきりわかる。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "この川[かわ]の流[なが]れの変遷[へんせん]は、古[ふる]い地図[ちず]を並[なら]べるとはっきりわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変遷", "label": "基本形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "時間がたつにつれて形やようすが変わっていくことを表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変遷", "is_correct": true, "explanation": "時間とともに形やようすが変わってきた過程を表し、人口の推移を見る文に合う。"}, {"text": "寿命", "is_correct": false, "explanation": "生き物や物の存続期間を表し、人口の変わり方を表せない。"}, {"text": "臭気", "is_correct": false, "explanation": "においを表す語で、人口の推移とは結びつかない。"}, {"text": "解体", "is_correct": false, "explanation": "物を分解する行為で、人口の変化を表せない。"}], "explanations": {"変遷": "時間とともに形やようすが変わってきた過程を表し、人口の推移を見る文に合う。", "寿命": "生き物や物の存続期間を表し、人口の変わり方を表せない。", "臭気": "においを表す語で、人口の推移とは結びつかない。", "解体": "物を分解する行為で、人口の変化を表せない。"}, "sentence_index": 0, "correct_answer": "変遷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "株価が一日で大きく変遷した。", "explanation": "ここは〈変動〉の意味。変遷は長い時間をかけた形の移り変わりを指し、一日の急な上下には使わない。"}, {"text": "春から、息子は別の学校へ変遷することになった。", "explanation": "ここは〈転校〉の意味。変遷は物事の姿や状態の移り変わりを指し、人の移動には使わない。"}, {"text": "病気が急に変遷して、入院が必要になった。", "explanation": "ここは〈進行〉の意味。変遷はゆっくりと姿が移り変わる過程を指すので、急な悪化には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変遷", "is_correct": true, "explanation": "祭りの形が時間とともに移り変わってきた過程を表し、文の対象に合う。"}, {"text": "聴力", "is_correct": false, "explanation": "耳の働きを表す語で、祭りの形の移り変わりには使えない。"}, {"text": "看板", "is_correct": false, "explanation": "店などの表示物を指し、祭りの形を表す語として合わない。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物による変化を表し、祭りの形の推移には当てはまらない。"}], "explanations": {"変遷": "祭りの形が時間とともに移り変わってきた過程を表し、文の対象に合う。", "聴力": "耳の働きを表す語で、祭りの形の移り変わりには使えない。", "看板": "店などの表示物を指し、祭りの形を表す語として合わない。", "発酵": "微生物による変化を表し、祭りの形の推移には当てはまらない。"}, "sentence_index": 6, "correct_answer": "変遷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川の水位が一晩で変遷した。", "explanation": "ここは〈上昇〉の意味。変遷は長い時間をかけた移り変わりを指すので、一晩での急な水位の変化には使わない。"}, {"text": "一家で地方へ変遷することになった。", "explanation": "ここは〈移住〉の意味。変遷は物事の状態の移り変わりを指し、人が住む場所を移す場合には使わない。"}, {"text": "ボタンを押すと、アプリの画面が別の画面へ変遷した。", "explanation": "ここは〈遷移〉の意味。ボタンで画面が切り替わることは遷移と言い、変遷は時間をかけた移り変わりを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域の気温の変遷が、昨年の記録で比べた。", "corrected_sentence": "この地域の気温の変遷を、昨年の記録で比べた。", "error_description": "「比べる」の対象は「を」で示す。「変遷が」は主語の助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38102, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は、昔の農具の変遷を、博物館の資料で作った。", "corrected_sentence": "祖父は、昔の農具の変遷を、博物館の資料で学んだ。", "error_description": "「変遷」と結びつくのは「学ぶ」などの動詞。「作った」は「変遷」と合わず、正しくは「学んだ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「変遷を見比べる」の目的語。写真で移り変わりを比べるため「を」が必要。"}, {"text": "に", "is_correct": false, "explanation": "「変遷に見比べてみた」は成り立たない。「見比べる」は対象に「を」を取る。"}, {"text": "で", "is_correct": false, "explanation": "「写真で」が既にあり、「変遷で」を置くと手段が重なって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「変遷へ見比べる」は方向を表す語として不自然。"}], "correct_answer": "を", "explanations": {"を": "「変遷を見比べる」の目的語。写真で移り変わりを比べるため「を」が必要。", "に": "「変遷に見比べてみた」は成り立たない。「見比べる」は対象に「を」を取る。", "で": "「写真で」が既にあり、「変遷で」を置くと手段が重なって不自然。", "へ": "「変遷へ見比べる」は方向を表す語として不自然。"}, "error_tags": {"に": "方向・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「税制の変遷がひと目でわかる」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「変遷とひと目でわかる」は並列にもならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表すため、「ひと目でわかる」の主語にはできない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すため、「変遷よりひと目でわかる」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「税制の変遷がひと目でわかる」の主語を示す。", "と": "「変遷とひと目でわかる」は並列にもならず、文が成り立たない。", "の": "連体修飾を表すため、「ひと目でわかる」の主語にはできない。", "より": "比較を表すため、「変遷よりひと目でわかる」は不自然。"}, "error_tags": {"と": "並列・共同", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が時間の経過とともに、別の状態や形に移り変わっていくこと。変化の過程。", "primary_collocate": null, "pronunciation": "へんせん", "ipa": "heɴseɴ", "syllable_count": 4, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "オートクチュールの歴史[れきし]は、単[たん]なる服飾[ふくしょく]の変遷[へんせん]を超[こ]え、人類[じんるい]の美的[びてき]探究[たんきゅう]と技術[ぎじゅつ]革新[かくしん]の軌跡[きせき]そのものである。", "sentence_source": "mined"}, {"text": "江戸時代から現代までの町並みの変遷を、写真で見比べてみた。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]から現代[げんだい]までの町並[まちな]みの変遷[へんせん]を、写真[しゃしん]で見比[みくら]べてみた。", "sentence_source": "generated"}, {"text": "この資料館では、日本語の表記の変遷が分かりやすく展示されている。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "この資料館[しりょうかん]では、日本語[にほんご]の表記[ひょうき]の変遷[へんせん]が分[わ]かりやすく展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "学校制服のデザインの変遷を調べて、レポートにまとめた。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "学校[がっこう]制服[せいふく]のデザインの変遷[へんせん]を調[しら]べて、レポートにまとめた。", "sentence_source": "generated"}, {"text": "時代とともに政党の主張が変わり、その変遷を追うのは簡単ではない。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "時代[じだい]とともに政党[せいとう]の主張[しゅちょう]が変[か]わり、その変遷[へんせん]を追[お]うのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "祖父は、駅前の商店街の変遷を長年見守ってきた。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "祖父[そふ]は、駅前[えきまえ]の商店街[しょうてんがい]の変遷[へんせん]を長年[ながねん]見守[みまも]ってきた。", "sentence_source": "generated"}, {"text": "彼女は、茶道の作法の変遷について論文を書いている。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、茶道[さどう]の作法[さほう]の変遷[へんせん]について論文[ろんぶん]を書[か]いている。", "sentence_source": "generated"}, {"text": "年表を見ると、この国の税制の変遷がひと目でわかる。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "年表[ねんぴょう]を見[み]ると、この国[くに]の税制[ぜいせい]の変遷[へんせん]がひと目[め]でわかる。", "sentence_source": "generated"}, {"text": "教科書の内容の変遷から、社会の価値観の変化が読み取れる。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "教科書[きょうかしょ]の内容[ないよう]の変遷[へんせん]から、社会[しゃかい]の価値観[かちかん]の変化[へんか]が読[よ]み取[と]れる。", "sentence_source": "generated"}, {"text": "携帯電話の機能の変遷をたどると、生活の変化も見えてくる。", "target_word": "変遷", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]の機能[きのう]の変遷[へんせん]をたどると、生活[せいかつ]の変化[へんか]も見[み]えてくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変遷", "label": "基本形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "時代の流れの中で物事が少しずつ姿を変えていく過程を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53e2584e-b6b1-41a3-9c04-5d3b7dab63bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変遷", "is_correct": true, "explanation": "時間をかけて移り変わってきた過程を表し、服飾の歴史の流れに合う。"}, {"text": "誠実", "is_correct": false, "explanation": "人の性質を表す語で、服飾の移り変わりを指せない。"}, {"text": "採点", "is_correct": false, "explanation": "評価する行為を表し、服飾の歴史とつながらない。"}, {"text": "体積", "is_correct": false, "explanation": "物の大きさを表す語で、歴史の推移には使えない。"}], "explanations": {"変遷": "時間をかけて移り変わってきた過程を表し、服飾の歴史の流れに合う。", "誠実": "人の性質を表す語で、服飾の移り変わりを指せない。", "採点": "評価する行為を表し、服飾の歴史とつながらない。", "体積": "物の大きさを表す語で、歴史の推移には使えない。"}, "sentence_index": 0, "correct_answer": "変遷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "信号が赤から青へ一瞬で変遷した。", "explanation": "ここは〈変化〉の意味。変遷は長い時間をかけた移り変わりの過程を指すので、一瞬の切り替えには合わない。"}, {"text": "来月から、彼は本社へ変遷することになった。", "explanation": "ここは〈異動〉の意味。変遷は物事の姿の移り変わりを指し、人の転勤には使わない。"}, {"text": "鉄が空気に触れて、表面が赤く変遷した。", "explanation": "ここは〈変色〉の意味。変色は色が変わることを指し、変遷は時間をかけた様子の移り変わりを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変遷", "is_correct": true, "explanation": "作法が時代とともに移り変わってきた過程を表し、論文の対象に合う。"}, {"text": "交渉", "is_correct": false, "explanation": "話し合いを表す語で、作法の移り変わりには使えない。"}, {"text": "運搬", "is_correct": false, "explanation": "物を運ぶ行為で、作法の推移を指せない。"}, {"text": "融資", "is_correct": false, "explanation": "資金を貸すことで、作法の歴史とは結びつかない。"}], "explanations": {"変遷": "作法が時代とともに移り変わってきた過程を表し、論文の対象に合う。", "交渉": "話し合いを表す語で、作法の移り変わりには使えない。", "運搬": "物を運ぶ行為で、作法の推移を指せない。", "融資": "資金を貸すことで、作法の歴史とは結びつかない。"}, "sentence_index": 6, "correct_answer": "変遷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その村は、わずか一晩で完全に変遷した。", "explanation": "ここは〈変貌〉の意味。変遷は長い時間をかけた移り変わりを指すので、一晩の急激な変化には合わない。"}, {"text": "雨音の調子が、急に変遷した。", "explanation": "ここは〈変調〉の意味。変遷は徐々に移り変わる過程を指すので、急な音の調子の変化には使わない。"}, {"text": "彼は、コンビニの仕事を辞めて、通信会社へ変遷した。", "explanation": "ここは〈転職〉の意味。変遷は物事の状態の移り変わりを指し、人が職を変える場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その地域の気候の変遷に、古い記録から調べた。", "corrected_sentence": "その地域の気候の変遷を、古い記録から調べた。", "error_description": "「調べる」の対象は「を」で示す。「変遷に」は助詞の誤りで、正しくは「変遷を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38103, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の服装の変遷を、本で作った。", "corrected_sentence": "昔の服装の変遷を、本で調べた。", "error_description": "「変遷」と結びつくのは「調べる」などの動詞。「作った」は「変遷」の動作として不自然で、正しくは「調べた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba438f15-5656-4075-b96c-5357eca0ea28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「出席する」は「〜に」で場や会合を示すので、「サミットに」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「出席」は「〜に出席する」と使うので、「サミットを出席する」は誤り。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「サミットから出席する」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は出席の場を示せず、「サミットより出席する」は続かない。"}], "correct_answer": "に", "explanations": {"に": "「出席する」は「〜に」で場や会合を示すので、「サミットに」が正しい。", "を": "「出席」は「〜に出席する」と使うので、「サミットを出席する」は誤り。", "から": "「から」は起点を示し、「サミットから出席する」は意味が通らない。", "より": "比較の「より」は出席の場を示せず、「サミットより出席する」は続かない。"}, "error_tags": {"を": "目的語の誤り", "から": "起点の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「去年のサミット」の「の」は、時期と会議を結ぶ。"}, {"text": "が", "is_correct": false, "explanation": "「去年が、サミットでは」は文の成分が続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「去年へサミット」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「去年でサミット」は時期を表せない。"}], "correct_answer": "の", "explanations": {"の": "「去年のサミット」の「の」は、時期と会議を結ぶ。", "が": "「去年が、サミットでは」は文の成分が続かず不自然。", "へ": "「へ」は方向を示し、「去年へサミット」は意味が通らない。", "で": "「で」は場所や手段を示すが、「去年でサミット」は時期を表せない。"}, "error_tags": {"が": "主語の誤り", "へ": "方向の誤り", "で": "場所・手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界の国々のリーダーが集まって話し合う大きな会議。", "primary_collocate": null, "pronunciation": "さみっと", "ipa": "samitto", "syllable_count": 4, "sentences": [{"text": "来月、日本で主要国のサミットが開かれる。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "来月[らいげつ]、日本[にほん]で主要国[しゅようこく]のサミットが開[ひら]かれる。", "sentence_source": "generated"}, {"text": "サミットには、各国の首相や大統領が出席する。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "サミットには、各国[かっこく]の首相[しゅしょう]や大統領[だいとうりょう]が出席[しゅっせき]する。", "sentence_source": "generated"}, {"text": "サミットの会場の周りは、警察官が多くて歩きにくい。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "サミットの会場[かいじょう]の周[まわ]りは、警察官[けいさつかん]が多[おお]くて歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "首脳たちはサミットで、気候変動について話し合った。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "首脳[しゅのう]たちはサミットで、気候[きこう]変動[へんどう]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "今年のサミットは、海の見えるホテルで行われた。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "今年[ことし]のサミットは、海[うみ]の見[み]えるホテルで行[おこな]われた。", "sentence_source": "generated"}, {"text": "サミットが開かれるので、駅の近くの道が通れなくなる。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "サミットが開[ひら]かれるので、駅[えき]の近[ちか]くの道[みち]が通[とお]れなくなる。", "sentence_source": "generated"}, {"text": "ニュースでは、サミットに集まった世界のリーダーが映っていた。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "ニュースでは、サミットに集[あつ]まった世界[せかい]のリーダーが映[うつ]っていた。", "sentence_source": "generated"}, {"text": "去年のサミットでは、食料不足が大きな話題になった。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "去年[きょねん]のサミットでは、食料[しょくりょう]不足[ぶそく]が大[おお]きな話題[わだい]になった。", "sentence_source": "generated"}, {"text": "サミットの前に、二つの国の大臣が先に会った。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "サミットの前[まえ]に、二[ふた]つの国[くに]の大臣[だいじん]が先[さき]に会[あ]った。", "sentence_source": "generated"}, {"text": "父はサミットのニュースを見て、世界の問題を考えた。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "父[ちち]はサミットのニュースを見[み]て、世界[せかい]の問題[もんだい]を考[かんが]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サミット", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "世界の国々のリーダーが集まって話し合う大きな会議", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サミット", "is_correct": true, "explanation": "「主要国のサミットが開かれる」は、各国の首脳が集まる会議という意味に合う。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、「主要国の地震が開かれる」は意味をなさない。"}, {"text": "台風", "is_correct": false, "explanation": "台風は自然現象で、「主要国の台風が開かれる」は文として通じない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は物の名前で、「主要国の花瓶が開かれる」は意味をなさない。"}], "explanations": {"サミット": "「主要国のサミットが開かれる」は、各国の首脳が集まる会議という意味に合う。", "地震": "地震は自然現象で、「主要国の地震が開かれる」は意味をなさない。", "台風": "台風は自然現象で、「主要国の台風が開かれる」は文として通じない。", "花瓶": "花瓶は物の名前で、「主要国の花瓶が開かれる」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "サミット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日のサミットで、両チームは一点も取れなかった。", "explanation": "ここは〈試合〉の意味。競技の対戦を指すので、各国の首脳が集まる会議には使わない。"}, {"text": "先生がサミットで新しい単元を説明した。", "explanation": "ここは〈授業〉の意味。教える場を指すので、国際会議のサミットとは違う。"}, {"text": "サミットで、友人がスピーチをした。", "explanation": "ここは〈結婚式〉の意味。祝いの席でのスピーチを指すので、国の首脳が集まる会議とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サミット", "is_correct": true, "explanation": "「ニュースでは、サミットに集まった世界のリーダーが映っていた」は、各国のリーダーが集まる会議の文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は人が集まる場所にならず、「雨に集まった世界のリーダー」は意味をなさない。"}, {"text": "机", "is_correct": false, "explanation": "机は集まる場所にならず、「机に集まった世界のリーダー」は文脈に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は集まる場所にならず、「椅子に集まった世界のリーダー」は意味をなさない。"}], "explanations": {"サミット": "「ニュースでは、サミットに集まった世界のリーダーが映っていた」は、各国のリーダーが集まる会議の文脈に合う。", "雨": "雨は人が集まる場所にならず、「雨に集まった世界のリーダー」は意味をなさない。", "机": "机は集まる場所にならず、「机に集まった世界のリーダー」は文脈に合わない。", "椅子": "椅子は集まる場所にならず、「椅子に集まった世界のリーダー」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "サミット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その画家の作品は、美術館のサミットで多くの人に展示された。", "explanation": "ここは〈展覧会〉の意味。作品を並べて見せる催しを指すので、国の首脳が集まる会議とは違う。"}, {"text": "バンドはサミットで、新しい曲を演奏した。", "explanation": "ここは〈演奏会〉の意味。音楽を披露する催しを指すので、首脳が集まる会議とは違う。"}, {"text": "投票日に、人々はサミットの投票所に並んだ。", "explanation": "ここは〈選挙〉の意味。有権者が投票する行為で、首脳が集まる会議とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年、ソウルで主要国のサミットを開かれる。", "corrected_sentence": "来年、ソウルで主要国のサミットが開かれる。", "error_description": "「開かれる」の主語は「サミット」なので「が」を使う。「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38104, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年のサミットは、古い城で開けられた。", "corrected_sentence": "今年のサミットは、古い城で開かれた。", "error_description": "「サミット」には「開かれる」を使う。「開けられた」は戸や箱を開ける動詞で、会議には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「サミットと呼ばれる」の「と」は、名前や呼称を示す。"}, {"text": "を", "is_correct": false, "explanation": "「サミットを呼ばれる」は、受け身の文で「を」を使えず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「サミットへ呼ばれる」は呼称を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所を示し、「サミットで呼ばれる」は呼称の意味にならない。"}], "correct_answer": "と", "explanations": {"と": "「サミットと呼ばれる」の「と」は、名前や呼称を示す。", "を": "「サミットを呼ばれる」は、受け身の文で「を」を使えず不自然。", "へ": "「へ」は方向を示し、「サミットへ呼ばれる」は呼称を表せない。", "で": "「で」は場所を示し、「サミットで呼ばれる」は呼称の意味にならない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "で": "場所の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「サミットが開かれ」の「が」は、開かれる主語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐだけで、「サミットの開かれ」では受け身の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、「サミットから開かれ」と主語を表せず意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、「サミットより開かれ」と主語を示せず文が続かない。"}], "correct_answer": "が", "explanations": {"が": "「サミットが開かれ」の「が」は、開かれる主語を示す。", "の": "「の」は名詞をつなぐだけで、「サミットの開かれ」では受け身の主語にならない。", "から": "起点を示す「から」は、「サミットから開かれ」と主語を表せず意味が通らない。", "より": "比較の「より」は、「サミットより開かれ」と主語を示せず文が続かない。"}, "error_tags": {"の": "連体修飾の誤り", "から": "起点の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "各国の首脳など重要な人物が集まって開く会議。", "primary_collocate": null, "pronunciation": "さみっと", "ipa": "samitto", "syllable_count": 4, "sentences": [{"text": "経済問題を話し合うサミットが、来週から始まる。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "経済[けいざい]問題[もんだい]を話[はな]し合[あ]うサミットが、来週[らいしゅう]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "主要国首脳会議は、一般にサミットと呼ばれる。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "主要国[しゅようこく]首脳[しゅのう]会議[かいぎ]は、一般[いっぱん]にサミットと呼[よ]ばれる。", "sentence_source": "generated"}, {"text": "サミットで合意された内容は、すぐに世界中に伝えられた。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "サミットで合意[ごうい]された内容[ないよう]は、すぐに世界中[せかいじゅう]に伝[つた]えられた。", "sentence_source": "generated"}, {"text": "大統領は、日程が合わず、サミットを欠席した。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "大統領[だいとうりょう]は、日程[にってい]が合[あ]わず、サミットを欠席[けっせき]した。", "sentence_source": "generated"}, {"text": "開催国は、サミットのために多くの警備員を用意した。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "開催国[かいさいこく]は、サミットのために多[おお]くの警備員[けいびいん]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "参加国の代表が集まるサミットは、三日間の予定だ。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "参加国[さんかこく]の代表[だいひょう]が集[あつ]まるサミットは、三日間[みっかかん]の予定[よてい]だ。", "sentence_source": "generated"}, {"text": "今回のサミットで、貧しい国を助ける計画が決まった。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "今回[こんかい]のサミットで、貧[まず]しい国[くに]を助[たす]ける計画[けいかく]が決[き]まった。", "sentence_source": "generated"}, {"text": "経済界のサミットが開かれ、企業の社長たちが意見を交わした。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "経済界[けいざいかい]のサミットが開[ひら]かれ、企業[きぎょう]の社長[しゃちょう]たちが意見[いけん]を交[か]わした。", "sentence_source": "generated"}, {"text": "小さな国の首相も、サミットでは大国と同じ席につく。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "小[ちい]さな国[くに]の首相[しゅしょう]も、サミットでは大国[たいこく]と同[おな]じ席[せき]につく。", "sentence_source": "generated"}, {"text": "サミットの結果を、記者が夜遅くまで報道した。", "target_word": "サミット", "complexity_tier": "T3", "furigana": "サミットの結果[けっか]を、記者[きしゃ]が夜遅[よるおそ]くまで報道[ほうどう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サミット", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "各国の首脳など重要な人物が集まって開く会議（首脳会議）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サミット", "is_correct": true, "explanation": "「経済問題を話し合うサミットが、来週から始まる」は、首脳たちの会議という文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は話し合う主体にならず、「経済問題を話し合う雨」は意味をなさない。"}, {"text": "机", "is_correct": false, "explanation": "机は話し合う主体にならず、「経済問題を話し合う机」は文脈に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は話し合う主体にならず、「経済問題を話し合う椅子」は意味をなさない。"}], "explanations": {"サミット": "「経済問題を話し合うサミットが、来週から始まる」は、首脳たちの会議という文脈に合う。", "雨": "雨は話し合う主体にならず、「経済問題を話し合う雨」は意味をなさない。", "机": "机は話し合う主体にならず、「経済問題を話し合う机」は文脈に合わない。", "椅子": "椅子は話し合う主体にならず、「経済問題を話し合う椅子」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "サミット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "そのサミットで、ボーカルが新曲を歌った。", "explanation": "ここは〈演奏会〉の意味。ステージで歌う催しを指すので、首脳が集まる会議とは違う。"}, {"text": "サミットの投票日に、人々は投票所に並んだ。", "explanation": "ここは〈選挙〉の意味。有権者が投票する行為で、首脳会議とは違う。"}, {"text": "そのサミットには、大勢のランナーが集まった。", "explanation": "ここは〈大会〉の意味。競技者が参加する催しで、各国の首脳が集まる会議ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サミット", "is_correct": true, "explanation": "「今回のサミットで、貧しい国を助ける計画が決まった」は、首脳会議の結果という文脈に合う。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは物の名前で、「今回の消しゴムで計画が決まった」は文脈に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は物の名前で、「今回の椅子で計画が決まった」は文脈に合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は物の名前で、「今回の花瓶で計画が決まった」は意味をなさない。"}], "explanations": {"サミット": "「今回のサミットで、貧しい国を助ける計画が決まった」は、首脳会議の結果という文脈に合う。", "消しゴム": "消しゴムは物の名前で、「今回の消しゴムで計画が決まった」は文脈に合わない。", "椅子": "椅子は物の名前で、「今回の椅子で計画が決まった」は文脈に合わない。", "花瓶": "花瓶は物の名前で、「今回の花瓶で計画が決まった」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "サミット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日のサミットで、両チームは一点も取れなかった。", "explanation": "ここは〈試合〉の意味。競技の対戦を指すので、首脳が集まる会議には使わない。"}, {"text": "先生がサミットで新しい単元を説明した。", "explanation": "ここは〈授業〉の意味。教える行為を指すので、国際会議のサミットとは違う。"}, {"text": "サミットで、友人がスピーチをした。", "explanation": "ここは〈結婚式〉の意味。祝いの席でのスピーチを指すので、国の首脳が集まる会議とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、東京で各国のサミットが開かれた。", "corrected_sentence": "来週、東京で各国のサミットが開かれる。", "error_description": "「来週」は未来の時期なので、動詞は「開かれる」にする。「開かれた」は過去の形で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38105, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今回のサミットを決まった内容を、記者が夜遅くまで報道した。", "corrected_sentence": "今回のサミットで決まった内容を、記者が夜遅くまで報道した。", "error_description": "「決まる」の場所を示すには「で」を使う。「サミットを決まった」の「を」が誤りで、正しくは「サミットで決まった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38106, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "を", "is_correct": false, "explanation": "「を」にすると「三つある」の主語にならず、文の骨組みが合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐだけで、「三つある」の述語を支えられない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「議題が三つある」の主題にはならない。"}, {"text": "は", "is_correct": true, "explanation": "「今日のアジェンダは」と主題を示し、その内容が三つあると続く正しい助詞。"}], "correct_answer": "は", "explanations": {"を": "「を」にすると「三つある」の主語にならず、文の骨組みが合わない。", "の": "「の」は名詞どうしをつなぐだけで、「三つある」の述語を支えられない。", "で": "「で」は手段や場所を示すので、「議題が三つある」の主題にはならない。", "は": "「今日のアジェンダは」と主題を示し、その内容が三つあると続く正しい助詞。"}, "error_tags": {"を": "目的語", "の": "所属・修飾", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38106, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、確認の対象を示す「を」の代わりにはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、確認の対象を表す文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「話し合う」の目的語を表せない。"}, {"text": "を", "is_correct": true, "explanation": "「アジェンダを生徒と話し合う」の目的語を示す正しい助詞。"}], "correct_answer": "を", "explanations": {"に": "「に」は方向や相手を示すので、確認の対象を示す「を」の代わりにはならない。", "へ": "「へ」は方向を示すので、確認の対象を表す文には合わない。", "の": "「の」は所属や修飾を示すので、「話し合う」の目的語を表せない。", "を": "「アジェンダを生徒と話し合う」の目的語を示す正しい助詞。"}, "error_tags": {"に": "方向・相手", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38106, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなでやることのリスト。", "primary_collocate": null, "pronunciation": "あじぇんだ", "ipa": "adʑeɴda", "syllable_count": 4, "sentences": [{"text": "会議の前に、アジェンダをみんなに送りました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "会議[かいぎ]の前[まえ]に、アジェンダをみんなに送[おく]りました。", "sentence_source": "generated"}, {"text": "今日のアジェンダは三つあります。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "今日[きょう]のアジェンダは三[みっ]つあります。", "sentence_source": "generated"}, {"text": "アジェンダを見て、話すことを確認しました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダを見[み]て、話[はな]すことを確認[かくにん]しました。", "sentence_source": "generated"}, {"text": "アジェンダに「旅行の計画」と書いておきます。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダに「旅行[りょこう]の計画[けいかく]」と書[か]いておきます。", "sentence_source": "generated"}, {"text": "クラブの集まりで、アジェンダを黒板に書きました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "クラブの集[あつ]まりで、アジェンダを黒板[こくばん]に書[か]きました。", "sentence_source": "generated"}, {"text": "時間がなくて、アジェンダの最後まで進みませんでした。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "時間[じかん]がなくて、アジェンダの最後[さいご]まで進[すす]みませんでした。", "sentence_source": "generated"}, {"text": "アジェンダがあるので、話があちこちに行きません。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダがあるので、話[はなし]があちこちに行[い]きません。", "sentence_source": "generated"}, {"text": "先生は、学級会のアジェンダを生徒と話し合って決めました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、学級会[がっきゅうかい]のアジェンダ[あじぇんだ]を生徒[せいと]と話し合[はなしあ]って決[き]めました。", "sentence_source": "generated"}, {"text": "みんなの意見を集めて、一つのアジェンダにまとめました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "みんなの意見[いけん]を集[あつ]めて、一[ひと]つのアジェンダにまとめました。", "sentence_source": "generated"}, {"text": "アジェンダの順番を変えて、大切な話を先にしました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダの順番[じゅんばん]を変[か]えて、大切[たいせつ]な話[はなし]を先[さき]にしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アジェンダ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "みんなで話したりやったりすることの一覧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38106, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湯気", "is_correct": false, "explanation": "湯気は立ちのぼる現象で、送るものではないので文が成り立たない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は自然現象で、みんなに送ることはできない。"}, {"text": "アジェンダ", "is_correct": true, "explanation": "会議の前に皆に送る、やることの一覧としての語。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日は空の光景で、会議の前に送るものではない。"}], "explanations": {"湯気": "湯気は立ちのぼる現象で、送るものではないので文が成り立たない。", "霧": "霧は自然現象で、みんなに送ることはできない。", "アジェンダ": "会議の前に皆に送る、やることの一覧としての語。", "夕日": "夕日は空の光景で、会議の前に送るものではない。"}, "sentence_index": 0, "correct_answer": "アジェンダ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アジェンダに砂糖を入れて、甘くしました。", "explanation": "ここは〈料理〉の意味。アジェンダは会議で話す予定の一覧で、砂糖を入れて味を変えるものではないので合わない。"}, {"text": "アジェンダに水をやって、大きく育てました。", "explanation": "ここは〈植物〉の意味。アジェンダは育てて水をやるものではないので、大きく育てる話とは合わない。"}, {"text": "アジェンダでドアを開けて、部屋に入りました。", "explanation": "ここは〈鍵〉の意味。アジェンダは鍵ではないので、ドアを開けるという話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38106, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夕立", "is_correct": false, "explanation": "夕立は降る雨で、話があちこちに行かない理由にはならない。"}, {"text": "アジェンダ", "is_correct": true, "explanation": "「アジェンダがある」ことで話の流れが決まり、話があちこちに行かないという文に合う。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は飛ぶ粒子で、話の流れを整える役割にはならない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象で、話の流れを整えるものではない。"}], "explanations": {"夕立": "夕立は降る雨で、話があちこちに行かない理由にはならない。", "アジェンダ": "「アジェンダがある」ことで話の流れが決まり、話があちこちに行かないという文に合う。", "花粉": "花粉は飛ぶ粒子で、話の流れを整える役割にはならない。", "雷": "雷は自然現象で、話の流れを整えるものではない。"}, "sentence_index": 6, "correct_answer": "アジェンダ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アジェンダが夜八時に放送されて、家で見ました。", "explanation": "ここは〈番組〉の意味。アジェンダは放送されるものではないので、夜八時に放送されたという話とは合わない。"}, {"text": "アジェンダを歌って、会議を始めました。", "explanation": "ここは〈歌〉の意味。アジェンダは歌うものではないので、歌って会議を始めたという話とは合わない。"}, {"text": "アジェンダがかぜをひいて、会議を休みました。", "explanation": "ここは〈風邪〉の意味。アジェンダは病気になるものではないので、かぜをひいて会議を休んだという話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
