INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38107, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、議題が書かれているという存在の文には合わない。"}, {"text": "も", "is_correct": false, "explanation": "「も」は後ろの「は」と続けられず、「もは」となって文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、議題が書かれているという文の述語を支えられない。"}, {"text": "に", "is_correct": true, "explanation": "「アジェンダには〜書かれています」で、書かれている場所を示す正しい助詞。"}], "correct_answer": "に", "explanations": {"を": "「を」は目的語を示すが、議題が書かれているという存在の文には合わない。", "も": "「も」は後ろの「は」と続けられず、「もは」となって文が成り立たない。", "の": "「の」は所属や修飾を示すので、議題が書かれているという文の述語を支えられない。", "に": "「アジェンダには〜書かれています」で、書かれている場所を示す正しい助詞。"}, "error_tags": {"を": "目的語", "も": "添加", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
