INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38107, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "会議などで話し合うことの一覧表。予定や議題をまとめたもの。", "primary_collocate": null, "pronunciation": "あじぇんだ", "ipa": "adʑeɴda", "syllable_count": 4, "sentences": [{"text": "部長は会議のアジェンダを前日に配ります。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は会議[かいぎ]のアジェンダを前日[ぜんじつ]に配[くば]ります。", "sentence_source": "generated"}, {"text": "アジェンダには、議題と時間の割り振りが書かれています。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダには、議題[ぎだい]と時間[じかん]の割[わ]り振[ふ]りが書[か]かれています。", "sentence_source": "generated"}, {"text": "アジェンダを事前に読んでおけば、会議がスムーズに進みます。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダを事前[じぜん]に読[よ]んでおけば、会議[かいぎ]がスムーズに進[すす]みます。", "sentence_source": "generated"}, {"text": "新しい議題をアジェンダに加えてください。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "新[あたら]しい議題[ぎだい]をアジェンダに加[くわ]えてください。", "sentence_source": "generated"}, {"text": "アジェンダ通りに進めたので、会議は一時間で終わりました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダ通[どお]りに進[すす]めたので、会議[かいぎ]は一時間[いちじかん]で終[お]わりました。", "sentence_source": "generated"}, {"text": "メールにアジェンダを添付しました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "メールにアジェンダを添付[てんぷ]しました。", "sentence_source": "generated"}, {"text": "アジェンダにない話題は、次回に回します。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダにない話題[わだい]は、次回[じかい]に回[まわ]します。", "sentence_source": "generated"}, {"text": "司会者はアジェンダを確認してから、会議を始めました。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]はアジェンダを確認[かくにん]してから、会議[かいぎ]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "今回のアジェンダは、予算の見直しが中心です。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "今回[こんかい]のアジェンダは、予算[よさん]の見直[みなお]しが中心[ちゅうしん]です。", "sentence_source": "generated"}, {"text": "アジェンダが多すぎて、一回では終わりません。", "target_word": "アジェンダ", "complexity_tier": "T3", "furigana": "アジェンダが多[おお]すぎて、一回[いっかい]では終[お]わりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アジェンダ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "会議で話し合う議題や予定をまとめた一覧表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38107, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雪", "is_correct": false, "explanation": "雪は降る自然現象で、会議の資料として配るものではない。"}, {"text": "アジェンダ", "is_correct": true, "explanation": "会議の内容をまとめて前日に配る一覧表としての語。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は飛ぶ粒子で、会議のために配るものではない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象で、会議の前に配る対象にならない。"}], "explanations": {"雪": "雪は降る自然現象で、会議の資料として配るものではない。", "アジェンダ": "会議の内容をまとめて前日に配る一覧表としての語。", "花粉": "花粉は飛ぶ粒子で、会議のために配るものではない。", "雷": "雷は自然現象で、会議の前に配る対象にならない。"}, "sentence_index": 0, "correct_answer": "アジェンダ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アジェンダを履いて、駅まで走りました。", "explanation": "ここは〈靴〉の意味。アジェンダは履くものではないので、履いて駅まで走ったという話とは合わない。"}, {"text": "アジェンダに塩を加えてください。", "explanation": "ここは〈スープ〉の意味。アジェンダは食べ物ではないので、塩を加える話とは合わない。"}, {"text": "アジェンダに餌をやって、散歩に連れて行きました。", "explanation": "ここは〈ペット〉の意味。アジェンダは生き物ではないので、餌をやって散歩に連れて行く話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38107, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、「〜にない話題」という形に入らない。"}, {"text": "台風", "is_correct": false, "explanation": "台風は自然現象で、話題の掲載先として文が成り立たない。"}, {"text": "夕立", "is_correct": false, "explanation": "夕立は降る雨で、話題を載せる語ではないので合わない。"}, {"text": "アジェンダ", "is_correct": true, "explanation": "「アジェンダにない話題」で、議題の一覧に載っていないという意味になる。"}], "explanations": {"夕焼け": "夕焼けは空の現象で、「〜にない話題」という形に入らない。", "台風": "台風は自然現象で、話題の掲載先として文が成り立たない。", "夕立": "夕立は降る雨で、話題を載せる語ではないので合わない。", "アジェンダ": "「アジェンダにない話題」で、議題の一覧に載っていないという意味になる。"}, "sentence_index": 6, "correct_answer": "アジェンダ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アジェンダを着て、会議に出かけました。", "explanation": "ここは〈服〉の意味。アジェンダは身につけるものではないので、着て会議に出かけたという話とは合わない。"}, {"text": "アジェンダを弾いて、曲を演奏しました。", "explanation": "ここは〈楽器〉の意味。アジェンダは楽器ではないので、弾いて曲を演奏したという話とは合わない。"}, {"text": "アジェンダを顔に塗って、化粧をしました。", "explanation": "ここは〈化粧品〉の意味。アジェンダは顔に塗るものではないので、顔に塗って化粧をしたという話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38107, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司会者は会議のアジェンダが当日に配ります。", "corrected_sentence": "司会者は会議のアジェンダを当日に配ります。", "error_description": "「配る」は目的語の「を」を取る。「が」は誤りで、「アジェンダを配る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38107, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今回のアジェンダを、新しい議題が中心です。", "corrected_sentence": "今回のアジェンダは、新しい議題が中心です。", "error_description": "「中心です」の主題を示すには「は」を使う。「を」は目的語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「機能が組み込まれている」の主語を示し、受身文として正しい。"}, {"text": "を", "is_correct": false, "explanation": "受身文では「を」で主語を示せないので、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「機能の組み込まれて」は文の主語にならず、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「機能と組み込まれて」は並列の意味になり、意味が合わない。"}], "correct_answer": "が", "explanations": {"が": "「機能が組み込まれている」の主語を示し、受身文として正しい。", "を": "受身文では「を」で主語を示せないので、文が成り立たない。", "の": "「機能の組み込まれて」は文の主語にならず、文が通らない。", "と": "「機能と組み込まれて」は並列の意味になり、意味が合わない。"}, "error_tags": {"を": "目的語（受身文では使えない）", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「授業に組み込む」の到着点・入れる先を示し、正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すので、組み込む先を示せず意味が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「授業の組み込んで」は名詞を修飾できず、文の動詞として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、文の意味が合わない。"}], "correct_answer": "に", "explanations": {"に": "「授業に組み込む」の到着点・入れる先を示し、正しい。", "から": "起点を示すので、組み込む先を示せず意味が合わない。", "の": "「授業の組み込んで」は名詞を修飾できず、文の動詞として成り立たない。", "より": "比較を表すので、文の意味が合わない。"}, "error_tags": {"から": "起点", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの中に、うまく入れること。", "primary_collocate": null, "pronunciation": "くみこむ", "ipa": "kɯmikomɯ", "syllable_count": 4, "sentences": [{"text": "技術者は、小さな部品を機械の中に組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "技術者[ぎじゅつしゃ]は、小[ちい]さな部品[ぶひん]を機械[きかい]の中[なか]に組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "このアプリには、地図の機能が組み込まれている。", "target_word": "組み込まれて", "complexity_tier": "T3", "furigana": "このアプリには、地図[ちず]の機能[きのう]が組[く]み込[こ]まれている。", "sentence_source": "generated"}, {"text": "新しい装置を、古い時計に組み込む。", "target_word": "組み込む", "complexity_tier": "T3", "furigana": "新[あたら]しい装置[そうち]を、古[ふる]い時計[とけい]に組[く]み込[こ]む。", "sentence_source": "generated"}, {"text": "彼女は好きな曲を、発表のビデオに組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は好[す]きな曲[きょく]を、発表[はっぴょう]のビデオに組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "壁にテレビを組み込むと、部屋が広く使える。", "target_word": "組み込む", "complexity_tier": "T3", "furigana": "壁[かべ]にテレビを組[く]み込[こ]むと、部屋[へや]が広[ひろ]く使[つか]える。", "sentence_source": "generated"}, {"text": "毎日のメニューに、ストレッチを組み込んでいる。", "target_word": "組み込んで", "complexity_tier": "T3", "furigana": "毎日[まいにち]のメニューに、ストレッチを組[く]み込[こ]んでいる。", "sentence_source": "generated"}, {"text": "設計者は、非常口を建物のデザインに組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T4", "furigana": "設計者[せっけいしゃ]は、非常口[ひじょうぐち]を建物[たてもの]のデザインに組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "先生は、ゲームを授業に組み込んで生徒を楽しませた。", "target_word": "組み込んで", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ゲームを授業[じゅぎょう]に組[く]み込[こ]んで生徒[せいと]を楽[たの]しませた。", "sentence_source": "generated"}, {"text": "電源が切れても動くように、電池を組み込む。", "target_word": "組み込む", "complexity_tier": "T3", "furigana": "電源[でんげん]が切[き]れても動[うご]くように、電池[でんち]を組[く]み込[こ]む。", "sentence_source": "generated"}, {"text": "この棚は、壁の中に組み込む形になっている。", "target_word": "組み込む", "complexity_tier": "T3", "furigana": "この棚[たな]は、壁[かべ]の中[なか]に組[く]み込[こ]む形[かたち]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み込む", "label": "基本形"}, {"form": "組み込んだ", "label": "過去形"}, {"form": "組み込んで", "label": "て形"}, {"form": "組み込まれて", "label": "受身て形"}, {"form": "組み込まない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "部品や機能を、全体の中にぴったり入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み込んだ", "is_correct": true, "explanation": "過去形で文末に置け、部品を機械の中に入れたという完了を表し正しい。"}, {"text": "組み込んで", "is_correct": false, "explanation": "て形は文末に置けないので、文として完結しない。"}, {"text": "組み込まれ", "is_correct": false, "explanation": "受身の連用形で、文末に置けないので文が成り立たない。"}, {"text": "組み込み", "is_correct": false, "explanation": "連用形・名詞形で、文末に置けないので文が完結しない。"}], "explanations": {"組み込んだ": "過去形で文末に置け、部品を機械の中に入れたという完了を表し正しい。", "組み込んで": "て形は文末に置けないので、文として完結しない。", "組み込まれ": "受身の連用形で、文末に置けないので文が成り立たない。", "組み込み": "連用形・名詞形で、文末に置けないので文が完結しない。"}, "sentence_index": 0, "correct_answer": "組み込んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "説明書を見ながら、机を組み込んだ。", "explanation": "ここは〈組み立てる〉の意味。部品を一つずつ合わせて作る場面では組み立てるを使い、組み込むは既にある全体に入れる意味で合わない。"}, {"text": "先輩と組み込んで仕事をした。", "explanation": "ここは〈組む〉（ペアになる）の意味。人と一緒に仕事をする場合、組み込むは使えない。"}, {"text": "寒いので、彼は布団を組み込んで寝た。", "explanation": "ここは〈くるむ〉の意味。体を布団で包む場面では包む・くるむを使い、組み込むは既にある全体の中に入れる意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み込んだ", "is_correct": true, "explanation": "過去形で文末に置け、非常口をデザインに入れたという完了を表し正しい。"}, {"text": "組み込ん", "is_correct": false, "explanation": "不完全な形で、文末に置けないので文が成り立たない。"}, {"text": "組み込みたく", "is_correct": false, "explanation": "願望の連用形で、文末に置けないので文が完結しない。"}, {"text": "組み込っ", "is_correct": false, "explanation": "不完全な形で、文として成り立たない。"}], "explanations": {"組み込んだ": "過去形で文末に置け、非常口をデザインに入れたという完了を表し正しい。", "組み込ん": "不完全な形で、文末に置けないので文が成り立たない。", "組み込みたく": "願望の連用形で、文末に置けないので文が完結しない。", "組み込っ": "不完全な形で、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "組み込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "かばんに服を組み込んで、ぎゅうぎゅうにした。", "explanation": "ここは〈詰め込む〉の意味。かばんに物を押し込む場面では詰め込むを使い、組み込むは全体の一部として入れる意味で合わない。"}, {"text": "コンセントにプラグを組み込む。", "explanation": "ここは〈差し込む〉の意味。プラグを穴に入れる動作は差し込むを使い、組み込むは全体の部分として入れる意味で合わない。"}, {"text": "借金を組み込んで困っている。", "explanation": "ここは〈抱え込む〉の意味。負担や問題を抱えることは抱え込むを使い、組み込むは部分として入れる意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい装置を、古い時計で組み込むことにした。", "corrected_sentence": "新しい装置を、古い時計に組み込むことにした。", "error_description": "「組み込む」は入れる先を「に」で示すので、「で」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組み込まれて", "is_correct": true, "explanation": "「いる」に続く受身のて形で、機能が組み込まれている状態を表し正しい。"}, {"text": "組み込まれ", "is_correct": false, "explanation": "連用形のみでは「いる」に続かないので、文が成り立たない。"}, {"text": "組み込ませ", "is_correct": false, "explanation": "使役の語幹で、「いる」には続かないので文が通らない。"}, {"text": "組み込む", "is_correct": false, "explanation": "辞書形は「いる」の前に置けないので、この位置では不自然。"}], "correct_form": "組み込まれて", "base_form": "組み込む", "form_label": "受身て形", "sentence_index": 1, "explanations": {"組み込まれて": "「いる」に続く受身のて形で、機能が組み込まれている状態を表し正しい。", "組み込まれ": "連用形のみでは「いる」に続かないので、文が成り立たない。", "組み込ませ": "使役の語幹で、「いる」には続かないので文が通らない。", "組み込む": "辞書形は「いる」の前に置けないので、この位置では不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38108, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員は、新しい機能を古いアプリに組み込まれた。", "corrected_sentence": "店員は、新しい機能を古いアプリに組み込んだ。", "error_description": "「組み込む」は能動詞で、主語は「店員」、目的語は「機能」。受身の「組み込まれた」は誤りで、正しくは「組み込んだ」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組み込んで", "is_correct": true, "explanation": "「生徒を楽しませた」へ続くて形で、授業に組み込んだうえで楽しませたという意味になり正しい。"}, {"text": "組み込もう", "is_correct": false, "explanation": "意志形は「生徒を楽しませた」と続かないので、文の流れに合わない。"}, {"text": "組み込みたい", "is_correct": false, "explanation": "願望形で、「組み込みたい生徒」となり意味が合わない。"}, {"text": "組み込ませる", "is_correct": false, "explanation": "使役形の辞書形で、「生徒を楽しませた」と続かないので文が通らない。"}], "correct_form": "組み込んで", "base_form": "組み込む", "form_label": "て形", "sentence_index": 7, "explanations": {"組み込んで": "「生徒を楽しませた」へ続くて形で、授業に組み込んだうえで楽しませたという意味になり正しい。", "組み込もう": "意志形は「生徒を楽しませた」と続かないので、文の流れに合わない。", "組み込みたい": "願望形で、「組み込みたい生徒」となり意味が合わない。", "組み込ませる": "使役形の辞書形で、「生徒を楽しませた」と続かないので文が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「チームに組み込む」の入れる先・到着点を示し、正しい。"}, {"text": "を", "is_correct": false, "explanation": "二つ目の「を」は組み込む先を示せず、文が不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「チームの組み込んだ」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「チームで組み込んだ」は手段の意味になり、入れる先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「チームに組み込む」の入れる先・到着点を示し、正しい。", "を": "二つ目の「を」は組み込む先を示せず、文が不自然になる。", "の": "「チームの組み込んだ」は文が成り立たない。", "で": "「チームで組み込んだ」は手段の意味になり、入れる先を示せない。"}, "error_tags": {"を": "目的語（二つ目は不可）", "の": "連体修飾", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「行事の計画に組み込んだ」の入れる先を示し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、組み込む先を示せず文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表し、入れる先を示せないので文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、文の意味が合わない。"}], "correct_answer": "に", "explanations": {"に": "「行事の計画に組み込んだ」の入れる先を示し、正しい。", "が": "主語を示すが、組み込む先を示せず文が通らない。", "と": "並列を表し、入れる先を示せないので文が成り立たない。", "より": "比較を表し、文の意味が合わない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物や人を、組織や計画などの一部分として含めること。", "primary_collocate": null, "pronunciation": "くみこむ", "ipa": "kɯmikomɯ", "syllable_count": 4, "sentences": [{"text": "市は、新しい道路を都市計画に組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "市[し]は、新[あたら]しい道路[どうろ]を都市計画[としけいかく]に組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "会社は、若い社員をプロジェクトのチームに組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、若[わか]い社員[しゃいん]をプロジェクトのチームに組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "予算に、修理の費用も組み込んでおく。", "target_word": "組み込んで", "complexity_tier": "T3", "furigana": "予算[よさん]に、修理[しゅうり]の費用[ひよう]も組[く]み込[こ]んでおく。", "sentence_source": "generated"}, {"text": "彼は、いつの間にか悪い組織に組み込まれていた。", "target_word": "組み込まれて", "complexity_tier": "T4", "furigana": "彼[かれ]は、いつの間[ま]にか悪[わる]い組織[そしき]に組[く]み込[こ]まれていた。", "sentence_source": "generated"}, {"text": "旅行の日程に、一日だけ自由な時間を組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "旅行[りょこう]の日程[にってい]に、一日[いちにち]だけ自由[じゆう]な時間[じかん]を組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "小さな村は、隣の町に組み込まれた。", "target_word": "組み込まれた", "complexity_tier": "T3", "furigana": "小[ちい]さな村[むら]は、隣[となり]の町[まち]に組[く]み込[こ]まれた。", "sentence_source": "generated"}, {"text": "監督は、控えの選手を作戦に組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "監督[かんとく]は、控[ひか]えの選手[せんしゅ]を作戦[さくせん]に組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "学校は、地域の人を行事の計画に組み込んだ。", "target_word": "組み込んだ", "complexity_tier": "T3", "furigana": "学校[がっこう]は、地域[ちいき]の人[ひと]を行事[ぎょうじ]の計画[けいかく]に組[く]み込[こ]んだ。", "sentence_source": "generated"}, {"text": "この制度は、外国人の働き手も社会に組み込む。", "target_word": "組み込む", "complexity_tier": "T4", "furigana": "この制度[せいど]は、外国人[がいこくじん]の働[はたら]き手[て]も社会[しゃかい]に組[く]み込[こ]む。", "sentence_source": "generated"}, {"text": "新入生を班に組み込む作業を、先生が進めている。", "target_word": "組み込む", "complexity_tier": "T3", "furigana": "新入生[しんにゅうせい]を班[はん]に組[く]み込[こ]む作業[さぎょう]を、先生[せんせい]が進[すす]めている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み込む", "label": "基本形"}, {"form": "組み込んだ", "label": "過去形"}, {"form": "組み込んで", "label": "て形"}, {"form": "組み込まれた", "label": "受身過去"}, {"form": "組み込まない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "人や項目を、組織や計画の一部として含めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み込んだ", "is_correct": true, "explanation": "過去形で文末に置け、道路を都市計画の一部にしたという完了を表し正しい。"}, {"text": "組み込んで", "is_correct": false, "explanation": "て形は文末に置けないので、文として完結しない。"}, {"text": "組み込まれ", "is_correct": false, "explanation": "受身の連用形で、文末に置けないので文が成り立たない。"}, {"text": "組み込み", "is_correct": false, "explanation": "連用形・名詞形で、文末に置けないので文が完結しない。"}], "explanations": {"組み込んだ": "過去形で文末に置け、道路を都市計画の一部にしたという完了を表し正しい。", "組み込んで": "て形は文末に置けないので、文として完結しない。", "組み込まれ": "受身の連用形で、文末に置けないので文が成り立たない。", "組み込み": "連用形・名詞形で、文末に置けないので文が完結しない。"}, "sentence_index": 0, "correct_answer": "組み込んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コップに水を組み込んだ。", "explanation": "ここは〈注ぐ〉の意味。コップに液体を入れる動作は注ぐを使い、組み込むは組織や計画の一部にする意味で合わない。"}, {"text": "雨が降ってきたので、傘を組み込んだ。", "explanation": "ここは〈差す〉の意味。傘を開く場面では差すを使い、組み込むは組織や計画の一部にする意味で合わない。"}, {"text": "髪に花を組み込んだ。", "explanation": "ここは〈挿す〉の意味。髪に花を飾る場面では挿すを使い、組み込むは組織や計画の一部にする意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み込んだ", "is_correct": true, "explanation": "過去形で文末に置け、控えの選手を作戦に入れたという完了を表し正しい。"}, {"text": "組み込ん", "is_correct": false, "explanation": "不完全な形で、文末に置けないので文が成り立たない。"}, {"text": "組み込みた", "is_correct": false, "explanation": "不完全な形で、文末に置けないので文が完結しない。"}, {"text": "組み込んだり", "is_correct": false, "explanation": "並列の形で、文末に置くと意味が通らない。"}], "explanations": {"組み込んだ": "過去形で文末に置け、控えの選手を作戦に入れたという完了を表し正しい。", "組み込ん": "不完全な形で、文末に置けないので文が成り立たない。", "組み込みた": "不完全な形で、文末に置けないので文が完結しない。", "組み込んだり": "並列の形で、文末に置くと意味が通らない。"}, "sentence_index": 6, "correct_answer": "組み込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "押し入れに、おもちゃを組み込んだ。", "explanation": "ここは〈隠す〉の意味。見えない所に物を置く場面では隠すを使い、組み込むは組織や計画の一部にする意味で合わない。"}, {"text": "新入生を温かく組み込んだ。", "explanation": "ここは〈迎える〉の意味。人を温かく迎える場合は迎えるを使い、組み込むは組織や計画の一部にする意味で合わない。"}, {"text": "隣の人と組み込んで練習した。", "explanation": "ここは〈組む〉（ペアを作る）の意味。人と一緒に練習する場合、組み込むは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は、古い橋を新しい計画で組み込んだ。", "corrected_sentence": "町は、古い橋を新しい計画に組み込んだ。", "error_description": "「組み込む」は入れる先を「に」で示すので、「で」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組み込んだ", "is_correct": true, "explanation": "文末の過去形で、チームに組み込んだという完了を表し正しい。"}, {"text": "組み込んで", "is_correct": false, "explanation": "て形は文末に置けないので、文として完結しない。"}, {"text": "組み込み", "is_correct": false, "explanation": "連用形は文末に置けないので、文が成り立たない。"}, {"text": "組み込まれ", "is_correct": false, "explanation": "受身の連用形で、文末に置けないので文が通らない。"}], "correct_form": "組み込んだ", "base_form": "組み込む", "form_label": "過去形", "sentence_index": 1, "explanations": {"組み込んだ": "文末の過去形で、チームに組み込んだという完了を表し正しい。", "組み込んで": "て形は文末に置けないので、文として完結しない。", "組み込み": "連用形は文末に置けないので、文が成り立たない。", "組み込まれ": "受身の連用形で、文末に置けないので文が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38109, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、ごみ処理を計画に組み込まれた。", "corrected_sentence": "町は、ごみ処理を計画に組み込んだ。", "error_description": "「ごみ処理を」と目的語があるので、能動の「組み込んだ」が正しい。受身の「組み込まれた」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組み込んだ", "is_correct": true, "explanation": "過去形で、行事の計画に組み込んだという完了を表し正しい。"}, {"text": "組み込もう", "is_correct": false, "explanation": "意志形は過去の出来事に合わないので、文の意味が成り立たない。"}, {"text": "組み込みたい", "is_correct": false, "explanation": "願望形で、過去の出来事を表せないので意味が合わない。"}, {"text": "組み込まず", "is_correct": false, "explanation": "否定の連用形で、完了を表す文の意味に合わない。"}], "correct_form": "組み込んだ", "base_form": "組み込む", "form_label": "過去形", "sentence_index": 7, "explanations": {"組み込んだ": "過去形で、行事の計画に組み込んだという完了を表し正しい。", "組み込もう": "意志形は過去の出来事に合わないので、文の意味が成り立たない。", "組み込みたい": "願望形で、過去の出来事を表せないので意味が合わない。", "組み込まず": "否定の連用形で、完了を表す文の意味に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
