INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38110, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すぐにしなければならない大事なこと", "primary_collocate": null, "pronunciation": "きゅうむ", "ipa": "kʲɯːmɯ", "syllable_count": 3, "sentences": [{"text": "川の水があふれる前に、住民を安全な場所へ移すのが急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]があふれる前[まえ]に、住民[じゅうみん]を安全[あんぜん]な場所[ばしょ]へ移[うつ]すのが急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "古い橋の修理は、町にとって急務になっている。", "target_word": "急務", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]の修理[しゅうり]は、町[まち]にとって急務[きゅうむ]になっている。", "sentence_source": "generated"}, {"text": "けが人の手当てが急務だと、医者は言った。", "target_word": "急務", "complexity_tier": "T3", "furigana": "けが人[にん]の手当[てあ]てが急務[きゅうむ]だと、医者[いしゃ]は言[い]った。", "sentence_source": "generated"}, {"text": "水がなくなった村では、井戸を掘ることが急務だった。", "target_word": "急務", "complexity_tier": "T3", "furigana": "水[みず]がなくなった村[むら]では、井戸[いど]を掘[ほ]ることが急務[きゅうむ]だった。", "sentence_source": "generated"}, {"text": "父が入院したので、家族の仕事の分担を決めるのが急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "父[ちち]が入院[にゅういん]したので、家族[かぞく]の仕事[しごと]の分担[ぶんたん]を決[き]めるのが急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "試験まで一週間しかないので、苦手な数学の復習が急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "試験[しけん]まで一週間[いっしゅうかん]しかないので、苦手[にがて]な数学[すうがく]の復習[ふくしゅう]が急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "食べ物が足りない避難所に、米を届けることが急務となった。", "target_word": "急務", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]が足[た]りない避難所[ひなんじょ]に、米[こめ]を届[とど]けることが急務[きゅうむ]となった。", "sentence_source": "generated"}, {"text": "店の電気が切れたままなので、早く直すことが急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "店[みせ]の電気[でんき]が切[き]れたままなので、早[はや]く直[なお]すことが急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "急に人が減ったため、新しい働き手を探すのが急務だった。", "target_word": "急務", "complexity_tier": "T3", "furigana": "急[きゅう]に人[ひと]が減[へ]ったため、新[あたら]しい働[はたら]き手[て]を探[さが]すのが急務[きゅうむ]だった。", "sentence_source": "generated"}, {"text": "雨漏りがひどいので、屋根を直すのが今の急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "雨漏[あまも]りがひどいので、屋根[やね]を直[なお]すのが今[いま]の急務[きゅうむ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "急務", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "今すぐ行うべき大切な仕事やこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38110, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "急務", "is_correct": true, "explanation": "「すぐに取り組むべき大事なこと」の意味で、避難を急ぐ文脈に合う。"}, {"text": "急増", "is_correct": false, "explanation": "数や量が急に増えることを指す。避難の作業を「移すのが急増だ」とは言えない。"}, {"text": "急変", "is_correct": false, "explanation": "状態が急に変わることを指す。「移すのが急変だ」は文として意味が通らない。"}, {"text": "急行", "is_correct": false, "explanation": "急いで行くこと、または急行列車を指す。「移すのが急行だ」では意味が成り立たない。"}], "explanations": {"急務": "「すぐに取り組むべき大事なこと」の意味で、避難を急ぐ文脈に合う。", "急増": "数や量が急に増えることを指す。避難の作業を「移すのが急増だ」とは言えない。", "急変": "状態が急に変わることを指す。「移すのが急変だ」は文として意味が通らない。", "急行": "急いで行くこと、または急行列車を指す。「移すのが急行だ」では意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "急務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中に急務が運ばれてきたので、医師は病院に残った。", "explanation": "ここは〈急患〉（急に治療が必要な患者）の意味。急患は人を指すが、急務は仕事や課題を表すので、運ばれてくる人には使わない。"}, {"text": "急務の列車に乗り遅れて、会議に間に合わなかった。", "explanation": "ここは〈急行〉（途中の停車駅が少ない列車）の意味。急行は列車の種類を指すが、急務は緊急の課題を表すので、列車には使わない。"}, {"text": "祖母が倒れたという知らせが届き、急務で会議を抜けた。", "explanation": "ここは〈急用〉（個人的な急ぎの用事）の意味。急用は個人の用事を指すが、急務は社会や組織の大きな課題を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38110, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "急務", "is_correct": true, "explanation": "「すぐに取り組むべき大事なこと」の意味で、避難所への米の輸送という緊急の課題に合う。"}, {"text": "急病", "is_correct": false, "explanation": "急に起こる病気を指す。「米を届けることが急病となった」は意味が通らない。"}, {"text": "急騰", "is_correct": false, "explanation": "物の値段が急に上がることを指す。米を届けることには当てはまらない。"}, {"text": "急流", "is_correct": false, "explanation": "流れの速い川を指す。「米を届けることが急流となった」は文として成り立たない。"}], "explanations": {"急務": "「すぐに取り組むべき大事なこと」の意味で、避難所への米の輸送という緊急の課題に合う。", "急病": "急に起こる病気を指す。「米を届けることが急病となった」は意味が通らない。", "急騰": "物の値段が急に上がることを指す。米を届けることには当てはまらない。", "急流": "流れの速い川を指す。「米を届けることが急流となった」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "急務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "税金を納めるのは、国民の急務だ。", "explanation": "ここは〈義務〉（果たすべき決まった役目）の意味。義務は決まった役目を指すが、急務は緊急に取り組むべき課題なので「国民の急務」とは言わない。"}, {"text": "川の急務に、船が流されてしまった。", "explanation": "ここは〈急流〉（流れの速い川）の意味。急流は川を指すが、急務は仕事や課題を表すので、川には使わない。"}, {"text": "急務の連絡なので、すぐに電話した。", "explanation": "ここは〈急ぎ〉（急ぐ必要があること）の意味。急ぎは個人的な用件にも使えるが、急務は社会や組織の大きな課題を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38110, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨で道路が崩れたので、通れる道を作ることが急務をなっている。", "corrected_sentence": "大雨で道路が崩れたので、通れる道を作ることが急務になっている。", "error_description": "誤: 「急務をなっている」→ 正: 「急務になっている」。「〜になる」の結果の相手は「に」で示す。「を」は目的語の助詞なので「なる」には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38110, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨で橋が壊れたので、橋の修理は町の急務なだ。", "corrected_sentence": "大雨で橋が壊れたので、橋の修理は町の急務だ。", "error_description": "誤: 「急務なだ」→ 正: 「急務だ」。急務は名詞なので「な」は付けない。「急務だ」または「急務の〜」の形で使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "を", "is_correct": false, "explanation": "「急務をなっている」となり、「なる」は目的語を取れないので不自然。"}, {"text": "と", "is_correct": true, "explanation": "「急務となっている」の「と」。「〜となる」で変化・結果を表す形で、ここで正しい。"}, {"text": "が", "is_correct": false, "explanation": "「急務がなっている」となり、「なる」の主語として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「急務でなっている」となり、「で」は手段・場所を示すので「なる」と続かない。"}], "correct_answer": "と", "explanations": {"を": "「急務をなっている」となり、「なる」は目的語を取れないので不自然。", "と": "「急務となっている」の「と」。「〜となる」で変化・結果を表す形で、ここで正しい。", "が": "「急務がなっている」となり、「なる」の主語として成り立たない。", "で": "「急務でなっている」となり、「で」は手段・場所を示すので「なる」と続かない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "緊急に取り組む必要があること。最優先で行うべき課題。", "primary_collocate": null, "pronunciation": "きゅうむ", "ipa": "kʲɯːmɯ", "syllable_count": 3, "sentences": [{"text": "人口が減る町では、若い人が住める環境づくりが急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "人口[じんこう]が減[へ]る町[まち]では、若[わか]い人[ひと]が住[す]める環境[かんきょう]づくりが急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "会社にとって、情報もれを防ぐ対策が急務となっている。", "target_word": "急務", "complexity_tier": "T3", "furigana": "会社[かいしゃ]にとって、情報[じょうほう]もれを防[ふせ]ぐ対策[たいさく]が急務[きゅうむ]となっている。", "sentence_source": "generated"}, {"text": "地震に備えて学校の建物を丈夫にすることが、市の急務である。", "target_word": "急務", "complexity_tier": "T3", "furigana": "地震[じしん]に備[そな]えて学校[がっこう]の建物[たてもの]を丈夫[じょうぶ]にすることが、市[し]の急務[きゅうむ]である。", "sentence_source": "generated"}, {"text": "地球の温度が上がっている今、ごみを減らすことは世界の急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の温度[おんど]が上[あ]がっている今[いま]、ごみを減[へ]らすことは世界[せかい]の急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "新製品の不良を調べて原因を見つけるのが、開発チームの急務だった。", "target_word": "急務", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の不良[ふりょう]を調[しら]べて原因[げんいん]を見[み]つけるのが、開発[かいはつ]チームの急務[きゅうむ]だった。", "sentence_source": "generated"}, {"text": "高齢者を支える仕組みを整えることは、国の急務と言える。", "target_word": "急務", "complexity_tier": "T3", "furigana": "高齢者[こうれいしゃ]を支[ささ]える仕組[しく]みを整[ととの]えることは、国[くに]の急務[きゅうむ]と言[い]える。", "sentence_source": "generated"}, {"text": "客が減り続ける店にとって、新しい売り方を考えるのが急務だ。", "target_word": "急務", "complexity_tier": "T3", "furigana": "客[きゃく]が減[へ]り続[つづ]ける店[みせ]にとって、新[あたら]しい売[う]り方[かた]を考[かんが]えるのが急務[きゅうむ]だ。", "sentence_source": "generated"}, {"text": "大会までに選手の体力をつけることが、監督の急務だった。", "target_word": "急務", "complexity_tier": "T3", "furigana": "大会[たいかい]までに選手[せんしゅ]の体力[たいりょく]をつけることが、監督[かんとく]の急務[きゅうむ]だった。", "sentence_source": "generated"}, {"text": "ネットの被害から子どもを守る方法を考えるのが急務である。", "target_word": "急務", "complexity_tier": "T3", "furigana": "ネットの被害[ひがい]から子[こ]どもを守[まも]る方法[ほうほう]を考[かんが]えるのが急務[きゅうむ]である。", "sentence_source": "generated"}, {"text": "病院で働く人が足りず、人材の確保が急務になっている。", "target_word": "急務", "complexity_tier": "T3", "furigana": "病院[びょういん]で働[はたら]く人[ひと]が足[た]りず、人材[じんざい]の確保[かくほ]が急務[きゅうむ]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "急務", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "社会や組織が最優先で取り組むべき緊急の課題", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "急務", "is_correct": true, "explanation": "「最優先で行うべき課題」の意味で、住環境づくりという社会の課題に合う。"}, {"text": "急騰", "is_correct": false, "explanation": "物の値段が急に上がることを指す。「環境づくりが急騰だ」とは言えない。"}, {"text": "急流", "is_correct": false, "explanation": "流れの速い川を指す。「環境づくりが急流だ」は文として成り立たない。"}, {"text": "急坂", "is_correct": false, "explanation": "勾配の急な坂を指す。「環境づくりが急坂だ」は意味が通らない。"}], "explanations": {"急務": "「最優先で行うべき課題」の意味で、住環境づくりという社会の課題に合う。", "急騰": "物の値段が急に上がることを指す。「環境づくりが急騰だ」とは言えない。", "急流": "流れの速い川を指す。「環境づくりが急流だ」は文として成り立たない。", "急坂": "勾配の急な坂を指す。「環境づくりが急坂だ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "急務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急務の胃炎で、一週間入院した。", "explanation": "ここは〈急性〉（症状が急に現れて進む）の意味。急性は病気の進み方を表すが、急務は緊急の課題を表すので、病名には付けない。"}, {"text": "夜中に急務の患者が救急車で運ばれてきた。", "explanation": "ここは〈急患〉（急に治療が必要な患者）の意味。急患は人を指すが、急務は仕事や課題を表すので、患者には使わない。"}, {"text": "急務ができたので、会議を早退した。", "explanation": "ここは〈急用〉（個人的な急ぎの用事）の意味。急用は個人の用事を指すが、急務は組織や社会の大きな課題を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "急務", "is_correct": true, "explanation": "「最優先で行うべき課題」の意味で、客の減少に対応する新しい売り方を考える課題に合う。"}, {"text": "急死", "is_correct": false, "explanation": "急に死ぬことを指す。「売り方を考えるのが急死だ」は成り立たない。"}, {"text": "急患", "is_correct": false, "explanation": "急に治療が必要になった患者を指す。「売り方を考えるのが急患だ」は意味が通らない。"}, {"text": "急増", "is_correct": false, "explanation": "数や量が急に増えることを指す。売り方を考えることを「急増」とは言えない。"}], "explanations": {"急務": "「最優先で行うべき課題」の意味で、客の減少に対応する新しい売り方を考える課題に合う。", "急死": "急に死ぬことを指す。「売り方を考えるのが急死だ」は成り立たない。", "急患": "急に治療が必要になった患者を指す。「売り方を考えるのが急患だ」は意味が通らない。", "急増": "数や量が急に増えることを指す。売り方を考えることを「急増」とは言えない。"}, "sentence_index": 6, "correct_answer": "急務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "救急車で急務が運ばれてきた。", "explanation": "ここは〈急患〉（救急で運ばれる患者）の意味。急患は患者を指すが、急務は仕事や課題を表すので、人の意味では使えない。"}, {"text": "川の急務に、船が流されてしまった。", "explanation": "ここは〈急流〉（流れの速い川）の意味。急流は川を指すが、急務は仕事や課題を表すので、川には使わない。"}, {"text": "車を運転するには、免許が急務だ。", "explanation": "ここは〈必要〉の意味。必要は欠かせないことを表すが、急務は緊急に取り組むべき課題を表すので、免許の要件には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい薬の開発が、研究所の急務をなった。", "corrected_sentence": "新しい薬の開発が、研究所の急務となった。", "error_description": "誤: 「急務をなった」→ 正: 「急務となった」。「〜となる」は結果を「と」で示す。「を」は目的語の助詞なので「なる」とは続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38111, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病院で働く人が足りず、医師の確保が急務なになっている。", "corrected_sentence": "病院で働く人が足りず、医師の確保が急務になっている。", "error_description": "誤: 「急務なになっている」→ 正: 「急務になっている」。「な」は形容動詞に付く語で、名詞の急務には付けない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
