INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38114, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "書いたり読んだりするためにまとめられた、紙や電子データの束のこと。", "primary_collocate": null, "pronunciation": "ぶんしょ", "ipa": "bɯɲɕo", "syllable_count": 3, "sentences": [{"text": "机の上に、古い文書の束が置いてある。", "target_word": "文書", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に、古[ふる]い文書[ぶんしょ]の束[たば]が置[お]いてある。", "sentence_source": "generated"}, {"text": "必要な文書を、コピーしてファイルに入れた。", "target_word": "文書", "complexity_tier": "T3", "furigana": "必要[ひつよう]な文書[ぶんしょ]を、コピーしてファイルに入[い]れた。", "sentence_source": "generated"}, {"text": "電子の文書は、メールで送ることができる。", "target_word": "文書", "complexity_tier": "T3", "furigana": "電子[でんし]の文書[ぶんしょ]は、メールで送[おく]ることができる。", "sentence_source": "generated"}, {"text": "文書を保存する前に、名前をつけた。", "target_word": "文書", "complexity_tier": "T3", "furigana": "文書[ぶんしょ]を保存[ほぞん]する前[まえ]に、名前[なまえ]をつけた。", "sentence_source": "generated"}, {"text": "この文書は、紙のものと同じ内容だ。", "target_word": "文書", "complexity_tier": "T3", "furigana": "この文書[ぶんしょ]は、紙[かみ]のものと同[おな]じ内容[ないよう]だ。", "sentence_source": "generated"}, {"text": "図書館には、昔の文書がたくさん残っている。", "target_word": "文書", "complexity_tier": "T3", "furigana": "図書館[としょかん]には、昔[むかし]の文書[ぶんしょ]がたくさん残[のこ]っている。", "sentence_source": "generated"}, {"text": "間違えて文書を消してしまい、あわてた。", "target_word": "文書", "complexity_tier": "T3", "furigana": "間違[まちが]えて文書[ぶんしょ]を消[け]してしまい、あわてた。", "sentence_source": "generated"}, {"text": "文書の最後のページに、地図がついている。", "target_word": "文書", "complexity_tier": "T3", "furigana": "文書[ぶんしょ]の最後[さいご]のページに、地図[ちず]がついている。", "sentence_source": "generated"}, {"text": "文書をプリンターで印刷して、机に並べた。", "target_word": "文書", "complexity_tier": "T3", "furigana": "文書[ぶんしょ]をプリンターで印刷[いんさつ]して、机[つくえ]に並[なら]べた。", "sentence_source": "generated"}, {"text": "パソコンで文書を開くと、画面に文字が出た。", "target_word": "文書", "complexity_tier": "T3", "furigana": "パソコンで文書[ぶんしょ]を開[ひら]くと、画面[がめん]に文字[もじ]が出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "文書", "label": "基本形"}], "register": "標準", "sense_fingerprint": "紙や電子データとしてまとめられた書類・ファイル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38114, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文書", "is_correct": true, "explanation": "紙や電子の書類の束を指し、「古い」「束」「置いてある」に合う。"}, {"text": "時計", "is_correct": false, "explanation": "束にして置くものではないので、「古い時計の束」とは言わない。"}, {"text": "電話", "is_correct": false, "explanation": "束にして置いてあるものではないので、ここには入らない。"}, {"text": "鍋", "is_correct": false, "explanation": "束にする物ではないので、「古い鍋の束」とは言わない。"}], "explanations": {"文書": "紙や電子の書類の束を指し、「古い」「束」「置いてある」に合う。", "時計": "束にして置くものではないので、「古い時計の束」とは言わない。", "電話": "束にして置いてあるものではないので、ここには入らない。", "鍋": "束にする物ではないので、「古い鍋の束」とは言わない。"}, "sentence_index": 0, "correct_answer": "文書"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その小説は、文書がとても美しい。", "explanation": "ここは〈文章〉の意味。小説の書き方を言うには文章を使い、文書は書類を指すので合わない。"}, {"text": "毎晩、寝る前に文書をつけている。", "explanation": "ここは〈日記〉の意味。日記をつけるとは言うが、文書は書類なので日記には使わない。"}, {"text": "この文書の主語はどれですか。", "explanation": "ここは〈文〉の意味。文法の文の主語を尋ねる文だが、文書は書類なので文法の単位は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38114, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文書", "is_correct": true, "explanation": "消せる書類や電子データを指し、「間違えて消してしまう」に合う。"}, {"text": "季節", "is_correct": false, "explanation": "消せるものではないので、ここには入らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "消せるものではないので、「間違えて消す」とは言わない。"}, {"text": "空", "is_correct": false, "explanation": "消せるものではないので、ここには入らない。"}], "explanations": {"文書": "消せる書類や電子データを指し、「間違えて消してしまう」に合う。", "季節": "消せるものではないので、ここには入らない。", "夕焼け": "消せるものではないので、「間違えて消す」とは言わない。", "空": "消せるものではないので、ここには入らない。"}, "sentence_index": 6, "correct_answer": "文書"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員に文書を言った。", "explanation": "ここは〈文句〉の意味。文句は言うものだが、文書は言う対象にならない。"}, {"text": "試合の文書をつけた。", "explanation": "ここは〈記録〉の意味。試合の結果を書き残すことは記録をつけると言い、文書では言わない。"}, {"text": "事故のあと、近くの文書に届け出た。", "explanation": "ここは〈分署〉（警察の支所）の意味。同じ読みの「分署」を指す場面で、書類の「文書」は届け出る場所にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38114, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の上に、古い文書を束が積んである。", "corrected_sentence": "机の上に、古い文書の束が積んである。", "error_description": "「文書」と「束」は「文書の束」と「の」でつながる。「を」は目的を表すため誤り。正しくは「文書の束」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38114, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、文書を夜おそくまで描いた。", "corrected_sentence": "彼は、文書を夜おそくまで書いた。", "error_description": "文書は書くものなので、「描く」（絵を描く）は誤り。正しくは「書いた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
