INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38115, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "仕事や手続きなどで使う、正式に書かれた書類のこと。", "primary_collocate": null, "pronunciation": "ぶんしょ", "ipa": "bɯɲɕo", "syllable_count": 3, "sentences": [{"text": "会社に出す文書は、間違いがないように確認する。", "target_word": "文書", "complexity_tier": "T3", "furigana": "会社[かいしゃ]に出[だ]す文書[ぶんしょ]は、間違[まちが]いがないように確認[かくにん]する。", "sentence_source": "generated"}, {"text": "契約の内容は、文書で残しておくべきだ。", "target_word": "文書", "complexity_tier": "T3", "furigana": "契約[けいやく]の内容[ないよう]は、文書[ぶんしょ]で残[のこ]しておくべきだ。", "sentence_source": "generated"}, {"text": "役所から、正式な文書が届いた。", "target_word": "文書", "complexity_tier": "T3", "furigana": "役所[やくしょ]から、正式[せいしき]な文書[ぶんしょ]が届[とど]いた。", "sentence_source": "generated"}, {"text": "口で伝えるだけでなく、文書にして提出する決まりだ。", "target_word": "文書", "complexity_tier": "T3", "furigana": "口[くち]で伝[つた]えるだけでなく、文書[ぶんしょ]にして提出[ていしゅつ]する決[き]まりだ。", "sentence_source": "generated"}, {"text": "学校は、保護者に文書で連絡した。", "target_word": "文書", "complexity_tier": "T3", "furigana": "学校[がっこう]は、保護者[ほごしゃ]に文書[ぶんしょ]で連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "会議の内容を文書にまとめて、全員に配った。", "target_word": "文書", "complexity_tier": "T3", "furigana": "会議[かいぎ]の内容[ないよう]を文書[ぶんしょ]にまとめて、全員[ぜんいん]に配[くば]った。", "sentence_source": "generated"}, {"text": "古い文書を調べると、町の歴史がわかる。", "target_word": "文書", "complexity_tier": "T3", "furigana": "古[ふる]い文書[ぶんしょ]を調[しら]べると、町[まち]の歴史[れきし]がわかる。", "sentence_source": "generated"}, {"text": "重要な文書には、責任者の印が押してある。", "target_word": "文書", "complexity_tier": "T3", "furigana": "重要[じゅうよう]な文書[ぶんしょ]には、責任者[せきにんしゃ]の印[いん]が押[お]してある。", "sentence_source": "generated"}, {"text": "文書の書き方は、会社ごとに決まりがある。", "target_word": "文書", "complexity_tier": "T3", "furigana": "文書[ぶんしょ]の書[か]き方[かた]は、会社[かいしゃ]ごとに決[き]まりがある。", "sentence_source": "generated"}, {"text": "この文書がなければ、手続きは進められない。", "target_word": "文書", "complexity_tier": "T3", "furigana": "この文書[ぶんしょ]がなければ、手続[てつづ]きは進[すす]められない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "文書", "label": "基本形"}], "register": "標準", "sense_fingerprint": "仕事や手続きで使う、正式に書かれた書類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38115, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文書", "is_correct": true, "explanation": "会社に出す正式な書類を指し、「間違いがないように確認する」対象として合う。"}, {"text": "天気", "is_correct": false, "explanation": "会社に出すものではなく、確認する対象にもならない。"}, {"text": "旅行", "is_correct": false, "explanation": "会社に出すものではなく、確認する対象にもならない。"}, {"text": "雨", "is_correct": false, "explanation": "会社に出すものではなく、確認する対象にもならない。"}], "explanations": {"文書": "会社に出す正式な書類を指し、「間違いがないように確認する」対象として合う。", "天気": "会社に出すものではなく、確認する対象にもならない。", "旅行": "会社に出すものではなく、確認する対象にもならない。", "雨": "会社に出すものではなく、確認する対象にもならない。"}, "sentence_index": 0, "correct_answer": "文書"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作文の文書を直した。", "explanation": "ここは〈文章〉の意味。作文の内容は文章で、文書は正式な書類を指すので合わない。"}, {"text": "財布を落とし、近くの文書に届け出た。", "explanation": "ここは〈分署〉（警察の支所）の意味。同じ読みの「分署」を指す場面で、書類の「文書」は届け出る場所にはならないので合わない。"}, {"text": "店員に文書を言った。", "explanation": "ここは〈文句〉の意味。文句は言うものだが、文書は言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38115, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文書", "is_correct": true, "explanation": "正式に書かれた記録を指し、「古い」「調べると歴史がわかる」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "古いものとして調べて歴史がわかる対象ではない。"}, {"text": "雲", "is_correct": false, "explanation": "古いものとして調べて歴史がわかる対象ではない。"}, {"text": "空", "is_correct": false, "explanation": "古いものとして調べて歴史がわかる対象ではない。"}], "explanations": {"文書": "正式に書かれた記録を指し、「古い」「調べると歴史がわかる」に合う。", "天気": "古いものとして調べて歴史がわかる対象ではない。", "雲": "古いものとして調べて歴史がわかる対象ではない。", "空": "古いものとして調べて歴史がわかる対象ではない。"}, "sentence_index": 6, "correct_answer": "文書"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地域の文書を大切に育てている。", "explanation": "ここは〈文化〉の意味。文化は育てるものだが、文書は育てる対象ではない。"}, {"text": "会議の文書をつけた。", "explanation": "ここは〈記録〉の意味。会議の内容を書き残すことは記録をつけると言い、文書はつけるものではないので合わない。"}, {"text": "毎晩、文書をつけている。", "explanation": "ここは〈日記〉の意味。日記をつけるとは言うが、文書は個人の日々の出来事を書くものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38115, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "役所から、正式な文書に受け取った。", "corrected_sentence": "役所から、正式な文書を受け取った。", "error_description": "「受け取る」は受け取る物を「を」で示す。「に」は誤り。正しくは「文書を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38115, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の記録を文書に作曲した。", "corrected_sentence": "会議の記録を文書にまとめた。", "error_description": "「文書にまとめる」が正しい。「作曲する」は曲を作る意味で、文書とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38116, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『連鎖すると』で、連鎖が起きたときの結果を示す条件の接続。"}, {"text": "を", "is_correct": false, "explanation": "連鎖は目的語を取らないので、『を』は文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を表すので、『連鎖で』は文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は向かう先を表すので、連鎖という動きには続かない。"}], "correct_answer": "と", "explanations": {"と": "『連鎖すると』で、連鎖が起きたときの結果を示す条件の接続。", "を": "連鎖は目的語を取らないので、『を』は文に合わない。", "で": "『で』は手段や場所を表すので、『連鎖で』は文の流れに合わない。", "へ": "『へ』は向かう先を表すので、連鎖という動きには続かない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
