INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38116, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものが、まるで鎖のように、つながっていること。", "primary_collocate": null, "pronunciation": "れんさ", "ipa": "ɾeɴsa", "syllable_count": 3, "sentences": [{"text": "小さなミスが連鎖して、工場全体が止まってしまった。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "小[ちい]さなミスが連鎖[れんさ]して、工場[こうじょう]全体[ぜんたい]が止[と]まってしまった。", "sentence_source": "generated"}, {"text": "悪いニュースが連鎖すると、人々の不安は大きくなる。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "悪[わる]いニュースが連鎖[れんさ]すると、人々[ひとびと]の不安[ふあん]は大[おお]きくなる。", "sentence_source": "generated"}, {"text": "事故は連鎖を起こし、後ろの車も次々にぶつかった。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "事故[じこ]は連鎖[れんさ]を起[お]こし、後[うし]ろの車[くるま]も次々[つぎつぎ]にぶつかった。", "sentence_source": "generated"}, {"text": "この連鎖を止めないと、被害はもっと広がるだろう。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "この連鎖[れんさ]を止[と]めないと、被害[ひがい]はもっと広[ひろ]がるだろう。", "sentence_source": "generated"}, {"text": "森では、植物を虫が食べ、その虫を鳥が食べるという連鎖が続いている。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "森では、植物を虫が食べ、その虫を鳥が食べるという連鎖[れんさ]が続いている。", "sentence_source": "generated"}, {"text": "笑いが連鎖して、教室中が明るい雰囲気になった。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "笑[わら]いが連鎖[れんさ]して、教室[きょうしつ]中[じゅう]が明[あか]るい雰囲気[ふんいき]になった。", "sentence_source": "generated"}, {"text": "倒産の連鎖を防ぐために、政府は銀行を支援した。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "倒産[とうさん]の連鎖[れんさ]を防[ふせ]ぐために、政府[せいふ]は銀行[ぎんこう]を支援[しえん]した。", "sentence_source": "generated"}, {"text": "大雨のあとに土砂崩れが起き、災害が連鎖した。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあとに土砂崩[どしゃくず]れが起[お]き、災害[さいがい]が連鎖[れんさ]した。", "sentence_source": "generated"}, {"text": "一人が拍手を始めると、拍手が連鎖して会場全体に広がった。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "一人[ひとり]が拍手[はくしゅ]を始[はじ]めると、拍手[はくしゅ]が連鎖[れんさ]して会場[かいじょう]全体[ぜんたい]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "悪い習慣の連鎖を、自分の代で終わらせたい。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "悪[わる]い習慣[しゅうかん]の連鎖[れんさ]を、自分[じぶん]の代[だい]で終[お]わらせたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連鎖", "label": "基本形"}, {"form": "連鎖する", "label": "サ変動詞"}, {"form": "連鎖して", "label": "テ形"}, {"form": "連鎖した", "label": "過去形"}], "register": "中立（常体）", "sense_fingerprint": "物事が鎖のように次々につながって起きること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38116, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "ものが次々とつながって起きる流れを表し、文の内容に合う。"}, {"text": "点検", "is_correct": false, "explanation": "点検は確かめる行為で、ミスが次々起きる流れを表さないので合わない。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定を遅らせることで、ミスが広がった原因の説明にならない。"}, {"text": "解決", "is_correct": false, "explanation": "解決すれば止まらないはずなので、工場全体が止まったという結果と矛盾する。"}], "explanations": {"連鎖": "ものが次々とつながって起きる流れを表し、文の内容に合う。", "点検": "点検は確かめる行為で、ミスが次々起きる流れを表さないので合わない。", "延期": "延期は予定を遅らせることで、ミスが広がった原因の説明にならない。", "解決": "解決すれば止まらないはずなので、工場全体が止まったという結果と矛盾する。"}, "sentence_index": 0, "correct_answer": "連鎖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三日連鎖で遅刻した。", "explanation": "ここは〈連続〉の意味。連鎖は一つが次を引き起こすようにつながる流れを指すので、ただ日が続く場合には使わない。"}, {"text": "この漫画は週刊誌で五年連鎖されている。", "explanation": "ここは〈連載〉の意味。連鎖は出来事が次々とつながる流れを指し、雑誌への掲載には使わない。"}, {"text": "同じ練習を何度も連鎖させて、技を身につける。", "explanation": "ここは〈反復〉の意味。連鎖は別々のものが次々つながることで、同じことを繰り返す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38116, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "倒産が次々と連なって広がる流れを指し、防ぐ対象に合う。"}, {"text": "解消", "is_correct": false, "explanation": "解消は問題を取り除くことで、防ぐ対象にはならない。"}, {"text": "譲渡", "is_correct": false, "explanation": "譲渡は権利や物を渡すことで、倒産を防ぐ対象ではない。"}, {"text": "実施", "is_correct": false, "explanation": "実施は行うことで、防ぐ対象として不自然。"}], "explanations": {"連鎖": "倒産が次々と連なって広がる流れを指し、防ぐ対象に合う。", "解消": "解消は問題を取り除くことで、防ぐ対象にはならない。", "譲渡": "譲渡は権利や物を渡すことで、倒産を防ぐ対象ではない。", "実施": "実施は行うことで、防ぐ対象として不自然。"}, "sentence_index": 6, "correct_answer": "連鎖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三つの部署が連鎖して、新商品を開発した。", "explanation": "ここは〈連携〉の意味。連鎖は前の出来事が次の出来事を引き起こす流れを指すので、部署同士が協力して働く場合には使わない。"}, {"text": "二つの歯車が連鎖して、同時に回る。", "explanation": "ここは〈連動〉の意味。歯車が噛み合って一緒に回ることは連動で、連鎖は一つずつ次へ引き継ぐ流れなので合わない。"}, {"text": "車両が連鎖して、一本の列車になった。", "explanation": "ここは〈連結〉の意味。連鎖は前から次へ続く流れを指すので、車両を物理的につなぐ場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38116, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ひとつの故障が連鎖に、生産ライン全体が止まった。", "corrected_sentence": "ひとつの故障が連鎖して、生産ライン全体が止まった。", "error_description": "連鎖は『連鎖して』の形で文をつなぐ。『して』を『に』にすると形が合わず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38116, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "借金の連鎖へ抜け出すため、家計の見直しを始めた。", "corrected_sentence": "借金の連鎖から抜け出すため、家計の見直しを始めた。", "error_description": "『抜け出す』は出どころを『から』で示す。『へ』は移動先を表すので、『連鎖へ』では意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
