INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38118, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「どのように」という意味で、何かをする方法や様子をたずねるときに使う言葉です。", "primary_collocate": null, "pronunciation": "いかに", "ipa": "ikani", "syllable_count": 3, "sentences": [{"text": "彼女は如何に努力を重ねて試験を乗り越えたのかを、私たちに話してくれた。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は如何(いか)に努力(どりょく)を重(かさ)ねて試験(しけん)を乗(の)り越(こ)えたのかを、私(わたし)たちに話(はな)してくれた。", "sentence_source": "generated"}, {"text": "如何にして試験に合格したのか、彼女は笑って教えてくれた。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "如何(いか)にして試験(しけん)に合格(ごうかく)したのか、彼女(かのじょ)は笑(わら)って教(おし)えてくれた。", "sentence_source": "generated"}, {"text": "この写真は、昔の人々が如何に町を守ってきたかを物語っている。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "この写真(しゃしん)は、昔(むかし)の人々(ひとびと)が如何(いか)に町(まち)を守(まも)ってきたかを物語(ものがた)っている。", "sentence_source": "generated"}, {"text": "彼は仲間を如何に励ましたかを、手紙に書いた。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "彼(かれ)は仲間(なかま)を如何(いか)に励(はげ)ましたかを、手紙(てがみ)に書(か)いた。", "sentence_source": "generated"}, {"text": "如何に生きるべきかという問いは、人類の大きなテーマだ。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "如何(いか)に生(い)きるべきかという問(と)いは、人類(じんるい)の大(おお)きなテーマだ。", "sentence_source": "generated"}, {"text": "先生は、健康を如何に守るかを生徒に説明した。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "先生(せんせい)は、健康(けんこう)を如何(いか)に守(まも)るかを生徒(せいと)に説明(せつめい)した。", "sentence_source": "generated"}, {"text": "町の人たちは、ごみを如何に減らすかを真剣に話し合った。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "町(まち)の人(ひと)たちは、ごみを如何(いか)に減(へ)らすかを真剣(しんけん)に話(はな)し合(あ)った。", "sentence_source": "generated"}, {"text": "事故のとき、彼が如何に落ち着いて行動したかを皆が話した。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "事故(じこ)のとき、彼(かれ)が如何(いか)に落(お)ち着(つ)いて行動(こうどう)したかを皆(みな)が話(はな)した。", "sentence_source": "generated"}, {"text": "この本を読むと、昔の人が如何に水を確保していたかがわかる。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "この本(ほん)を読(よ)むと、昔(むかし)の人(ひと)が如何(いか)に水(みず)を確保(かくほ)していたかがわかる。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、この仕事を如何に進めるべきかがよくわかった。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)を聞(き)いて、この仕事(しごと)を如何(いか)に進(すす)めるべきかがよくわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "如何に", "label": "副詞形"}, {"form": "如何にして", "label": "連語（方法を問う）"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "副詞「どのように」。如何に〜か、如何にして〜の形で方法や程度を問う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38118, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如何に", "is_correct": true, "explanation": "「どのように」の意味で、努力の仕方を問う「〜かを」の文に合う。"}, {"text": "ふと", "is_correct": false, "explanation": "「思いがけず」の意味。努力の方法を述べる文には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "「決して〜ない」と否定と呼応する語で、肯定の文には使えない。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで〜ようだ」と比喩の形に呼応する語で、そのままでは文が成り立たない。"}], "explanations": {"如何に": "「どのように」の意味で、努力の仕方を問う「〜かを」の文に合う。", "ふと": "「思いがけず」の意味。努力の方法を述べる文には合わない。", "決して": "「決して〜ない」と否定と呼応する語で、肯定の文には使えない。", "まるで": "「まるで〜ようだ」と比喩の形に呼応する語で、そのままでは文が成り立たない。"}, "sentence_index": 0, "correct_answer": "如何に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如何に三時に駅に着いた。", "explanation": "ここは〈ちょうど〉（ぴったりその時刻）の意味。如何には方法や様子を問う語で、時刻をぴったり示す文には使えない。"}, {"text": "如何に長年の夢がかなった。", "explanation": "ここは〈ついに〉（とうとう）の意味。如何には方法や様子を問う語で、ついに結果に至ったことを述べる文には使えない。"}, {"text": "如何に約束は守る。", "explanation": "ここは〈必ず〉（きっと）の意味。如何には方法を問う語で、決意を言い切る文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38118, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如何に", "is_correct": true, "explanation": "「どのように」の意味で、ごみを減らす方法を問う文に合う。"}, {"text": "あいにく", "is_correct": false, "explanation": "「残念ながら」の意味。方法を問う文には合わない。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも〜ない」と否定と呼応する語で、肯定の文には使えない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "「ぜひ〜したい」と願望と呼応する語で、「〜かを話し合った」の形には合わない。"}], "explanations": {"如何に": "「どのように」の意味で、ごみを減らす方法を問う文に合う。", "あいにく": "「残念ながら」の意味。方法を問う文には合わない。", "必ずしも": "「必ずしも〜ない」と否定と呼応する語で、肯定の文には使えない。", "ぜひ": "「ぜひ〜したい」と願望と呼応する語で、「〜かを話し合った」の形には合わない。"}, "sentence_index": 6, "correct_answer": "如何に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如何に昔の友人に会った。", "explanation": "ここは〈偶然〉（思いがけず）の意味。如何には方法を問う語で、偶然の出来事を述べる文には使えない。"}, {"text": "結局、如何に雨は降らなかった。", "explanation": "ここは〈結局〉（最終的に）の意味。如何には方法を問う語で、最終的な結果を述べる文には使えない。"}, {"text": "もちろん、如何に彼は賛成した。", "explanation": "ここは〈もちろん〉（当然）の意味。如何には方法を問う語で、当然のことを述べる文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38118, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、この薬の効果を如何で確かめたかを発表した。", "corrected_sentence": "研究者は、この薬の効果を如何に確かめたかを発表した。", "error_description": "誤: 「如何で」→ 正: 「如何に」。「如何に（どのように）」は副詞なので「に」で終わる。「で」では副詞として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38118, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校では、ごみを如何な減らすかを真剣に話し合った。", "corrected_sentence": "学校では、ごみを如何に減らすかを真剣に話し合った。", "error_description": "誤: 「如何な減らす」→ 正: 「如何に減らす」。「如何な」は連体詞で名詞を修飾する形。動詞「減らす」を修飾するには副詞の「如何に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」で、直感によって使い方がわかるという文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "「直感を使い方がわかる」となり、わかる手段として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「直感に使い方がわかる」となり、手段を示す形にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、手段として使い方がわかることにつながらない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」で、直感によって使い方がわかるという文意に合う。", "を": "「直感を使い方がわかる」となり、わかる手段として成り立たない。", "に": "「直感に使い方がわかる」となり、手段を示す形にならず不自然。", "へ": "方向を表す「へ」では、手段として使い方がわかることにつながらない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「直感で選んだ」は手段を表し、直感によって服を選んだという文意に合う。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、直感と比べて選んだという別の意味になり、文の意味が変わる。"}, {"text": "を", "is_correct": false, "explanation": "「直感を選んだ服」は直感を選ぶ対象になり、手段の文意に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では、選ぶ相手や手段にならず文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「直感で選んだ」は手段を表し、直感によって服を選んだという文意に合う。", "より": "比較の「より」では、直感と比べて選んだという別の意味になり、文の意味が変わる。", "を": "「直感を選んだ服」は直感を選ぶ対象になり、手段の文意に合わない。", "へ": "方向の「へ」では、選ぶ相手や手段にならず文が成り立たない。"}, "error_tags": {"より": "比較", "と": "並列", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを見たり聞いたりしたときに、考えなくてもすぐにわかること。", "primary_collocate": null, "pronunciation": "ちょっかん", "ipa": "tɕokkaɴ", "syllable_count": 4, "sentences": [{"text": "その絵を見た瞬間、直感で作者の悲しみが伝わってきた。", "target_word": "直感", "complexity_tier": "T3", "furigana": "その絵[え]を見[み]た瞬間[しゅんかん]、直感[ちょっかん]で作者[さくしゃ]の悲[かな]しみが伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "この商品は、直感で使い方がわかるように作られている。", "target_word": "直感", "complexity_tier": "T3", "furigana": "この商品[しょうひん]は、直感[ちょっかん]で使[つか]い方[かた]がわかるように作[つく]られている。", "sentence_source": "generated"}, {"text": "店に入ったとき、直感で「ここは当たりだ」と思った。", "target_word": "直感", "complexity_tier": "T3", "furigana": "店[みせ]に入[はい]ったとき、直感[ちょっかん]で「ここは当[あ]たりだ」と思[おも]った。", "sentence_source": "generated"}, {"text": "子どもは、大人の怒った声を聞くと直感で危険を感じる。", "target_word": "直感", "complexity_tier": "T3", "furigana": "子[こ]どもは、大人[おとな]の怒[おこ]った声[こえ]を聞[き]くと直感[ちょっかん]で危険[きけん]を感[かん]じる。", "sentence_source": "generated"}, {"text": "説明書を読まなくても、直感で操作できるアプリが人気だ。", "target_word": "直感", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]まなくても、直感[ちょっかん]で操作[そうさ]できるアプリが人気[にんき]だ。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、直感でうそだとわかった。", "target_word": "直感", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]を聞[き]いて、直感[ちょっかん]でうそだとわかった。", "sentence_source": "generated"}, {"text": "地図を見て、直感で近道だと気づいた。", "target_word": "直感", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]て、直感[ちょっかん]で近道[ちかみち]だと気[き]づいた。", "sentence_source": "generated"}, {"text": "直感で選んだ服が、意外にもよく似合っていた。", "target_word": "直感", "complexity_tier": "T3", "furigana": "直感[ちょっかん]で選[えら]んだ服[ふく]が、意外[いがい]にもよく似合[にあ]っていた。", "sentence_source": "generated"}, {"text": "彼女の表情を見て、直感で何かあったとすぐに察した。", "target_word": "直感", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の表情[ひょうじょう]を見[み]て、直感[ちょっかん]で何[なに]かあったとすぐに察[さっ]した。", "sentence_source": "generated"}, {"text": "このデザインは、直感で美しいと感じられるものだ。", "target_word": "直感", "complexity_tier": "T3", "furigana": "このデザインは、直感[ちょっかん]で美[うつく]しいと感[かん]じられるものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直感", "label": "基本形"}, {"form": "直感で", "label": "手段・格助詞つき"}], "register": "中立", "sense_fingerprint": "見聞きした瞬間に、考えずにすぐ悟ること(直感でわかる・直感で感じる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直感", "is_correct": true, "explanation": "見た瞬間にすぐ伝わるという文意に合う、感じ取る手段を表す語。"}, {"text": "鉄骨", "is_correct": false, "explanation": "建築資材で、絵を見て悲しみが伝わる手段にはならない。"}, {"text": "配線", "is_correct": false, "explanation": "電気の線を指し、作者の悲しみを伝える手段として意味が通らない。"}, {"text": "祝日", "is_correct": false, "explanation": "日付の区分で、絵から感情が伝わる手段とは言えない。"}], "explanations": {"直感": "見た瞬間にすぐ伝わるという文意に合う、感じ取る手段を表す語。", "鉄骨": "建築資材で、絵を見て悲しみが伝わる手段にはならない。", "配線": "電気の線を指し、作者の悲しみを伝える手段として意味が通らない。", "祝日": "日付の区分で、絵から感情が伝わる手段とは言えない。"}, "sentence_index": 0, "correct_answer": "直感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "証拠を集めて、じっくり直感を組み立てた。", "explanation": "ここは〈推理〉の意味。直感は考えずにすぐわかるものなので、組み立てて作るものではない。"}, {"text": "いくら考えても、彼の行き先は直感がつかない。", "explanation": "ここは〈見当〉の意味。〈見当がつく〉は推し量って見当をつけることで、直感は考えずに分かることなので、〈つかない〉とは合わない。"}, {"text": "週末の直感を立てるのに、一時間かけた。", "explanation": "ここは〈計画〉の意味。直感は立てて組むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直感", "is_correct": true, "explanation": "地図を見て近道に気づいた手段として、考えずに感じ取る語で文意に合う。"}, {"text": "段差", "is_correct": false, "explanation": "地面の高低差を指し、近道に気づく手段にはならない。"}, {"text": "卒業", "is_correct": false, "explanation": "学校を終える出来事で、地図から近道に気づく手段として意味が通らない。"}, {"text": "帽子", "is_correct": false, "explanation": "身につける物で、地図を見て近道に気づく手段とは言えない。"}], "explanations": {"直感": "地図を見て近道に気づいた手段として、考えずに感じ取る語で文意に合う。", "段差": "地面の高低差を指し、近道に気づく手段にはならない。", "卒業": "学校を終える出来事で、地図から近道に気づく手段として意味が通らない。", "帽子": "身につける物で、地図を見て近道に気づく手段とは言えない。"}, "sentence_index": 6, "correct_answer": "直感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔の直感がよみがえり、胸が熱くなった。", "explanation": "ここは〈思い出〉の意味。直感は過去を思い出す語ではなく、その場で感じ取るものなので合わない。"}, {"text": "その話を聞いて、直感がこみ上げて涙が出た。", "explanation": "ここは〈感情〉の意味。こみ上げるのは感情の方で、直感は考えずに分かることを指すので、涙とともに込み上げるとは言えない。"}, {"text": "窓辺で直感にふけり、長い時間ぼんやりしていた。", "explanation": "ここは〈感慨〉の意味。直感は心にしみて浸る対象ではないので、ふけるとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの音を聞いた瞬間、直感を母が帰ってきたとわかった。", "corrected_sentence": "ドアの音を聞いた瞬間、直感で母が帰ってきたとわかった。", "error_description": "「直感で〜とわかる」は手段を表す「で」を使う。「を」は直感を目的語にする形で、わかる手段にならないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38120, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "合図を聞いて、直感で危険を数えた。", "corrected_sentence": "合図を聞いて、直感で危険を察した。", "error_description": "「直感で危険を察する」が自然な組み合わせ。「数える」は数量を数える動詞で、直感でわかった内容には合わないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「直感で」は手段・よりどころを表し、直感を根拠に信じたという文意に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」なので、直感を根拠に思った内容とはつながらず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は修飾を表すため、直感を文の手段として示す形にならず文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すため、直感を根拠とする文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "「直感で」は手段・よりどころを表し、直感を根拠に信じたという文意に合う。", "へ": "方向を表す「へ」なので、直感を根拠に思った内容とはつながらず不自然。", "の": "「の」は修飾を表すため、直感を文の手段として示す形にならず文が崩れる。", "と": "「と」は並列や相手を表すため、直感を根拠とする文脈に合わない。"}, "error_tags": {"へ": "方向", "の": "修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「母の直感は」と主題を示す形で、直感の鋭さを述べる文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」だと「直感を鋭くて」となり、述語の鋭いと結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表す「に」だと「直感に鋭くて」となり、文の骨組みが崩れる。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」だと「直感で鋭くて」となり、直感の性質を述べる文にならない。"}], "correct_answer": "は", "explanations": {"は": "「母の直感は」と主題を示す形で、直感の鋭さを述べる文に合う。", "を": "目的語を表す「を」だと「直感を鋭くて」となり、述語の鋭いと結びつかない。", "に": "方向や相手を表す「に」だと「直感に鋭くて」となり、文の骨組みが崩れる。", "で": "手段を表す「で」だと「直感で鋭くて」となり、直感の性質を述べる文にならない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "論理や分析を介さずに、物事を直接的に感じ取る心のはたらき。", "primary_collocate": null, "pronunciation": "ちょっかん", "ipa": "tɕokkaɴ", "syllable_count": 4, "sentences": [{"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "直感", "complexity_tier": "T4", "furigana": "デザイナーの直感[ちょっかん]に頼[たよ]るのではなく、計算[けいさん]された論理[ろんり]によって、機能的[きのうてき]かつ独創的[どくそうてき]な都市空間[としくうかん]を創出[そうしゅつ]することが目指[めざ]されています。", "sentence_source": "mined"}, {"text": "彼女は直感で、この人は信じられると思った。", "target_word": "直感", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は直感[ちょっかん]で、この人[ひと]は信[しん]じられると思[おも]った。", "sentence_source": "generated"}, {"text": "直感を信じて選んだ道が、結果的に正しかった。", "target_word": "直感", "complexity_tier": "T3", "furigana": "直感[ちょっかん]を信[しん]じて選[えら]んだ道[みち]が、結果的[けっかてき]に正[ただ]しかった。", "sentence_source": "generated"}, {"text": "論理的に考えると不利だったが、直感に従ってこの会社に入った。", "target_word": "直感", "complexity_tier": "T3", "furigana": "論理的[ろんりてき]に考[かんが]えると不利[ふり]だったが、直感[ちょっかん]に従[したが]ってこの会社[かいしゃ]に入[はい]った。", "sentence_source": "generated"}, {"text": "長年の経験があるので、彼の直感はよく当たる。", "target_word": "直感", "complexity_tier": "T3", "furigana": "長年[ながねん]の経験[けいけん]があるので、彼[かれ]の直感[ちょっかん]はよく当[あ]たる。", "sentence_source": "generated"}, {"text": "初めて会った瞬間、直感でこの人とは気が合うと感じた。", "target_word": "直感", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]った瞬間[しゅんかん]、直感[ちょっかん]でこの人[ひと]とは気[き]が合[あ]うと感[かん]じた。", "sentence_source": "generated"}, {"text": "直感だけで決めずに、データも確かめてから判断しよう。", "target_word": "直感", "complexity_tier": "T3", "furigana": "直感[ちょっかん]だけで決[き]めずに、データも確[たし]かめてから判断[はんだん]しよう。", "sentence_source": "generated"}, {"text": "母の直感は鋭くて、私がうそをつくとすぐに見抜かれる。", "target_word": "直感", "complexity_tier": "T3", "furigana": "母[はは]の直感[ちょっかん]は鋭[するど]くて、私[わたし]がうそをつくとすぐに見抜[みぬ]かれる。", "sentence_source": "generated"}, {"text": "難しい試験でも、直感で選んだ答えが正解のことが多い。", "target_word": "直感", "complexity_tier": "T3", "furigana": "難[むずか]しい試験[しけん]でも、直感[ちょっかん]で選[えら]んだ答[こた]えが正解[せいかい]のことが多[おお]い。", "sentence_source": "generated"}, {"text": "彼は直感に頼りすぎて、計画を立てるのが苦手だ。", "target_word": "直感", "complexity_tier": "T3", "furigana": "彼[かれ]は直感[ちょっかん]に頼[たよ]りすぎて、計画[けいかく]を立[た]てるのが苦手[にがて]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直感", "label": "基本形"}, {"form": "直感で", "label": "手段・格助詞つき"}], "register": "中立", "sense_fingerprint": "理屈や分析を使わず、判断や選択の拠り所になる心の感じ(直感に頼る・直感を信じる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直感", "is_correct": true, "explanation": "論理を介さずに感じ取る心のはたらきで、デザイナーが頼るものとして文意が通る。"}, {"text": "都市空間", "is_correct": false, "explanation": "創り出される対象であり、人が頼るものにはならないので文が成り立たない。"}, {"text": "創出", "is_correct": false, "explanation": "作り出す行為を表す語で、頼る対象にはならない。"}, {"text": "祝日", "is_correct": false, "explanation": "日付の区分で、デザイナーが頼る対象としては意味が通らない。"}], "explanations": {"直感": "論理を介さずに感じ取る心のはたらきで、デザイナーが頼るものとして文意が通る。", "都市空間": "創り出される対象であり、人が頼るものにはならないので文が成り立たない。", "創出": "作り出す行為を表す語で、頼る対象にはならない。", "祝日": "日付の区分で、デザイナーが頼る対象としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "直感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "足の裏の直感が鈍くなった。", "explanation": "ここは〈感覚〉の意味。直感は論理を介さずに物事を感じ取る心のはたらきで、体の感覚は指さないので合わない。"}, {"text": "彼は直感を並べて、チームを説得した。", "explanation": "ここは〈理屈〉の意味。直感は理由として並べて示せるものではないので、理屈の代わりにはならない。"}, {"text": "警察は直感をたくさん集めて、犯人を特定した。", "explanation": "ここは〈証拠〉の意味。直感は集めて積み上げる材料ではないので、証拠の代わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直感", "is_correct": true, "explanation": "直感だけで判断を決めないという文意に合う語で、ここでの判断材料として自然。"}, {"text": "祝日", "is_correct": false, "explanation": "判断の根拠として「祝日だけで決める」とは言えず、文が成り立たない。"}, {"text": "卒業", "is_correct": false, "explanation": "出来事を表す語で、判断を決める根拠としての「だけで決める」に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "物質名で、判断を決めるための根拠としては意味が通らない。"}], "explanations": {"直感": "直感だけで判断を決めないという文意に合う語で、ここでの判断材料として自然。", "祝日": "判断の根拠として「祝日だけで決める」とは言えず、文が成り立たない。", "卒業": "出来事を表す語で、判断を決める根拠としての「だけで決める」に合わない。", "砂糖": "物質名で、判断を決めるための根拠としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "直感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔の直感がよみがえり、懐かしくなった。", "explanation": "ここは〈記憶〉の意味。直感は過去を思い出す語ではなく、その場で感じ取るものなので合わない。"}, {"text": "その話を聞いて、直感が高ぶって涙が出た。", "explanation": "ここは〈感情〉の意味。直感は感情のように高ぶるものではないので合わない。"}, {"text": "彼は直感にふけって、一日じゅう夢を見ていた。", "explanation": "ここは〈空想〉の意味。直感は心の中で思い描くものではなく、ふける対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は直感を従って、すぐに決めた。", "corrected_sentence": "彼は直感に従って、すぐに決めた。", "error_description": "「従う」は「〜に従う」の形で助詞「に」を取る。直感に「を」を付けたのは誤りで、正しくは「直感に従って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38121, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直感が使って、危険を避けられた。", "corrected_sentence": "直感が働いて、危険を避けられた。", "error_description": "直感が主語のとき、述語は「働く」を使う。「使う」は人や道具を主語にする動詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "「作り方に追究している」は成り立たない。「追究する」は目的語に「を」を取る。"}, {"text": "を", "is_correct": true, "explanation": "「作り方を追究している」の「を」。追究する対象（目的語）を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「作り方へ追究している」は方向を表すが、追究の対象は示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」で、ここでは文が成り立たない。"}], "correct_answer": "を", "explanations": {"に": "「作り方に追究している」は成り立たない。「追究する」は目的語に「を」を取る。", "を": "「作り方を追究している」の「を」。追究する対象（目的語）を示す。", "へ": "「作り方へ追究している」は方向を表すが、追究の対象は示せず不自然。", "と": "相手や並列を示す「と」で、ここでは文が成り立たない。"}, "error_tags": {"に": "相手・方向", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "主語を示す「が」だが、「続ける」は他動詞なので目的語を示す「を」が必要。"}, {"text": "を", "is_correct": true, "explanation": "「追究を続けている」の「を」。続ける対象（目的語）を示す。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ「の」で、動詞「続けている」の目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、ここでは比べる文にならない。"}], "correct_answer": "を", "explanations": {"が": "主語を示す「が」だが、「続ける」は他動詞なので目的語を示す「を」が必要。", "を": "「追究を続けている」の「を」。続ける対象（目的語）を示す。", "の": "名詞をつなぐ「の」で、動詞「続けている」の目的語にはならない。", "より": "比較の「より」で、ここでは比べる文にならない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを深く考えて、正しい答えや方法を見つけようとすること。", "primary_collocate": null, "pronunciation": "ついきゅう", "ipa": "tsɯikʲɯː", "syllable_count": 4, "sentences": [{"text": "科学者は、真理の追究に一生をささげた。", "target_word": "追究", "complexity_tier": "T3", "furigana": "科学者(かがくしゃ)は、真理(しんり)の追究(ついきゅう)に一生(いっしょう)をささげた。", "sentence_source": "generated"}, {"text": "彼は、おいしいパンの作り方を追究している。", "target_word": "追究", "complexity_tier": "T3", "furigana": "彼(かれ)は、おいしいパンの作(つく)り方(かた)を追究(ついきゅう)している。", "sentence_source": "generated"}, {"text": "事故の原因を追究するために、専門家が集まった。", "target_word": "追究", "complexity_tier": "T3", "furigana": "事故(じこ)の原因(げんいん)を追究(ついきゅう)するために、専門家(せんもんか)が集(あつ)まった。", "sentence_source": "generated"}, {"text": "長い時間をかけて追究した結果、ようやく正しい方法が見つかった。", "target_word": "追究", "complexity_tier": "T3", "furigana": "長(なが)い時間(じかん)をかけて追究(ついきゅう)した結果(けっか)、ようやく正(ただ)しい方法(ほうほう)が見(み)つかった。", "sentence_source": "generated"}, {"text": "美しい音を追究する職人が、毎日楽器を作っている。", "target_word": "追究", "complexity_tier": "T3", "furigana": "美(うつく)しい音(おと)を追究(ついきゅう)する職人(しょくにん)が、毎日(まいにち)楽器(がっき)を作(つく)っている。", "sentence_source": "generated"}, {"text": "先生は、答えを追究する姿勢が大切だと話した。", "target_word": "追究", "complexity_tier": "T3", "furigana": "先生(せんせい)は、答(こた)えを追究(ついきゅう)する姿勢(しせい)が大切(たいせつ)だと話(はな)した。", "sentence_source": "generated"}, {"text": "自分に合う勉強法を追究して、成績が上がった。", "target_word": "追究", "complexity_tier": "T3", "furigana": "自分(じぶん)に合(あ)う勉強法(べんきょうほう)を追究(ついきゅう)して、成績(せいせき)が上(あ)がった。", "sentence_source": "generated"}, {"text": "彼女は、安全な薬の追究を続けている。", "target_word": "追究", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は、安全(あんぜん)な薬(くすり)の追究(ついきゅう)を続(つづ)けている。", "sentence_source": "generated"}, {"text": "答えが出ないからといって、追究をやめてはいけない。", "target_word": "追究", "complexity_tier": "T3", "furigana": "答(こた)えが出(で)ないからといって、追究(ついきゅう)をやめてはいけない。", "sentence_source": "generated"}, {"text": "研究者たちは、病気を防ぐ方法を追究している。", "target_word": "追究", "complexity_tier": "T3", "furigana": "研究者(けんきゅうしゃ)たちは、病気(びょうき)を防(ふせ)ぐ方法(ほうほう)を追究(ついきゅう)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "追究", "label": "名詞形"}, {"form": "追究する", "label": "サ変動詞・辞書形"}, {"form": "追究した", "label": "過去形"}, {"form": "追究している", "label": "継続形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "動作名詞。正しい答え・真理・方法・原因を深く考えて見つけようとすること（追求・追及とは別語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "「真理を深く考えて見つけようとすること」の意味で、一生をささげる対象に合う。"}, {"text": "献上", "is_correct": false, "explanation": "目上の人に物を差し上げること。「真理の献上」は文として成り立たない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作ること。真理は作るものではないので合わない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売ること。真理を売ることはないので合わない。"}], "explanations": {"追究": "「真理を深く考えて見つけようとすること」の意味で、一生をささげる対象に合う。", "献上": "目上の人に物を差し上げること。「真理の献上」は文として成り立たない。", "製造": "物を作ること。真理は作るものではないので合わない。", "販売": "商品を売ること。真理を売ることはないので合わない。"}, "sentence_index": 0, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "畑に来たシカを追究した。", "explanation": "ここは〈追い払う〉（追い出す）の意味。追究は深く考えて答えを見つける意味で、動物を追い払う場面には使わない。"}, {"text": "注文に、ミルクを追究した。", "explanation": "ここは〈追加〉（後から加える）の意味。追究は真理や原因を深く探る意味なので、注文に物を加える場面では使わない。"}, {"text": "故人を追究する式が行われた。", "explanation": "ここは〈追悼〉（死者をしのぶこと）の意味。追究は原因や真理を探る意味で、故人をしのぶ式には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "「深く考えて答えを見つけようとすること」の意味で、勉強法を探る文に合う。"}, {"text": "収穫", "is_correct": false, "explanation": "作物を取り入れること。勉強法には合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "地中から鉱物を掘り出すこと。文として成り立たない。"}, {"text": "払拭", "is_correct": false, "explanation": "不安や疑いを取り除くこと。「勉強法を払拭して」は意味が通らない。"}], "explanations": {"追究": "「深く考えて答えを見つけようとすること」の意味で、勉強法を探る文に合う。", "収穫": "作物を取り入れること。勉強法には合わない。", "採掘": "地中から鉱物を掘り出すこと。文として成り立たない。", "払拭": "不安や疑いを取り除くこと。「勉強法を払拭して」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レポートの最後に、注意書きを追究した。", "explanation": "ここは〈追記〉（後から書き加える）の意味。追究は原因や真理を深く探る意味で、文書に書き加える場面では使わない。"}, {"text": "前の車を追究して、先に出た。", "explanation": "ここは〈追い越す〉（前の車を抜く）の意味。追い越すは前の車を抜いて先に出ることを指すが、追究は真理や原因を探る意味なので、車を抜く場面には使わない。"}, {"text": "猟師がシカの足跡を追究した。", "explanation": "ここは〈追跡〉（跡をたどって追いかける）の意味。追究は深く探る意味で、足跡を追いかける場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、真理の追究で一生をささげた。", "corrected_sentence": "研究者は、真理の追究に一生をささげた。", "error_description": "誤: 「追究で」→ 正: 「追究に」。「ささげる」は「〜に〜をささげる」の形で、対象を「に」で示す。「で」は手段・場所を示すので、ここでは成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38122, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自分に合う練習法を追究、成績が上がった。", "corrected_sentence": "自分に合う練習法を追究して、成績が上がった。", "error_description": "誤: 「追究、」→ 正: 「追究して、」。「追究」は名詞なので、文の中で動詞として働かせるには「して」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「追究には」で、〜を行うためには、という前提や条件を表す。"}, {"text": "を", "is_correct": false, "explanation": "「追究を」は目的語を示す形で、「まだ時間が必要だ」と続くと文の骨格が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "「追究がは」と主格の「が」に「は」が続かず、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「追究の」は連体修飾で、後ろに修飾される名詞がなく文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「追究には」で、〜を行うためには、という前提や条件を表す。", "を": "「追究を」は目的語を示す形で、「まだ時間が必要だ」と続くと文の骨格が崩れる。", "が": "「追究がは」と主格の「が」に「は」が続かず、文として成り立たない。", "の": "「追究の」は連体修飾で、後ろに修飾される名詞がなく文が成り立たない。"}, "error_tags": {"に": "条件・前提", "を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある問題や課題について、深く考えたり探求したりすること。", "primary_collocate": null, "pronunciation": "ついきゅう", "ipa": "tsɯikʲɯː", "syllable_count": 4, "sentences": [{"text": "学生たちは、環境問題を深く追究して発表した。", "target_word": "追究", "complexity_tier": "T3", "furigana": "学生(がくせい)たちは、環境(かんきょう)問題(もんだい)を深(ふか)く追究(ついきゅう)して発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "この課題の追究には、まだ時間が必要だ。", "target_word": "追究", "complexity_tier": "T3", "furigana": "この課題(かだい)の追究(ついきゅう)には、まだ時間(じかん)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "彼は人生の意味という問いを、一人で追究してきた。", "target_word": "追究", "complexity_tier": "T3", "furigana": "彼(かれ)は人生(じんせい)の意味(いみ)という問(と)いを、一人(ひとり)で追究(ついきゅう)してきた。", "sentence_source": "generated"}, {"text": "先生は、疑問を自分で追究することを勧めた。", "target_word": "追究", "complexity_tier": "T3", "furigana": "先生(せんせい)は、疑問(ぎもん)を自分(じぶん)で追究(ついきゅう)することを勧(すす)めた。", "sentence_source": "generated"}, {"text": "歴史の謎を追究する授業が、とても人気だ。", "target_word": "追究", "complexity_tier": "T3", "furigana": "歴史(れきし)の謎(なぞ)を追究(ついきゅう)する授業(じゅぎょう)が、とても人気(にんき)だ。", "sentence_source": "generated"}, {"text": "追究したいテーマを、一つ選んでください。", "target_word": "追究", "complexity_tier": "T3", "furigana": "追究(ついきゅう)したいテーマを、一(ひと)つ選(えら)んでください。", "sentence_source": "generated"}, {"text": "彼女の追究は、教室の小さな疑問から始まった。", "target_word": "追究", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の追究(ついきゅう)は、教室(きょうしつ)の小(ちい)さな疑問(ぎもん)から始(はじ)まった。", "sentence_source": "generated"}, {"text": "町の川が汚れる理由を追究する活動に、私も参加した。", "target_word": "追究", "complexity_tier": "T3", "furigana": "町(まち)の川(かわ)が汚(よご)れる理由(りゆう)を追究(ついきゅう)する活動(かつどう)に、私(わたし)も参加(さんか)した。", "sentence_source": "generated"}, {"text": "一つの問題を追究すると、新しい疑問も見えてくる。", "target_word": "追究", "complexity_tier": "T3", "furigana": "一(ひと)つの問題(もんだい)を追究(ついきゅう)すると、新(あたら)しい疑問(ぎもん)も見(み)えてくる。", "sentence_source": "generated"}, {"text": "彼は言葉の成り立ちを追究する研究を続けている。", "target_word": "追究", "complexity_tier": "T3", "furigana": "彼(かれ)は言葉(ことば)の成(な)り立(た)ちを追究(ついきゅう)する研究(けんきゅう)を続(つづ)けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "追究", "label": "名詞形"}, {"form": "追究する", "label": "サ変動詞・辞書形"}, {"form": "追究した", "label": "過去形"}, {"form": "追究したい", "label": "願望形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "動作名詞。問題・課題・疑問・テーマを深く考え探求すること（追求・追及とは別語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "「深く追究して発表した」で、問題を探求する意味として自然に入る。"}, {"text": "購入", "is_correct": false, "explanation": "買うことなので、「環境問題を深く購入して」では意味が通らない。"}, {"text": "配布", "is_correct": false, "explanation": "配ることなので、問題を深く探る行為には合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除することなので、問題の探求とは結びつかない。"}], "explanations": {"追究": "「深く追究して発表した」で、問題を探求する意味として自然に入る。", "購入": "買うことなので、「環境問題を深く購入して」では意味が通らない。", "配布": "配ることなので、問題を深く探る行為には合わない。", "清掃": "掃除することなので、問題の探求とは結びつかない。"}, "sentence_index": 0, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府は反対派の議員を追究して、国外へ追い出した。", "explanation": "ここは〈追放〉の意味。人を組織や国から追い出す場合は「追放」を使い、「追究」は問題を深く探る意味に限る。"}, {"text": "警察は逃げた車を追究して、高速道路を走った。", "explanation": "ここは〈追跡〉の意味。動いている車や人を追いかける場面では「追跡」を使い、「追究」は合わない。"}, {"text": "探検隊は未知の島を追究して、上陸した。", "explanation": "ここは〈探索〉の意味。実際の場所を歩き回って調べる場合は「探索」「探検」を使い、「追究」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "「彼女の追究」で、疑問を深く探る行為を指す名詞として自然に入る。"}, {"text": "保管", "is_correct": false, "explanation": "物を大事にしまっておくことなので、疑問の始まりとは結びつかない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届けることなので、教室での疑問には合わない。"}, {"text": "運搬", "is_correct": false, "explanation": "物を運ぶことなので、疑問から始まるという文脈とは合わない。"}], "explanations": {"追究": "「彼女の追究」で、疑問を深く探る行為を指す名詞として自然に入る。", "保管": "物を大事にしまっておくことなので、疑問の始まりとは結びつかない。", "配達": "物を届けることなので、教室での疑問には合わない。", "運搬": "物を運ぶことなので、疑問から始まるという文脈とは合わない。"}, "sentence_index": 6, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は上司の意見を何でも追究して、言いなりになった。", "explanation": "ここは〈追従〉の意味（相手に逆らわず従うこと）。人に従う場面では「追従」を使い、意見を探る意味の「追究」は合わない。"}, {"text": "ランナーは先頭の選手を追究して、ゴール前で追い越した。", "explanation": "ここは〈追い越す〉の意味。前の人や車を抜く場面では「追い越す」を使い、「追究」は使わない。"}, {"text": "リストに新しい項目を追究した。", "explanation": "ここは〈追加〉の意味。項目を付け足す場合は「追加」を使い、「追究」は問題を探る場合に限る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その疑問を追究に、答えを探した。", "corrected_sentence": "その疑問を追究して、答えを探した。", "error_description": "「追究」は「追究する」の形で使うため、直後の「に」は誤り。「追究して」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38123, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の歴史を追究たいと思って、図書館へ行った。", "corrected_sentence": "町の歴史を追究したいと思って、図書館へ行った。", "error_description": "サ変名詞「追究」に「たい」を続けるには「し」が必要。「追究たい」は誤りで、「追究したい」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
