INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38124, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「誕生を知らせる」で、知らせる内容を「を」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「誕生へ知らせる」は「知らせる」の対象として成り立たず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「誕生と知らせる」は対象を示す形にならず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「誕生の知らせる」は連体修飾が宙に浮き、「はがき」にかからない。"}], "correct_answer": "を", "explanations": {"を": "「誕生を知らせる」で、知らせる内容を「を」で示す。", "へ": "「誕生へ知らせる」は「知らせる」の対象として成り立たず、不自然。", "と": "「誕生と知らせる」は対象を示す形にならず、不自然。", "の": "「誕生の知らせる」は連体修飾が宙に浮き、「はがき」にかからない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "引用・並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38124, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が生まれること。新しいものができること。", "primary_collocate": null, "pronunciation": "たんじょう", "ipa": "tandʑoː", "syllable_count": 4, "sentences": [{"text": "姉に赤ちゃんが生まれて、家族みんなが誕生を喜んだ。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "姉(あね)に赤(あか)ちゃんが生(う)まれて、家族(かぞく)みんなが誕生(たんじょう)を喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "新しい会社の誕生を、町の人たちが祝った。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "新(あたら)しい会社(かいしゃ)の誕生(たんじょう)を、町(まち)の人(ひと)たちが祝(いわ)った。", "sentence_source": "generated"}, {"text": "孫の誕生を聞いて、祖父は涙を流した。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "孫(まご)の誕生(たんじょう)を聞(き)いて、祖父(そふ)は涙(なみだ)を流(なが)した。", "sentence_source": "generated"}, {"text": "新しい駅の誕生で、町はずいぶん便利になった。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "新(あたら)しい駅(えき)の誕生(たんじょう)で、町(まち)はずいぶん便利(べんり)になった。", "sentence_source": "generated"}, {"text": "双子の誕生に、病院は明るい空気に包まれた。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "双子(ふたご)の誕生(たんじょう)に、病院(びょういん)は明(あか)るい空気(くうき)に包(つつ)まれた。", "sentence_source": "generated"}, {"text": "この歌は、子どもの誕生を記念して作られた。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "この歌(うた)は、子(こ)どもの誕生(たんじょう)を記念(きねん)して作(つく)られた。", "sentence_source": "generated"}, {"text": "新しいクラブの誕生に、多くの生徒が喜んだ。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "新(あたら)しいクラブの誕生(たんじょう)に、多(おお)くの生徒(せいと)が喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "友人から、赤ちゃんの誕生を知らせるはがきが届いた。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "友人(ゆうじん)から、赤(あか)ちゃんの誕生(たんじょう)を知(し)らせるはがきが届(とど)いた。", "sentence_source": "generated"}, {"text": "新しい国の誕生は、世界中で大きなニュースになった。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "新(あたら)しい国(くに)の誕生(たんじょう)は、世界中(せかいじゅう)で大(おお)きなニュースになった。", "sentence_source": "generated"}, {"text": "町の人たちは、新しい美術館の誕生を心待ちにしている。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "町(まち)の人(ひと)たちは、新(あたら)しい美術館(びじゅつかん)の誕生(たんじょう)を心待(こころま)ちにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誕生", "label": "名詞形"}, {"form": "誕生する", "label": "サ変動詞・辞書形"}, {"form": "誕生した", "label": "過去形"}, {"form": "誕生して", "label": "て形"}], "register": "標準・やや改まった表現", "sense_fingerprint": "動作名詞。人（赤ちゃん）が生まれること、または会社・駅・組織など新しいものができること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38124, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誕生", "is_correct": true, "explanation": "「誕生を喜んだ」で、赤ちゃんが生まれたこと自体を喜ぶ意味になる。"}, {"text": "購入", "is_correct": false, "explanation": "買うことなので、家族が喜ぶ対象としては文が成り立たない。"}, {"text": "配布", "is_correct": false, "explanation": "配ることなので、赤ちゃんの出来事を喜ぶ文脈には合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除することなので、家族が喜ぶ対象にはならない。"}], "explanations": {"誕生": "「誕生を喜んだ」で、赤ちゃんが生まれたこと自体を喜ぶ意味になる。", "購入": "買うことなので、家族が喜ぶ対象としては文が成り立たない。", "配布": "配ることなので、赤ちゃんの出来事を喜ぶ文脈には合わない。", "清掃": "掃除することなので、家族が喜ぶ対象にはならない。"}, "sentence_index": 0, "correct_answer": "誕生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週の日曜日は、母の誕生だから、家族で食事に行く予定だ。", "explanation": "ここは〈誕生日〉の意味。「誕生」は生まれること自体を指し、日付を表す場合は「誕生日」と言う。"}, {"text": "昨夜、大きな地震が誕生した。", "explanation": "ここは〈発生〉の意味。地震や事故のように起こる出来事には「発生」を使い、「誕生」は生まれ出るものに限る。"}, {"text": "祖父が先月、静かに誕生した。", "explanation": "ここは〈死去〉の意味。「誕生」は生まれることなので、亡くなった場合には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38124, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誕生", "is_correct": true, "explanation": "「新しいクラブの誕生に」で、クラブができたことを指す名詞として自然に入る。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼むことなので、クラブができたことを喜ぶ文脈には合わない。"}, {"text": "保管", "is_correct": false, "explanation": "物をしまっておくことなので、クラブの成立とは結びつかない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届けることなので、クラブができたことには使えない。"}], "explanations": {"誕生": "「新しいクラブの誕生に」で、クラブができたことを指す名詞として自然に入る。", "注文": "品物を頼むことなので、クラブができたことを喜ぶ文脈には合わない。", "保管": "物をしまっておくことなので、クラブの成立とは結びつかない。", "配達": "物を届けることなので、クラブができたことには使えない。"}, "sentence_index": 6, "correct_answer": "誕生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場の入口に、見慣れない男が誕生した。", "explanation": "ここは〈出現〉の意味。それまでいなかった人や物が姿を現す場合は「出現」を使い、「誕生」は生まれ出ることを指す。"}, {"text": "彼は大阪の誕生で、ずっと大阪で育った。", "explanation": "ここは〈生まれ〉の意味（出身地）。人の出身地は「〜生まれ」で表し、「誕生」では言わない。"}, {"text": "父は今朝、五時に誕生して、畑へ向かった。", "explanation": "ここは〈出かける〉の意味。畑へ行くことには「出かける」や「向かう」を使い、「誕生」は生まれ出ることにしか使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38124, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい学校が誕生されて、町が明るくなった。", "corrected_sentence": "新しい学校が誕生して、町が明るくなった。", "error_description": "「誕生する」は自動詞なので受け身の「誕生される」は使えない。「誕生して」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38124, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族は赤ちゃんの誕生が喜んだ。", "corrected_sentence": "家族は赤ちゃんの誕生を喜んだ。", "error_description": "「喜ぶ」は対象を「を」で示すため、「誕生が」は誤り。「誕生を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
