INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38125, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や動物がこの世に生まれ出ること。また、新しい事柄や物が現れること。", "primary_collocate": null, "pronunciation": "たんじょう", "ipa": "tandʑoː", "syllable_count": 4, "sentences": [{"text": "動物園でパンダの赤ちゃんが誕生した。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "動物園(どうぶつえん)でパンダの赤(あか)ちゃんが誕生(たんじょう)した。", "sentence_source": "generated"}, {"text": "水族館では、イルカの誕生が大きな話題になった。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "水族館(すいぞくかん)では、イルカの誕生(たんじょう)が大(おお)きな話題(わだい)になった。", "sentence_source": "generated"}, {"text": "新しい星の誕生は、望遠鏡で観察できる。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "新(あたら)しい星(ほし)の誕生(たんじょう)は、望遠鏡(ぼうえんきょう)で観察(かんさつ)できる。", "sentence_source": "generated"}, {"text": "地球上に生命が誕生したのは、数十億年前だ。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "地球上(ちきゅうじょう)に生命(せいめい)が誕生(たんじょう)したのは、数十億年前(すうじゅうおくねんまえ)だ。", "sentence_source": "generated"}, {"text": "卵から子ガメが誕生する瞬間を、みんなで見守った。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "卵(たまご)から子(こ)ガメが誕生(たんじょう)する瞬間(しゅんかん)を、みんなで見守(みまも)った。", "sentence_source": "generated"}, {"text": "江戸時代に、新しい文化が誕生した。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "江戸時代(えどじだい)に、新(あたら)しい文化(ぶんか)が誕生(たんじょう)した。", "sentence_source": "generated"}, {"text": "新しいスポーツが誕生するまでには、長い歴史がある。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "新(あたら)しいスポーツが誕生(たんじょう)するまでには、長(なが)い歴史(れきし)がある。", "sentence_source": "generated"}, {"text": "彼の発明から、便利な道具が誕生した。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "彼(かれ)の発明(はつめい)から、便利(べんり)な道具(どうぐ)が誕生(たんじょう)した。", "sentence_source": "generated"}, {"text": "牧場で子牛が誕生し、子どもたちは大喜びした。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "牧場(ぼくじょう)で子牛(こうし)が誕生(たんじょう)し、子(こ)どもたちは大喜(おおよろこ)びした。", "sentence_source": "generated"}, {"text": "二つの川が出会う場所に、小さな町が誕生した。", "target_word": "誕生", "complexity_tier": "T3", "furigana": "二(ふた)つの川(かわ)が出会(であ)う場所(ばしょ)に、小(ちい)さな町(まち)が誕生(たんじょう)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誕生", "label": "名詞形"}, {"form": "誕生する", "label": "サ変動詞・辞書形"}, {"form": "誕生した", "label": "過去形"}, {"form": "誕生し", "label": "連用形"}], "register": "標準・やや改まった表現", "sense_fingerprint": "動作名詞。動物・生命が生まれ出ること、または文化・星・発明など新しい事柄や物が現れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38125, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誕生", "is_correct": true, "explanation": "「誕生した」で、赤ちゃんが生まれ出たことを表す。"}, {"text": "出発", "is_correct": false, "explanation": "人や乗り物が出かけることなので、赤ちゃんには使わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終わりにすることなので、生き物には使えない。"}, {"text": "購入", "is_correct": false, "explanation": "買うことなので、赤ちゃんを主語にすると意味が通らない。"}], "explanations": {"誕生": "「誕生した」で、赤ちゃんが生まれ出たことを表す。", "出発": "人や乗り物が出かけることなので、赤ちゃんには使わない。", "解散": "集まりを終わりにすることなので、生き物には使えない。", "購入": "買うことなので、赤ちゃんを主語にすると意味が通らない。"}, "sentence_index": 0, "correct_answer": "誕生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨夜、町の工場で大きな火事が誕生した。", "explanation": "ここは〈発生〉の意味。火事や事故のように起こる出来事には「発生」を使い、「誕生」は生まれ出るものに限る。"}, {"text": "子どもたちは放課後、公園で誕生して遊んだ。", "explanation": "ここは〈集まる〉の意味。人が集まる場面には「集まる」を使い、「誕生」は生まれ出ることに限る。"}, {"text": "彼女は三日前に町へ誕生して、すぐ仕事を探し始めた。", "explanation": "ここは〈到着〉の意味。町へ来ることには「到着」や「引っ越し」を使い、「誕生」は生まれ出ることに限る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38125, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誕生", "is_correct": true, "explanation": "「誕生するまでには」で、新しいスポーツが生まれ出ることを表す。"}, {"text": "廃止", "is_correct": false, "explanation": "制度などをやめることなので、新しく生まれる過程には合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除くことなので、新しいスポーツの成立とは結びつかない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届けることなので、スポーツには使えない。"}], "explanations": {"誕生": "「誕生するまでには」で、新しいスポーツが生まれ出ることを表す。", "廃止": "制度などをやめることなので、新しく生まれる過程には合わない。", "撤去": "取り除くことなので、新しいスポーツの成立とは結びつかない。", "配達": "物を届けることなので、スポーツには使えない。"}, "sentence_index": 6, "correct_answer": "誕生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は朝八時に誕生して、会社へ出かけた。", "explanation": "ここは〈出勤〉の意味。会社へ行くことには「出勤」を使い、「誕生」は生まれ出ることにしか使わない。"}, {"text": "彼は東京の誕生で、ずっと東京で育った。", "explanation": "ここは〈生まれ〉の意味（出身地）。人の出身地は「〜生まれ」で表し、「誕生」では言わない。"}, {"text": "彼は夜十時に誕生して、家へ帰った。", "explanation": "ここは〈帰宅〉の意味。家へ戻ることには「帰宅」を使い、「誕生」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38125, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球に生命が誕生ました。", "corrected_sentence": "地球に生命が誕生しました。", "error_description": "「誕生する」はサ変動詞なので、丁寧形は「誕生しました」となる。「し」が抜けている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38125, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この時代に、豊かな文化を誕生した。", "corrected_sentence": "この時代に、豊かな文化が誕生した。", "error_description": "「誕生する」は自動詞で、主語を「が」で示す。「を」は目的語を示すため、「文化を誕生した」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「規制する」の目的語なので「を」。「使い方を規制する」と続く。"}, {"text": "に", "is_correct": false, "explanation": "「使い方に規制することにした」は「に」の格が成り立たず、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、規制の対象とは結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「使い方と規制することにした」は文として成立しない。"}], "correct_answer": "を", "explanations": {"を": "「規制する」の目的語なので「を」。「使い方を規制する」と続く。", "に": "「使い方に規制することにした」は「に」の格が成り立たず、文が通らない。", "へ": "「へ」は方向を表すが、規制の対象とは結びつかない。", "と": "「と」は並列や相手を表すが、「使い方と規制することにした」は文として成立しない。"}, "error_tags": {"に": "位置", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「会話を規制している」のように、「規制する」の目的語なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "「大声での会話が規制している」は、会話を主語にできず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、規制の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、規制の対象には当たらない。"}], "correct_answer": "を", "explanations": {"を": "「会話を規制している」のように、「規制する」の目的語なので「を」。", "が": "「大声での会話が規制している」は、会話を主語にできず不自然。", "より": "「より」は比較を表すので、規制の対象を示せない。", "から": "「から」は起点を表すので、規制の対象には当たらない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や物の行動や使い方を、決まりで止めること。", "primary_collocate": null, "pronunciation": "きせい", "ipa": "kiseː", "syllable_count": 3, "sentences": [{"text": "夜の公園では、大きな音を出すことが規制されている。", "target_word": "規制", "complexity_tier": "T3", "furigana": "夜[よる]の公園[こうえん]では、大[おお]きな音[おと]を出[だ]すことが規制[きせい]されている。", "sentence_source": "generated"}, {"text": "学校は、スマホの使い方を規制することにした。", "target_word": "規制", "complexity_tier": "T3", "furigana": "学校[がっこう]は、スマホの使[つか]い方[かた]を規制[きせい]することにした。", "sentence_source": "generated"}, {"text": "車の通行を規制したので、駅前の道が静かになった。", "target_word": "規制", "complexity_tier": "T3", "furigana": "車[くるま]の通行[つうこう]を規制[きせい]したので、駅前[えきまえ]の道[みち]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "規制が厳しすぎると、子どもたちは自由に遊べない。", "target_word": "規制", "complexity_tier": "T3", "furigana": "規制[きせい]が厳[きび]しすぎると、子[こ]どもたちは自由[じゆう]に遊[あそ]べない。", "sentence_source": "generated"}, {"text": "川の水が増えたため、橋の通行が規制された。", "target_word": "規制", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が増[ふ]えたため、橋[はし]の通行[つうこう]が規制[きせい]された。", "sentence_source": "generated"}, {"text": "祭りの日は、会場の近くで車の駐車が規制される。", "target_word": "規制", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、会場[かいじょう]の近[ちか]くで車[くるま]の駐車[ちゅうしゃ]が規制[きせい]される。", "sentence_source": "generated"}, {"text": "町では、ごみを出す時間に規制を設けている。", "target_word": "規制", "complexity_tier": "T3", "furigana": "町[まち]では、ごみを出[だ]す時間[じかん]に規制[きせい]を設[もう]けている。", "sentence_source": "generated"}, {"text": "図書館は、大声での会話を規制している。", "target_word": "規制", "complexity_tier": "T3", "furigana": "図書館[としょかん]は、大声[おおごえ]での会話[かいわ]を規制[きせい]している。", "sentence_source": "generated"}, {"text": "規制があっても、ルールを守らない人はいる。", "target_word": "規制", "complexity_tier": "T3", "furigana": "規制[きせい]があっても、ルールを守[まも]らない人[ひと]はいる。", "sentence_source": "generated"}, {"text": "事故のあと、プールで泳げる人数が規制された。", "target_word": "規制", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、プールで泳[およ]げる人数[にんずう]が規制[きせい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "規制する", "label": "辞書形"}, {"form": "規制した", "label": "過去形"}, {"form": "規制される", "label": "受身形"}, {"form": "規制して", "label": "て形"}], "register": "中立（普通体）", "sense_fingerprint": "決まりを作って、人の行動や物の使い方を制限すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "規制", "is_correct": true, "explanation": "「決まりで行動を止める」意味で、大きな音を出すことを止めるという文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は点数をつける意味で、「大きな音を出すこと」の前後には使えず文が成立しない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を別の言語に置き換えることで、行為や音には使えない。"}, {"text": "修理", "is_correct": false, "explanation": "修理は壊れたものを直すことで、音を出す行為には使えない。"}], "explanations": {"規制": "「決まりで行動を止める」意味で、大きな音を出すことを止めるという文脈に合う。", "採点": "採点は点数をつける意味で、「大きな音を出すこと」の前後には使えず文が成立しない。", "翻訳": "翻訳は言葉を別の言語に置き換えることで、行為や音には使えない。", "修理": "修理は壊れたものを直すことで、音を出す行為には使えない。"}, "sentence_index": 0, "correct_answer": "規制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、機械の温度を規制して、毎日記録している。", "explanation": "ここは〈管理・調節〉の意味。規制は人の行動や物の使い方を決まりで止めることなので、機械の温度には使わない。"}, {"text": "毎朝、姿勢を規制するために体操をしている。", "explanation": "ここは〈正す〉の意味。規制は行動を止める意味で、体の形を直すことには使わない。"}, {"text": "風邪で上がった熱を、薬で規制している。", "explanation": "ここは〈抑える〉の意味。規制は決まりで行動を止めることで、体の熱には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "規制", "is_correct": true, "explanation": "「決まりで行動を止める」意味で、ごみを出す時間に設けるものとして合う。"}, {"text": "採寸", "is_correct": false, "explanation": "採寸は体や物の寸法を測ることで、時間に設けるものではない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むことで、「時間に設ける」とは合わない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗車は車に乗ることで、「時間に設ける」とは合わない。"}], "explanations": {"規制": "「決まりで行動を止める」意味で、ごみを出す時間に設けるものとして合う。", "採寸": "採寸は体や物の寸法を測ることで、時間に設けるものではない。", "注文": "注文は品物を頼むことで、「時間に設ける」とは合わない。", "乗車": "乗車は車に乗ることで、「時間に設ける」とは合わない。"}, "sentence_index": 6, "correct_answer": "規制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキを三人で規制して、平等に分けた。", "explanation": "ここは〈分配〉の意味。規制は行動を決まりで止める意味で、物を分けることには使わない。"}, {"text": "冷蔵庫で、野菜の鮮度を規制して保った。", "explanation": "ここは〈保存〉の意味。規制は人の行動を止めることで、食品の状態を保つ意味では使わない。"}, {"text": "台風で壊れた屋根を、すぐに規制して直した。", "explanation": "ここは〈修理〉の意味。規制は行動や使い方を止める意味で、建物を直すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、夜の公園での花火に規制している。", "corrected_sentence": "市は、夜の公園での花火を規制している。", "error_description": "「規制する」は目的語に「を」をとる。「花火に規制している」の「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38126, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、祭りの日に車の通行を規制ている。", "corrected_sentence": "町は、祭りの日に車の通行を規制している。", "error_description": "「規制している」の「し」が抜けた誤り。「規制ている」は動詞の形として不完全で、正しくは「規制している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「規制が厳しくなる」の主語なので「が」。"}, {"text": "を", "is_correct": false, "explanation": "「規制を厳しくなる」は、厳しくなるという自動詞と目的語が結びつかず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「厳しくなる」の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「規制より」では文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「規制が厳しくなる」の主語なので「が」。", "を": "「規制を厳しくなる」は、厳しくなるという自動詞と目的語が結びつかず文が成立しない。", "へ": "「へ」は方向を表すので、「厳しくなる」の主語にはならない。", "より": "「より」は比較を表し、「規制より」では文として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「法律で規制する」の「で」は、法律という手段で規制するという意味を表す。"}, {"text": "に", "is_correct": false, "explanation": "「法律に規制する」は、「に」の格が成り立たず文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、規制の手段にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、規制の手段にはならない。"}], "correct_answer": "で", "explanations": {"で": "「法律で規制する」の「で」は、法律という手段で規制するという意味を表す。", "に": "「法律に規制する」は、「に」の格が成り立たず文が通らない。", "より": "「より」は比較を表すので、規制の手段にはならない。", "から": "「から」は起点を表すので、規制の手段にはならない。"}, "error_tags": {"に": "位置", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "法律や規則などで、ある行為や物事をしてはいけないと決めること。また、その決まり。", "primary_collocate": null, "pronunciation": "きせい", "ipa": "kiseː", "syllable_count": 3, "sentences": [{"text": "政府は、新しい薬の販売について規制を強めた。", "target_word": "規制", "complexity_tier": "T3", "furigana": "政府[せいふ]は、新[あたら]しい薬[くすり]の販売[はんばい]について規制[きせい]を強[つよ]めた。", "sentence_source": "generated"}, {"text": "排気ガスに対する規制が、来年から厳しくなる。", "target_word": "規制", "complexity_tier": "T3", "furigana": "排気[はいき]ガスに対[たい]する規制[きせい]が、来年[らいねん]から厳[きび]しくなる。", "sentence_source": "generated"}, {"text": "法律による規制がないため、問題が広がった。", "target_word": "規制", "complexity_tier": "T3", "furigana": "法律[ほうりつ]による規制[きせい]がないため、問題[もんだい]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "国は、食品に使える添加物を規制している。", "target_word": "規制", "complexity_tier": "T3", "furigana": "国[くに]は、食品[しょくひん]に使[つか]える添加物[てんかぶつ]を規制[きせい]している。", "sentence_source": "generated"}, {"text": "銀行の取引には、さまざまな規制がある。", "target_word": "規制", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]の取引[とりひき]には、さまざまな規制[きせい]がある。", "sentence_source": "generated"}, {"text": "規制を守らない会社は、罰金を払うことになる。", "target_word": "規制", "complexity_tier": "T3", "furigana": "規制[きせい]を守[まも]らない会社[かいしゃ]は、罰金[ばっきん]を払[はら]うことになる。", "sentence_source": "generated"}, {"text": "環境を守るため、海への廃棄物の排出が規制された。", "target_word": "規制", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]るため、海[うみ]への廃棄物[はいきぶつ]の排出[はいしゅつ]が規制[きせい]された。", "sentence_source": "generated"}, {"text": "外国のお金の動きを、法律で規制する国もある。", "target_word": "規制", "complexity_tier": "T3", "furigana": "外国[がいこく]のお金[かね]の動[うご]きを、法律[ほうりつ]で規制[きせい]する国[くに]もある。", "sentence_source": "generated"}, {"text": "新しい規制ができて、小さな店は対応に苦労した。", "target_word": "規制", "complexity_tier": "T3", "furigana": "新[あたら]しい規制[きせい]ができて、小[ちい]さな店[みせ]は対応[たいおう]に苦労[くろう]した。", "sentence_source": "generated"}, {"text": "専門家は、ドローンの飛行を規制する法律が必要だと述べた。", "target_word": "規制", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、ドローンの飛行[ひこう]を規制[きせい]する法律[ほうりつ]が必要[ひつよう]だと述[の]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "規制する", "label": "辞書形"}, {"form": "規制した", "label": "過去形"}, {"form": "規制される", "label": "受身形"}, {"form": "規制して", "label": "て形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "国や組織が法律・規則によって特定の行為を禁じたり制限したりすること、またその決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "規制", "is_correct": true, "explanation": "「規制を強める」は、法律や規則で制限を厳しくするという意味で文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を別の言語に置き換えることで、「強めた」とは組み合わない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は点数をつける意味で、「販売について」の後に「強めた」と続かない。"}, {"text": "修理", "is_correct": false, "explanation": "修理は壊れたものを直すことで、「強めた」とは組み合わず文が通らない。"}], "explanations": {"規制": "「規制を強める」は、法律や規則で制限を厳しくするという意味で文脈に合う。", "翻訳": "翻訳は言葉を別の言語に置き換えることで、「強めた」とは組み合わない。", "採点": "採点は点数をつける意味で、「販売について」の後に「強めた」と続かない。", "修理": "修理は壊れたものを直すことで、「強めた」とは組み合わず文が通らない。"}, "sentence_index": 0, "correct_answer": "規制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この倉庫では、食品の在庫を規制して、毎日数えている。", "explanation": "ここは〈管理〉の意味。規制は人の行動や使い方を決まりで止めることで、在庫の数を扱う意味ではない。"}, {"text": "薬を飲んで、くしゃみを規制した。", "explanation": "ここは〈抑える〉の意味。規制は決まりによる制限で、体の反応には使わない。"}, {"text": "毎日ワイヤーで、歯並びを規制している。", "explanation": "ここは〈矯正〉の意味。規制は行動を止める意味で、歯並びを整えることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "規制", "is_correct": true, "explanation": "「排出を規制された」は、決まりで海への排出を禁じたという文脈に合う。"}, {"text": "予約", "is_correct": false, "explanation": "予約は席や日時を前もって取っておくことで、「排出が予約された」は意味が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むことで、排出には使えない。"}, {"text": "採寸", "is_correct": false, "explanation": "採寸は寸法を測ることで、排出の文脈には合わない。"}], "explanations": {"規制": "「排出を規制された」は、決まりで海への排出を禁じたという文脈に合う。", "予約": "予約は席や日時を前もって取っておくことで、「排出が予約された」は意味が通らない。", "注文": "注文は品物を頼むことで、排出には使えない。", "採寸": "採寸は寸法を測ることで、排出の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "規制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、答案を規制して一枚ずつ採点した。", "explanation": "ここは〈採点〉の意味。規制は決まりで行動を止めることで、答案に点数をつける意味では使わない。"}, {"text": "工場で、機械の部品を規制して点検した。", "explanation": "ここは〈点検〉の意味。規制は行動や使い方を止める意味で、部品を調べることには使わない。"}, {"text": "ファイルを規制して、机の上を整理した。", "explanation": "ここは〈整理〉の意味。規制は行動を決まりで止める意味で、物を並べ直すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国は、輸入の食品について規制に強めた。", "corrected_sentence": "国は、輸入の食品について規制を強めた。", "error_description": "「規制を強める」の目的語は「を」。「規制に強めた」の「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38127, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "県は、深夜の大きな音を規制ている。", "corrected_sentence": "県は、深夜の大きな音を規制している。", "error_description": "「している」の「し」が抜けた誤り。「規制ている」は不完全な形で、正しくは「規制している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この道具のおかげで」の「の」。「道具の（力）おかげ」と名詞をつなぐ助詞。"}, {"text": "が", "is_correct": false, "explanation": "「道具がおかげで」は成り立たない。名詞をつなぐには「の」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「道具をおかげで」は不自然。「を」は目的語を示すので、ここでは合わない。"}, {"text": "に", "is_correct": false, "explanation": "「道具におかげで」は成り立たない。「に」は方向や相手を示すので、ここでは合わない。"}], "correct_answer": "の", "explanations": {"の": "「この道具のおかげで」の「の」。「道具の（力）おかげ」と名詞をつなぐ助詞。", "が": "「道具がおかげで」は成り立たない。名詞をつなぐには「の」が必要。", "を": "「道具をおかげで」は不自然。「を」は目的語を示すので、ここでは合わない。", "に": "「道具におかげで」は成り立たない。「に」は方向や相手を示すので、ここでは合わない。"}, "error_tags": {"が": "subject marker, does not join nouns", "を": "object marker, not the joiner", "に": "direction or target, not the joiner"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「良い道具を選ぶと」の「を」。選ぶ対象の目的語に付く助詞。"}, {"text": "が", "is_correct": false, "explanation": "「良い道具が選ぶと」は不自然。選ぶ対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「良い道具に選ぶと」は成り立たない。「に」は方向や相手を示すので、ここでは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「良い道具へ選ぶと」は成り立たない。「へ」は方向を示すので、選ぶ対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「良い道具を選ぶと」の「を」。選ぶ対象の目的語に付く助詞。", "が": "「良い道具が選ぶと」は不自然。選ぶ対象は「を」で示す。", "に": "「良い道具に選ぶと」は成り立たない。「に」は方向や相手を示すので、ここでは合わない。", "へ": "「良い道具へ選ぶと」は成り立たない。「へ」は方向を示すので、選ぶ対象には合わない。"}, "error_tags": {"が": "subject marker, not the object of 選ぶ", "に": "direction or target, not the object", "へ": "direction, not the object"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かをするときの手助けになるもの。", "primary_collocate": null, "pronunciation": "どうぐ", "ipa": "doːɡɯ", "syllable_count": 3, "sentences": [{"text": "庭の仕事には、ハサミやシャベルなどの道具が必要だ。", "target_word": "道具", "complexity_tier": "T3", "furigana": "庭[にわ]の仕事[しごと]には、ハサミやシャベルなどの道具[どうぐ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この道具のおかげで、固いふたが簡単に開いた。", "target_word": "道具", "complexity_tier": "T3", "furigana": "この道具[どうぐ]のおかげで、固[かた]いふたが簡単[かんたん]に開[あ]いた。", "sentence_source": "generated"}, {"text": "弟は工作の道具を机の上に広げて、船を作っている。", "target_word": "道具", "complexity_tier": "T3", "furigana": "弟[おとうと]は工作[こうさく]の道具[どうぐ]を机[つくえ]の上[うえ]に広[ひろ]げて、船[ふね]を作[つく]っている。", "sentence_source": "generated"}, {"text": "使った道具は、片づけてから帰りましょう。", "target_word": "道具", "complexity_tier": "T3", "furigana": "使[つか]った道具[どうぐ]は、片[かた]づけてから帰[かえ]りましょう。", "sentence_source": "generated"}, {"text": "魚をつるには、竿やえさなどの道具がいる。", "target_word": "道具", "complexity_tier": "T3", "furigana": "魚[さかな]をつるには、竿[さお]やえさなどの道具[どうぐ]がいる。", "sentence_source": "generated"}, {"text": "道具が古くなったので、新しいものに替えた。", "target_word": "道具", "complexity_tier": "T3", "furigana": "道具[どうぐ]が古[ふる]くなったので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "母は掃除の道具を持って、窓をふき始めた。", "target_word": "道具", "complexity_tier": "T3", "furigana": "母[はは]は掃除[そうじ]の道具[どうぐ]を持[も]って、窓[まど]をふき始[はじ]めた。", "sentence_source": "generated"}, {"text": "良い道具を選ぶと、作業の時間が短くなる。", "target_word": "道具", "complexity_tier": "T3", "furigana": "良[よ]い道具[どうぐ]を選[えら]ぶと、作業[さぎょう]の時間[じかん]が短[みじか]くなる。", "sentence_source": "generated"}, {"text": "山登りの道具は軽いほど、体が楽になる。", "target_word": "道具", "complexity_tier": "T3", "furigana": "山登[やまのぼ]りの道具[どうぐ]は軽[かる]いほど、体[からだ]が楽[らく]になる。", "sentence_source": "generated"}, {"text": "道具を大切にする人は、仕事も丁寧だ。", "target_word": "道具", "complexity_tier": "T3", "furigana": "道具[どうぐ]を大切[たいせつ]にする人[ひと]は、仕事[しごと]も丁寧[ていねい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "道具", "label": "基本形"}, {"form": "道具の", "label": "連体形"}, {"form": "道具を使う", "label": "よく使う形"}], "register": "標準", "sense_fingerprint": "作業をするときに手助けとして使う物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "「ハサミやシャベルなどの道具」の「道具」。作業に使う物を指し、空所に入る。"}, {"text": "野菜", "is_correct": false, "explanation": "「ハサミやシャベルなどの野菜」は意味をなさない。庭仕事で必要な物には合わない。"}, {"text": "果物", "is_correct": false, "explanation": "「ハサミやシャベルなどの果物」は成り立たない。作業の手助けとなる物には合わない。"}, {"text": "洋服", "is_correct": false, "explanation": "「ハサミやシャベルなどの洋服」は不自然。庭仕事で必要な物には合わない。"}], "explanations": {"道具": "「ハサミやシャベルなどの道具」の「道具」。作業に使う物を指し、空所に入る。", "野菜": "「ハサミやシャベルなどの野菜」は意味をなさない。庭仕事で必要な物には合わない。", "果物": "「ハサミやシャベルなどの果物」は成り立たない。作業の手助けとなる物には合わない。", "洋服": "「ハサミやシャベルなどの洋服」は不自然。庭仕事で必要な物には合わない。"}, "sentence_index": 0, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この選手は道具があるので、試合の流れを読むのが上手だ。", "explanation": "ここは〈能力〉（力量や技量）の意味。道具は何かをするときの手助けになるものを指すので、選手の力量を表すのには合わない。"}, {"text": "今夜の道具は、豆腐と卵だ。", "explanation": "ここは〈材料〉（料理に使う食材）の意味。道具は何かをするときの手助けになるものを指すので、食材の意味では使わない。"}, {"text": "彼女の道具は明るい声で、周りを笑顔にする。", "explanation": "ここは〈持ち味〉（その人らしさ）の意味。道具は手助けになるものを指すので、人柄を表す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "「掃除の道具を持って」の「道具」。掃除に使う物を指し、空所に入る。"}, {"text": "太陽", "is_correct": false, "explanation": "「掃除の太陽を持って」は意味をなさない。掃除に使う物として太陽は合わない。"}, {"text": "海", "is_correct": false, "explanation": "「掃除の海を持って」は成り立たない。掃除に使う物として海は合わない。"}, {"text": "空", "is_correct": false, "explanation": "「掃除の空を持って」は成り立たない。掃除に使う物として空は合わない。"}], "explanations": {"道具": "「掃除の道具を持って」の「道具」。掃除に使う物を指し、空所に入る。", "太陽": "「掃除の太陽を持って」は意味をなさない。掃除に使う物として太陽は合わない。", "海": "「掃除の海を持って」は成り立たない。掃除に使う物として海は合わない。", "空": "「掃除の空を持って」は成り立たない。掃除に使う物として空は合わない。"}, "sentence_index": 6, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道具に従って、皆で試合を楽しむ。", "explanation": "ここは〈規則〉（守るべき決まり）の意味。道具は目的を果たす手段を指すので、従うべき決まりの意味では使わない。"}, {"text": "彼は道具が確かで、どんな仕事もこなす。", "explanation": "ここは〈技術〉（腕前や方法）の意味。道具は手段を指すので、仕事をこなす腕前の確かさには合わない。"}, {"text": "この道具はいつも不機嫌で、部屋を暗くする。", "explanation": "ここは〈気分〉（その時の心の状態）の意味。道具は目的を果たす手段を指すので、人の機嫌には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "料理の道具に、きれいに洗っておく。", "corrected_sentence": "料理の道具を、きれいに洗っておく。", "error_description": "「料理の道具を洗う」の「を」が「に」になっている。「洗う」は目的語に「を」を取るので、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38128, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい道具に使うと、作業がずっと楽になる。", "corrected_sentence": "新しい道具を使うと、作業がずっと楽になる。", "error_description": "「道具を使う」の「を」が「に」になっている。「使う」は目的語に「を」を取るので、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「道具を手入れする」の「を」。手入れの対象を示す目的語に付く助詞。"}, {"text": "が", "is_correct": false, "explanation": "「道具が手入れしている」は成り立たない。手入れの対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「道具に手入れしている」は不自然。「に」は方向や相手を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「道具で手入れしている」は文が成り立たない。「で」は手段や場所を示すので合わない。"}], "correct_answer": "を", "explanations": {"を": "「道具を手入れする」の「を」。手入れの対象を示す目的語に付く助詞。", "が": "「道具が手入れしている」は成り立たない。手入れの対象は「を」で示す。", "に": "「道具に手入れしている」は不自然。「に」は方向や相手を示すので合わない。", "で": "「道具で手入れしている」は文が成り立たない。「で」は手段や場所を示すので合わない。"}, "error_tags": {"が": "subject marker, not the object of 手入れ", "に": "direction or target, not the object", "で": "place or means, not the object"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「争いの道具にしてはいけない」の「に」。「〜にする」の形で、道具として扱う相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「道具を〜してはいけない」は「する」と結びつかない。「〜にする」の形を崩すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「道具でしてはいけない」は不自然。「〜にする」の「に」が必要で、「で」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「道具がしてはいけない」は成り立たない。主語を示す「が」は、ここでは合わない。"}], "correct_answer": "に", "explanations": {"に": "「争いの道具にしてはいけない」の「に」。「〜にする」の形で、道具として扱う相手を示す。", "を": "「道具を〜してはいけない」は「する」と結びつかない。「〜にする」の形を崩すので合わない。", "で": "「道具でしてはいけない」は不自然。「〜にする」の「に」が必要で、「で」は合わない。", "が": "「道具がしてはいけない」は成り立たない。主語を示す「が」は、ここでは合わない。"}, "error_tags": {"を": "object marker, does not fit 〜にする", "で": "place or means, not the target of する", "が": "subject marker, does not fit"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある目的を達成するために使われる、人や物のことを指す。", "primary_collocate": null, "pronunciation": "どうぐ", "ipa": "doːɡɯ", "syllable_count": 3, "sentences": [{"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "道具", "complexity_tier": "T3", "furigana": "すなわち、技術的[ぎじゅつてき]革新[かくしん]は単[たん]なる効率化[こうりつか]の道具[どうぐ]にとどまらず、教育[きょういく]の公平性[こうへいせい]と個別[こべつ]最適化[さいてきか]を両立[りょうりつ]させる新[あら]たな認識論的[にんしきろんてき]枠組[わくぐ]みを構築[こうちく]し得[う]るという点[てん]に、その本質的[ほんしつてき]な教育的[きょういくてき]示唆[しさ]が存[そん]すると言[い]えよう。", "sentence_source": "mined"}, {"text": "大工は、仕事で使う道具をいつもきれいに手入れしている。", "target_word": "道具", "complexity_tier": "T3", "furigana": "大工[だいく]は、仕事[しごと]で使[つか]う道具[どうぐ]をいつもきれいに手入[ていれ]れしている。", "sentence_source": "generated"}, {"text": "言葉は、気持ちを伝えるための大切な道具だ。", "target_word": "道具", "complexity_tier": "T3", "furigana": "言葉[ことば]は、気持[きも]ちを伝[つた]えるための大切[たいせつ]な道具[どうぐ]だ。", "sentence_source": "generated"}, {"text": "彼は上司の出世の道具として使われていただけだった。", "target_word": "道具", "complexity_tier": "T3", "furigana": "彼[かれ]は上司[じょうし]の出世[しゅっせ]の道具[どうぐ]として使[つか]われていただけだった。", "sentence_source": "generated"}, {"text": "料理の道具がそろっていないと、新しい店は開けない。", "target_word": "道具", "complexity_tier": "T3", "furigana": "料理[りょうり]の道具[どうぐ]がそろっていないと、新[あたら]しい店[みせ]は開[ひら]けない。", "sentence_source": "generated"}, {"text": "スマホは情報を集める便利な道具になった。", "target_word": "道具", "complexity_tier": "T3", "furigana": "スマホは情報[じょうほう]を集[あつ]める便利[べんり]な道具[どうぐ]になった。", "sentence_source": "generated"}, {"text": "祖父は古い道具を直しながら、何十年も使い続けている。", "target_word": "道具", "complexity_tier": "T3", "furigana": "祖父[そふ]は古[ふる]い道具[どうぐ]を直[なお]しながら、何十年[なんじゅうねん]も使[つか]い続[つづ]けている。", "sentence_source": "generated"}, {"text": "子どもを争いの道具にしてはいけない。", "target_word": "道具", "complexity_tier": "T3", "furigana": "子[こ]どもを争[あらそ]いの道具[どうぐ]にしてはいけない。", "sentence_source": "generated"}, {"text": "キャンプへ行く前に、必要な道具を箱に入れた。", "target_word": "道具", "complexity_tier": "T3", "furigana": "キャンプへ行[い]く前[まえ]に、必要[ひつよう]な道具[どうぐ]を箱[はこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "絵を描く道具を買うために、アルバイトを始めた。", "target_word": "道具", "complexity_tier": "T3", "furigana": "絵[え]を描[か]く道具[どうぐ]を買[か]うために、アルバイトを始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "道具", "label": "基本形"}, {"form": "道具の", "label": "連体形"}, {"form": "道具として", "label": "資格を表す形"}], "register": "標準", "sense_fingerprint": "目的のために使われる物や、手段として使われる人・物事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "「効率化の道具にとどまらず」の「道具」。手段として使われる物を指し、空所に入る。"}, {"text": "布団", "is_correct": false, "explanation": "「効率化の布団」は意味をなさない。技術革新を論じる文脈に布団は合わない。"}, {"text": "玄関", "is_correct": false, "explanation": "「効率化の玄関」は成り立たない。文脈は効率化の手段を論じているので玄関は合わない。"}, {"text": "財布", "is_correct": false, "explanation": "「効率化の財布」とは言わない。技術革新の文脈に財布は合わない。"}], "explanations": {"道具": "「効率化の道具にとどまらず」の「道具」。手段として使われる物を指し、空所に入る。", "布団": "「効率化の布団」は意味をなさない。技術革新を論じる文脈に布団は合わない。", "玄関": "「効率化の玄関」は成り立たない。文脈は効率化の手段を論じているので玄関は合わない。", "財布": "「効率化の財布」とは言わない。技術革新の文脈に財布は合わない。"}, "sentence_index": 0, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は英語の道具が高く、外国の会社で働いている。", "explanation": "ここは〈能力〉（力量や技量）の意味。道具は目的を果たすための手段を指すので、英語の力量を表す語としては合わない。"}, {"text": "今夜の道具は、鶏肉と野菜だ。", "explanation": "ここは〈材料〉（料理に使う食材）の意味。道具は目的を果たすための手段を指すので、食材の意味では使わない。"}, {"text": "この道具は、彼の代表作として知られている。", "explanation": "ここは〈作品〉（作り上げた芸術作品）の意味。道具は目的を果たすための手段で、完成した作品は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "「古い道具を直しながら」の「道具」。直す対象の器具を指し、空所に入る。"}, {"text": "太陽", "is_correct": false, "explanation": "「古い太陽を直す」は意味をなさない。直せる対象として太陽は合わない。"}, {"text": "海", "is_correct": false, "explanation": "「古い海を直す」は成り立たない。修理の対象として海は合わない。"}, {"text": "空", "is_correct": false, "explanation": "「古い空を直す」は不自然。直せる対象として空は合わない。"}], "explanations": {"道具": "「古い道具を直しながら」の「道具」。直す対象の器具を指し、空所に入る。", "太陽": "「古い太陽を直す」は意味をなさない。直せる対象として太陽は合わない。", "海": "「古い海を直す」は成り立たない。修理の対象として海は合わない。", "空": "「古い空を直す」は不自然。直せる対象として空は合わない。"}, "sentence_index": 6, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この展覧会の道具は、海と空だ。", "explanation": "ここは〈題材〉（作品で描くテーマ）の意味。道具は目的を果たすための手段を指すので、描く対象には使わない。"}, {"text": "先生の道具として、名画を真似した。", "explanation": "ここは〈手本〉（見習う見本）の意味。道具は目的を果たすための手段を指すので、手本の意味では使わない。"}, {"text": "友達の道具を描いて、絵のモデルにした。", "explanation": "ここは〈被写体〉（描かれる相手）の意味。道具は目的を果たすために使われる人や物を指すので、描く相手には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大切な人を、お金を稼ぐ道具に扱ってはいけない。", "corrected_sentence": "大切な人を、お金を稼ぐ道具として扱ってはいけない。", "error_description": "「道具として扱う」の「として」が「に」になっている。「として」は資格を表す形で、「道具に扱う」は不自然。「として」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38129, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は、子どもを守るための道具を作られた。", "corrected_sentence": "この機械は、子どもを守るための道具が作られた。", "error_description": "誤：「道具を作られた」の「を」→正：「道具が作られた」の「が」。受け身の主語は「が」で示し、「を」は付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
