INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38130, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人に何かをするように言ったり、動かしたりすること。", "primary_collocate": null, "pronunciation": "うながす", "ipa": "ɯnaɡasɯ", "syllable_count": 4, "sentences": [{"text": "店員は迷っている客に、試着してみるよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "店員[てんいん]は迷[まよ]っている客[きゃく]に、試着[しちゃく]してみるよう促[うなが]した。", "sentence_source": "generated"}, {"text": "議長は委員たちに意見を出すよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "議長[ぎちょう]は委員[いいん]たちに意見[いけん]を出[だ]すよう促[うなが]した。", "sentence_source": "generated"}, {"text": "看護師は患者の背中に手を添えて、椅子に座るよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "看護師[かんごし]は患者[かんじゃ]の背中[せなか]に手[て]を添[そ]えて、椅子[いす]に座[すわ]るよう促[うなが]した。", "sentence_source": "generated"}, {"text": "先生は黙っている生徒に、答えを言うよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "先生[せんせい]は黙[だま]っている生徒[せいと]に、答[こた]えを言[い]うよう促[うなが]した。", "sentence_source": "generated"}, {"text": "受付の人が名前を呼んで、順番に部屋へ入るよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "受付[うけつけ]の人[ひと]が名前[なまえ]を呼[よ]んで、順番[じゅんばん]に部屋[へや]へ入[はい]るよう促[うなが]した。", "sentence_source": "generated"}, {"text": "友人は私に、早く結論を出すよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "友人[ゆうじん]は私[わたし]に、早[はや]く結論[けつろん]を出[だ]すよう促[うなが]した。", "sentence_source": "generated"}, {"text": "通知が届くたびに、アプリは利用者に更新を促す。", "target_word": "促す", "complexity_tier": "T3", "furigana": "通知[つうち]が届[とど]くたびに、アプリは利用者[りようしゃ]に更新[こうしん]を促[うなが]す。", "sentence_source": "generated"}, {"text": "審判は選手に、試合を再開するよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "審判[しんぱん]は選手[せんしゅ]に、試合[しあい]を再開[さいかい]するよう促[うなが]した。", "sentence_source": "generated"}, {"text": "上司は部下に、報告書の提出を促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "上司[じょうし]は部下[ぶか]に、報告書[ほうこくしょ]の提出[ていしゅつ]を促[うなが]した。", "sentence_source": "generated"}, {"text": "彼女は迷う弟の肩をたたいて、前へ進むよう促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は迷[まよ]う弟[おとうと]の肩[かた]をたたいて、前[まえ]へ進[すす]むよう促[うなが]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "促す", "label": "辞書形"}, {"form": "促した", "label": "過去形"}, {"form": "促して", "label": "て形"}, {"form": "促さない", "label": "否定形"}, {"form": "促される", "label": "受身形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "相手に向かって、言葉や身振りで「そうしてください」と行動を勧めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38130, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促した", "is_correct": true, "explanation": "過去形で、「試着してみるよう促した」と文を完結させる。"}, {"text": "促して", "is_correct": false, "explanation": "て形は文を終えられないので、「。」で終わる文には合わない。"}, {"text": "促され", "is_correct": false, "explanation": "受身の連用形で、文末に続かない。"}, {"text": "促そう", "is_correct": false, "explanation": "意志形で、過去の出来事を述べる文には合わない。"}], "explanations": {"促した": "過去形で、「試着してみるよう促した」と文を完結させる。", "促して": "て形は文を終えられないので、「。」で終わる文には合わない。", "促され": "受身の連用形で、文末に続かない。", "促そう": "意志形で、過去の出来事を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "促した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強盗は店員の金庫を促した。", "explanation": "ここは〈奪い取る〉の意味。促すは人に行動を働きかける語で、金庫を奪う意味はない。"}, {"text": "母は遅刻した息子の罪を促した。", "explanation": "ここは〈咎める〉の意味。促すは行動を勧める語で、とがめる意味はない。"}, {"text": "男は店員の財布を大声で促した。", "explanation": "ここは〈怒鳴る〉の意味。促すは人に行動を働きかける語で、財布は対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38130, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促す", "is_correct": true, "explanation": "辞書形で、習慣的に働きかける様子を文末で表す。"}, {"text": "促し", "is_correct": false, "explanation": "連用形は文末で止まれず、「。」で終わる文には合わない。"}, {"text": "促さ", "is_correct": false, "explanation": "未然形は文末に続かないので合わない。"}, {"text": "促せば", "is_correct": false, "explanation": "仮定形は後件がないと文が完結しないので合わない。"}], "explanations": {"促す": "辞書形で、習慣的に働きかける様子を文末で表す。", "促し": "連用形は文末で止まれず、「。」で終わる文には合わない。", "促さ": "未然形は文末に続かないので合わない。", "促せば": "仮定形は後件がないと文が完結しないので合わない。"}, "sentence_index": 6, "correct_answer": "促す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は泣く弟の涙を促した。", "explanation": "ここは〈泣き止ませる〉の意味。促すは涙を止める意味はないので、涙には使わない。"}, {"text": "彼は母に泣きながら小遣いを促した。", "explanation": "ここは〈懇願する〉の意味。促すは頼み込む意味ではなく、小遣いをせびる場面にも合わない。"}, {"text": "彼は話しかけてきた友人の口を促した。", "explanation": "ここは〈無視する〉の意味。促すは相手を無視する意味ではなく、口を促すのも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38130, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "議長は委員たちに意見を述べると促した。", "corrected_sentence": "議長は委員たちに意見を述べるよう促した。", "error_description": "誤りは「述べると」。「促す」は内容を「〜するよう」で示すので、「と」は不自然。正しくは「述べるよう」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "促した", "is_correct": true, "explanation": "過去形で、議長が委員に働きかけた出来事を表す。"}, {"text": "促せ", "is_correct": false, "explanation": "命令形で、事実を述べる文の述語にはならない。"}, {"text": "促して", "is_correct": false, "explanation": "て形で、文の述語として完結しない。"}, {"text": "促される", "is_correct": false, "explanation": "受身形で、議長が働きかける側である文の意味と合わない。"}], "correct_form": "促した", "base_form": "促す", "form_label": "過去形", "sentence_index": 1, "explanations": {"促した": "過去形で、議長が委員に働きかけた出来事を表す。", "促せ": "命令形で、事実を述べる文の述語にはならない。", "促して": "て形で、文の述語として完結しない。", "促される": "受身形で、議長が働きかける側である文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38130, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "審判は選手で、ボールを拾うよう促した。", "corrected_sentence": "審判は選手に、ボールを拾うよう促した。", "error_description": "誤りは「選手で」。「促す」は働きかける相手を「に」で示すので、「で」は誤り。正しくは「選手に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "促した", "is_correct": true, "explanation": "過去形で、審判が選手に働きかけた出来事を表す。"}, {"text": "促して", "is_correct": false, "explanation": "て形で、文の述語として完結しない。"}, {"text": "促せば", "is_correct": false, "explanation": "仮定形で、後件がないと文が完結しない。"}, {"text": "促し", "is_correct": false, "explanation": "連用形で、文末の述語として完結しない。"}], "correct_form": "促した", "base_form": "促す", "form_label": "過去形", "sentence_index": 7, "explanations": {"促した": "過去形で、審判が選手に働きかけた出来事を表す。", "促して": "て形で、文の述語として完結しない。", "促せば": "仮定形で、後件がないと文が完結しない。", "促し": "連用形で、文末の述語として完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
