INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38131, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物事に働きかけて、行動や変化を起こさせること。", "primary_collocate": null, "pronunciation": "うながす", "ipa": "ɯnaɡasɯ", "syllable_count": 4, "sentences": [{"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "促す", "complexity_tier": "T3", "furigana": "資金[しきん]のみならず、経営[けいえい]の知見[ちけん]や人的[じんてき]ネットワークが注入[ちゅうにゅう]されることで、個々[ここ]の企業[きぎょう]の成長[せいちょう]が触発[しょくはつ]され、結果[けっか]として社会[しゃかい]実装[じっそう]を加速[かそく]させ、ひいては経済[けいざい]構造[こうぞう]の変革[へんかく]を促[うなが]す強力[きょうりょく]な原動力[げんどうりょく]となるのだ。", "sentence_source": "mined"}, {"text": "先生は緊張している生徒に、ゆっくり話すように促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "先生[せんせい]は緊張[きんちょう]している生徒[せいと]に、ゆっくり話[はな]すように促[うなが]した。", "sentence_source": "generated"}, {"text": "市は住民に早めの避難を促すため、放送で呼びかけた。", "target_word": "促す", "complexity_tier": "T3", "furigana": "市[し]は住民[じゅうみん]に早[はや]めの避難[ひなん]を促[うなが]すため、放送[ほうそう]で呼[よ]びかけた。", "sentence_source": "generated"}, {"text": "司会者が発言を促すと、会場から次々と手が挙がった。", "target_word": "促す", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]が発言[はつげん]を促[うなが]すと、会場[かいじょう]から次々[つぎつぎ]と手[て]が挙[あ]がった。", "sentence_source": "generated"}, {"text": "医者は患者に生活習慣の見直しを促した。", "target_word": "促した", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]に生活[せいかつ]習慣[しゅうかん]の見直[みなお]しを促[うなが]した。", "sentence_source": "generated"}, {"text": "警察は運転手に注意を促す看板を道路に立てた。", "target_word": "促す", "complexity_tier": "T3", "furigana": "警察[けいさつ]は運転手[うんてんしゅ]に注意[ちゅうい]を促[うなが]す看板[かんばん]を道路[どうろ]に立[た]てた。", "sentence_source": "generated"}, {"text": "母は子どもに宿題を始めるよう促したが、返事がなかった。", "target_word": "促した", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもに宿題[しゅくだい]を始[はじ]めるよう促[うなが]したが、返事[へんじ]がなかった。", "sentence_source": "generated"}, {"text": "駅員は乗客に、奥へ進むよう促していた。", "target_word": "促して", "complexity_tier": "T3", "furigana": "駅員[えきいん]は乗客[じょうきゃく]に、奥[おく]へ進[すす]むよう促[うなが]していた。", "sentence_source": "generated"}, {"text": "彼の失敗は、社員に安全の確認を促すきっかけとなった。", "target_word": "促す", "complexity_tier": "T3", "furigana": "彼[かれ]の失敗[しっぱい]は、社員[しゃいん]に安全[あんぜん]の確認[かくにん]を促[うなが]すきっかけとなった。", "sentence_source": "generated"}, {"text": "社長は役員に決断を促したものの、結論は出なかった。", "target_word": "促した", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は役員[やくいん]に決断[けつだん]を促[うなが]したものの、結論[けつろん]は出[で]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "促す", "label": "辞書形"}, {"form": "促した", "label": "過去形"}, {"form": "促して", "label": "て形"}, {"form": "促さない", "label": "否定形"}, {"form": "促される", "label": "受身形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "相手が行動や変化に向かうように、言葉や出来事で働きかけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38131, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促す", "is_correct": true, "explanation": "辞書形で、直後の「強力な原動力」を修飾する形として文脈に合う。"}, {"text": "促せ", "is_correct": false, "explanation": "命令形で、名詞「原動力」を修飾できず、文の形を作れない。"}, {"text": "促される", "is_correct": false, "explanation": "受身形にすると「変革が促される」となり、ここの「変革を」の格と合わない。"}, {"text": "促そう", "is_correct": false, "explanation": "意志形は「〜しよう」の形で、名詞を修飾できないので合わない。"}], "explanations": {"促す": "辞書形で、直後の「強力な原動力」を修飾する形として文脈に合う。", "促せ": "命令形で、名詞「原動力」を修飾できず、文の形を作れない。", "促される": "受身形にすると「変革が促される」となり、ここの「変革を」の格と合わない。", "促そう": "意志形は「〜しよう」の形で、名詞を修飾できないので合わない。"}, "sentence_index": 0, "correct_answer": "促す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末、友人を映画に促した。", "explanation": "ここは〈誘う〉の意味。促すは相手に行動を働きかける語だが、遊びに誘う場面では使わないので不自然。"}, {"text": "会社は社員の名札を促した。", "explanation": "ここは〈配る〉の意味。名札を配るのは配布で、促すは働きかける語なので合わない。"}, {"text": "村は毎年夏に盆踊りの櫓を促している。", "explanation": "ここは〈組み立てる〉の意味。櫓を組むのは組み立てで、促すは働きかける語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38131, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促した", "is_correct": true, "explanation": "過去形。「〜したが」と続けて、働きかけた事実を述べられる。"}, {"text": "促せ", "is_correct": false, "explanation": "命令形は「促せが」となり、「たが」の前に続かない。"}, {"text": "促し", "is_correct": false, "explanation": "連用形は「促しが」となり、後ろの「が」と続かない。"}, {"text": "促さ", "is_correct": false, "explanation": "未然形は「促さたが」となり、過去の「た」を続けられない。"}], "explanations": {"促した": "過去形。「〜したが」と続けて、働きかけた事実を述べられる。", "促せ": "命令形は「促せが」となり、「たが」の前に続かない。", "促し": "連用形は「促しが」となり、後ろの「が」と続かない。", "促さ": "未然形は「促さたが」となり、過去の「た」を続けられない。"}, "sentence_index": 6, "correct_answer": "促した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は騒いだ生徒の机を促した。", "explanation": "ここは〈片付ける〉の意味。机を片付けるのは片付けで、促すは人に行動を働きかける語なので机には合わない。"}, {"text": "農家は畑の雑草を促した。", "explanation": "ここは〈抜く〉の意味。雑草を抜くのは除去で、促すは働きかける語なので合わない。"}, {"text": "看護師は赤ん坊の体温を促した。", "explanation": "ここは〈測る〉の意味。促すは人に行動を働きかける語で、体温を測る場面では使わないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
