INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38133, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「若者の間に定着する」で、根づく場所を示します。"}, {"text": "を", "is_correct": false, "explanation": "「定着する」は「を」で場所を取れません。"}, {"text": "と", "is_correct": false, "explanation": "「間と定着する」は文として成り立ちません。"}, {"text": "や", "is_correct": false, "explanation": "「間や定着している」は文として成り立ちません。"}], "correct_answer": "に", "explanations": {"に": "「若者の間に定着する」で、根づく場所を示します。", "を": "「定着する」は「を」で場所を取れません。", "と": "「間と定着する」は文として成り立ちません。", "や": "「間や定着している」は文として成り立ちません。"}, "error_tags": {"を": "object_marker", "と": "comitative", "や": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "根づかずに消えることで、「定着」の反対です。"}, {"text": "普及", "is_correct": false, "explanation": "広まることで、「定着」に近い意味です。"}, {"text": "成長", "is_correct": false, "explanation": "育つことで、反対の関係ではありません。"}, {"text": "発表", "is_correct": false, "explanation": "公にすることで、反対の関係ではありません。"}], "correct_answer": "消滅", "explanations": {"消滅": "根づかずに消えることで、「定着」の反対です。", "普及": "広まることで、「定着」に近い意味です。", "成長": "育つことで、反対の関係ではありません。", "発表": "公にすることで、反対の関係ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
