INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38133, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事や状態が、社会や集団の中で広く受け入れられ、一般的なものとして根づくこと。", "primary_collocate": null, "pronunciation": "ていちゃく", "ipa": "teitɕakɯ", "syllable_count": 4, "sentences": [{"text": "この習慣は、地域の人々の間に広く定着している。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "この言葉は、若者の間に定着している。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "新しい制度が社会に定着するまで、時間がかかる。", "target_word": "定着", "complexity_tier": "T4", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "キャッシュレス決済は、日本でも定着した。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "リモートワークの定着で、働き方が大きく変わった。", "target_word": "定着", "complexity_tier": "T4", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "地域に定着した祭りが、毎年多くの人を集める。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "その習慣は、家庭にしっかり定着していった。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "定着には、国民の理解が欠かせない。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "ごみの分別は、町の中で定着しつつある。", "target_word": "定着", "complexity_tier": "T3", "furigana": "ていちゃく", "sentence_source": "generated"}, {"text": "新しい文化が定着するかどうかは、まだ分からない。", "target_word": "定着", "complexity_tier": "T4", "furigana": "ていちゃく", "sentence_source": "generated"}], "morphological_forms": [{"form": "定着する", "label": "活用"}, {"form": "定着した", "label": "活用"}, {"form": "定着させる", "label": "活用"}, {"form": "定着率", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 社会に根づいて広まること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
