INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38133, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その風習は、今も村を定着している。", "corrected_sentence": "その風習は、今も村に定着している。", "error_description": "「定着する」は場所を「に」で示します。「を」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38133, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい働き方は、すでに会社で定着になっている。", "corrected_sentence": "新しい働き方は、すでに会社で定着している。", "error_description": "「定着」は「する」と結びつきます。「定着になる」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「基本ができていない」の主語なので「が」。"}, {"text": "を", "is_correct": false, "explanation": "「基本をができていない」は文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「できていない」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すので、「できていない」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「基本ができていない」の主語なので「が」。", "を": "「基本をができていない」は文が成立しない。", "へ": "「へ」は方向を表すので、「できていない」の主語にはならない。", "と": "「と」は相手や並列を表すので、「できていない」の主語にはならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ピアノの基本は、正しい姿勢で座ることだ」の「は」で、基本について話題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ピアノの基本を」の後に続く他動詞がなく、「を」は文として成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「基本で、正しい姿勢で座ることだ」は手段の意味にならず文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「基本の、正しい姿勢で座ることだ」は、名詞を結ぶ「の」が続かず文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "「ピアノの基本は、正しい姿勢で座ることだ」の「は」で、基本について話題を示す。", "を": "「ピアノの基本を」の後に続く他動詞がなく、「を」は文として成立しない。", "で": "「基本で、正しい姿勢で座ることだ」は手段の意味にならず文が成立しない。", "の": "「基本の、正しい姿勢で座ることだ」は、名詞を結ぶ「の」が続かず文が成立しない。"}, "error_tags": {"を": "目的語", "で": "手段", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、もとになる大事なところ。", "primary_collocate": null, "pronunciation": "きほん", "ipa": "kihoɴ", "syllable_count": 3, "sentences": [{"text": "料理は基本を覚えてから、自分の味を考えるといい。", "target_word": "基本", "complexity_tier": "T3", "furigana": "料理[りょうり]は基本[きほん]を覚[おぼ]えてから、自分[じぶん]の味[あじ]を考[かんが]えるといい。", "sentence_source": "generated"}, {"text": "基本ができていないので、難しい問題は解けない。", "target_word": "基本", "complexity_tier": "T3", "furigana": "基本[きほん]ができていないので、難[むずか]しい問題[もんだい]は解[と]けない。", "sentence_source": "generated"}, {"text": "毎日の基本の練習を休まないことが上達の近道だ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "毎日[まいにち]の基本[きほん]の練習[れんしゅう]を休[やす]まないことが上達[じょうたつ]の近道[ちかみち]だ。", "sentence_source": "generated"}, {"text": "野球の基本を知らない人に、細かいルールを話しても分からない。", "target_word": "基本", "complexity_tier": "T3", "furigana": "野球[やきゅう]の基本[きほん]を知[し]らない人[ひと]に、細[こま]かいルールを話[はな]しても分[わ]からない。", "sentence_source": "generated"}, {"text": "英語は基本から勉強し直したら、少しずつ話せるようになった。", "target_word": "基本", "complexity_tier": "T3", "furigana": "英語[えいご]は基本[きほん]から勉強[べんきょう]し直[なお]したら、少[すこ]しずつ話[はな]せるようになった。", "sentence_source": "generated"}, {"text": "先生は新しい技よりも、まず基本を大切にしなさいと言った。", "target_word": "基本", "complexity_tier": "T3", "furigana": "先生[せんせい]は新[あたら]しい技[わざ]よりも、まず基本[きほん]を大切[たいせつ]にしなさいと言[い]った。", "sentence_source": "generated"}, {"text": "基本を守って運転すれば、事故の危険はぐっと減る。", "target_word": "基本", "complexity_tier": "T3", "furigana": "基本[きほん]を守[まも]って運転[うんてん]すれば、事故[じこ]の危険[きけん]はぐっと減[へ]る。", "sentence_source": "generated"}, {"text": "ピアノの基本は、正しい姿勢で座ることだ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "ピアノの基本[きほん]は、正[ただ]しい姿勢[しせい]で座[すわ]ることだ。", "sentence_source": "generated"}, {"text": "彼は応用は得意だが、基本が弱くて試験で失敗した。", "target_word": "基本", "complexity_tier": "T3", "furigana": "彼[かれ]は応用[おうよう]は得意[とくい]だが、基本[きほん]が弱[よわ]くて試験[しけん]で失敗[しっぱい]した。", "sentence_source": "generated"}, {"text": "絵を描くときの基本は、よく見ることだ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "絵[え]を描[か]くときの基本[きほん]は、よく見[み]ることだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基本", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "何かを身につけたりやったりするときに、まず押さえるべきもとになる大事なこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 休ま (Zipf 3.79), 上達 (Zipf 3.76), 近道 (Zipf 3.46)']::text[], 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本", "is_correct": true, "explanation": "「基本を覚える」で、料理を始めるときの土台となる大事なことを指す。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、「覚えてから」の対象にはならない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時間の時点のことで、料理の土台を表す文脈には合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を届ける制度のことで、覚える対象として文が成立しない。"}], "explanations": {"基本": "「基本を覚える」で、料理を始めるときの土台となる大事なことを指す。", "天気": "天気は空模様のことで、「覚えてから」の対象にはならない。", "時刻": "時刻は時間の時点のことで、料理の土台を表す文脈には合わない。", "郵便": "郵便は手紙や荷物を届ける制度のことで、覚える対象として文が成立しない。"}, "sentence_index": 0, "correct_answer": "基本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この机は基本が大きくて、部屋に入らなかった。", "explanation": "ここは〈大きさ〉の意味。基本は物事の土台や大事な部分で、物の寸法には使わない。"}, {"text": "このカレーは基本が辛くて、子どもは食べられなかった。", "explanation": "ここは〈辛さ〉の意味。基本は味の強さを表さないので、この文では〈辛さ〉と言うべき。"}, {"text": "彼は、マラソンの基本を三時間で走りきった。", "explanation": "ここは〈コース〉の意味。基本は走る道のりを指さないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本", "is_correct": true, "explanation": "「基本を守って運転する」で、交通のもとになる大事な決まりを指す。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分のことで、「守って運転する」の対象にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部のことで、「守って運転する」の対象にはならない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目のことで、「守って運転する」の対象にはならない。"}], "explanations": {"基本": "「基本を守って運転する」で、交通のもとになる大事な決まりを指す。", "季節": "季節は一年の区分のことで、「守って運転する」の対象にはならない。", "窓": "窓は建物の開口部のことで、「守って運転する」の対象にはならない。", "色": "色は見た目のことで、「守って運転する」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "基本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は毎朝、基本を一枚ずつ丁寧に焼いていた。", "explanation": "ここは〈せんべい〉の意味。基本は抽象的な大事な部分で、焼く対象にはならない。"}, {"text": "昨日の基本は、雨で試合が中止になったことだ。", "explanation": "ここは〈出来事〉の意味。基本は物事の土台を指すので、起きたことには使わない。"}, {"text": "この花は、基本が夜に光るので珍しい。", "explanation": "ここは〈特徴〉の意味。基本は土台や大事な部分を表し、花の性質は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日、基本に練習すれば、上達が早い。", "corrected_sentence": "毎日、基本を練習すれば、上達が早い。", "error_description": "「練習する」の目的語は「を」。「基本に練習」の「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38134, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "基本な練習を毎日続けよう。", "corrected_sentence": "基本の練習を毎日続けよう。", "error_description": "「基本」は名詞なので「の」で続ける。「基本な」は誤りで、正しくは「基本の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
