INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38135, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「チームの基本の方針」の後ろの「の」で、基本と方針を結びつける。"}, {"text": "を", "is_correct": false, "explanation": "「基本を方針に合わない」は文が成立せず、「を」は目的語を示すが対象が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すが、「基本で方針に合わない」では文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「方針に合わない」と続かない。"}], "correct_answer": "の", "explanations": {"の": "「チームの基本の方針」の後ろの「の」で、基本と方針を結びつける。", "を": "「基本を方針に合わない」は文が成立せず、「を」は目的語を示すが対象が合わない。", "で": "「で」は手段や場所を表すが、「基本で方針に合わない」では文が成立しない。", "から": "「から」は起点を表すので、「方針に合わない」と続かない。"}, "error_tags": {"を": "目的語", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38135, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の土台や中心となる、もっとも大事な部分。", "primary_collocate": null, "pronunciation": "きほん", "ipa": "kihoɴ", "syllable_count": 3, "sentences": [{"text": "この会社の基本の考え方は、お客様を一番に考えることだ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の基本[きほん]の考[かんが]え方[かた]は、お客様[きゃくさま]を一番[いちばん]に考[かんが]えることだ。", "sentence_source": "generated"}, {"text": "家族を大切にすることが、私の生き方の基本だ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "家族[かぞく]を大切[たいせつ]にすることが、私[わたし]の生[い]き方[かた]の基本[きほん]だ。", "sentence_source": "generated"}, {"text": "民主主義の基本は、みんなの意見を聞くことだ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "民主主義[みんしゅしゅぎ]の基本[きほん]は、みんなの意見[いけん]を聞[き]くことだ。", "sentence_source": "generated"}, {"text": "計画の基本が決まったので、細かい部分は後で相談しよう。", "target_word": "基本", "complexity_tier": "T3", "furigana": "計画[けいかく]の基本[きほん]が決[き]まったので、細[こま]かい部分[ぶぶん]は後[あと]で相談[そうだん]しよう。", "sentence_source": "generated"}, {"text": "約束を守ることは、人と付き合う基本だ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]ることは、人[ひと]と付[つ]き合[あ]う基本[きほん]だ。", "sentence_source": "generated"}, {"text": "契約書は、すべての取引の基本になる大切な書類だ。", "target_word": "基本", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]は、すべての取引[とりひき]の基本[きほん]になる大切[たいせつ]な書類[しょるい]だ。", "sentence_source": "generated"}, {"text": "基本を変えずに、デザインだけを新しくした。", "target_word": "基本", "complexity_tier": "T3", "furigana": "基本[きほん]を変[か]えずに、デザインだけを新[あたら]しくした。", "sentence_source": "generated"}, {"text": "チームの基本の方針に合わない提案は、受け入れられなかった。", "target_word": "基本", "complexity_tier": "T3", "furigana": "チームの基本[きほん]の方針[ほうしん]に合[あ]わない提案[ていあん]は、受[う]け入[い]れられなかった。", "sentence_source": "generated"}, {"text": "健康の基本は、よく食べてよく眠ることだと思う。", "target_word": "基本", "complexity_tier": "T3", "furigana": "健康[けんこう]の基本[きほん]は、よく食[た]べてよく眠[ねむ]ることだと思[おも]う。", "sentence_source": "generated"}, {"text": "学校の基本のルールは、入学式の日に説明される。", "target_word": "基本", "complexity_tier": "T3", "furigana": "学校[がっこう]の基本[きほん]のルールは、入学式[にゅうがくしき]の日[ひ]に説明[せつめい]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基本", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "考え方や決まりなど、物事全体の土台や中心になるもっとも大事な部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本", "is_correct": true, "explanation": "「会社の基本の考え方」で、会社の土台となる大事な考え方を指す。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履き物のことで、「考え方」を修飾する意味にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分のことで、「考え方」の修飾にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、「考え方」の修飾にはならない。"}], "explanations": {"基本": "「会社の基本の考え方」で、会社の土台となる大事な考え方を指す。", "靴": "靴は履き物のことで、「考え方」を修飾する意味にはならない。", "季節": "季節は一年の区分のことで、「考え方」の修飾にはならない。", "天気": "天気は空模様のことで、「考え方」の修飾にはならない。"}, "sentence_index": 0, "correct_answer": "基本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい店長の基本が決まったので、来月から働く。", "explanation": "ここは〈担当〉の意味。基本は物事の中心や土台で、人の役割を表す意味では使わない。"}, {"text": "彼女の基本は、とても明るく親切だ。", "explanation": "ここは〈性格〉の意味。基本は物事の土台を表し、人の性格は指さない。"}, {"text": "旅行の天気は、来週の金曜日に決まった。", "explanation": "天気は決めるものではなく、基本の意味では成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本", "is_correct": true, "explanation": "「基本を変えずに」で、デザイン以外の土台となる部分を指す。"}, {"text": "天気", "is_correct": false, "explanation": "天気は変えたり直したりする対象ではなく、文が成立しない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を届ける制度のことで、「変えずに」の対象にはならない。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は汚れを取ることで、「変えずに」の対象にはならない。"}], "explanations": {"基本": "「基本を変えずに」で、デザイン以外の土台となる部分を指す。", "天気": "天気は変えたり直したりする対象ではなく、文が成立しない。", "郵便": "郵便は手紙や荷物を届ける制度のことで、「変えずに」の対象にはならない。", "掃除": "掃除は汚れを取ることで、「変えずに」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "基本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝の基本は、マイナス三度だった。", "explanation": "ここは〈気温〉の意味。基本は物事の土台や大事な部分で、気温の数値を指す意味ではない。"}, {"text": "息子の基本は、もう百七十センチだ。", "explanation": "ここは〈身長〉の意味。基本は土台や中心を表し、身長の数値は指さない。"}, {"text": "この電池の基本を、一本ずつ丁寧に袋に詰めた。", "explanation": "ここは〈部品〉の意味。基本は物事の中心となる大事な部分で、物として袋に詰めるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38135, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行の基本が決めたので、ホテルを探そう。", "corrected_sentence": "旅行の基本が決まったので、ホテルを探そう。", "error_description": "「基本」が主語なので、自動詞の「決まる」を使う。「決めた」は他動詞で、正しくは「決まった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38135, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の基本を決まったので、細かい部分は後で話す。", "corrected_sentence": "会議の基本が決まったので、細かい部分は後で話す。", "error_description": "「決まる」の主語は「が」で示す。「基本を決まった」の「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
