INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38136, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「ほとんど」という意味で、全部ではないけれど、とても近いことを言う言葉です。", "primary_collocate": null, "pronunciation": "ほとんど", "ipa": "hotoɴdo", "syllable_count": 4, "sentences": [{"text": "教室の生徒は殆ど帰って、残っているのは三人だけだ。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の生徒[せいと]は殆[ほとん]ど帰[かえ]って、残[のこ]っているのは三人[さんにん]だけだ。", "sentence_source": "generated"}, {"text": "宿題は殆ど終わったので、あとは作文だけだ。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]は殆[ほとん]ど終[お]わったので、あとは作文[さくぶん]だけだ。", "sentence_source": "generated"}, {"text": "町の店は殆ど閉まっていて、夜は静かだった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "町[まち]の店[みせ]は殆[ほとん]ど閉[し]まっていて、夜[よる]は静[しず]かだった。", "sentence_source": "generated"}, {"text": "貯金は殆ど使ってしまい、来月の生活が心配だ。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "貯金[ちょきん]は殆[ほとん]ど使[つか]ってしまい、来月[らいげつ]の生活[せいかつ]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "箱の中のりんごは殆ど腐っていた。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]のりんごは殆[ほとん]ど腐[くさ]っていた。", "sentence_source": "generated"}, {"text": "部屋の荷物は殆ど運び終えた。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "部屋[へや]の荷物[にもつ]は殆[ほとん]ど運[はこ]び終[お]えた。", "sentence_source": "generated"}, {"text": "クラスの友達の殆どが、あの映画を見たそうだ。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "クラスの友達[ともだち]の殆[ほとん]どが、あの映画[えいが]を見[み]たそうだ。", "sentence_source": "generated"}, {"text": "殆どの人が賛成したが、一人だけ反対した。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "殆[ほとん]どの人[ひと]が賛成[さんせい]したが、一人[ひとり]だけ反対[はんたい]した。", "sentence_source": "generated"}, {"text": "今年の夏休みは殆ど毎日、プールに通った。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "今年[ことし]の夏休[なつやす]みは殆[ほとん]ど毎日[まいにち]、プールに通[かよ]った。", "sentence_source": "generated"}, {"text": "冷蔵庫の中の野菜は殆ど食べてしまった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の中[なか]の野菜[やさい]は殆[ほとん]ど食[た]べてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "殆ど", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "全部ではないが、それに近いほどの大部分を表す（人や物の数・量）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全て", "is_correct": false, "explanation": "「全て」は例外なく全部という意味。全員が帰ったなら残りが三人になるはずがなく、文が矛盾する。"}, {"text": "殆ど", "is_correct": true, "explanation": "ここは「ほとんど」の意味。「残っているのは三人だけ」と続くので、大部分が帰ったことを表す。"}, {"text": "必ず", "is_correct": false, "explanation": "「必ず」は確実・例外なしの意味。大部分が帰った状況を表せず、残りの人数の文と合わない。"}, {"text": "初めて", "is_correct": false, "explanation": "「初めて」は最初に、の意味。帰った順番を表すだけで、大部分が帰ったことは表せない。"}], "explanations": {"全て": "「全て」は例外なく全部という意味。全員が帰ったなら残りが三人になるはずがなく、文が矛盾する。", "殆ど": "ここは「ほとんど」の意味。「残っているのは三人だけ」と続くので、大部分が帰ったことを表す。", "必ず": "「必ず」は確実・例外なしの意味。大部分が帰った状況を表せず、残りの人数の文と合わない。", "初めて": "「初めて」は最初に、の意味。帰った順番を表すだけで、大部分が帰ったことは表せない。"}, "sentence_index": 0, "correct_answer": "殆ど"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その服は殆ど高くて、買えなかった。", "explanation": "ここは「とても」（程度が非常に高い）の意味。殆ど は「ほぼ」なので、程度の極端な強さは表せない。"}, {"text": "試験は殆ど合格した。", "explanation": "ここは合否のように二つに一つで決まる結果の話。殆ど は程度や大部分を表す副詞なので、合格か不合格かを決める文には使わない。"}, {"text": "駅には殆ど五時頃に着いた。", "explanation": "ここは「大体」（おおよそ）の意味。殆ど は「ほぼ・大部分」の意味なので、時刻の見積もりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ずっと", "is_correct": false, "explanation": "「ずっと」は長く続く時間を表す副詞。「友達のずっとが」と名詞につながらず、この空所には入らない。"}, {"text": "時々", "is_correct": false, "explanation": "「時々」は時たま起こる頻度を表す副詞。「友達の時々が」と名詞につながらず、文が成り立たない。"}, {"text": "きっと", "is_correct": false, "explanation": "「きっと」は確信を表す副詞。「友達のきっとが」と名詞につながらず、この空所には入らない。"}, {"text": "殆ど", "is_correct": true, "explanation": "ここは「殆ど」（大部分）の意味。「友達の殆どが映画を見た」で、友達の大部分が見たことを表す。"}], "explanations": {"ずっと": "「ずっと」は長く続く時間を表す副詞。「友達のずっとが」と名詞につながらず、この空所には入らない。", "時々": "「時々」は時たま起こる頻度を表す副詞。「友達の時々が」と名詞につながらず、文が成り立たない。", "きっと": "「きっと」は確信を表す副詞。「友達のきっとが」と名詞につながらず、この空所には入らない。", "殆ど": "ここは「殆ど」（大部分）の意味。「友達の殆どが映画を見た」で、友達の大部分が見たことを表す。"}, "sentence_index": 6, "correct_answer": "殆ど"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車は殆ど十時に着いた。", "explanation": "ここは「ちょうど」（ぴったり）の意味。殆ど は「ほぼ」なので、時刻をぴったり指す場面では使わない。"}, {"text": "その店には殆ど行ったことがある。", "explanation": "ここは「一度」（一回）の意味。殆ど は「ほぼ」で、回数が一回だと示す場面には使わない。"}, {"text": "この駅には殆ど来たのは今日が初めてだ。", "explanation": "ここは一回きりの経験を述べる場面（来た回数を言う文）。殆ど は程度の副詞なので、回数が一度きりだと示す文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ケーキは殆どの食べ終えたが、一つだけ残っている。", "corrected_sentence": "ケーキは殆ど食べ終えたが、一つだけ残っている。", "error_description": "「殆どの食べ終えた」は「殆どの」の後に名詞が必要なのに動詞が続くため誤り。副詞として動詞に直接つなげ、「殆ど食べ終えた」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "時間が経ったので、話の内容は殆ど忘れたない。", "corrected_sentence": "時間が経ったので、話の内容は殆ど忘れた。", "error_description": "「忘れた」の後に「ない」を付けた「忘れたない」は活用の誤り。過去形は「忘れた」が正しく、否定にするなら「忘れなかった」となる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
