INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38137, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38137, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "物事の大部分がそうである様子。数量や程度が、完全ではないが、それに近い状態を表す副詞。", "primary_collocate": null, "pronunciation": "ほとんど", "ipa": "hotoɴdo", "syllable_count": 4, "sentences": [{"text": "殆ど雨は降らなかったので、畑の土が乾いてしまった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "殆[ほとん]ど雨[あめ]は降[ふ]らなかったので、畑[はたけ]の土[つち]が乾[かわ]いてしまった。", "sentence_source": "generated"}, {"text": "寝不足で、会議の内容は殆ど覚えていない。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]で、会議[かいぎ]の内容[ないよう]は殆[ほとん]ど覚[おぼ]えていない。", "sentence_source": "generated"}, {"text": "山道は暗くて、足元が殆ど見えなかった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "山道[やまみち]は暗[くら]くて、足元[あしもと]が殆[ほとん]ど見[み]えなかった。", "sentence_source": "generated"}, {"text": "吹雪の中を歩いたが、視界が悪くて殆ど前に進めなかった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "吹雪[ふぶき]の中[なか]を歩[ある]いたが、視界[しかい]が悪[わる]くて殆[ほと]ど前[まえ]に進[すす]めなかった。", "sentence_source": "generated"}, {"text": "彼の日本語は殆ど完璧で、外国人とは思えない。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "彼[かれ]の日本語[にほんご]は殆[ほとん]ど完璧[かんぺき]で、外国人[がいこくじん]とは思[おも]えない。", "sentence_source": "generated"}, {"text": "試験の問題が難しくて、殆ど答えられなかった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "試験[しけん]の問題[もんだい]が難[むずか]しくて、殆[ほとん]ど答[こた]えられなかった。", "sentence_source": "generated"}, {"text": "病気になってから、運動は殆どしていない。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "病気[びょうき]になってから、運動[うんどう]は殆[ほとん]どしていない。", "sentence_source": "generated"}, {"text": "二人の意見は殆ど同じなので、話し合いはすぐ終わった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "二人[ふたり]の意見[いけん]は殆[ほとん]ど同[おな]じなので、話[はな]し合[あ]いはすぐ終[お]わった。", "sentence_source": "generated"}, {"text": "長い坂を登り続けて、体力が殆ど残っていなかった。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "長[なが]い坂[さか]を登[のぼ]り続[つづ]けて、体力[たいりょく]が殆[ほと]ど残[のこ]っていなかった。", "sentence_source": "generated"}, {"text": "外が静かで、車の音は殆ど聞こえない。", "target_word": "殆ど", "complexity_tier": "T3", "furigana": "外[そと]が静[しず]かで、車[くるま]の音[おと]は殆[ほとん]ど聞[き]こえない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "殆ど", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "程度や状態が完全に近いこと。否定と使うと「ほぼ〜ない」の意味になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38137, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必ず", "is_correct": false, "explanation": "「必ず」は例外なく確実にの意味。否定と続けると「必ずしも〜ない」になり、「必ず雨は降らなかった」は不自然で入らない。"}, {"text": "殆ど", "is_correct": true, "explanation": "ここは「殆ど」（ほぼ〜ない）の用法。雨がほとんど降らなかったので畑の土が乾いた、と続く。"}, {"text": "初めて", "is_correct": false, "explanation": "「初めて」は最初に、の意味。「初めて雨は降らなかった」は意味が通らず、畑の乾燥にもつながらない。"}, {"text": "やっと", "is_correct": false, "explanation": "「やっと」は長く待ったあとに、の意味。「やっと雨は降らなかった」では前後の畑の乾きとつながらず不自然。"}], "explanations": {"必ず": "「必ず」は例外なく確実にの意味。否定と続けると「必ずしも〜ない」になり、「必ず雨は降らなかった」は不自然で入らない。", "殆ど": "ここは「殆ど」（ほぼ〜ない）の用法。雨がほとんど降らなかったので畑の土が乾いた、と続く。", "初めて": "「初めて」は最初に、の意味。「初めて雨は降らなかった」は意味が通らず、畑の乾燥にもつながらない。", "やっと": "「やっと」は長く待ったあとに、の意味。「やっと雨は降らなかった」では前後の畑の乾きとつながらず不自然。"}, "sentence_index": 0, "correct_answer": "殆ど"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "そのケーキは殆ど甘くて、食べられなかった。", "explanation": "ここは「とても」（程度が非常に高い）の意味。殆ど は「ほぼ」なので、程度の極端な強さは表せない。"}, {"text": "会議は殆ど三時頃に終わった。", "explanation": "ここは「大体」（おおよそ）の意味。殆ど は「ほぼ」の意味なので、時刻の見積もりには使わない。"}, {"text": "彼は殆ど優勝した。", "explanation": "ここは優勝のような二つに一つの結果の話。殆ど は程度や大部分を表す副詞なので、勝ち負けを決める結果には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38137, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一斉に", "is_correct": false, "explanation": "「一斉に」は多くの人が同時に、の意味。運動を同時にするかどうかの話になり、病気の後の文脈に合わない。"}, {"text": "さっそく", "is_correct": false, "explanation": "「さっそく」は間を置かずすぐにの意味。病気になってからの話とつながらず、文が不自然。"}, {"text": "殆ど", "is_correct": true, "explanation": "ここは「殆ど」（ほぼ〜ない）の意味。病気になってから運動はほとんどしていない、と続く。"}, {"text": "大急ぎで", "is_correct": false, "explanation": "「大急ぎで」は急いでの意味。運動を急いでしないという意味になり、病気の後の文脈に合わない。"}], "explanations": {"一斉に": "「一斉に」は多くの人が同時に、の意味。運動を同時にするかどうかの話になり、病気の後の文脈に合わない。", "さっそく": "「さっそく」は間を置かずすぐにの意味。病気になってからの話とつながらず、文が不自然。", "殆ど": "ここは「殆ど」（ほぼ〜ない）の意味。病気になってから運動はほとんどしていない、と続く。", "大急ぎで": "「大急ぎで」は急いでの意味。運動を急いでしないという意味になり、病気の後の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "殆ど"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合は殆ど七時に始まった。", "explanation": "ここは「ちょうど」（ぴったり）の意味。殆ど は「ほぼ」なので、時刻をぴったり指す場面では使わない。"}, {"text": "その映画は殆ど面白い。", "explanation": "ここは「最も」（程度が最上）の意味。殆ど は「ほぼ」で、程度の最高を表す場面には使わない。"}, {"text": "この駅に殆ど来たのは今日が初めてだ。", "explanation": "ここは一回きりの経験を述べる場面（来た回数を言う文）。殆ど は程度の副詞なので、回数が一度きりだと示す文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38137, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海は荒れていて、船は殆ど出られないかった。", "corrected_sentence": "海は荒れていて、船は殆ど出られなかった。", "error_description": "否定の過去形は「出られなかった」。「出られないかった」は活用の誤りで、「殆ど」の後の動詞が壊れている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38137, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝不足で、授業の内容は殆どに頭に入らなかった。", "corrected_sentence": "寝不足で、授業の内容は殆ど頭に入らなかった。", "error_description": "副詞の「殆ど」の直後に「に」を付けた「殆どに」は誤り。助詞を付けず「殆ど頭に入らなかった」とするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "ここは「変更になった」の「に」。変更という状態に変わったことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「変更を」の後に「なった」が続くと文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「変更で」では「なった」と続かず、この文の形に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する助詞。「変更の」の後に「なった」が続くと名詞句が成り立たず、文として不成立。"}], "correct_answer": "に", "explanations": {"に": "ここは「変更になった」の「に」。変更という状態に変わったことを表す。", "を": "「を」は目的語を表すが、「変更を」の後に「なった」が続くと文が成り立たない。", "で": "「で」は場所や手段を表す。「変更で」では「なった」と続かず、この文の形に合わない。", "の": "「の」は名詞を修飾する助詞。「変更の」の後に「なった」が続くと名詞句が成り立たず、文として不成立。"}, "error_tags": {"を": "目的語（〜になる形に合わない）", "で": "場所・手段（結果の状態を表さない）", "の": "名詞修飾（名詞句が成り立たない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「名前が変更した」では他動詞の変更と合わず、文が成り立たない。"}, {"text": "を", "is_correct": true, "explanation": "ここは「名前を変更した」の「を」。変更の目的語を示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「名前で変更した」では目的語が示されず、文の意味に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。「名前より変更した」では比べる対象が合わず、この文には入らない。"}], "correct_answer": "を", "explanations": {"が": "「が」は主語を示す。「名前が変更した」では他動詞の変更と合わず、文が成り立たない。", "を": "ここは「名前を変更した」の「を」。変更の目的語を示す。", "で": "「で」は手段や場所を表す。「名前で変更した」では目的語が示されず、文の意味に合わない。", "より": "「より」は比較を表す。「名前より変更した」では比べる対象が合わず、この文には入らない。"}, "error_tags": {"が": "主語（変更の目的語にならない）", "で": "手段・場所（目的語を示さない）", "より": "比較（比べる対象がない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "前とは別のものにすること。", "primary_collocate": null, "pronunciation": "へんこう", "ipa": "heŋkoː", "syllable_count": 4, "sentences": [{"text": "台風のため、旅行の日にちを変更することにした。", "target_word": "変更", "complexity_tier": "T3", "furigana": "台風[たいふう]のため、旅行[りょこう]の日[ひ]にちを変更[へんこう]することにした。", "sentence_source": "generated"}, {"text": "会議の場所が変更になったと、先生から連絡があった。", "target_word": "変更", "complexity_tier": "T3", "furigana": "会議[かいぎ]の場所[ばしょ]が変更[へんこう]になったと、先生[せんせい]から連絡[れんらく]があった。", "sentence_source": "generated"}, {"text": "急に予定を変更したので、友達に謝った。", "target_word": "変更", "complexity_tier": "T3", "furigana": "急[きゅう]に予定[よてい]を変更[へんこう]したので、友達[ともだち]に謝[あやま]った。", "sentence_source": "generated"}, {"text": "住所を変更したら、役所に届けを出さなければならない。", "target_word": "変更", "complexity_tier": "T3", "furigana": "住所[じゅうしょ]を変更[へんこう]したら、役所[やくしょ]に届[とど]けを出[だ]さなければならない。", "sentence_source": "generated"}, {"text": "計画の変更は、みんなで相談してから決めよう。", "target_word": "変更", "complexity_tier": "T3", "furigana": "計画[けいかく]の変更[へんこう]は、みんなで相談[そうだん]してから決[き]めよう。", "sentence_source": "generated"}, {"text": "天気が悪いので、遠足は来週に変更された。", "target_word": "変更", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]いので、遠足[えんそく]は来週[らいしゅう]に変更[へんこう]された。", "sentence_source": "generated"}, {"text": "予約を変更したい人は、前の日までに電話する決まりだ。", "target_word": "変更", "complexity_tier": "T3", "furigana": "予約[よやく]を変更[へんこう]したい人[ひと]は、前[まえ]の日[ひ]までに電話[でんわ]する決[き]まりだ。", "sentence_source": "generated"}, {"text": "店の名前を変更したが、客は前の名前で呼んでいる。", "target_word": "変更", "complexity_tier": "T3", "furigana": "店[みせ]の名前[なまえ]を変更[へんこう]したが、客[きゃく]は前[まえ]の名前[なまえ]で呼[よ]んでいる。", "sentence_source": "generated"}, {"text": "試合の時間が変更されて、私は少し遅れて着いた。", "target_word": "変更", "complexity_tier": "T3", "furigana": "試合[しあい]の時間[じかん]が変更[へんこう]されて、私[わたし]は少[すこ]し遅[おく]れて着[つ]いた。", "sentence_source": "generated"}, {"text": "彼は進学先を変更して、別の大学を受けることにした。", "target_word": "変更", "complexity_tier": "T3", "furigana": "彼[かれ]は進学先[しんがくさき]を変更[へんこう]して、別[べつ]の大学[だいがく]を受[う]けることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変更", "label": "基本形"}, {"form": "変更する", "label": "辞書形"}, {"form": "変更した", "label": "過去形"}, {"form": "変更される", "label": "受身形"}], "register": "中立（普通体）", "sense_fingerprint": "予定・場所・日時など、決まっていたものを別のものに替えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変身", "is_correct": false, "explanation": "「変身」は姿や正体が別のものに変わること。日にちは姿を変える対象ではないので、この文には入らない。"}, {"text": "変更", "is_correct": true, "explanation": "ここは「変更」（前とは別のものにすること）の意味。旅行の日にちを改める、の意味で文が通る。"}, {"text": "変換", "is_correct": false, "explanation": "「変換」は別の形式に換えること。日にちを形式換えするという意味になり、この文の内容と合わない。"}, {"text": "変色", "is_correct": false, "explanation": "「変色」は色が変わること。日にちは色を持たないので、この文には入らない。"}], "explanations": {"変身": "「変身」は姿や正体が別のものに変わること。日にちは姿を変える対象ではないので、この文には入らない。", "変更": "ここは「変更」（前とは別のものにすること）の意味。旅行の日にちを改める、の意味で文が通る。", "変換": "「変換」は別の形式に換えること。日にちを形式換えするという意味になり、この文の内容と合わない。", "変色": "「変色」は色が変わること。日にちは色を持たないので、この文には入らない。"}, "sentence_index": 0, "correct_answer": "変更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "季節が変更して、木の葉は赤くなった。", "explanation": "ここは「変化」（自然に少しずつ変わる）の意味。変更は人が決めて改める場合に使い、季節の移り変わりには合わない。"}, {"text": "誤字を変更して、正しい表記にした。", "explanation": "ここは「修正」（直すこと）の意味。変更は別のものに替える意味で、誤りを直す場面には合わない。"}, {"text": "彼は性格を変更して、すっかり明るくなった。", "explanation": "ここは「変わる・改める」（自分で性格が変わる）の意味。変更は計画や規則を別のものに替える場合に使い、人の性格には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変形", "is_correct": false, "explanation": "「変形」は形が変わること。予約を形として変える意味になり、この文の内容とは合わない。"}, {"text": "変調", "is_correct": false, "explanation": "「変調」は音や信号の調子を変えること。予約には使わず、この文には入らない。"}, {"text": "変更", "is_correct": true, "explanation": "ここは「変更」（前の予約を別の内容に改める）の意味。予約を改めたい人は前日までに電話する、と続く。"}, {"text": "変速", "is_correct": false, "explanation": "「変速」は速度や段を切り替えること。予約には使わず、この文には入らない。"}], "explanations": {"変形": "「変形」は形が変わること。予約を形として変える意味になり、この文の内容とは合わない。", "変調": "「変調」は音や信号の調子を変えること。予約には使わず、この文には入らない。", "変更": "ここは「変更」（前の予約を別の内容に改める）の意味。予約を改めたい人は前日までに電話する、と続く。", "変速": "「変速」は速度や段を切り替えること。予約には使わず、この文には入らない。"}, "sentence_index": 6, "correct_answer": "変更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い電池を変更して、新しいものに替えた。", "explanation": "ここは「交換」（同じ種類のものを替える）の意味。変更は内容や方針を改める意味で、物を入れ替える場面には使わない。"}, {"text": "彼女は気持ちを変更して、すぐ笑った。", "explanation": "ここは「心が変わる」（心の状態が変化する）の意味。変更は計画や規則など内容を改める場合に使い、人の心には使わない。"}, {"text": "財産を変更して、子どもたちに配った。", "explanation": "ここは「分配する」（いくつかに分けて配る）の意味。変更は内容や状態を改める意味で、物を配る場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行の予定を変更きたので、ホテルも取り直した。", "corrected_sentence": "旅行の予定を変更したので、ホテルも取り直した。", "error_description": "「変更」に続く動詞は「する」の連用形「し」＋「た」。「変更きた」は活用の誤りで、正しくは「変更したので」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38138, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予約を変更しるなら、前日までに連絡してください。", "corrected_sentence": "予約を変更するなら、前日までに連絡してください。", "error_description": "「変更」に続く「する」の活用が誤り。「しる」は活用形として成り立たず、正しくは「変更するなら」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "ここは「内容を変更する」の「を」。変更の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「内容が変更するには」では他動詞の変更と合わず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「内容で変更する」では目的語が示されず、文の意味に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。「内容より変更する」では比べる対象が合わず、この文には入らない。"}], "correct_answer": "を", "explanations": {"を": "ここは「内容を変更する」の「を」。変更の目的語を示す。", "が": "「が」は主語を示す。「内容が変更するには」では他動詞の変更と合わず、文が成り立たない。", "で": "「で」は手段や場所を表す。「内容で変更する」では目的語が示されず、文の意味に合わない。", "より": "「より」は比較を表す。「内容より変更する」では比べる対象が合わず、この文には入らない。"}, "error_tags": {"が": "主語（変更の目的語にならない）", "で": "手段・場所（目的語を示さない）", "より": "比較（比べる対象がない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "ここは「後から変更できない」の「から」。後の時点から変えられないという意味を表す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞の連体修飾。「後の変更できない」では修飾すべき名詞が続かず、文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「後が変更できない」では主語と述語が合わず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列を表す。「後と変更できない」では意味がつながらず、この文には入らない。"}], "correct_answer": "から", "explanations": {"から": "ここは「後から変更できない」の「から」。後の時点から変えられないという意味を表す。", "の": "「の」は名詞の連体修飾。「後の変更できない」では修飾すべき名詞が続かず、文として成り立たない。", "が": "「が」は主語を示す。「後が変更できない」では主語と述語が合わず、文が成り立たない。", "と": "「と」は引用や並列を表す。「後と変更できない」では意味がつながらず、この文には入らない。"}, "error_tags": {"が": "主語（述語と合わない）", "と": "引用・並列（意味がつながらない）", "の": "名詞修飾（後に名詞がなく不成立）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を別の状態や内容に改めること。", "primary_collocate": null, "pronunciation": "へんこう", "ipa": "heŋkoː", "syllable_count": 4, "sentences": [{"text": "パスワードを変更しておかないと、不正に使われる心配がある。", "target_word": "変更", "complexity_tier": "T3", "furigana": "パスワードを変更[へんこう]しておかないと、不正[ふせい]に使[つか]われる心配[しんぱい]がある。", "sentence_source": "generated"}, {"text": "契約の内容を変更するには、双方の許可が必要だ。", "target_word": "変更", "complexity_tier": "T3", "furigana": "契約[けいやく]の内容[ないよう]を変更[へんこう]するには、双方[そうほう]の許可[きょか]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "画面の設定を変更したら、文字が大きく見やすくなった。", "target_word": "変更", "complexity_tier": "T3", "furigana": "画面[がめん]の設定[せってい]を変更[へんこう]したら、文字[もじ]が大[おお]きく見[み]やすくなった。", "sentence_source": "generated"}, {"text": "変更した部分は、赤い字で書いておく。", "target_word": "変更", "complexity_tier": "T3", "furigana": "変更[へんこう]した部分[ぶぶん]は、赤[あか]い字[じ]で書[か]いておく。", "sentence_source": "generated"}, {"text": "書類の名前に間違いがあったので、変更の手続きをした。", "target_word": "変更", "complexity_tier": "T3", "furigana": "書類[しょるい]の名前[なまえ]に間違[まちが]いがあったので、変更[へんこう]の手続[てつづ]きをした。", "sentence_source": "generated"}, {"text": "規則の変更は、全員に知らせてから実施される。", "target_word": "変更", "complexity_tier": "T3", "furigana": "規則[きそく]の変更[へんこう]は、全員[ぜんいん]に知[し]らせてから実施[じっし]される。", "sentence_source": "generated"}, {"text": "メニューの一部を変更して、新しい料理を加えた。", "target_word": "変更", "complexity_tier": "T3", "furigana": "メニューの一部[いちぶ]を変更[へんこう]して、新[あたら]しい料理[りょうり]を加[くわ]えた。", "sentence_source": "generated"}, {"text": "一度出した申込書の内容は、後から変更できない。", "target_word": "変更", "complexity_tier": "T3", "furigana": "一度[いちど]出[だ]した申込書[もうしこみしょ]の内容[ないよう]は、後[あと]から変更[へんこう]できない。", "sentence_source": "generated"}, {"text": "席の変更を頼んだが、満席で断られた。", "target_word": "変更", "complexity_tier": "T3", "furigana": "席[せき]の変更[へんこう]を頼[たの]んだが、満席[まんせき]で断[ことわ]られた。", "sentence_source": "generated"}, {"text": "変更の理由が説明されなかったので、社員は不満を持った。", "target_word": "変更", "complexity_tier": "T3", "furigana": "変更[へんこう]の理由[りゆう]が説明[せつめい]されなかったので、社員[しゃいん]は不満[ふまん]を持[も]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変更", "label": "基本形"}, {"form": "変更する", "label": "辞書形"}, {"form": "変更した", "label": "過去形"}, {"form": "変更できない", "label": "可能否定形"}], "register": "中立（普通体）", "sense_fingerprint": "設定・規則・契約など、内容や状態を改めて別のものにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdb59fc6-234a-4954-a9bd-1c955e4429c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変装", "is_correct": false, "explanation": "「変装」は姿を偽ること。パスワードを偽る意味になり、設定を改める文脈に合わない。"}, {"text": "変速", "is_correct": false, "explanation": "「変速」は速度や段を切り替えること。パスワードには合わず、文が通らない。"}, {"text": "変調", "is_correct": false, "explanation": "「変調」は音や信号の調子を変えること。パスワードには使わず、この文には入らない。"}, {"text": "変更", "is_correct": true, "explanation": "ここは「変更」（設定を改めて別のものにする）の意味。パスワードを改めておかないと心配がある、と続く。"}], "explanations": {"変装": "「変装」は姿を偽ること。パスワードを偽る意味になり、設定を改める文脈に合わない。", "変速": "「変速」は速度や段を切り替えること。パスワードには合わず、文が通らない。", "変調": "「変調」は音や信号の調子を変えること。パスワードには使わず、この文には入らない。", "変更": "ここは「変更」（設定を改めて別のものにする）の意味。パスワードを改めておかないと心配がある、と続く。"}, "sentence_index": 0, "correct_answer": "変更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物の重さを変更して、中身を確かめた。", "explanation": "ここは「確認」（中身を調べる）の意味。変更は内容や状態を改める意味で、調べて確かめる場面には使わない。"}, {"text": "表情を変更して、にっこり笑った。", "explanation": "ここは「顔つきを変える」（表情が変化する）の意味。変更は設定や規則などの内容を改める場合に使い、人の表情には使わない。"}, {"text": "机の上を変更して、すっきりさせた。", "explanation": "ここは「整理」（散らかったものを片づける）の意味。変更は別のものに替える意味で、片づける場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変身", "is_correct": false, "explanation": "「変身」は姿や正体が別のものに変わること。メニューの一部が姿を変える意味になり、この文の内容と合わない。"}, {"text": "変色", "is_correct": false, "explanation": "「変色」は色が変わること。メニューの一部の色だけを変える意味になり、料理を加える文脈に合わない。"}, {"text": "変更", "is_correct": true, "explanation": "ここは「変更」（内容や状態を改める）の意味。メニューの一部を改めて新しい料理を加えた、と続く。"}, {"text": "変転", "is_correct": false, "explanation": "「変転」は次々と移り変わること。メニューの一部を変える意味にはならず、この文には入らない。"}], "explanations": {"変身": "「変身」は姿や正体が別のものに変わること。メニューの一部が姿を変える意味になり、この文の内容と合わない。", "変色": "「変色」は色が変わること。メニューの一部の色だけを変える意味になり、料理を加える文脈に合わない。", "変更": "ここは「変更」（内容や状態を改める）の意味。メニューの一部を改めて新しい料理を加えた、と続く。", "変転": "「変転」は次々と移り変わること。メニューの一部を変える意味にはならず、この文には入らない。"}, "sentence_index": 6, "correct_answer": "変更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達は誕生日を変更して、皆で大笑いした。", "explanation": "ここは「祝う」（お祝いする）の意味。変更は内容や状態を改める意味で、お祝いの場面には使わない。"}, {"text": "答案を変更して、点数を付けた。", "explanation": "ここは「採点」（点数を付ける）の意味。変更は別のものに替える意味で、点数を付ける場面には使わない。"}, {"text": "天気を変更して、傘を買った。", "explanation": "ここは「気象を操作する」（天気を人の手で変える）の意味。変更は人が決めた内容を改める意味で、自然の現象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "規則の内容を変更しには、全員の同意が必要だ。", "corrected_sentence": "規則の内容を変更するには、全員の同意が必要だ。", "error_description": "「変更」に続く「する」の活用が誤り。「変更しには」は「変更するには」の形でなければならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38139, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の規則を変更すたので、社員に説明があった。", "corrected_sentence": "会社の規則を変更したので、社員に説明があった。", "error_description": "「変更」に続く動詞の過去形は「変更した」。「変更すた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c321f65-53a4-45ca-90e7-5b4e579881d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「寿命」が「長い」の主語になる「が」で、ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」になり、「寿命を長い」と続かないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置・帰着の「に」になり、「寿命に長い」とは続かないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」になり、「寿命で長い」と続かないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「寿命」が「長い」の主語になる「が」で、ここに合う。", "を": "目的語の「を」になり、「寿命を長い」と続かないので合わない。", "に": "位置・帰着の「に」になり、「寿命に長い」とは続かないので合わない。", "で": "手段・場所の「で」になり、「寿命で長い」と続かないので合わない。"}, "error_tags": {"を": "目的語", "に": "位置・帰着", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や生き物が、長く使えたり生き続けたりする期間のこと。", "primary_collocate": null, "pronunciation": "じゅみょう", "ipa": "dʑɯmʲoː", "syllable_count": 3, "sentences": [{"text": "この電池は寿命が長いので、何か月も使えます。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "この電池[でんち]は寿命[じゅみょう]が長[なが]いので、何[なん]か月[げつ]も使[つか]えます。", "sentence_source": "generated"}, {"text": "犬の寿命は、種類によって少し違います。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "犬[いぬ]の寿命[じゅみょう]は、種類[しゅるい]によって少[すこ]し違[ちが]います。", "sentence_source": "generated"}, {"text": "古い冷蔵庫の寿命が来て、新しいのを買いました。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "古[ふる]い冷蔵庫[れいぞうこ]の寿命[じゅみょう]が来[き]て、新[あたら]しいのを買[か]いました。", "sentence_source": "generated"}, {"text": "毎日大切に使うと、くつの寿命が延びます。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "毎日[まいにち]大切[たいせつ]に使[つか]うと、くつの寿命[じゅみょう]が延[の]びます。", "sentence_source": "generated"}, {"text": "蛍の寿命は短くて、大人になって二週間ほどです。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "蛍[ほたる]の寿命[じゅみょう]は短[みじか]くて、大人[おとな]になって二週間[にしゅうかん]ほどです。", "sentence_source": "generated"}, {"text": "パソコンの寿命は、普通五年ぐらいと言われます。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "パソコンの寿命[じゅみょう]は、普通[ふつう]五年[ごねん]ぐらいと言[い]われます。", "sentence_source": "generated"}, {"text": "電球の寿命が切れて、部屋が急に暗くなった。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "電球[でんきゅう]の寿命[じゅみょう]が切[き]れて、部屋[へや]が急[きゅう]に暗[くら]くなった。", "sentence_source": "generated"}, {"text": "亀は寿命が長い動物として知られています。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "亀[かめ]は寿命[じゅみょう]が長[なが]い動物[どうぶつ]として知[し]られています。", "sentence_source": "generated"}, {"text": "水に濡れたせいで、携帯電話の寿命が短くなった。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "水[みず]に濡[ぬ]れたせいで、携帯電話[けいたいでんわ]の寿命[じゅみょう]が短[みじか]くなった。", "sentence_source": "generated"}, {"text": "花の寿命を延ばすために、毎日水を替えます。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "花[はな]の寿命[じゅみょう]を延[の]ばすために、毎日[まいにち]水[みず]を替[か]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寿命", "label": "基本形"}], "register": "中立", "sense_fingerprint": "使える・生きられる期間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "使える期間の長さを表す語で、「寿命が長い」の形で電池に合う。"}, {"text": "容量", "is_correct": false, "explanation": "電気をためられる量を表すので、「長い」とは結びつかず合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の強さを表す語で、期間の長さは表さないので合わない。"}, {"text": "温度", "is_correct": false, "explanation": "熱さの度合いを表すので、「長い」とは言えず合わない。"}], "explanations": {"寿命": "使える期間の長さを表す語で、「寿命が長い」の形で電池に合う。", "容量": "電気をためられる量を表すので、「長い」とは結びつかず合わない。", "電圧": "電気の強さを表す語で、期間の長さは表さないので合わない。", "温度": "熱さの度合いを表すので、「長い」とは言えず合わない。"}, "sentence_index": 0, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医師は必死に患者の寿命を救った。", "explanation": "ここは〈命〉の意味。「命を救う」とは言うが、寿命は救うものではないので合わない。"}, {"text": "私は寿命が二十歳です。", "explanation": "ここは〈年齢〉の意味。「年齢が二十歳」とは言えるが、寿命は一生の長さを表すので今の年齢には使えない。"}, {"text": "この牛乳は寿命が今日までです。", "explanation": "ここは〈期限〉の意味。食品の期限は「期限」「賞味期限」と言い、寿命とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "終わりを迎えるものとして使われ、「寿命が尽きる」の形で電球に合う。"}, {"text": "電圧", "is_correct": false, "explanation": "電気の強さを表す語で、「尽きる」とは言わないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "光の色は尽きるものではないので、ここでは合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは尽きるものではないので、「尽きて」と続かず合わない。"}], "explanations": {"寿命": "終わりを迎えるものとして使われ、「寿命が尽きる」の形で電球に合う。", "電圧": "電気の強さを表す語で、「尽きる」とは言わないので合わない。", "色": "光の色は尽きるものではないので、ここでは合わない。", "重さ": "重さは尽きるものではないので、「尽きて」と続かず合わない。"}, "sentence_index": 6, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は寿命を取り戻すため、毎日よく眠る。", "explanation": "ここは〈健康〉の意味。寿命は取り戻すものではなく、「健康を取り戻す」と言う。"}, {"text": "風邪をひくと寿命が上がる。", "explanation": "ここは〈体温〉の意味。体の熱は上がると言えるが、寿命が上がるとは言わないので合わない。"}, {"text": "野菜は寿命が豊富だ。", "explanation": "ここは〈栄養〉の意味。栄養は豊富と言えるが、寿命の量が豊富とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このストーブは寿命を長いので、冬の間ずっと使えます。", "corrected_sentence": "このストーブは寿命が長いので、冬の間ずっと使えます。", "error_description": "「寿命」が「長い」の主語になるときの助詞は「が」。「を」は誤りで、「寿命が長い」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38140, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このヒーターは寿命を延ばしために、掃除をします。", "corrected_sentence": "このヒーターは寿命を延ばすために、掃除をします。", "error_description": "「延ばす」の連用形「延ばし」に「ために」は続かない。基本形の「延ばすために」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
