INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38141, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「寿命」が「短い」の主語になる「が」で、ここに合う。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。『寿命と短い』では主語にならず、形容詞に続かない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。『寿命へ短い』では形容詞に続かず、文が成り立たない"}, {"text": "から", "is_correct": false, "explanation": "起点・原因を示す。『寿命から短い』では主語の働きをせず、文が成り立たない"}], "correct_answer": "が", "explanations": {"が": "「寿命」が「短い」の主語になる「が」で、ここに合う。", "と": "並列を示す。『寿命と短い』では主語にならず、形容詞に続かない", "へ": "方向を示す。『寿命へ短い』では形容詞に続かず、文が成り立たない", "から": "起点・原因を示す。『寿命から短い』では主語の働きをせず、文が成り立たない"}, "error_tags": {"と": "並列", "へ": "方向", "から": "起点・原因"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38141, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物が、壊れたり劣化したりせずに長くもつ性質。", "primary_collocate": null, "pronunciation": "じゅみょう", "ipa": "dʑɯmʲoː", "syllable_count": 3, "sentences": [{"text": "この木材は寿命が長く、百年以上もつ。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "この木材[もくざい]は寿命[じゅみょう]が長[なが]く、百年[ひゃくねん]以上[いじょう]もつ。", "sentence_source": "generated"}, {"text": "このカバンは縫い目が丈夫で、寿命が長い。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "このカバンはぬいめがじょうぶで、寿命[じゅみょう]がながい。", "sentence_source": "generated"}, {"text": "寿命の長いタイヤを選べば、交換の回数が減ります。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "寿命[じゅみょう]の長[なが]いタイヤを選[えら]べば、交換[こうかん]の回数[かいすう]が減[へ]ります。", "sentence_source": "generated"}, {"text": "安いスピーカーは寿命が短く、一年で壊れることもある。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "安い[やすい]スピーカーは寿命[じゅみょう]が短く、一年で壊れることもある。", "sentence_source": "generated"}, {"text": "寿命の短い製品ばかり作ると、ごみが増える。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "寿命[じゅみょう]の短[みじか]い製品[せいひん]ばかり作[つく]ると、ごみが増[ふ]える。", "sentence_source": "generated"}, {"text": "この機械は設計がよく、寿命が二倍になった。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "この機械[きかい]は設計[せっけい]がよく、寿命[じゅみょう]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "定期的に油を差せば、この工具は寿命を延ばせる。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "定期的[ていきてき]に油[あぶら]を差[さ]せば、この工具[こうぐ]は寿命[じゅみょう]を延[の]ばせる。", "sentence_source": "generated"}, {"text": "この部品は熱に弱く、寿命が短い。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "この部品[ぶひん]は熱[ねつ]に弱[よわ]く、寿命[じゅみょう]が短[みじか]い。", "sentence_source": "generated"}, {"text": "太陽光パネルの寿命は、二十年以上と言われている。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "太陽光[たいようこう]パネルの寿命[じゅみょう]は、二十年[にじゅうねん]以上[いじょう]と言[い]われている。", "sentence_source": "generated"}, {"text": "この塗料は寿命が長く、十年は塗り直さなくて済む。", "target_word": "寿命", "complexity_tier": "T3", "furigana": "この塗料[とりょう]は寿命[じゅみょう]が長[なが]く、十年[じゅうねん]は塗[ぬ]り直[なお]さなくて済[す]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寿命", "label": "基本形"}], "register": "中立", "sense_fingerprint": "壊れず長くもつ性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 差せ (Zipf 1.82), 延ばせる (Zipf 1.69)']::text[], 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38141, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "壊れずにもつ期間の長さを表す語で、「寿命が長い」と木材に合う。"}, {"text": "強度", "is_correct": false, "explanation": "耐える力の強さを表すので、「長く」とは結びつかず合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "硬い程度を表すので、期間の長さには合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重い程度を表すので、「長く、百年以上もつ」とは続かず合わない。"}], "explanations": {"寿命": "壊れずにもつ期間の長さを表す語で、「寿命が長い」と木材に合う。", "強度": "耐える力の強さを表すので、「長く」とは結びつかず合わない。", "硬さ": "硬い程度を表すので、期間の長さには合わない。", "重さ": "重い程度を表すので、「長く、百年以上もつ」とは続かず合わない。"}, "sentence_index": 0, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この机は寿命が高く、重い荷物も載せられる。", "explanation": "ここは〈強度〉の意味。耐える力は「高い」と言えるが、寿命は期間なので「高い」とは言わないので合わない。"}, {"text": "この板は寿命が十ミリある。", "explanation": "ここは〈厚さ〉の意味。厚さは十ミリと言えるが、寿命は期間の長さでミリでは表さないので合わない。"}, {"text": "この靴は寿命が安い。", "explanation": "ここは〈価格〉の意味。値段は安いと言えるが、寿命は値段の高低では言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38141, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "延ばせる期間の長さを表す語で、工具の使える期間に合う。"}, {"text": "重量", "is_correct": false, "explanation": "重さを表すので、「延ばせる」の対象にはならず合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は延ばせるものではないので、ここでは合わない。"}, {"text": "温度", "is_correct": false, "explanation": "熱さの度合いは延ばせるものではないので、合わない。"}], "explanations": {"寿命": "延ばせる期間の長さを表す語で、工具の使える期間に合う。", "重量": "重さを表すので、「延ばせる」の対象にはならず合わない。", "色": "色は延ばせるものではないので、ここでは合わない。", "温度": "熱さの度合いは延ばせるものではないので、合わない。"}, "sentence_index": 6, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この塗料は寿命が鮮やかで、人気がある。", "explanation": "ここは〈色〉の意味。色は鮮やかと言えるが、寿命は鮮やかさでは表さないので合わない。"}, {"text": "この塗料は寿命が強く、部屋に残る。", "explanation": "ここは〈におい〉の意味。においは強いと言えるが、寿命は強さでは表さないので合わない。"}, {"text": "この塗料は寿命が速いので、すぐに使える。", "explanation": "ここは〈乾燥〉の意味。乾く速さは速いと言えるが、寿命は速いとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38141, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この缶は寿命に長く、十年は使えます。", "corrected_sentence": "この缶は寿命が長く、十年は使えます。", "error_description": "「寿命」が「長く」の主語になるときの助詞は「が」。「に」は誤りで、「寿命が長く」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38141, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このバッグは寿命が長しく、毎日使っても平気だ。", "corrected_sentence": "このバッグは寿命が長く、毎日使っても平気だ。", "error_description": "形容詞「長い」の連用形は「長く」。「長しく」とは言わないので、「長く」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
