INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38142, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "「希有」という言葉は、あまりないこと、とても珍しいことを表します。", "primary_collocate": null, "pronunciation": "けう", "ipa": "keɯ", "syllable_count": 2, "sentences": [{"text": "彼は希有の才能に恵まれた音楽家だ。", "target_word": "希有", "complexity_tier": "T3", "furigana": "彼[かれ]は希有[けう]の才能[さいのう]に恵[めぐ]まれた音楽家[おんがくか]だ。", "sentence_source": "generated"}, {"text": "これほど希有の体験は、一生に一度あるかないかだ。", "target_word": "希有", "complexity_tier": "T3", "furigana": "これほど希有[けう]の体験[たいけん]は、一生[いっしょう]に一度[いちど]あるかないかだ。", "sentence_source": "generated"}, {"text": "希有の存在として、その学者は世界中に知られている。", "target_word": "希有", "complexity_tier": "T3", "furigana": "希有[けう]の存在[そんざい]として、その学者[がくしゃ]は世界中[せかいじゅう]に知[し]られている。", "sentence_source": "generated"}, {"text": "国宝級の希有の名品が、博物館に展示されている。", "target_word": "希有", "complexity_tier": "T3", "furigana": "国宝級[こくほうきゅう]の希有[けう]の名品[めいひん]が、博物館[はくぶつかん]に展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "彼女のような希有の人材は、会社にとって宝だ。", "target_word": "希有", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のような希有[けう]の人材[じんざい]は、会社[かいしゃ]にとって宝[たから]だ。", "sentence_source": "generated"}, {"text": "希有の出来事に、町じゅうが大騒ぎになった。", "target_word": "希有", "complexity_tier": "T3", "furigana": "希有[けう]の出来事[できごと]に、町[まち]じゅうが大騒[おおさわ]ぎになった。", "sentence_source": "generated"}, {"text": "希有の天才と呼ばれた棋士が、七十歳で亡くなった。", "target_word": "希有", "complexity_tier": "T3", "furigana": "希有[けう]の天才[てんさい]と呼[よ]ばれた棋士[きし]が、七十歳[ななじゅっさい]で亡[な]くなった。", "sentence_source": "generated"}, {"text": "その島には、他では見られない希有の生き物がすんでいる。", "target_word": "希有", "complexity_tier": "T3", "furigana": "その島[しま]には、他[ほか]では見[み]られない希有[けう]の生[い]き物[もの]がすんでいる。", "sentence_source": "generated"}, {"text": "百年に一度という希有の天文現象を、皆で見上げた。", "target_word": "希有", "complexity_tier": "T3", "furigana": "百年[ひゃくねん]に一度[いちど]という希有[けう]の天文現象[てんもんげんしょう]を、皆[みな]で見上[みあ]げた。", "sentence_source": "generated"}, {"text": "彼は希有の記憶力を持ち、一度見た顔は忘れない。", "target_word": "希有", "complexity_tier": "T3", "furigana": "彼[かれ]は希有[けう]の記憶力[きおくりょく]を持[も]ち、一度[いちど]見[み]た顔[かお]は忘[わす]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "希有", "label": "基本形"}, {"form": "希有の", "label": "連体形(の)"}], "register": "formal", "sense_fingerprint": "ほとんど存在しないほど珍しいこと。「希有の+名詞」の形で才能・存在・出来事などを修飾する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38142, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "希有", "is_correct": true, "explanation": "正解。「希有の才能」で、めったにない才能に恵まれたことを表す。"}, {"text": "平凡", "is_correct": false, "explanation": "平凡は特別なところがないという意味。「恵まれた」才能とは矛盾する。"}, {"text": "軽薄", "is_correct": false, "explanation": "軽薄は考えや態度が浅いという意味で、才能の希少さを表せず、恵まれたとも結びつかない。"}, {"text": "不要", "is_correct": false, "explanation": "不要は必要ないという意味。才能に恵まれたという文では意味をなさない。"}], "explanations": {"希有": "正解。「希有の才能」で、めったにない才能に恵まれたことを表す。", "平凡": "平凡は特別なところがないという意味。「恵まれた」才能とは矛盾する。", "軽薄": "軽薄は考えや態度が浅いという意味で、才能の希少さを表せず、恵まれたとも結びつかない。", "不要": "不要は必要ないという意味。才能に恵まれたという文では意味をなさない。"}, "sentence_index": 0, "correct_answer": "希有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その知らせは町の人々に大きな希有をもたらした。", "explanation": "ここは〈希望〉の意味。「大きな希望をもたらす」の語を希有に置き換えた誤りで、希有はめったにないさまを表す。"}, {"text": "標高が高くなると、空気が希有になる。", "explanation": "ここは〈希薄〉の意味。空気の密度が低いことを表す語で、めったにないという希有は当てはまらない。"}, {"text": "堤防が壊れて希有の水が流れ出した。", "explanation": "ここは〈大量〉の意味。水の量が多いことを表す語で、希有は数量ではなく珍しさを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38142, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "希有", "is_correct": true, "explanation": "正解。「希有の天才」で、めったにない天才と呼ばれたことを表す。"}, {"text": "陳腐", "is_correct": false, "explanation": "陳腐は古くさく新鮮味がないという意味で、天才と呼ばれることと矛盾する。"}, {"text": "不運", "is_correct": false, "explanation": "不運は運が悪いという意味で、天才という評価とは結びつかない。"}, {"text": "滑稽", "is_correct": false, "explanation": "滑稽はおかしいさまを表す語で、天才と呼ばれる棋士の描写には合わない。"}], "explanations": {"希有": "正解。「希有の天才」で、めったにない天才と呼ばれたことを表す。", "陳腐": "陳腐は古くさく新鮮味がないという意味で、天才と呼ばれることと矛盾する。", "不運": "不運は運が悪いという意味で、天才という評価とは結びつかない。", "滑稽": "滑稽はおかしいさまを表す語で、天才と呼ばれる棋士の描写には合わない。"}, "sentence_index": 6, "correct_answer": "希有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の資料を希有にまとめて、全員に配った。", "explanation": "ここは〈簡潔に〉の意味。資料を短くまとめることは簡潔にと言い、希有はめったにないさまを表す語なので合わない。"}, {"text": "この地方希有の料理が、夏になると食卓に並ぶ。", "explanation": "ここは〈稀少〉の意味に合わない。夏ごとに食卓に並ぶ料理はめったにないものではないので、希有の〈めったにない〉と矛盾する。"}, {"text": "彼の毎日は希有の繰り返しだ。", "explanation": "ここは〈平凡〉の意味。平凡の繰り返しはありふれた日々のこと。希有は珍しさを表すので、日常の繰り返しには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38142, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は希有が才能を持つ画家として知られている。", "corrected_sentence": "彼女は希有の才能を持つ画家として知られている。", "error_description": "名詞の「希有」が後ろの名詞を修飾するには「の」が必要。「が」を付けると「希有」が主語になり、「才能を持つ」と続かず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38142, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その投手は希有を制球力で知られていた。", "corrected_sentence": "その投手は希有の制球力で知られていた。", "error_description": "名詞の「希有」の後には、後ろの名詞を修飾する「の」が必要。「を」では「知られる」の目的語にならず、文として不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
