INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38143, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「希有」とは、めったにないさま、非常に珍しいことを意味する形容動詞（ナ形容詞）です。", "primary_collocate": null, "pronunciation": "けう", "ipa": "keɯ", "syllable_count": 2, "sentences": [{"text": "これほど優しい人は、今の時代では希有だ。", "target_word": "希有", "complexity_tier": "T3", "furigana": "これほど優[やさ]しい人[ひと]は、今[いま]の時代[じだい]では希有[けう]だ。", "sentence_source": "generated"}, {"text": "彼のように努力を続けられる人は希有な存在だ。", "target_word": "希有", "complexity_tier": "T3", "furigana": "彼[かれ]のように努力[どりょく]を続[つづ]けられる人[ひと]は希有[けう]な存在[そんざい]だ。", "sentence_source": "generated"}, {"text": "希有な才能を持つ少女が、国際大会で優勝した。", "target_word": "希有", "complexity_tier": "T3", "furigana": "希有[けう]な才能[さいのう]を持[も]つ少女[しょうじょ]が、国際大会[こくさいたいかい]で優勝[ゆうしょう]した。", "sentence_source": "generated"}, {"text": "この品質の絹は、世界でも希有だと言われる。", "target_word": "希有", "complexity_tier": "T3", "furigana": "この品質[ひんしつ]の絹[きぬ]は、世界[せかい]でも希有[けう]だと言[い]われる。", "sentence_source": "generated"}, {"text": "友人のために全財産を差し出すとは、希有なことだ。", "target_word": "希有", "complexity_tier": "T3", "furigana": "友人[ゆうじん]のために全財産[ぜんざいさん]を差[さ]し出[だ]すとは、希有[けう]なことだ。", "sentence_source": "generated"}, {"text": "同じ花が一年に二度咲くのは希有で、専門家も驚いた。", "target_word": "希有", "complexity_tier": "T3", "furigana": "同[おな]じ花[はな]が一年[いちねん]に二度[にど]咲[さ]くのは希有[けう]で、専門家[せんもんか]も驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "希有な機会を得られたことに、心から感謝している。", "target_word": "希有", "complexity_tier": "T3", "furigana": "希有[けう]な機会[きかい]を得[え]られたことに、心[こころ]から感謝[かんしゃ]している。", "sentence_source": "generated"}, {"text": "人の話を最後まで聞ける子どもは、実は希有である。", "target_word": "希有", "complexity_tier": "T3", "furigana": "人[ひと]の話[はなし]を最後[さいご]まで聞[き]ける子[こ]どもは、実[じつ]は希有[けう]である。", "sentence_source": "generated"}, {"text": "雪の降らない街で積雪を見るのは、希有な経験だった。", "target_word": "希有", "complexity_tier": "T3", "furigana": "雪[ゆき]の降[ふ]らない街[まち]で積雪[せきせつ]を見[み]るのは、希有[けう]な経験[けいけん]だった。", "sentence_source": "generated"}, {"text": "彼女の歌声は希有な美しさを持っている。", "target_word": "希有", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌声[うたごえ]は希有[けう]な美[うつく]しさを持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "希有だ", "label": "終止形"}, {"form": "希有な", "label": "連体形"}, {"form": "希有で", "label": "連用形(で)"}, {"form": "希有に", "label": "連用形(に)"}, {"form": "希有である", "label": "断定(である)"}, {"form": "希有だった", "label": "過去形"}], "register": "formal", "sense_fingerprint": "めったにないほど珍しいさま。「希有だ・希有な・希有で」とナ形容詞として述語や連体修飾に使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38143, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "希有", "is_correct": true, "explanation": "正解。「今の時代では希有だ」で、今どき優しい人がめったにいないことを表す。"}, {"text": "不要", "is_correct": false, "explanation": "不要は必要ないという意味。優しい人を評価する文に入れると、意味が通らない。"}, {"text": "退屈", "is_correct": false, "explanation": "退屈は時間を持て余す意味で、人の性質を評する文には合わない。"}, {"text": "陳腐", "is_correct": false, "explanation": "陳腐は古くさいという意味で、優しさという人柄の評価には当てはまらない。"}], "explanations": {"希有": "正解。「今の時代では希有だ」で、今どき優しい人がめったにいないことを表す。", "不要": "不要は必要ないという意味。優しい人を評価する文に入れると、意味が通らない。", "退屈": "退屈は時間を持て余す意味で、人の性質を評する文には合わない。", "陳腐": "陳腐は古くさいという意味で、優しさという人柄の評価には当てはまらない。"}, "sentence_index": 0, "correct_answer": "希有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジュースに水を加えると、味が希有になる。", "explanation": "ここは〈希薄〉の意味。味の濃さが薄くなることを表す語で、めったにないという希有とは意味が違う。"}, {"text": "この地域の景気は希有だと言われる。", "explanation": "ここは〈不安定〉の意味。景気が安定しないことを表す語で、珍しさを表す希有は合わない。"}, {"text": "彼の説明は希有で、誰が聞いても分かる。", "explanation": "ここは〈明確〉の意味。内容がはっきりしていることを表す語で、希有は珍しさを表すので説明の明快さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38143, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "希有", "is_correct": true, "explanation": "正解。「希有な機会」で、めったにない機会を得られたことへの感謝を表す。"}, {"text": "凡庸", "is_correct": false, "explanation": "凡庸はごく普通で優れた点がないという意味。得がたい機会への感謝とは矛盾する。"}, {"text": "滑稽", "is_correct": false, "explanation": "滑稽はおかしいさまを表す語で、感謝の文脈には合わない。"}, {"text": "粗雑", "is_correct": false, "explanation": "粗雑は雑で行き届かないという意味。大切な機会には当てはまらない。"}], "explanations": {"希有": "正解。「希有な機会」で、めったにない機会を得られたことへの感謝を表す。", "凡庸": "凡庸はごく普通で優れた点がないという意味。得がたい機会への感謝とは矛盾する。", "滑稽": "滑稽はおかしいさまを表す語で、感謝の文脈には合わない。", "粗雑": "粗雑は雑で行き届かないという意味。大切な機会には当てはまらない。"}, "sentence_index": 6, "correct_answer": "希有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この写真は色が希有で、細部までくっきりしている。", "explanation": "ここは〈鮮明〉の意味。色や輪郭がはっきりしていることを表す語で、希有は珍しさを表すので写真の鮮やかさには合わない。"}, {"text": "この扉は希有で、がっちりしている。", "explanation": "ここは〈頑丈〉の意味。堅くしっかりしていることを表す語で、めったにないという希有とは意味が合わない。"}, {"text": "このスープは希有で、味わいが深い。", "explanation": "ここは〈濃厚〉の意味。味が濃くこくがあることを表す語で、珍しさを表す希有は味の濃さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38143, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この宝石は希有だ輝きを放っている。", "corrected_sentence": "この宝石は希有な輝きを放っている。", "error_description": "名詞「輝き」を修飾するには連体形「希有な」が必要。「希有だ」は述語の形で、名詞の前には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "希有な", "is_correct": true, "explanation": "正解。「な」を付けて名詞「存在」を修飾する連体形。"}, {"text": "希有だ", "is_correct": false, "explanation": "終止形で、名詞「存在」の前に直接置けない。"}, {"text": "希有で", "is_correct": false, "explanation": "連用形（中止）で、名詞を修飾する位置には使えない。"}, {"text": "希有に", "is_correct": false, "explanation": "連用形で副詞的な働きになり、「存在」を修飾できない。"}], "correct_form": "希有な", "base_form": "希有だ", "form_label": "連体形（希有な）", "sentence_index": 1, "explanations": {"希有な": "正解。「な」を付けて名詞「存在」を修飾する連体形。", "希有だ": "終止形で、名詞「存在」の前に直接置けない。", "希有で": "連用形（中止）で、名詞を修飾する位置には使えない。", "希有に": "連用形で副詞的な働きになり、「存在」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38143, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その画家の筆致は希有が美しさを持つ。", "corrected_sentence": "その画家の筆致は希有な美しさを持つ。", "error_description": "名詞修飾の「希有な」が必要なところを「希有が」にした誤り。「希有が」では主語になり、後ろの「美しさ」を修飾できず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "希有", "is_correct": true, "explanation": "正解。「希有である」の語幹にあたる形で、ナ形容詞の基本となる語幹。"}, {"text": "希有な", "is_correct": false, "explanation": "連体形で名詞に続く形。文末の述語の位置には合わない。"}, {"text": "希有だった", "is_correct": false, "explanation": "過去形で、今の評価を述べる文の時制と合わない。"}, {"text": "希有である", "is_correct": false, "explanation": "断定の形で、語幹の「希有」とは形が違う。"}], "correct_form": "希有", "base_form": "希有だ", "form_label": "語幹（希有である）", "sentence_index": 7, "explanations": {"希有": "正解。「希有である」の語幹にあたる形で、ナ形容詞の基本となる語幹。", "希有な": "連体形で名詞に続く形。文末の述語の位置には合わない。", "希有だった": "過去形で、今の評価を述べる文の時制と合わない。", "希有である": "断定の形で、語幹の「希有」とは形が違う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38144, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "行き先を表す「へ」が合います。"}, {"text": "の", "is_correct": false, "explanation": "「公園の行きます」は文になりません。"}, {"text": "が", "is_correct": false, "explanation": "「公園が行きます」は、公園が動くことになり不自然です。"}, {"text": "か", "is_correct": false, "explanation": "「公園か行きます」は文法的に成り立ちません。"}], "correct_answer": "へ", "explanations": {"へ": "行き先を表す「へ」が合います。", "の": "「公園の行きます」は文になりません。", "が": "「公園が行きます」は、公園が動くことになり不自然です。", "か": "「公園か行きます」は文法的に成り立ちません。"}, "error_tags": {"の": "noun_link", "が": "subject_marker", "か": "question_marker"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38144, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "食べる場所を表す「で」が合います。"}, {"text": "を", "is_correct": false, "explanation": "「公園をお弁当を食べたい」は「を」が重なり不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「食べる」は移動の動詞ではないので「へ」は合いません。"}, {"text": "ば", "is_correct": false, "explanation": "名詞のあとに「ば」は付きません。"}], "correct_answer": "で", "explanations": {"で": "食べる場所を表す「で」が合います。", "を": "「公園をお弁当を食べたい」は「を」が重なり不自然です。", "へ": "「食べる」は移動の動詞ではないので「へ」は合いません。", "ば": "名詞のあとに「ば」は付きません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "ば": "conditional"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38144, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外で遊んだり、花や木を見たりする大きな場所です。", "primary_collocate": null, "pronunciation": "こうえん", "ipa": "koːeɴ", "syllable_count": 4, "sentences": [{"text": "公園は広い。", "target_word": "公園", "complexity_tier": "T1", "furigana": "公園[こうえん]は広[ひろ]い。", "sentence_source": "generated"}, {"text": "公園で遊ぶ。", "target_word": "公園", "complexity_tier": "T1", "furigana": "公園[こうえん]で遊[あそ]ぶ。", "sentence_source": "generated"}, {"text": "日曜日に公園へ行きます。", "target_word": "公園", "complexity_tier": "T2", "furigana": "日曜日[にちようび]に公園[こうえん]へ行[い]きます。", "sentence_source": "generated"}, {"text": "公園に木と花があります。", "target_word": "公園", "complexity_tier": "T2", "furigana": "公園[こうえん]に木[き]と花[はな]があります。", "sentence_source": "generated"}, {"text": "子どもたちが公園で走っている。", "target_word": "公園", "complexity_tier": "T3", "furigana": "子[こ]どもたちが公園[こうえん]で走[はし]っている。", "sentence_source": "generated"}, {"text": "公園に咲いているきれいな花を見た。", "target_word": "公園", "complexity_tier": "T3", "furigana": "公園[こうえん]に咲[さ]いているきれいな花[はな]を見[み]た。", "sentence_source": "generated"}, {"text": "犬を連れて公園を歩きました。", "target_word": "公園", "complexity_tier": "T3", "furigana": "犬[いぬ]を連[つ]れて公園[こうえん]を歩[ある]きました。", "sentence_source": "generated"}, {"text": "天気がよければ、公園でお弁当を食べたい。", "target_word": "公園", "complexity_tier": "T4", "furigana": "天気[てんき]がよければ、公園[こうえん]でお弁当[べんとう]を食[た]べたい。", "sentence_source": "generated"}, {"text": "公園の池に鳥が集まるのを見て、写真を撮った。", "target_word": "公園", "complexity_tier": "T4", "furigana": "公園[こうえん]の池[いけ]に鳥[とり]が集[あつ]まるのを見[み]て、写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "新しくできた公園は広くて、休みの日には家族連れで賑わう。", "target_word": "公園", "complexity_tier": "T5", "furigana": "新[あたら]しくできた公園[こうえん]は広[ひろ]くて、休[やす]みの日[ひ]には家族連[かぞくづ]れで賑[にぎ]わう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公園内", "label": "派生"}, {"form": "国立公園", "label": "派生"}, {"form": "都市公園", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 外で遊び花や木を見る広い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38144, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公園", "is_correct": true, "explanation": "見出し語「こうえん」そのものです。"}, {"text": "光栄", "is_correct": false, "explanation": "「こうえい」で、最後の音が違います。"}, {"text": "高原", "is_correct": false, "explanation": "「こうげん」で、三番目の音が違います。"}, {"text": "交換", "is_correct": false, "explanation": "「こうかん」で、三番目の音が違います。"}, {"text": "公団", "is_correct": false, "explanation": "「こうだん」で、三番目の音が違います。"}], "explanations": {"公園": "見出し語「こうえん」そのものです。", "光栄": "「こうえい」で、最後の音が違います。", "高原": "「こうげん」で、三番目の音が違います。", "交換": "「こうかん」で、三番目の音が違います。", "公団": "「こうだん」で、三番目の音が違います。"}, "sentence_index": null, "correct_answer": "公園"}, "level_3": {"options": [{"text": "公園", "is_correct": true, "explanation": "広い場所を表す名詞で、文の意味に合います。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段は「広い」と言えないので意味が合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "形は合うが、音楽は「広い」と言えないので意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は「広い」と言えないので意味が合わない。"}], "explanations": {"公園": "広い場所を表す名詞で、文の意味に合います。", "値段": "形は合うが、値段は「広い」と言えないので意味が合わない。", "音楽": "形は合うが、音楽は「広い」と言えないので意味が合わない。", "天気": "形は合うが、天気は「広い」と言えないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "公園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園を飲んで、元気になりました。", "explanation": "「公園」は場所なので、飲むことはできません。"}, {"text": "公園は電話で話すときに使う道具です。", "explanation": "「公園」を道具の意味で使っていて、誤りです。"}, {"text": "母は公園を着て出かけました。", "explanation": "「公園」は場所なので、着るものとしては使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
