INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38145, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "公園とは、人々が休んだり遊んだりするために作られた、樹木や花壇、遊具などがある公共の屋外スペースのことです。", "primary_collocate": null, "pronunciation": "こうえん", "ipa": "koːeɴ", "syllable_count": 4, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り方で一人の少年が手作りのレモネードを販売していた。", "target_word": "公園", "complexity_tier": "T6", "furigana": "記録的[きろくてき]な暑[あつ]さが続[つづ]く夏[なつ]の午後[ごご]、公園[こうえん]の入[い]り方[かた]で一人[ひとり]の少年[しょうねん]が手作[てづく]りのレモネードを販売[はんばい]していた。", "sentence_source": "mined"}, {"text": "公園に行く。", "target_word": "公園", "complexity_tier": "T1", "furigana": "公園[こうえん]に行[い]く。", "sentence_source": "generated"}, {"text": "公園で友だちと遊びます。", "target_word": "公園", "complexity_tier": "T2", "furigana": "公園[こうえん]で友[とも]だちと遊[あそ]びます。", "sentence_source": "generated"}, {"text": "近くに大きい公園があります。", "target_word": "公園", "complexity_tier": "T2", "furigana": "近[ちか]くに大[おお]きい公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "毎朝、公園を走っています。", "target_word": "公園", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、公園[こうえん]を走[はし]っています。", "sentence_source": "generated"}, {"text": "公園のベンチで本を読んだ。", "target_word": "公園", "complexity_tier": "T3", "furigana": "公園[こうえん]のベンチで本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "雨が止んだら、公園へ散歩に行こうと思う。", "target_word": "公園", "complexity_tier": "T4", "furigana": "雨[あめ]が止[や]んだら、公園[こうえん]へ散歩[さんぽ]に行[い]こうと思[おも]う。", "sentence_source": "generated"}, {"text": "桜の咲く公園は人でいっぱいだった。", "target_word": "公園", "complexity_tier": "T3", "furigana": "桜[さくら]の咲[さ]く公園[こうえん]は人[ひと]でいっぱいだった。", "sentence_source": "generated"}, {"text": "この公園は、市民が気軽に自然と触れ合える場所として作られた。", "target_word": "公園", "complexity_tier": "T5", "furigana": "この公園[こうえん]は、市民[しみん]が気軽[きがる]に自然[しぜん]と触[ふ]れ合[あ]える場所[ばしょ]として作[つく]られた。", "sentence_source": "generated"}, {"text": "公園の入り口に、新しい看板が立てられた。", "target_word": "公園", "complexity_tier": "T4", "furigana": "公園[こうえん]の入[い]り口[ぐち]に、新[あたら]しい看板[かんばん]が立[た]てられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公園内", "label": "派生"}, {"form": "国立公園", "label": "派生"}, {"form": "都市公園", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人々が憩う公共の屋外空間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 触れ合える (Zipf 2.29)']::text[], '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
